/// Graph topology metrics used for intelligent algorithm auto-selection.
///
/// For diagram types that map unambiguously to a specific algorithm (e.g. Mindmap → Radial),
/// the metrics are not consulted. For general graph types (Flowchart, Class, State, ER, etc.),
/// these metrics drive the choice between Sugiyama, Force, and Tree layouts.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct GraphMetrics {
    pub node_count: usize,
    pub edge_count: usize,
    /// `edge_count / node_count` (0.0 when no nodes).
    pub edge_to_node_ratio: f32,
    /// Number of DFS back-edges (proxy for cycle density).
    pub back_edge_count: usize,
    /// Number of strongly connected components with more than one node.
    pub scc_count: usize,
    /// Size of the largest SCC (1 means no cycles).
    pub max_scc_size: usize,
    /// Nodes with in-degree 0 (candidate roots for tree layout).
    pub root_count: usize,
    /// True when the graph has no back-edges and a single root — an exact tree.
    pub is_tree_like: bool,
    /// True when the edge-to-node ratio is low (< 1.2), suggesting sparse connectivity.
    pub is_sparse: bool,
    /// True when the edge-to-node ratio is high (> 2.0), suggesting dense connectivity.
    pub is_dense: bool,
}

impl GraphMetrics {
    /// Compute graph metrics from the IR.  Runs DFS back-edge detection and Tarjan SCC
    /// detection in O(V+E) time, so this is cheap relative to actual layout.
    #[must_use]
    pub fn from_ir(ir: &MermaidDiagramIr) -> Self {
        if let Some(cached) = try_graph_metrics_cache_hit(ir) {
            return cached;
        }

        let start = Instant::now();
        let node_count = ir.nodes.len();
        let edges = resolved_edges(ir);
        let edge_count = edges.len();
        let edge_to_node_ratio = if node_count == 0 {
            0.0
        } else {
            edge_count as f32 / node_count as f32
        };

        let mut in_degree = vec![0_usize; node_count];
        for edge in &edges {
            in_degree[edge.target] = in_degree[edge.target].saturating_add(1);
        }
        let root_count = in_degree.iter().filter(|d| **d == 0).count();

        let back_edge_count = count_back_edges(node_count, &edges);

        // No back edges ⇒ the graph is acyclic ⇒ every strongly-connected component is a singleton,
        // so `scc_count == 0` and `max_scc_size == 1`. Skip the O(V+E) Tarjan SCC pass and the node
        // priority computation that only feeds it — a no-op result for the common DAG case. This
        // metrics struct is rebuilt for the Auto algorithm-selection posteriors on every layout, so
        // the saved traversals shave the selection overhead on the (cache-cold) hot path.
        let (scc_count, max_scc_size) = if back_edge_count == 0 {
            (0, 1)
        } else {
            // `scc_count` + `max_scc_size` are invariant to the SCC visit order (the strongly-connected
            // decomposition is unique — only the component LIST ORDER depends on the priority, and the
            // metrics never read the order). So skip `stable_node_priorities`'s O(N log N) node-id
            // String-memcmp sort (its only purpose is deterministic component order) and pass an identity
            // priority. Byte-identical `scc_count`/`max_scc_size` ⇒ byte-identical algorithm selection.
            let identity_priority: Vec<usize> = (0..node_count).collect();
            let cycle_detection = detect_cycle_components(node_count, &edges, &identity_priority);
            let scc_count = cycle_detection.cyclic_component_indexes.len();
            let max_scc_size = cycle_detection
                .components
                .iter()
                .filter(|c| c.len() > 1)
                .map(Vec::len)
                .max()
                .unwrap_or(1);
            (scc_count, max_scc_size)
        };

        let is_tree_like = node_count > 0
            && back_edge_count == 0
            && root_count == 1
            && edge_count == node_count - 1;
        let is_sparse = edge_to_node_ratio < 1.2;
        let is_dense = edge_to_node_ratio > 2.0;

        let metrics = Self {
            node_count,
            edge_count,
            edge_to_node_ratio,
            back_edge_count,
            scc_count,
            max_scc_size,
            root_count,
            is_tree_like,
            is_sparse,
            is_dense,
        };

        record_graph_metrics_cache_miss(ir, metrics, start.elapsed(), node_count);
        metrics
    }
}

fn try_graph_metrics_cache_hit(ir: &MermaidDiagramIr) -> Option<GraphMetrics> {
    ACTIVE_INCREMENTAL_STATE.with(|slot| {
        let mut state = slot.borrow_mut();
        let state = state.as_mut()?;
        if let Some((cached_ir, cached_metrics)) = state.graph_metrics_cache.as_ref()
            && metrics_topology_equal(cached_ir, ir)
        {
            let cached_metrics = *cached_metrics;
            let total_nodes = ir.nodes.len();
            let summary = IncrementalQuerySummary {
                query_type: "graph_metrics",
                cache_hit: true,
                recomputed_nodes: 0,
                total_nodes,
                recompute_duration_us: 0,
            };
            trace!(
                query_type = summary.query_type,
                cache_hit = summary.cache_hit,
                recomputed_nodes = summary.recomputed_nodes,
                total_nodes = summary.total_nodes,
                recompute_duration_us = summary.recompute_duration_us,
                "incremental.recompute"
            );
            state.record_query(summary);
            return Some(cached_metrics);
        }
        None
    })
}

fn record_graph_metrics_cache_miss(
    ir: &MermaidDiagramIr,
    metrics: GraphMetrics,
    duration: std::time::Duration,
    total_nodes: usize,
) {
    ACTIVE_INCREMENTAL_STATE.with(|slot| {
        let mut state = slot.borrow_mut();
        let Some(state) = state.as_mut() else {
            return;
        };
        let recompute_duration_us = duration.as_micros().try_into().unwrap_or(u64::MAX);
        // Reuse the pass snapshot as the comparison anchor when it matches the queried IR (it
        // always does for the engine's own pass); only exotic callers pay a fresh clone. The
        // stored snapshot only needs to be metrics-topology-equal to the IR whose metrics were
        // cached, so reusing an equal snapshot is exact.
        let snapshot = state
            .pass_snapshot
            .as_ref()
            .filter(|snapshot| metrics_topology_equal(snapshot, ir))
            .cloned()
            .unwrap_or_else(|| Arc::new(ir.clone()));
        state.graph_metrics_cache = Some((snapshot, metrics));
        let summary = IncrementalQuerySummary {
            query_type: "graph_metrics",
            cache_hit: false,
            recomputed_nodes: total_nodes,
            total_nodes,
            recompute_duration_us,
        };
        debug!(
            query_type = summary.query_type,
            total_nodes, "incremental.cache_miss"
        );
        trace!(
            query_type = summary.query_type,
            dependency = "graph_topology",
            "incremental.dependency_update"
        );
        trace!(
            query_type = summary.query_type,
            cache_hit = summary.cache_hit,
            recomputed_nodes = summary.recomputed_nodes,
            total_nodes = summary.total_nodes,
            recompute_duration_us = summary.recompute_duration_us,
            "incremental.recompute"
        );
        state.record_query(summary);
    });
}

/// Metrics-relevant topology equality, covering exactly the inputs of `resolved_edges` (whose
/// resolved index pairs the former `graph_metrics_cache_key` hashed): node count, raw edge
/// endpoints, and port→node assignments (port resolution feeds resolved endpoints). No
/// allocation, short-circuits at the first difference, and cannot false-hit on a hash collision.
/// Conservative vs the hash: an edit that changes raw endpoints while resolving to identical
/// index pairs now misses and recomputes the same metrics instead of hitting.
fn metrics_topology_equal(previous: &MermaidDiagramIr, current: &MermaidDiagramIr) -> bool {
    previous.nodes.len() == current.nodes.len()
        && previous.edges.len() == current.edges.len()
        && previous.ports.len() == current.ports.len()
        && previous
            .edges
            .iter()
            .zip(&current.edges)
            .all(|(previous_edge, current_edge)| {
                previous_edge.from == current_edge.from && previous_edge.to == current_edge.to
            })
        && previous
            .ports
            .iter()
            .zip(&current.ports)
            .all(|(previous_port, current_port)| previous_port.node == current_port.node)
}

const INCREMENTAL_DEPENDENCY_GRAPH_BYPASS_NODE_THRESHOLD: usize = 50;
/// The largest flat connectivity fragment that remains one invalidation region. Larger connected
/// flowcharts carry no semantic subgraph boundary, so deterministic input-order windows provide
/// the bounded fallback that keeps a local edit from invalidating the entire document.
const FLAT_COMPONENT_REGION_NODE_CAP: usize = 64;

fn track_dependency_graph_query(ir: &MermaidDiagramIr) {
    ACTIVE_INCREMENTAL_STATE.with(|slot| {
        let mut state = slot.borrow_mut();
        let Some(state) = state.as_mut() else {
            return;
        };

        let total_nodes = ir.nodes.len();
        if total_nodes < INCREMENTAL_DEPENDENCY_GRAPH_BYPASS_NODE_THRESHOLD {
            let summary = IncrementalQuerySummary {
                query_type: "dependency_graph_bypass",
                cache_hit: false,
                recomputed_nodes: 0,
                total_nodes,
                recompute_duration_us: 0,
            };
            trace!(
                query_type = summary.query_type,
                node_threshold = INCREMENTAL_DEPENDENCY_GRAPH_BYPASS_NODE_THRESHOLD,
                total_nodes = summary.total_nodes,
                "incremental.dependency_update"
            );
            state.record_query(summary);
            return;
        }

        let snapshot = state
            .pass_snapshot
            .get_or_insert_with(|| Arc::new(ir.clone()))
            .clone();
        if let Some(cached) = state.dependency_graph_cache.as_mut()
            && dependency_topology_equal(&cached.ir, ir)
        {
            let dirty_nodes = dirty_nodes_for_edits(&cached.graph, &cached.graph, &cached.ir, ir);
            let summary = IncrementalQuerySummary {
                query_type: "dependency_graph",
                cache_hit: true,
                recomputed_nodes: dirty_nodes,
                total_nodes,
                recompute_duration_us: 0,
            };
            trace!(
                query_type = summary.query_type,
                cache_hit = summary.cache_hit,
                dirty_nodes = summary.recomputed_nodes,
                total_nodes = summary.total_nodes,
                total_regions = cached.graph.regions().len(),
                "incremental.dependency_update"
            );
            cached.ir = snapshot;
            state.record_query(summary);
            return;
        }

        let start = Instant::now();
        let graph = LayoutDependencyGraph::from_ir(ir);
        let recompute_duration_us = saturating_elapsed_micros(start.elapsed());
        let dirty_nodes = state
            .dependency_graph_cache
            .as_ref()
            .map_or(total_nodes, |cached| {
                dirty_nodes_for_edits(&cached.graph, &graph, &cached.ir, ir)
            });
        let summary = IncrementalQuerySummary {
            query_type: "dependency_graph",
            cache_hit: false,
            recomputed_nodes: dirty_nodes.max(1).min(total_nodes),
            total_nodes,
            recompute_duration_us,
        };
        trace!(
            query_type = summary.query_type,
            cache_hit = summary.cache_hit,
            dirty_nodes = summary.recomputed_nodes,
            total_nodes = summary.total_nodes,
            total_regions = graph.regions().len(),
            recompute_duration_us = summary.recompute_duration_us,
            "incremental.dependency_update"
        );
        state.dependency_graph_cache = Some(CachedDependencyGraph {
            graph: Arc::new(graph),
            ir: snapshot,
        });
        state.record_query(summary);
    });
}

fn dirty_nodes_for_edits(
    previous_graph: &LayoutDependencyGraph,
    current_graph: &LayoutDependencyGraph,
    previous_ir: &MermaidDiagramIr,
    current_ir: &MermaidDiagramIr,
) -> usize {
    dirty_node_indexes_for_edits(previous_graph, current_graph, previous_ir, current_ir).len()
}

fn dirty_node_indexes_for_edits(
    previous_graph: &LayoutDependencyGraph,
    current_graph: &LayoutDependencyGraph,
    previous_ir: &MermaidDiagramIr,
    current_ir: &MermaidDiagramIr,
) -> BTreeSet<usize> {
    let LayoutDiff {
        edits,
        topology_equal: same_topology,
    } = derive_layout_diff(previous_ir, current_ir);
    if edits.is_empty() {
        return BTreeSet::new();
    }
    let mut dirty_current = DirtySet::default();
    let mut dirty_previous = DirtySet::default();

    for edit in edits {
        match edit {
            LayoutEdit::NodeRemoved { .. } | LayoutEdit::EdgeRemoved { .. } if !same_topology => {
                let located = previous_graph.locate_dirty_regions(edit);
                dirty_previous.extend(previous_graph.propagate_dirty(&located).regions);
            }
            _ => {
                let located = current_graph.locate_dirty_regions(edit);
                dirty_current.extend(current_graph.propagate_dirty(&located).regions);
            }
        }
    }

    if same_topology {
        dirty_current.extend(dirty_previous.regions);
        return dirty_nodes_from_sets(current_graph, &dirty_current, current_ir.nodes.len());
    }

    let mut dirty_nodes =
        dirty_nodes_from_sets(current_graph, &dirty_current, current_ir.nodes.len());
    dirty_nodes.extend(dirty_nodes_from_sets(
        previous_graph,
        &dirty_previous,
        current_ir.nodes.len(),
    ));
    dirty_nodes
}

fn dirty_nodes_from_sets<G: DependencyGraph>(
    graph: &G,
    dirty: &DirtySet,
    max_node_count: usize,
) -> BTreeSet<usize> {
    dirty
        .regions
        .iter()
        .filter_map(|region_id| graph.regions().get(region_id))
        .flat_map(|region| region.node_indexes.iter().copied())
        .filter(|node_index| *node_index < max_node_count)
        .collect()
}

fn incremental_region_members(
    ir: &MermaidDiagramIr,
    dirty_members: &BTreeSet<usize>,
) -> Vec<usize> {
    let mut members = dirty_members.clone();
    for edge in &ir.edges {
        let Some(source) = endpoint_node_index(ir, edge.from) else {
            continue;
        };
        let Some(target) = endpoint_node_index(ir, edge.to) else {
            continue;
        };
        if dirty_members.contains(&source) {
            members.insert(target);
        }
        if dirty_members.contains(&target) {
            members.insert(source);
        }
    }
    members.into_iter().collect()
}

fn incremental_overlap_alignment(
    dirty_members: &BTreeSet<usize>,
    local_entries: &BTreeMap<usize, (LayoutRect, usize, usize)>,
    nodes: &[LayoutNodeBox],
) -> Option<(f32, f32)> {
    let mut anchor_count = 0_u32;
    let mut dx_total = 0.0_f32;
    let mut dy_total = 0.0_f32;

    for (&node_index, (bounds, _, _)) in local_entries {
        if dirty_members.contains(&node_index) {
            continue;
        }
        let Some(previous_node) = nodes.get(node_index) else {
            continue;
        };
        dx_total += previous_node.bounds.center().x - bounds.center().x;
        dy_total += previous_node.bounds.center().y - bounds.center().y;
        anchor_count = anchor_count.saturating_add(1);
    }

    (anchor_count > 0).then_some((
        dx_total / anchor_count as f32,
        dy_total / anchor_count as f32,
    ))
}

/// Smooth edges that cross a dirty/clean subgraph boundary.
///
/// After incremental re-layout, edges with one endpoint in the dirty region and one in
/// the clean region may have intermediate waypoints that create visual kinks. This pass
/// applies a gentle Laplacian smoothing to interior waypoints of boundary edges, pulling
/// each interior point toward the midpoint of its neighbors to reduce angular
/// discontinuities while preserving the start and end anchors.
fn smooth_boundary_edges(
    ir: &MermaidDiagramIr,
    edges: &mut [LayoutEdgePath],
    dirty_node_indexes: &BTreeSet<usize>,
) {
    const SMOOTHING_FACTOR: f32 = 0.3;
    const SMOOTHING_PASSES: usize = 2;

    for edge_path in edges.iter_mut() {
        let Some(edge) = ir.edges.get(edge_path.edge_index) else {
            continue;
        };
        let source = endpoint_node_index(ir, edge.from);
        let target = endpoint_node_index(ir, edge.to);
        let (Some(src), Some(tgt)) = (source, target) else {
            continue;
        };
        let src_dirty = dirty_node_indexes.contains(&src);
        let tgt_dirty = dirty_node_indexes.contains(&tgt);
        // Only smooth boundary-crossing edges (one dirty, one clean).
        if src_dirty == tgt_dirty {
            continue;
        }
        if edge_path.points.len() < 3 {
            continue;
        }
        // Laplacian smoothing: pull interior points toward neighbor midpoints.
        for _ in 0..SMOOTHING_PASSES {
            let len = edge_path.points.len();
            for i in 1..len - 1 {
                let prev = edge_path.points[i - 1];
                let next = edge_path.points[i + 1];
                let mid_x = (prev.x + next.x) * 0.5;
                let mid_y = (prev.y + next.y) * 0.5;
                let pt = &mut edge_path.points[i];
                pt.x += (mid_x - pt.x) * SMOOTHING_FACTOR;
                pt.y += (mid_y - pt.y) * SMOOTHING_FACTOR;
            }
        }
    }
}

/// The edit list between two IRs, plus whether they share a dependency topology.
struct LayoutDiff {
    edits: Vec<LayoutEdit>,
    /// Equivalent to [`dependency_topology_equal`], but derived during the same walk that
    /// produces `edits`.
    ///
    /// The two used to run back to back over the same IR pair in
    /// `dirty_node_indexes_for_edits`, and `dependency_topology_equal` re-compared the very
    /// node ids and subgraph membership vectors the edit derivation had just compared — a
    /// second full pass of string and `Vec<String>` equality over every node, edge and
    /// subgraph. Topology ignores labels, titles, arrows, directions and spans, so it is a
    /// strict subset of what the edit walk already decides.
    topology_equal: bool,
}

fn derive_layout_diff(previous: &MermaidDiagramIr, current: &MermaidDiagramIr) -> LayoutDiff {
    let mut edits = Vec::new();
    let shared_nodes = previous.nodes.len().min(current.nodes.len());

    // A length change is itself a topology change, and it also means the trailing
    // added/removed loops below will fire.
    let mut topology_equal = previous.nodes.len() == current.nodes.len()
        && previous.edges.len() == current.edges.len()
        && previous.graph.subgraphs.len() == current.graph.subgraphs.len();

    // Walk the two node arrays in lockstep. `zip` already stops at the shorter side, which is
    // exactly `shared_nodes`, and it drops the per-iteration bounds checks that indexing both
    // arrays by a loop counter forced on every node of every pass.
    let previous_graph_nodes = previous.graph.nodes.as_slice();
    let current_graph_nodes = current.graph.nodes.as_slice();
    for (node_index, (left, right)) in previous.nodes.iter().zip(current.nodes.iter()).enumerate() {
        // Topology-bearing fields first, so that establishing a node changed ALSO settles its
        // contribution to `topology_equal` without a second comparison. Label text is checked
        // last because it is the one field that can change without changing topology.
        let changed = if left.id != right.id
            || previous_graph_nodes
                .get(node_index)
                .map(|node| &node.subgraphs)
                != current_graph_nodes
                    .get(node_index)
                    .map(|node| &node.subgraphs)
        {
            topology_equal = false;
            true
        } else {
            node_labels_differ(previous, left.label, current, right.label)
        };

        if changed {
            edits.push(LayoutEdit::NodeChanged { node_index });
        }
    }
    for node_index in shared_nodes..previous.nodes.len() {
        edits.push(LayoutEdit::NodeRemoved { node_index });
    }
    for node_index in shared_nodes..current.nodes.len() {
        edits.push(LayoutEdit::NodeAdded { node_index });
    }

    let shared_edges = previous.edges.len().min(current.edges.len());
    for (edge_index, (left, right)) in previous.edges.iter().zip(current.edges.iter()).enumerate() {
        // Endpoints are the topology-bearing half of an edge; arrow, label and span are not.
        let endpoints_differ = left.from != right.from || left.to != right.to;
        if endpoints_differ {
            topology_equal = false;
        }

        if endpoints_differ
            || left.arrow != right.arrow
            || left.label != right.label
            || left.span != right.span
        {
            edits.push(LayoutEdit::EdgeRemoved { edge_index });
            edits.push(LayoutEdit::EdgeAdded { edge_index });
        }
    }
    for edge_index in shared_edges..previous.edges.len() {
        edits.push(LayoutEdit::EdgeRemoved { edge_index });
    }
    for edge_index in shared_edges..current.edges.len() {
        edits.push(LayoutEdit::EdgeAdded { edge_index });
    }

    let shared_subgraphs = previous
        .graph
        .subgraphs
        .len()
        .min(current.graph.subgraphs.len());
    for (subgraph_index, (left, right)) in previous
        .graph
        .subgraphs
        .iter()
        .zip(current.graph.subgraphs.iter())
        .enumerate()
    {
        // Id, parent and members carry topology; title, direction and span do not.
        let topology_differs =
            left.id != right.id || left.parent != right.parent || left.members != right.members;
        if topology_differs {
            topology_equal = false;
        }

        if topology_differs
            || left.title != right.title
            || left.direction != right.direction
            || left.span != right.span
        {
            edits.push(LayoutEdit::SubgraphChanged { subgraph_index });
        }
    }
    for subgraph_index in shared_subgraphs..previous.graph.subgraphs.len() {
        edits.push(LayoutEdit::SubgraphChanged { subgraph_index });
    }
    for subgraph_index in shared_subgraphs..current.graph.subgraphs.len() {
        edits.push(LayoutEdit::SubgraphChanged { subgraph_index });
    }

    LayoutDiff {
        edits,
        topology_equal,
    }
}

/// Whether two nodes' labels differ, by id first and only then by resolved text.
///
/// Folds what used to be two separate clauses — an id comparison and a pair of
/// `Option`-unwrapping text lookups — into one self-contained decision. Two ids that differ are
/// already a change, so the text never has to be resolved; two absent labels are both empty and
/// cannot differ; and equal ids need only ONE id resolved against each arena instead of
/// unwrapping an `Option` per side. Keeping it in one function means the cheap-first ordering is
/// a property of this function rather than a hidden dependency on clause order at the call site.
fn node_labels_differ(
    previous: &MermaidDiagramIr,
    previous_label: Option<fm_core::IrLabelId>,
    current: &MermaidDiagramIr,
    current_label: Option<fm_core::IrLabelId>,
) -> bool {
    match (previous_label, current_label) {
        (None, None) => false,
        (Some(previous_id), Some(current_id)) if previous_id == current_id => {
            label_text_by_id(previous, previous_id) != label_text_by_id(current, current_id)
        }
        _ => true,
    }
}

/// Resolve a label id to its text, or `""` when the arena does not hold it.
fn label_text_by_id(ir: &MermaidDiagramIr, label_id: fm_core::IrLabelId) -> &str {
    ir.labels
        .get(label_id.0)
        .map_or("", |label| label.text.as_str())
}

/// Exact equality probe between the engine's cached IR snapshot and the incoming IR.
///
/// This replaces the former full-IR FNV fingerprint scan (`stable_layout_request_hash`): equality
/// short-circuits at the first difference and has no collision risk, so a memo hit now means the
/// inputs are truly identical rather than merely hash-equal. Sections are ordered cheapest-first
/// and most-frequently-edited-first (interactive edits are overwhelmingly label-text edits), so a
/// miss usually exits before the O(nodes + edges) tail. Destructuring keeps this in lockstep with
/// the IR: adding a field to `MermaidDiagramIr` fails compilation here until it is compared.
fn memo_ir_equal(previous: &MermaidDiagramIr, current: &MermaidDiagramIr) -> bool {
    let MermaidDiagramIr {
        diagram_type,
        direction,
        nodes,
        edges,
        ports,
        clusters,
        graph,
        labels,
        label_markup,
        constraints,
        style_refs,
        style_defs,
        meta,
        // Deck directives are consumed strictly after layout. Retitling a slide must re-render
        // without invalidating geometry or this layout memo.
        deck: _,
        sequence_meta,
        gantt_meta,
        xy_chart_meta,
        pie_meta,
        quadrant_meta,
        packet_meta,
        git_graph_meta,
        state_notes,
        diagnostics,
    } = previous;
    *diagram_type == current.diagram_type
        && *direction == current.direction
        && nodes.len() == current.nodes.len()
        && edges.len() == current.edges.len()
        && *labels == current.labels
        && *label_markup == current.label_markup
        && *nodes == current.nodes
        && *edges == current.edges
        && *ports == current.ports
        && *clusters == current.clusters
        && *constraints == current.constraints
        && *style_refs == current.style_refs
        && *style_defs == current.style_defs
        && *graph == current.graph
        && *meta == current.meta
        && *sequence_meta == current.sequence_meta
        && *gantt_meta == current.gantt_meta
        && *xy_chart_meta == current.xy_chart_meta
        && *pie_meta == current.pie_meta
        && *quadrant_meta == current.quadrant_meta
        && *packet_meta == current.packet_meta
        && *git_graph_meta == current.git_graph_meta
        && *state_notes == current.state_notes
        && *diagnostics == current.diagnostics
}

/// Exact topology equality between two IRs, covering precisely the fields the former
/// `dependency_graph_cache_key` FNV hash covered: node/edge/subgraph counts, node ids,
/// per-node subgraph memberships, edge endpoints, and subgraph id/parent/members. Everything
/// else (labels, spans, styles, meta) is intentionally NOT compared — label-only edits must
/// keep reusing the cached dependency graph. Short-circuits at the first difference and,
/// unlike the hash, cannot false-hit on a collision.
fn dependency_topology_equal(previous: &MermaidDiagramIr, current: &MermaidDiagramIr) -> bool {
    previous.nodes.len() == current.nodes.len()
        && previous.edges.len() == current.edges.len()
        && previous.graph.subgraphs.len() == current.graph.subgraphs.len()
        && previous.nodes.iter().zip(&current.nodes).enumerate().all(
            |(node_index, (previous_node, current_node))| {
                previous_node.id == current_node.id
                    && previous
                        .graph
                        .nodes
                        .get(node_index)
                        .map(|node| &node.subgraphs)
                        == current
                            .graph
                            .nodes
                            .get(node_index)
                            .map(|node| &node.subgraphs)
            },
        )
        && previous
            .edges
            .iter()
            .zip(&current.edges)
            .all(|(previous_edge, current_edge)| {
                previous_edge.from == current_edge.from && previous_edge.to == current_edge.to
            })
        && previous
            .graph
            .subgraphs
            .iter()
            .zip(&current.graph.subgraphs)
            .all(|(previous_subgraph, current_subgraph)| {
                previous_subgraph.id == current_subgraph.id
                    && previous_subgraph.parent == current_subgraph.parent
                    && previous_subgraph.members == current_subgraph.members
            })
}

fn hash_u64(hash: &mut u64, value: u64) {
    for byte in value.to_le_bytes() {
        *hash ^= u64::from(byte);
        *hash = hash.wrapping_mul(0x0100_0000_01b3);
    }
}

fn hash_str(hash: &mut u64, value: &str) {
    for byte in value.as_bytes() {
        *hash ^= u64::from(*byte);
        *hash = hash.wrapping_mul(0x0100_0000_01b3);
    }
}

/// Count DFS back-edges without full SCC decomposition.
fn count_back_edges(node_count: usize, edges: &[OrientedEdge]) -> usize {
    if node_count == 0 {
        return 0;
    }
    // CSR adjacency (flat targets + per-source offsets) instead of `vec![vec![]; n]` — one heap alloc
    // per source, i.e. ~one per node on a chain/tree. Count out-degrees, prefix-sum to offsets, fill;
    // the DFS reads each source's `[adj_start[n], adj_start[n+1])` segment in edge order. Byte-identical
    // (same neighbors in the same order → same back-edge count). No sort/dedup, so offsets suffice.
    let mut adj_start = vec![0_usize; node_count + 1];
    for edge in edges {
        if edge.source < node_count && edge.target < node_count {
            adj_start[edge.source + 1] += 1;
        }
    }
    for i in 1..adj_start.len() {
        adj_start[i] += adj_start[i - 1];
    }
    let mut adj_flat = vec![0_usize; adj_start[node_count]];
    {
        let mut cursor = adj_start.clone();
        for edge in edges {
            if edge.source < node_count && edge.target < node_count {
                adj_flat[cursor[edge.source]] = edge.target;
                cursor[edge.source] += 1;
            }
        }
    }
    let mut color = vec![0_u8; node_count];
    let mut back_edges = 0_usize;
    let mut stack: Vec<(usize, usize)> = Vec::new();
    for start in 0..node_count {
        if color[start] != 0 {
            continue;
        }
        stack.push((start, 0));
        color[start] = 1;
        while let Some((node, idx)) = stack.last_mut() {
            if *idx < adj_start[*node + 1] - adj_start[*node] {
                let neighbor = adj_flat[adj_start[*node] + *idx];
                *idx += 1;
                match color[neighbor] {
                    0 => {
                        color[neighbor] = 1;
                        stack.push((neighbor, 0));
                    }
                    1 => back_edges += 1,
                    _ => {}
                }
            } else {
                color[*node] = 2;
                stack.pop();
            }
        }
    }
    back_edges
}

#[derive(Debug, Clone, PartialEq)]
pub struct LayoutCycleCluster {
    pub head_node_index: usize,
    pub member_node_indexes: Vec<usize>,
    pub bounds: LayoutRect,
}

#[derive(Debug, Clone, PartialEq)]
pub struct LayoutClusterDivider {
    pub cluster_index: usize,
    pub start: LayoutPoint,
    pub end: LayoutPoint,
}

/// Centrality tier for semantic styling of nodes.
///
/// Nodes are classified into tiers based on their relative centrality scores
/// for use in visual emphasis and styling.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
pub enum CentralityTier {
    /// Node has high centrality (top 20% of scores).
    High,
    /// Node has medium centrality (middle 60% of scores).
    #[default]
    Medium,
    /// Node has low centrality (bottom 20% of scores).
    Low,
}

impl CentralityTier {
    /// Get the CSS class suffix for this centrality tier.
    #[must_use]
    pub const fn css_class_suffix(&self) -> &'static str {
        match self {
            Self::High => "high",
            Self::Medium => "medium",
            Self::Low => "low",
        }
    }
}

/// Centrality data for a single node.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NodeCentrality {
    /// Index of the node in the IR.
    pub node_index: usize,
    /// Quantized centrality score (higher = more central).
    pub score: u32,
    /// Tier classification based on score distribution.
    pub tier: CentralityTier,
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct LayoutExtensions {
    pub bands: Vec<LayoutBand>,
    pub axis_ticks: Vec<LayoutAxisTick>,
    /// Gantt has one unconditional bottom axis and an optional top axis.
    pub gantt_axis_rows: Vec<LayoutGanttAxisRow>,
    pub cluster_dividers: Vec<LayoutClusterDivider>,
    /// Activation bars for sequence diagrams — narrow rectangles on lifelines
    /// indicating when a participant is active (processing a message).
    pub activation_bars: Vec<LayoutActivationBar>,
    /// Sequence diagram notes — text boxes positioned near participant lifelines.
    pub sequence_notes: Vec<LayoutSequenceNote>,
    /// Sequence diagram interaction fragments (loop, alt, par, etc.).
    pub sequence_fragments: Vec<LayoutSequenceFragment>,
    /// Sequence lifecycle markers such as destroy crosses on lifelines.
    pub sequence_lifecycle_markers: Vec<LayoutSequenceLifecycleMarker>,
    /// Mirrored participant headers rendered at the bottom of sequence diagrams.
    pub sequence_mirror_headers: Vec<LayoutNodeBox>,
    /// Node centrality data for semantic styling (populated when FNX is enabled).
    pub node_centrality: Vec<NodeCentrality>,
    /// Gantt task-name placements. Empty for every other diagram type; when empty the renderer keeps
    /// its previous behaviour of centring the label on the bar.
    /// The gantt day axis, when this layout has one. `None` for every other diagram type.
    pub gantt_day_axis: Option<LayoutGanttDayAxis>,
    pub gantt_task_labels: Vec<LayoutGanttTaskLabel>,
    /// CONTINUATION boxes for packet-beta fields that cross a 32-bit row boundary. Empty for every
    /// other diagram type and for any packet whose fields are row-aligned; when empty the renderer
    /// draws each field as the single box its `LayoutNodeBox` describes.
    pub packet_field_continuations: Vec<LayoutPacketFieldContinuation>,
    /// `stateDiagram` note boxes, one per `note left/right of X` whose target resolves to a node.
    /// Empty for every other diagram type and for a state diagram that declares no notes, in which
    /// case nothing about the layout changes.
    pub state_notes: Vec<LayoutStateNote>,
}

/// Which side of its target state a [`LayoutStateNote`] was placed on.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StateNoteSide {
    Left,
    Right,
}

/// A `stateDiagram` note box, positioned beside the state it annotates.
///
/// `ir.state_notes` has been parsed and carried since the note syntax landed, but until bd-a6l4
/// nothing read it except `memo_ir_equal` — so `note right of X : text` was accepted, hashed for
/// incremental equality, and then dropped on the floor. This is the geometry that makes it visible.
///
/// Decided in layout, not the renderer, for the reason bd-h9gx established for gantt labels: a note
/// sits outside every node box `compute_bounds` measured, so only layout can grow the canvas to hold
/// it. A renderer-only placement lands outside the viewBox and is clipped.
#[derive(Debug, Clone, PartialEq)]
pub struct LayoutStateNote {
    /// Index into [`DiagramLayout::nodes`] for the state this note annotates.
    pub node_index: usize,
    /// Side the note was placed on, from `IrStateNote::position`.
    pub side: StateNoteSide,
    /// Note text; may be multi-line for the `note right of X … end note` form.
    pub text: String,
    pub bounds: LayoutRect,
    /// Leader line from the state's edge to the note's edge, drawn dashed like mermaid-js's.
    pub leader_start: LayoutPoint,
    pub leader_end: LayoutPoint,
}

/// One extra box for a packet-beta field that does not fit in the row its start bit belongs to.
///
/// A `LayoutNodeBox` is 1:1 with a node — `fm-render-svg` indexes layout nodes by `node_index` and
/// derives element ids from it — so a field spanning two rows cannot be expressed as two node
/// boxes. It is carried here instead, the same shape bd-h9gx used for gantt labels: geometry the
/// renderer must not re-derive, decided in layout because only layout can grow the diagram bounds
/// to hold it.
///
/// The field's FIRST row segment stays in `DiagramLayout::nodes`; this covers rows 2..n. The
/// incumbent does the same split — mermaid-js 11.15.0's `getNextFittingBlock` cuts a block at
/// `n * bitsPerRow` and carries the remainder to the next word, with both halves keeping the
/// original label (bd-8vr0).
#[derive(Debug, Clone, PartialEq)]
pub struct LayoutPacketFieldContinuation {
    /// Index into [`DiagramLayout::nodes`] / `ir.nodes` for the field this continues.
    pub node_index: usize,
    /// Which row of the field this is; 1 for the first continuation.
    pub segment: usize,
    pub bounds: LayoutRect,
}

