use shapes::{node_path, rounded_rect_path};

fn build_cluster_layer(layout: &DiagramLayout) -> RenderGroup {
    let mut layer =
        RenderGroup::new(Some(String::from("clusters"))).with_source(RenderSource::Diagram);

    for cluster in &layout.clusters {
        layer.children.push(RenderItem::Path(RenderPath {
            source: RenderSource::Cluster(cluster.cluster_index),
            commands: rounded_rect_path(cluster.bounds, 8.0),
            fill: Some(FillStyle::Solid {
                color: String::from("#e2e8f0"),
                opacity: 0.24,
            }),
            stroke: Some(StrokeStyle::solid("#94a3b8", 1.0)),
            marker_start: MarkerKind::None,
            marker_end: MarkerKind::None,
        }));
    }

    for divider in &layout.extensions.cluster_dividers {
        let mut stroke = StrokeStyle::solid("#64748b", 1.0);
        stroke.dash_array = vec![6.0, 4.0];
        layer.children.push(RenderItem::Path(RenderPath {
            source: RenderSource::Cluster(divider.cluster_index),
            commands: vec![
                PathCmd::MoveTo {
                    x: divider.start.x,
                    y: divider.start.y,
                },
                PathCmd::LineTo {
                    x: divider.end.x,
                    y: divider.end.y,
                },
            ],
            fill: None,
            stroke: Some(stroke),
            marker_start: MarkerKind::None,
            marker_end: MarkerKind::None,
        }));
    }

    if !layout.clusters.is_empty() {
        layer.clip = Some(RenderClip::Rect(RenderRect::from(layout.bounds)));
    }

    layer
}

fn build_edge_layer(ir: &MermaidDiagramIr, layout: &DiagramLayout) -> RenderGroup {
    let mut layer =
        RenderGroup::new(Some(String::from("edges"))).with_source(RenderSource::Diagram);

    for edge in &layout.edges {
        if edge.points.len() < 2 {
            continue;
        }

        let mut commands = Vec::with_capacity(edge.points.len() * 2);
        let n = edge.points.len();

        // Implement smoothing logic (Catmull-Rom to Cubic Bezier)
        commands.push(PathCmd::MoveTo {
            x: edge.points[0].x,
            y: edge.points[0].y,
        });

        if n == 2 {
            commands.push(PathCmd::LineTo {
                x: edge.points[1].x,
                y: edge.points[1].y,
            });
        } else {
            let t: f32 = 0.25; // Tension factor matching legacy renderer
            for i in 0..(n - 1) {
                let p_prev = if i == 0 {
                    edge.points[0]
                } else {
                    edge.points[i - 1]
                };
                let p_cur = edge.points[i];
                let p_next = edge.points[i + 1];
                let p_next2 = if i + 2 < n {
                    edge.points[i + 2]
                } else {
                    edge.points[n - 1]
                };

                commands.push(PathCmd::CubicTo {
                    c1x: (p_next.x - p_prev.x).mul_add(t, p_cur.x),
                    c1y: (p_next.y - p_prev.y).mul_add(t, p_cur.y),
                    c2x: (p_next2.x - p_cur.x).mul_add(-t, p_next.x),
                    c2y: (p_next2.y - p_cur.y).mul_add(-t, p_next.y),
                    x: p_next.x,
                    y: p_next.y,
                });
            }
        }

        let mut stroke = StrokeStyle::solid("#475569", 1.5);
        let mut marker_end = MarkerKind::None;
        let mut marker_start = MarkerKind::None;

        if let Some(ir_edge) = ir.edges.get(edge.edge_index) {
            // ⚠️ ER CARDINALITY IS DECIDED FIRST AND WINS, because an ER relationship carries an
            // `arrow` too and the arm below would put a flowchart arrowhead on it. mermaid draws no
            // arrowhead on a relationship line at all — the crow's-foot markers ARE its end
            // decoration (bd-dun16). A notation naming no shape on a side leaves that side bare.
            let er_forms = ir_edge
                .er_notation()
                .map(fm_core::parse_er_cardinality_forms);
            if let Some((left, right)) = er_forms {
                if let Some(left) = left {
                    marker_start = MarkerKind::er_pair(left).0;
                }
                if let Some(right) = right {
                    marker_end = MarkerKind::er_pair(right).1;
                }
            } else if edge.reversed {
                stroke.dash_array = vec![4.0, 4.0];
                stroke.color = String::from("#94a3b8");
                marker_end = MarkerKind::Open;
            } else {
                match ir_edge.arrow {
                    fm_core::ArrowType::Line => marker_end = MarkerKind::None,
                    fm_core::ArrowType::Arrow => marker_end = MarkerKind::Arrow,
                    fm_core::ArrowType::OpenArrow => marker_end = MarkerKind::Open,
                    fm_core::ArrowType::HalfArrowTop => marker_end = MarkerKind::HalfArrowTop,
                    fm_core::ArrowType::HalfArrowBottom => {
                        marker_end = MarkerKind::HalfArrowBottom;
                    }
                    fm_core::ArrowType::HalfArrowTopReverse => {
                        marker_start = MarkerKind::HalfArrowBottom;
                    }
                    fm_core::ArrowType::HalfArrowBottomReverse => {
                        marker_start = MarkerKind::HalfArrowTop;
                    }
                    fm_core::ArrowType::StickArrowTop => marker_end = MarkerKind::StickArrowTop,
                    fm_core::ArrowType::StickArrowBottom => {
                        marker_end = MarkerKind::StickArrowBottom;
                    }
                    fm_core::ArrowType::StickArrowTopReverse => {
                        marker_start = MarkerKind::StickArrowBottom;
                    }
                    fm_core::ArrowType::StickArrowBottomReverse => {
                        marker_start = MarkerKind::StickArrowTop;
                    }
                    fm_core::ArrowType::ThickArrow => {
                        stroke.width = 2.5;
                        marker_end = MarkerKind::ThickArrow;
                    }
                    fm_core::ArrowType::DottedArrow => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_end = MarkerKind::Arrow;
                    }
                    fm_core::ArrowType::DottedOpenArrow => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_end = MarkerKind::Open;
                    }
                    fm_core::ArrowType::DottedCross => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_end = MarkerKind::Cross;
                    }
                    fm_core::ArrowType::HalfArrowTopDotted => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_end = MarkerKind::HalfArrowTop;
                    }
                    fm_core::ArrowType::HalfArrowBottomDotted => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_end = MarkerKind::HalfArrowBottom;
                    }
                    fm_core::ArrowType::HalfArrowTopReverseDotted => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_start = MarkerKind::HalfArrowBottom;
                    }
                    fm_core::ArrowType::HalfArrowBottomReverseDotted => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_start = MarkerKind::HalfArrowTop;
                    }
                    fm_core::ArrowType::StickArrowTopDotted => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_end = MarkerKind::StickArrowTop;
                    }
                    fm_core::ArrowType::StickArrowBottomDotted => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_end = MarkerKind::StickArrowBottom;
                    }
                    fm_core::ArrowType::StickArrowTopReverseDotted => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_start = MarkerKind::StickArrowBottom;
                    }
                    fm_core::ArrowType::StickArrowBottomReverseDotted => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_start = MarkerKind::StickArrowTop;
                    }
                    fm_core::ArrowType::Circle => marker_end = MarkerKind::Circle,
                    fm_core::ArrowType::Cross => marker_end = MarkerKind::Cross,
                    // `o--o` / `x--x` mark BOTH ends (bd-zdpwd), exactly as `<-->` does below.
                    fm_core::ArrowType::CircleBoth => {
                        marker_start = MarkerKind::Circle;
                        marker_end = MarkerKind::Circle;
                    }
                    fm_core::ArrowType::CrossBoth => {
                        marker_start = MarkerKind::Cross;
                        marker_end = MarkerKind::Cross;
                    }
                    // `o==o` / `x==x` — same markers, THICK stroke (bd-lrl48). mermaid strips the
                    // leading marker before reading the stroke, so the weight comes from the `==`.
                    fm_core::ArrowType::ThickCircle => {
                        stroke.width = 2.5;
                        marker_end = MarkerKind::Circle;
                    }
                    fm_core::ArrowType::ThickCross => {
                        stroke.width = 2.5;
                        marker_end = MarkerKind::Cross;
                    }
                    fm_core::ArrowType::ThickCircleBoth => {
                        stroke.width = 2.5;
                        marker_start = MarkerKind::Circle;
                        marker_end = MarkerKind::Circle;
                    }
                    fm_core::ArrowType::ThickCrossBoth => {
                        stroke.width = 2.5;
                        marker_start = MarkerKind::Cross;
                        marker_end = MarkerKind::Cross;
                    }
                    fm_core::ArrowType::DottedCircle => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_end = MarkerKind::Circle;
                    }
                    fm_core::ArrowType::DottedCircleBoth => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_start = MarkerKind::Circle;
                        marker_end = MarkerKind::Circle;
                    }
                    fm_core::ArrowType::DottedCrossBoth => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_start = MarkerKind::Cross;
                        marker_end = MarkerKind::Cross;
                    }
                    fm_core::ArrowType::ThickLine => {
                        stroke.width = 2.5;
                        marker_end = MarkerKind::None;
                    }
                    fm_core::ArrowType::DottedLine => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_end = MarkerKind::None;
                    }
                    fm_core::ArrowType::DoubleArrow => {
                        marker_start = MarkerKind::Arrow;
                        marker_end = MarkerKind::Arrow;
                    }
                    fm_core::ArrowType::DoubleThickArrow => {
                        stroke.width = 2.5;
                        marker_start = MarkerKind::ThickArrow;
                        marker_end = MarkerKind::ThickArrow;
                    }
                    fm_core::ArrowType::DoubleDottedArrow => {
                        stroke.dash_array = vec![6.0, 4.0];
                        stroke.line_cap = LineCap::Round;
                        marker_start = MarkerKind::Arrow;
                        marker_end = MarkerKind::Arrow;
                    }
                    // UML aggregation/composition mark the OWNING end: the source for `o--`/`*--`,
                    // the target for the reversed `--o`/`--*`.
                    fm_core::ArrowType::Aggregation => {
                        marker_start = MarkerKind::DiamondOpen;
                    }
                    fm_core::ArrowType::AggregationReverse => {
                        marker_end = MarkerKind::DiamondOpen;
                    }
                    fm_core::ArrowType::Composition => {
                        marker_start = MarkerKind::Diamond;
                    }
                    fm_core::ArrowType::CompositionReverse => {
                        marker_end = MarkerKind::Diamond;
                    }
                    // Generalization marks the PARENT end: source for `<|--`, target for `--|>`.
                    fm_core::ArrowType::Inheritance => {
                        marker_start = MarkerKind::TriangleOpenStart;
                    }
                    fm_core::ArrowType::InheritanceReverse => {
                        marker_end = MarkerKind::TriangleOpen;
                    }
                }
            }
        }

        layer.children.push(RenderItem::Path(RenderPath {
            source: RenderSource::Edge(edge.edge_index),
            commands,
            fill: None,
            stroke: Some(stroke),
            marker_start,
            marker_end,
        }));
    }

    layer
}

fn build_node_layer(ir: &MermaidDiagramIr, layout: &DiagramLayout) -> RenderGroup {
    let mut layer =
        RenderGroup::new(Some(String::from("nodes"))).with_source(RenderSource::Diagram);

    for node_box in &layout.nodes {
        let shape = ir
            .nodes
            .get(node_box.node_index)
            .map_or(fm_core::NodeShape::Rect, |node| node.shape);

        layer.children.push(RenderItem::Path(RenderPath {
            source: RenderSource::Node(node_box.node_index),
            commands: node_path(node_box.bounds, shape),
            fill: Some(FillStyle::Solid {
                color: String::from("#ffffff"),
                opacity: 1.0,
            }),
            stroke: Some(StrokeStyle::solid("#94a3b8", 1.5)),
            marker_start: MarkerKind::None,
            marker_end: MarkerKind::None,
        }));
    }

    for node_box in &layout.extensions.sequence_mirror_headers {
        let shape = ir
            .nodes
            .get(node_box.node_index)
            .map_or(fm_core::NodeShape::Rect, |node| node.shape);

        layer.children.push(RenderItem::Path(RenderPath {
            source: RenderSource::Node(node_box.node_index),
            commands: node_path(node_box.bounds, shape),
            fill: Some(FillStyle::Solid {
                color: String::from("#ffffff"),
                opacity: 1.0,
            }),
            stroke: Some(StrokeStyle::solid("#94a3b8", 1.5)),
            marker_start: MarkerKind::None,
            marker_end: MarkerKind::None,
        }));
    }

    layer
}

fn build_label_layer(ir: &MermaidDiagramIr, layout: &DiagramLayout) -> RenderGroup {
    let mut layer =
        RenderGroup::new(Some(String::from("labels"))).with_source(RenderSource::Diagram);

    for node_box in &layout.nodes {
        let Some(node) = ir.nodes.get(node_box.node_index) else {
            continue;
        };
        let label_text = display_node_label(ir, node);
        if label_text.is_empty() {
            continue;
        }

        layer.children.push(RenderItem::Text(RenderText {
            source: RenderSource::Node(node_box.node_index),
            text: label_text,
            x: node_box.bounds.x + (node_box.bounds.width / 2.0),
            y: node_box.bounds.y + (node_box.bounds.height / 2.0),
            font_size: 14.0,
            align: TextAlign::Middle,
            baseline: TextBaseline::Middle,
            fill: FillStyle::Solid {
                color: String::from("#0f172a"),
                opacity: 1.0,
            },
        }));
    }

    for node_box in &layout.extensions.sequence_mirror_headers {
        let Some(node) = ir.nodes.get(node_box.node_index) else {
            continue;
        };
        let label_text = display_node_label(ir, node);
        if label_text.is_empty() {
            continue;
        }

        layer.children.push(RenderItem::Text(RenderText {
            source: RenderSource::Node(node_box.node_index),
            text: label_text,
            x: node_box.bounds.x + (node_box.bounds.width / 2.0),
            y: node_box.bounds.y + (node_box.bounds.height / 2.0),
            font_size: 14.0,
            align: TextAlign::Middle,
            baseline: TextBaseline::Middle,
            fill: FillStyle::Solid {
                color: String::from("#0f172a"),
                opacity: 1.0,
            },
        }));
    }

    for edge in &layout.edges {
        let Some(label) = ir
            .edges
            .get(edge.edge_index)
            .and_then(|edge_ir| edge_ir.label)
            .and_then(|label_id| ir.labels.get(label_id.0))
        else {
            continue;
        };

        let midpoint = edge_label_position(edge);
        layer.children.push(RenderItem::Text(RenderText {
            source: RenderSource::Edge(edge.edge_index),
            text: label.text.clone(),
            x: midpoint.x,
            y: midpoint.y,
            font_size: 12.0,
            align: TextAlign::Middle,
            baseline: TextBaseline::Middle,
            fill: FillStyle::Solid {
                color: String::from("#334155"),
                opacity: 1.0,
            },
        }));
    }

    for cluster in &layout.clusters {
        let Some(title) = ir
            .clusters
            .get(cluster.cluster_index)
            .and_then(|cluster_ir| cluster_ir.title)
            .and_then(|label_id| ir.labels.get(label_id.0))
        else {
            continue;
        };

        layer.children.push(RenderItem::Text(RenderText {
            source: RenderSource::Cluster(cluster.cluster_index),
            text: title.text.clone(),
            x: cluster.bounds.x + 10.0,
            y: cluster.bounds.y + 8.0,
            font_size: 12.0,
            align: TextAlign::Start,
            baseline: TextBaseline::Top,
            fill: FillStyle::Solid {
                color: String::from("#64748b"),
                opacity: 1.0,
            },
        }));
    }

    layer
}

fn edge_label_position(edge_path: &LayoutEdgePath) -> LayoutPoint {
    if edge_path.points.len() == 4 {
        let p1 = &edge_path.points[1];
        let p2 = &edge_path.points[2];
        LayoutPoint {
            x: f32::midpoint(p1.x, p2.x),
            y: f32::midpoint(p1.y, p2.y),
        }
    } else if edge_path.points.len() == 2 {
        let p1 = &edge_path.points[0];
        let p2 = &edge_path.points[1];
        LayoutPoint {
            x: f32::midpoint(p1.x, p2.x),
            y: f32::midpoint(p1.y, p2.y),
        }
    } else if edge_path.points.is_empty() {
        LayoutPoint { x: 0.0, y: 0.0 }
    } else {
        let midpoint_index = edge_path.points.len() / 2;
        edge_path.points[midpoint_index]
    }
}

#[must_use]
pub fn layout(ir: &MermaidDiagramIr, algorithm: LayoutAlgorithm) -> LayoutStats {
    layout_diagram_traced_with_algorithm(ir, algorithm)
        .layout
        .stats
}

#[must_use]
pub fn layout_diagram(ir: &MermaidDiagramIr) -> DiagramLayout {
    Arc::unwrap_or_clone(layout_diagram_traced(ir).layout)
}

#[must_use]
pub fn layout_diagram_with_cycle_strategy(
    ir: &MermaidDiagramIr,
    cycle_strategy: CycleStrategy,
) -> DiagramLayout {
    Arc::unwrap_or_clone(layout_diagram_traced_with_cycle_strategy(ir, cycle_strategy).layout)
}

#[must_use]
pub fn layout_diagram_with_config(ir: &MermaidDiagramIr, config: LayoutConfig) -> DiagramLayout {
    Arc::unwrap_or_clone(
        layout_diagram_traced_with_config(ir, LayoutAlgorithm::Auto, config).layout,
    )
}

#[must_use]
pub fn layout_diagram_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    layout_diagram_traced_with_algorithm_and_cycle_strategy(
        ir,
        LayoutAlgorithm::Auto,
        default_cycle_strategy(),
    )
}

#[must_use]
pub fn layout_diagram_traced_with_cycle_strategy(
    ir: &MermaidDiagramIr,
    cycle_strategy: CycleStrategy,
) -> TracedLayout {
    layout_diagram_traced_with_algorithm_and_cycle_strategy(
        ir,
        LayoutAlgorithm::Auto,
        cycle_strategy,
    )
}

#[must_use]
pub fn layout_diagram_traced_with_algorithm(
    ir: &MermaidDiagramIr,
    algorithm: LayoutAlgorithm,
) -> TracedLayout {
    layout_diagram_traced_with_algorithm_and_cycle_strategy(ir, algorithm, default_cycle_strategy())
}

#[must_use]
pub fn layout_diagram_traced_with_algorithm_and_guardrails(
    ir: &MermaidDiagramIr,
    algorithm: LayoutAlgorithm,
    guardrails: LayoutGuardrails,
) -> TracedLayout {
    layout_diagram_traced_with_config_and_guardrails(
        ir,
        algorithm,
        LayoutConfig {
            cycle_strategy: default_cycle_strategy(),
            ..LayoutConfig::default()
        },
        guardrails,
    )
}

#[must_use]
pub fn layout_diagram_traced_with_algorithm_and_cycle_strategy(
    ir: &MermaidDiagramIr,
    algorithm: LayoutAlgorithm,
    cycle_strategy: CycleStrategy,
) -> TracedLayout {
    layout_diagram_traced_with_config(
        ir,
        algorithm,
        LayoutConfig {
            cycle_strategy,
            ..LayoutConfig::default()
        },
    )
}

#[must_use]
pub fn layout_diagram_traced_with_config(
    ir: &MermaidDiagramIr,
    algorithm: LayoutAlgorithm,
    config: LayoutConfig,
) -> TracedLayout {
    layout_diagram_traced_with_config_and_guardrails(
        ir,
        algorithm,
        config,
        LayoutGuardrails::default(),
    )
}

#[must_use]
pub fn layout_diagram_traced_with_config_and_guardrails(
    ir: &MermaidDiagramIr,
    algorithm: LayoutAlgorithm,
    config: LayoutConfig,
    guardrails: LayoutGuardrails,
) -> TracedLayout {
    let start = Instant::now();
    let mut traced =
        compute_traced_layout_with_config_and_guardrails(ir, algorithm, config, guardrails);
    let recompute_duration_us = saturating_elapsed_micros(start.elapsed());
    traced.trace.incremental = IncrementalRecomputeTrace {
        query_type: "layout_full_recompute",
        cache_hit: false,
        recomputed_nodes: ir.nodes.len(),
        total_nodes: ir.nodes.len(),
        recompute_duration_us,
    };
    debug!(
        query_type = traced.trace.incremental.query_type,
        cache_hit = traced.trace.incremental.cache_hit,
        recomputed_nodes = traced.trace.incremental.recomputed_nodes,
        total_nodes = traced.trace.incremental.total_nodes,
        recompute_duration_us,
        "incremental.recompute"
    );
    traced
}

#[must_use]
pub fn layout_diagram_incremental_traced_with_config_and_guardrails(
    session: &SharedIncrementalLayoutSession,
    ir: &MermaidDiagramIr,
    algorithm: LayoutAlgorithm,
    config: LayoutConfig,
    guardrails: LayoutGuardrails,
) -> IncrementalTracedLayout {
    let session_guard = ActiveIncrementalSessionGuard::install(Rc::clone(session));
    ACTIVE_INCREMENTAL_STATE.with(|slot| {
        if let Some(state) = slot.borrow_mut().as_mut() {
            state.begin_pass();
        }
    });
    let traced =
        layout_diagram_traced_with_config_and_guardrails(ir, algorithm, config, guardrails);
    let incremental = session_guard.finish().current_summary;
    IncrementalTracedLayout {
        traced,
        incremental,
    }
}

fn compute_traced_layout_with_config_and_guardrails(
    ir: &MermaidDiagramIr,
    algorithm: LayoutAlgorithm,
    config: LayoutConfig,
    guardrails: LayoutGuardrails,
) -> TracedLayout {
    track_dependency_graph_query(ir);
    let dispatch = dispatch_layout_algorithm_with_config(ir, algorithm, &config);
    let guard = evaluate_layout_guardrails(ir, dispatch.selected, guardrails);
    let mut guarded_dispatch = dispatch;
    guarded_dispatch.selected = guard.selected_algorithm;
    if guard.fallback_applied {
        guarded_dispatch.reason = guard.reason;
    }

    // Captured before `config` is moved into the dispatch arms; a caller that supplied custom
    // `font_metrics` must have its notes measured with them, not with the default preset.
    let state_note_metrics = matches!(ir.diagram_type, DiagramType::State | DiagramType::Class)
        .then(|| {
            config
                .font_metrics
                .clone()
                .unwrap_or_else(fm_core::FontMetrics::default_metrics)
        });

    let mut traced = match guarded_dispatch.selected {
        LayoutAlgorithm::Sugiyama | LayoutAlgorithm::Auto => {
            layout_diagram_sugiyama_traced_with_config(ir, config)
        }
        LayoutAlgorithm::Force => layout_diagram_force_traced(ir),
        LayoutAlgorithm::Tree => layout_diagram_tree_traced(ir),
        LayoutAlgorithm::Radial => layout_diagram_radial_traced(ir),
        LayoutAlgorithm::Timeline => layout_diagram_timeline_traced(ir),
        LayoutAlgorithm::Gantt => layout_diagram_gantt_traced(ir),
        LayoutAlgorithm::XyChart => layout_diagram_xychart_traced(ir),
        LayoutAlgorithm::Sankey => layout_diagram_sankey_traced(ir),
        LayoutAlgorithm::Kanban => layout_diagram_kanban_traced(ir),
        LayoutAlgorithm::Grid => layout_diagram_grid_traced(ir),
        LayoutAlgorithm::Packet => layout_diagram_packet_traced(ir),
        LayoutAlgorithm::Sequence => layout_diagram_sequence_traced(ir),
        LayoutAlgorithm::Pie => layout_diagram_pie_traced(ir),
        LayoutAlgorithm::Quadrant => layout_diagram_quadrant_traced(ir),
        LayoutAlgorithm::GitGraph => layout_diagram_gitgraph_traced(ir),
        LayoutAlgorithm::Architecture => layout_diagram_architecture_traced(ir),
    };
    // State notes are attached HERE, after the dispatch match rather than inside one algorithm, for
    // two reasons: a state diagram can land on Sugiyama, Force, Tree or Radial depending on config
    // and guardrails, and the placement only needs final node boxes, which every arm has produced by
    // now. `build_state_note_geometry` returns empty for every non-state diagram and for a state
    // diagram with no notes, so this is a no-op — not merely a cheap one — everywhere else (bd-a6l4).
    if let Some(metrics) = state_note_metrics.filter(|_| !ir.state_notes.is_empty()) {
        let layout = Arc::make_mut(&mut traced.layout);
        let notes = build_state_note_geometry(ir, &layout.nodes, &metrics);
        layout.extensions.state_notes = notes;
        extend_bounds_for_state_notes(layout);
    }
    traced.trace.dispatch = guarded_dispatch;
    traced.trace.guard = guard;
    traced.trace.snapshots.insert(
        0,
        LayoutStageSnapshot {
            stage: "dispatch",
            reversed_edges: 0,
            crossing_count: 0,
            node_count: ir.nodes.len(),
            edge_count: ir.edges.len(),
        },
    );
    let phase_iterations = traced.trace.snapshots.len();
    // Freshly built by the dispatch match (refcount 1) ⇒ clone-free `make_mut`.
    Arc::make_mut(&mut traced.layout).stats.phase_iterations = phase_iterations;
    traced
}

impl IncrementalLayoutEngine {
    #[must_use]
    pub fn layout_diagram_traced_with_config_and_guardrails(
        &mut self,
        ir: &MermaidDiagramIr,
        algorithm: LayoutAlgorithm,
        config: LayoutConfig,
        guardrails: LayoutGuardrails,
    ) -> TracedLayout {
        let start = Instant::now();
        let key = layout_memo_key(algorithm, &config, guardrails);

        if let Some(cached) = &self.cached
            && cached.key == key
            && memo_ir_equal(&cached.ir, ir)
        {
            let mut traced = cached.traced.clone();
            let recompute_duration_us = saturating_elapsed_micros(start.elapsed());
            traced.trace.incremental = IncrementalRecomputeTrace {
                query_type: "layout_memoized_reuse",
                cache_hit: true,
                recomputed_nodes: 0,
                total_nodes: ir.nodes.len(),
                recompute_duration_us,
            };
            debug!(
                query_type = traced.trace.incremental.query_type,
                cache_hit = traced.trace.incremental.cache_hit,
                recomputed_nodes = traced.trace.incremental.recomputed_nodes,
                total_nodes = traced.trace.incremental.total_nodes,
                recompute_duration_us,
                "incremental.recompute"
            );
            return traced;
        }

        trace!(algorithm = algorithm.as_str(), "incremental.cache_miss");
        let mut incremental_state = IncrementalCacheState {
            graph_metrics_cache: self.graph_metrics_cache.take(),
            // Move, don't clone: nothing reads `self.node_size_cache` while the pass runs (all
            // in-pass access goes through the installed thread-local state), and every exit path
            // below writes the state's map back onto `self`.
            node_size_cache: std::mem::take(&mut self.node_size_cache),
            dependency_graph_cache: self.dependency_graph_cache.clone(),
            current_summary: IncrementalLayoutSummary::default(),
            pass_snapshot: None,
        };
        incremental_state.begin_pass();
        let state_guard = ActiveIncrementalStateGuard::install(incremental_state);
        if let Some(mut traced) =
            self.try_incremental_subgraph_relayout(ir, algorithm, &config, guardrails, key)
        {
            let selective_recomputed_nodes = traced.trace.incremental.recomputed_nodes.max(1);
            let mut incremental_state = state_guard.finish();
            let snapshot = incremental_state
                .pass_snapshot
                .take()
                .unwrap_or_else(|| Arc::new(ir.clone()));
            let recompute_duration_us = saturating_elapsed_micros(start.elapsed());

            self.graph_metrics_cache = incremental_state.graph_metrics_cache;
            self.node_size_cache = incremental_state.node_size_cache;
            self.dependency_graph_cache = incremental_state.dependency_graph_cache;
            traced.trace.incremental = IncrementalRecomputeTrace {
                // Preserve the inner path's query_type: the size-stable fast path reports a
                // distinct marker so tests and diagnostics can verify it actually fired.
                query_type: traced.trace.incremental.query_type,
                cache_hit: false,
                recomputed_nodes: selective_recomputed_nodes,
                total_nodes: incremental_state
                    .current_summary
                    .total_nodes
                    .max(ir.nodes.len()),
                recompute_duration_us,
            };
            debug!(
                query_type = traced.trace.incremental.query_type,
                cache_hit = traced.trace.incremental.cache_hit,
                recomputed_nodes = traced.trace.incremental.recomputed_nodes,
                total_nodes = traced.trace.incremental.total_nodes,
                recompute_duration_us,
                "incremental.recompute"
            );
            self.cached = Some(CachedTracedLayout {
                key,
                ir: snapshot,
                traced: traced.clone(),
            });
            return traced;
        }

        let mut traced =
            compute_traced_layout_with_config_and_guardrails(ir, algorithm, config, guardrails);
        let mut incremental_state = state_guard.finish();
        let snapshot = incremental_state
            .pass_snapshot
            .take()
            .unwrap_or_else(|| Arc::new(ir.clone()));

        let recompute_duration_us = saturating_elapsed_micros(start.elapsed());

        self.graph_metrics_cache = incremental_state.graph_metrics_cache;
        self.node_size_cache = incremental_state.node_size_cache;
        self.dependency_graph_cache = incremental_state.dependency_graph_cache;
        traced.trace.incremental = IncrementalRecomputeTrace {
            query_type: if incremental_state.current_summary.cache_hits > 0 {
                "layout_full_recompute_with_query_reuse"
            } else {
                "layout_full_recompute"
            },
            cache_hit: false,
            recomputed_nodes: if incremental_state.current_summary.recomputed_nodes > 0 {
                incremental_state.current_summary.recomputed_nodes
            } else {
                ir.nodes.len()
            },
            total_nodes: incremental_state
                .current_summary
                .total_nodes
                .max(ir.nodes.len()),
            recompute_duration_us,
        };
        debug!(
            query_type = traced.trace.incremental.query_type,
            cache_hit = traced.trace.incremental.cache_hit,
            recomputed_nodes = traced.trace.incremental.recomputed_nodes,
            total_nodes = traced.trace.incremental.total_nodes,
            recompute_duration_us,
            "incremental.recompute"
        );
        self.cached = Some(CachedTracedLayout {
            key,
            ir: snapshot,
            traced: traced.clone(),
        });
        traced
    }

    pub fn clear(&mut self) {
        self.cached = None;
        self.graph_metrics_cache = None;
        self.node_size_cache.clear();
        self.dependency_graph_cache = None;
    }

    fn try_incremental_subgraph_relayout(
        &self,
        ir: &MermaidDiagramIr,
        algorithm: LayoutAlgorithm,
        config: &LayoutConfig,
        guardrails: LayoutGuardrails,
        key: LayoutMemoKey,
    ) -> Option<TracedLayout> {
        let cached_layout = self.cached.as_ref()?;
        let cached_graph = self.dependency_graph_cache.as_ref()?;
        if ir.nodes.len() < INCREMENTAL_DEPENDENCY_GRAPH_BYPASS_NODE_THRESHOLD {
            return None;
        }
        if ir.diagram_type != DiagramType::Flowchart {
            return None;
        }

        if ir.nodes.len() != cached_graph.ir.nodes.len() {
            return None;
        }

        let edits = derive_layout_diff(&cached_graph.ir, ir).edits;
        if edits.is_empty() {
            return None;
        }
        if edits.iter().any(|edit| {
            matches!(
                edit,
                LayoutEdit::NodeAdded { .. } | LayoutEdit::NodeRemoved { .. }
            )
        }) {
            return None;
        }

        // Label/style-only edits leave the dependency topology unchanged, so the cached
        // dependency graph can be reused and the dirty set derived directly from edits.
        let all_node_changes = edits
            .iter()
            .all(|e| matches!(e, LayoutEdit::NodeChanged { .. }));

        let metrics = config
            .font_metrics
            .clone()
            .unwrap_or_else(fm_core::FontMetrics::default_metrics);

        // Size-stable memo fast path (Adapton region memoization), checked BEFORE algorithm
        // dispatch and guardrail evaluation: when the config key is unchanged, the topology is
        // unchanged (label-text-only node edits), and every dirty node's freshly measured size
        // is bit-equal to its cached box, every downstream phase — dispatch, guardrail fallback
        // selection, and the full deterministic layout — is a pure function of inputs that have
        // not changed, so the cached geometry (and the cached dispatch/guard decisions carried
        // in its trace) is exactly what recomputing would produce. Serving it keeps size-stable
        // label edits cheap even on graphs large enough that guardrails re-route the pipeline
        // off Sugiyama, where the selective region relayout below is unavailable.
        if all_node_changes && cached_layout.key == key && !size_stable_fast_path_disabled() {
            let dirty_node_indexes: BTreeSet<usize> = edits
                .iter()
                .filter_map(|e| match e {
                    LayoutEdit::NodeChanged { node_index } => Some(*node_index),
                    _ => None,
                })
                .collect();
            let label_text_only_and_size_stable = !dirty_node_indexes.is_empty()
                && dirty_node_indexes.iter().all(|&node_index| {
                    match (
                        cached_graph.ir.nodes.get(node_index),
                        ir.nodes.get(node_index),
                        cached_layout.traced.layout.nodes.get(node_index),
                    ) {
                        (Some(previous), Some(node), Some(node_box)) => {
                            // NodeChanged also fires for id and subgraph-membership edits,
                            // which can move the node between regions and clusters; cached
                            // geometry only stays valid for label-TEXT-only changes.
                            previous.id == node.id
                                && cached_graph
                                    .ir
                                    .graph
                                    .nodes
                                    .get(node_index)
                                    .map(|graph_node| &graph_node.subgraphs)
                                    == ir
                                        .graph
                                        .nodes
                                        .get(node_index)
                                        .map(|graph_node| &graph_node.subgraphs)
                                && {
                                    let (width, height) = compute_node_size(ir, node, &metrics);
                                    width.to_bits() == node_box.bounds.width.to_bits()
                                        && height.to_bits() == node_box.bounds.height.to_bits()
                                }
                        }
                        _ => false,
                    }
                });
            if label_text_only_and_size_stable {
                let mut dirty = DirtySet::default();
                let mut recomputed_node_count = 0usize;
                for (region_id, region) in cached_graph.graph.regions() {
                    if !region.node_indexes.is_disjoint(&dirty_node_indexes) {
                        dirty.insert(*region_id);
                        recomputed_node_count += region.node_indexes.len();
                    }
                }
                if !dirty.is_empty() {
                    // Maintains the dependency cache and installs the shared per-pass IR
                    // snapshot exactly like the slow path, so cache freshness semantics are
                    // identical whichever path serves the request.
                    track_dependency_graph_query(ir);
                    let incremental_start = Instant::now();

                    let mut nodes = cached_layout.traced.layout.nodes.clone();
                    for (node_index, node_box) in nodes.iter_mut().enumerate() {
                        node_box.span = ir
                            .nodes
                            .get(node_index)
                            .map_or(Span::default(), |node| node.span_primary);
                    }
                    let dirty_regions: Vec<LayoutRect> = dirty
                        .regions
                        .iter()
                        .filter_map(|region_id| {
                            cached_graph.graph.regions().get(region_id).map(|region| {
                                layout_bounds_for_members(
                                    &region.node_indexes.iter().copied().collect::<Vec<_>>(),
                                    &nodes,
                                )
                                .unwrap_or(LayoutRect {
                                    x: 0.0,
                                    y: 0.0,
                                    width: 0.0,
                                    height: 0.0,
                                })
                            })
                        })
                        .collect();

                    // The cached trace already carries the dispatch and guard decisions
                    // computed for this same topology and config; reuse them verbatim.
                    let mut trace = cached_layout.traced.trace.clone();
                    // Same retention rule as the slow path below: keep the original
                    // full-layout phase snapshots plus exactly the latest incremental one.
                    trace
                        .snapshots
                        .retain(|snapshot| snapshot.stage != "incremental_subgraph_relayout");
                    push_snapshot(
                        &mut trace,
                        "incremental_subgraph_relayout",
                        ir.nodes.len(),
                        ir.edges.len(),
                        cached_layout.traced.layout.stats.reversed_edges,
                        cached_layout.traced.layout.stats.crossing_count,
                    );
                    let mut stats = cached_layout.traced.layout.stats;
                    stats.phase_iterations = trace.snapshots.len();

                    return Some(TracedLayout {
                        layout: Arc::new(DiagramLayout {
                            nodes,
                            clusters: cached_layout.traced.layout.clusters.clone(),
                            cycle_clusters: cached_layout.traced.layout.cycle_clusters.clone(),
                            edges: cached_layout.traced.layout.edges.clone(),
                            bounds: cached_layout.traced.layout.bounds,
                            stats,
                            extensions: cached_layout.traced.layout.extensions.clone(),
                            dirty_regions,
                        }),
                        trace: LayoutTrace {
                            incremental: IncrementalRecomputeTrace {
                                query_type: "layout_incremental_subgraph_relayout_size_stable",
                                cache_hit: false,
                                recomputed_nodes: recomputed_node_count,
                                total_nodes: ir.nodes.len(),
                                recompute_duration_us: saturating_elapsed_micros(
                                    incremental_start.elapsed(),
                                ),
                            },
                            ..trace
                        },
                    });
                }
            }
        }

        let dispatch = dispatch_layout_algorithm(ir, algorithm);
        let guard = evaluate_layout_guardrails(ir, dispatch.selected, guardrails);
        // A FORCED BUDGET disqualifies selective relayout too (bd-s6tkz), for the same reason a
        // fallback or a non-Sugiyama dispatch already does one line below: the result would not be
        // the layout this IR actually has.
        //
        // Under a budget the layout is ITERATION-LIMITED. Selective relayout seeds it from the
        // PREVIOUS positions while a full recompute seeds from scratch, and the cap stops either
        // from converging — so the two land in different places and the incremental one never
        // recovers. Measured on a 72-node dense flowchart after a single label edit: bounds
        // 17741x276 against 18515x178, a 774x98 difference with ALL 72 nodes moved, stable across
        // repeated passes. A COLD engine on the same edited IR matched the full recompute exactly,
        // which is what identifies the warm seed rather than the budget as the thing at fault.
        //
        // This repo's stated contract is that incremental "produces a visually identical (but
        // possibly translated) layout", and a sibling test asserts the two SVGs are byte-identical.
        // The engine, not the contract, was wrong. The divergence only ever appeared above the
        // guardrail threshold — the passing tests use 56 and 64 nodes and never cross it.
        if guard.fallback_applied
            || guard.selected_algorithm != LayoutAlgorithm::Sugiyama
            || guard.time_budget_exceeded
            || guard.iteration_budget_exceeded
            || guard.route_budget_exceeded
        {
            return None;
        }

        track_dependency_graph_query(ir);
        let incremental_start = Instant::now();
        let current_graph = if all_node_changes || dependency_topology_equal(&cached_graph.ir, ir) {
            Arc::clone(&cached_graph.graph)
        } else {
            Arc::new(LayoutDependencyGraph::from_ir(ir))
        };
        let dirty_node_indexes = if all_node_changes {
            edits
                .iter()
                .filter_map(|e| match e {
                    LayoutEdit::NodeChanged { node_index } => Some(*node_index),
                    _ => None,
                })
                .collect()
        } else {
            dirty_node_indexes_for_edits(&cached_graph.graph, &current_graph, &cached_graph.ir, ir)
        };
        if dirty_node_indexes.is_empty() {
            return None;
        }

        let mut dirty = DirtySet::default();
        let mut recomputed_node_count = 0usize;
        for (region_id, region) in current_graph.regions() {
            if !region.node_indexes.is_disjoint(&dirty_node_indexes) {
                dirty.insert(*region_id);
                recomputed_node_count += region.node_indexes.len();
            }
        }
        if dirty.is_empty() {
            return None;
        }
        // EVERY region dirty means there is no CLEAN region left to anchor against, and this path is
        // built entirely around having one: each dirty region is relaid locally and then translated
        // so that its centre lands back on its PREVIOUS bounds centre
        // (`previous_bounds.center() - local_bounds.center()`, below). That translation is what keeps
        // an incremental edit from shifting the untouched parts of the picture -- and it is only
        // meaningful when some part is actually untouched.
        //
        // With nothing stable to anchor to, every region pins freshly computed geometry onto stale
        // positions: a full recompute wearing an incremental hat, and one that produces a DIFFERENT
        // picture than recomputing would (bd-8pna). Measured on this bead's own fixture, 62 of 64
        // node boxes disagreed with a full recompute and the canvas came out 11920.0 tall against
        // 11733.5, anchored to the previous topology's extent.
        //
        // This is a whole-set property, not a tuned threshold: one clean region is enough to make the
        // anchoring meaningful, and zero is never enough. The single-edge-toggle edit that
        // `incremental_layout_engine_selectively_relayouts_large_topology_change_with_stable_nodes`
        // exercises dirties 1 of 2 regions and is provably identical to a full recompute, so it keeps
        // the incremental path; this bead's fixture dirties 30 of 30 and now takes the correct one.
        if dirty.regions.len() == current_graph.regions().len() {
            return None;
        }

        let node_sizes = compute_node_sizes(ir, &metrics);
        // The incremental path must resolve spacing the same way the full path does, or an edit would
        // silently re-lay part of the diagram at the default gaps.
        let spacing = spacing_with_source_hints(config.spacing, ir);
        let mut nodes = cached_layout.traced.layout.nodes.clone();
        let highlighted_edge_indexes: BTreeSet<_> = cached_layout
            .traced
            .layout
            .edges
            .iter()
            .filter(|edge| edge.reversed)
            .map(|edge| edge.edge_index)
            .collect();

        for region_id in &dirty.regions {
            let Some(region) = current_graph.regions().get(region_id) else {
                continue;
            };
            let dirty_members: Vec<_> = region.node_indexes.iter().copied().collect();
            let dirty_member_set = region.node_indexes.clone();
            if dirty_members.is_empty() {
                continue;
            }
            let local_members = incremental_region_members(ir, &region.node_indexes);
            let Some(previous_bounds) = layout_bounds_for_members(&dirty_members, &nodes) else {
                continue;
            };
            let Some(local_layout) = build_subgraph_local_layout(
                ir,
                &local_members,
                ir.direction,
                &node_sizes,
                &nodes,
                spacing,
            ) else {
                continue;
            };
            let Some(local_bounds) = layout_bounds_for_entries(&local_layout) else {
                continue;
            };
            let dx = previous_bounds.center().x - local_bounds.center().x;
            let dy = previous_bounds.center().y - local_bounds.center().y;
            let local_entries: BTreeMap<_, _> = local_layout
                .into_iter()
                .map(|(node_index, bounds, rank, order)| (node_index, (bounds, rank, order)))
                .collect();
            let (dx, dy) = if dirty_members.len() <= 3 {
                // For very small dirty sets, centroid anchoring is sufficient
                // and avoids the expensive overlap alignment computation.
                (dx, dy)
            } else {
                incremental_overlap_alignment(&dirty_member_set, &local_entries, &nodes)
                    .unwrap_or((dx, dy))
            };
            for node_index in dirty_members {
                let Some((bounds, rank, order)) = local_entries.get(&node_index).copied() else {
                    continue;
                };
                let Some(node_box) = nodes.get_mut(node_index) else {
                    continue;
                };
                node_box.bounds.x = bounds.x + dx;
                node_box.bounds.y = bounds.y + dy;
                node_box.bounds.width = bounds.width;
                node_box.bounds.height = bounds.height;
                node_box.rank = rank;
                node_box.order = order;
                node_box.span = ir
                    .nodes
                    .get(node_index)
                    .map_or(Span::default(), |node| node.span_primary);
            }
        }

        for (node_index, node_box) in nodes.iter_mut().enumerate() {
            node_box.span = ir
                .nodes
                .get(node_index)
                .map_or(Span::default(), |node| node.span_primary);
        }

        let mut edges = build_edge_paths(
            ir,
            &nodes,
            &highlighted_edge_indexes,
            // Resolved the same way as the full path; wiring only one would make an edited
            // diagram re-route part of itself with the caller's default instead of the source's
            // request.
            edge_routing_with_source_hints(config.edge_routing, ir),
        );
        smooth_boundary_edges(ir, &mut edges, &dirty_node_indexes);
        bundle_parallel_edges(ir, &mut edges);
        let clusters = build_cluster_boxes(ir, &nodes, spacing, &metrics);
        let cluster_dividers = build_state_cluster_dividers(ir, &nodes, &clusters);
        let cycle_clusters = cached_layout.traced.layout.cycle_clusters.clone();
        let collapsed_count = cycle_clusters.len();
        let bounds = compute_bounds(&nodes, &clusters, &edges, spacing);
        let (total_edge_length, reversed_edge_total_length) = compute_edge_length_metrics(&edges);

        let mut trace = cached_layout.traced.trace.clone();
        trace.dispatch = dispatch;
        trace.guard = guard;
        // The cached trace is re-cloned and re-stored on every incremental pass; without this
        // retain, each pass appends one more "incremental_subgraph_relayout" snapshot FOREVER —
        // unbounded memory growth in long-lived engines (fm-wasm holds one per app) and an
        // O(edit-count) clone tax on every subsequent edit. Keep the original full-layout phase
        // snapshots and exactly the latest incremental one.
        trace
            .snapshots
            .retain(|snapshot| snapshot.stage != "incremental_subgraph_relayout");
        push_snapshot(
            &mut trace,
            "incremental_subgraph_relayout",
            ir.nodes.len(),
            ir.edges.len(),
            cached_layout.traced.layout.stats.reversed_edges,
            cached_layout.traced.layout.stats.crossing_count,
        );

        let stats = LayoutStats {
            node_count: ir.nodes.len(),
            edge_count: ir.edges.len(),
            crossing_count: cached_layout.traced.layout.stats.crossing_count,
            crossing_count_before_refinement: cached_layout
                .traced
                .layout
                .stats
                .crossing_count_before_refinement,
            reversed_edges: cached_layout.traced.layout.stats.reversed_edges,
            cycle_count: cached_layout.traced.layout.stats.cycle_count,
            cycle_node_count: cached_layout.traced.layout.stats.cycle_node_count,
            max_cycle_size: cached_layout.traced.layout.stats.max_cycle_size,
            collapsed_clusters: collapsed_count,
            reversed_edge_total_length,
            total_edge_length,
            phase_iterations: trace.snapshots.len(),
        };

        let dirty_regions: Vec<LayoutRect> = dirty
            .regions
            .iter()
            .filter_map(|region_id| {
                current_graph.regions().get(region_id).map(|region| {
                    layout_bounds_for_members(
                        &region.node_indexes.iter().copied().collect::<Vec<_>>(),
                        &nodes,
                    )
                    .unwrap_or(LayoutRect {
                        x: 0.0,
                        y: 0.0,
                        width: 0.0,
                        height: 0.0,
                    })
                })
            })
            .collect();

        Some(TracedLayout {
            layout: Arc::new(DiagramLayout {
                nodes,
                clusters,
                cycle_clusters,
                edges,
                bounds,
                stats,
                extensions: LayoutExtensions {
                    cluster_dividers,
                    ..LayoutExtensions::default()
                },
                dirty_regions,
            }),
            trace: LayoutTrace {
                incremental: IncrementalRecomputeTrace {
                    query_type: "layout_incremental_subgraph_relayout",
                    cache_hit: false,
                    recomputed_nodes: recomputed_node_count,
                    total_nodes: ir.nodes.len(),
                    recompute_duration_us: saturating_elapsed_micros(incremental_start.elapsed()),
                },
                ..trace
            },
        })
    }
}

fn layout_memo_key(
    algorithm: LayoutAlgorithm,
    config: &LayoutConfig,
    guardrails: LayoutGuardrails,
) -> LayoutMemoKey {
    let metrics = config
        .font_metrics
        .as_ref()
        .cloned()
        .unwrap_or_else(fm_core::FontMetrics::default_metrics);
    LayoutMemoKey {
        algorithm,
        cycle_strategy: config.cycle_strategy,
        collapse_cycle_clusters: config.collapse_cycle_clusters,
        fnx_enabled: config.fnx_enabled,
        edge_routing: config.edge_routing,
        constraint_solver: config.constraint_solver,
        constraint_solver_wall_clock_valve_ms: config.constraint_solver_wall_clock_valve_ms,
        node_spacing_bits: config.spacing.node_spacing.to_bits(),
        rank_spacing_bits: config.spacing.rank_spacing.to_bits(),
        cluster_padding_bits: config.spacing.cluster_padding.to_bits(),
        sequence_participant_gap_extra_bits: config
            .spacing
            .sequence_participant_gap_extra
            .to_bits(),
        sequence_min_message_gap_bits: config.spacing.sequence_min_message_gap.to_bits(),
        font_size_bits: metrics.font_size().to_bits(),
        avg_char_width_bits: metrics.avg_char_width().to_bits(),
        line_height_bits: metrics.line_height_px().to_bits(),
        max_layout_time_ms: guardrails.max_layout_time_ms,
        max_layout_iterations: guardrails.max_layout_iterations,
        max_route_ops: guardrails.max_route_ops,
    }
}

fn saturating_elapsed_micros(duration: std::time::Duration) -> u64 {
    duration.as_micros().min(u128::from(u64::MAX)) as u64
}

fn dispatch_layout_algorithm(ir: &MermaidDiagramIr, requested: LayoutAlgorithm) -> LayoutDispatch {
    dispatch_layout_algorithm_with_config(ir, requested, &LayoutConfig::default())
}

fn dispatch_layout_algorithm_with_config(
    ir: &MermaidDiagramIr,
    requested: LayoutAlgorithm,
    config: &LayoutConfig,
) -> LayoutDispatch {
    let dispatch = match requested {
        LayoutAlgorithm::Auto => preferred_layout_algorithm_with_config(ir, config),
        explicit => {
            if algorithm_available_for_diagram(ir.diagram_type, explicit) {
                LayoutDispatch {
                    requested,
                    selected: explicit,
                    capability_unavailable: false,
                    decision_mode: "explicit_request",
                    reason: "explicit_request_honored",
                    ..LayoutDispatch::default()
                }
            } else {
                let mut selected = preferred_layout_algorithm_with_config(ir, config);
                selected.requested = requested;
                selected.capability_unavailable = true;
                selected.decision_mode = "requested_capability_fallback";
                selected.reason = "requested_algorithm_capability_unavailable_for_diagram_type";
                selected
            }
        }
    };
    info!(
        event = "layout.dispatch",
        requested = dispatch.requested.as_str(),
        selected = dispatch.selected.as_str(),
        capability_unavailable = dispatch.capability_unavailable,
        decision_mode = dispatch.decision_mode,
        reason = dispatch.reason,
        selected_expected_loss_permille = dispatch.selected_expected_loss_permille,
        diagram_type = ir.diagram_type.as_str(),
        node_count = ir.nodes.len(),
        edge_count = ir.edges.len(),
        "layout.dispatch"
    );
    dispatch
}

/// Return a static reason string that explains *why* the auto-selector chose this algorithm.
fn auto_selection_reason(ir: &MermaidDiagramIr, selected: LayoutAlgorithm) -> &'static str {
    match ir.diagram_type {
        DiagramType::Mindmap => return "auto_diagram_type_mindmap",
        DiagramType::Timeline => return "auto_diagram_type_timeline",
        DiagramType::Gantt => return "auto_diagram_type_gantt",
        DiagramType::Pie => return "auto_diagram_type_pie",
        DiagramType::QuadrantChart => return "auto_diagram_type_quadrant",
        DiagramType::GitGraph => return "auto_diagram_type_gitgraph",
        DiagramType::PacketBeta => return "auto_diagram_type_packet",
        DiagramType::XyChart => return "auto_diagram_type_xychart",
        DiagramType::Sankey => return "auto_diagram_type_sankey",
        DiagramType::Journey | DiagramType::Kanban => return "auto_diagram_type_kanban",
        DiagramType::BlockBeta => return "auto_diagram_type_block_beta",
        DiagramType::ArchitectureBeta if selected == LayoutAlgorithm::Architecture => {
            return "auto_diagram_type_architecture";
        }
        DiagramType::Sequence => return "auto_diagram_type_sequence",
        _ => {}
    }
    match selected {
        LayoutAlgorithm::Tree => "auto_metrics_tree_like",
        LayoutAlgorithm::Force => {
            let metrics = GraphMetrics::from_ir(ir);
            if metrics.is_dense {
                "auto_metrics_dense_graph"
            } else {
                "auto_metrics_sparse_disconnected"
            }
        }
        _ => "auto_metrics_default_sugiyama",
    }
}

fn preferred_layout_algorithm_with_config(
    ir: &MermaidDiagramIr,
    config: &LayoutConfig,
) -> LayoutDispatch {
    let selected = match ir.diagram_type {
        DiagramType::Mindmap => LayoutAlgorithm::Radial,
        DiagramType::Timeline => LayoutAlgorithm::Timeline,
        DiagramType::Gantt => LayoutAlgorithm::Gantt,
        DiagramType::XyChart => LayoutAlgorithm::XyChart,
        DiagramType::Sankey => LayoutAlgorithm::Sankey,
        DiagramType::Journey | DiagramType::Kanban => LayoutAlgorithm::Kanban,
        DiagramType::BlockBeta => LayoutAlgorithm::Grid,
        DiagramType::Sequence => LayoutAlgorithm::Sequence,
        DiagramType::Pie => LayoutAlgorithm::Pie,
        DiagramType::QuadrantChart => LayoutAlgorithm::Quadrant,
        DiagramType::GitGraph => LayoutAlgorithm::GitGraph,
        DiagramType::PacketBeta => LayoutAlgorithm::Packet,
        // The specialization is conditional ON THE INPUT, not on the diagram type alone: the
        // direction-aware placement has nothing to honour when no edge declares a side, so an
        // architecture-beta diagram written without `a:R --> L:b` keeps falling through to the
        // general selector and its layout is byte-for-byte what it was before bd-zce4. Deciding
        // this here rather than inside the algorithm keeps the dispatch trace honest — the
        // recorded `selected` is the algorithm that actually ran.
        DiagramType::ArchitectureBeta if architecture_declares_a_side(ir) => {
            LayoutAlgorithm::Architecture
        }
        _ => return select_general_graph_algorithm_with_config(ir, config),
    };
    LayoutDispatch {
        requested: LayoutAlgorithm::Auto,
        selected,
        capability_unavailable: false,
        decision_mode: "diagram_type_specialized",
        reason: auto_selection_reason(ir, selected),
        ..LayoutDispatch::default()
    }
}

/// For general graph types (Flowchart, Class, State, ER, C4, Requirement, etc.),
/// analyze graph topology metrics to choose between Sugiyama, Tree, and Force.
fn select_general_graph_algorithm_with_config(
    ir: &MermaidDiagramIr,
    config: &LayoutConfig,
) -> LayoutDispatch {
    let metrics = GraphMetrics::from_ir(ir);

    // Trivial graphs: Sugiyama handles them efficiently.
    if metrics.node_count <= 2 {
        return LayoutDispatch {
            requested: LayoutAlgorithm::Auto,
            selected: LayoutAlgorithm::Sugiyama,
            capability_unavailable: false,
            decision_mode: "expected_loss_general_graph_v1",
            reason: "auto_metrics_default_sugiyama",
            posterior_tree_like_permille: 50,
            posterior_dense_graph_permille: 50,
            posterior_layered_permille: 900,
            selected_expected_loss_permille: 135,
            sugiyama_expected_loss_permille: 135,
            tree_expected_loss_permille: 540,
            force_expected_loss_permille: 610,
        };
    }

    let (tree_like, dense_graph, layered_general) = general_graph_posterior_permille(metrics);
    let sugiyama_loss = expected_loss_permille(
        ir,
        LayoutAlgorithm::Sugiyama,
        tree_like,
        dense_graph,
        layered_general,
    );
    let tree_loss = expected_loss_permille(
        ir,
        LayoutAlgorithm::Tree,
        tree_like,
        dense_graph,
        layered_general,
    );
    let force_loss = expected_loss_permille(
        ir,
        LayoutAlgorithm::Force,
        tree_like,
        dense_graph,
        layered_general,
    );
    let base_selected = select_min_loss_algorithm(sugiyama_loss, tree_loss, force_loss);

    let mut decision_mode = "expected_loss_general_graph_v1";
    let adjusted_sugiyama_loss = sugiyama_loss;
    let mut adjusted_tree_loss = tree_loss;
    let mut adjusted_force_loss = force_loss;

    if let Some(signals) = compute_fnx_layout_selection_signals(ir, config) {
        let tree_bonus = fnx_tree_loss_bonus_permille(metrics, signals);
        let force_bonus = fnx_force_loss_bonus_permille(metrics, signals);
        if tree_bonus > 0 || force_bonus > 0 {
            decision_mode = "expected_loss_general_graph_v2_fnx";
            adjusted_tree_loss = adjusted_tree_loss.saturating_sub(tree_bonus);
            adjusted_force_loss = adjusted_force_loss.saturating_sub(force_bonus);
        }
    }

    let selected = select_min_loss_algorithm(
        adjusted_sugiyama_loss,
        adjusted_tree_loss,
        adjusted_force_loss,
    );

    let selected_expected_loss_permille = match selected {
        LayoutAlgorithm::Tree => adjusted_tree_loss,
        LayoutAlgorithm::Force => adjusted_force_loss,
        _ => adjusted_sugiyama_loss,
    };
    let reason =
        if decision_mode == "expected_loss_general_graph_v2_fnx" && selected != base_selected {
            match selected {
                LayoutAlgorithm::Tree => "auto_fnx_hub_spoke_tree",
                LayoutAlgorithm::Force => "auto_fnx_fragmented_force",
                _ => auto_selection_reason(ir, selected),
            }
        } else {
            auto_selection_reason(ir, selected)
        };

    LayoutDispatch {
        requested: LayoutAlgorithm::Auto,
        selected,
        capability_unavailable: false,
        decision_mode,
        reason,
        selected_expected_loss_permille,
        posterior_tree_like_permille: tree_like,
        posterior_dense_graph_permille: dense_graph,
        posterior_layered_permille: layered_general,
        sugiyama_expected_loss_permille: adjusted_sugiyama_loss,
        tree_expected_loss_permille: adjusted_tree_loss,
        force_expected_loss_permille: adjusted_force_loss,
    }
}

fn select_min_loss_algorithm(
    sugiyama_loss: u32,
    tree_loss: u32,
    force_loss: u32,
) -> LayoutAlgorithm {
    [
        (LayoutAlgorithm::Sugiyama, sugiyama_loss),
        (LayoutAlgorithm::Tree, tree_loss),
        (LayoutAlgorithm::Force, force_loss),
    ]
    .into_iter()
    .min_by_key(|(algorithm, loss)| (*loss, algorithm.as_str()))
    .map_or(LayoutAlgorithm::Sugiyama, |(algorithm, _)| algorithm)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
struct FnxLayoutSelectionSignals {
    component_count: usize,
    articulation_point_count: usize,
    bridge_count: usize,
    peak_degree_centrality_permille: u16,
}

#[cfg(all(feature = "fnx-integration", not(target_arch = "wasm32")))]
fn compute_fnx_layout_selection_signals(
    ir: &MermaidDiagramIr,
    config: &LayoutConfig,
) -> Option<FnxLayoutSelectionSignals> {
    if !config.fnx_enabled || ir.nodes.is_empty() {
        return None;
    }

    let (graph, _) = ir_to_graph(ir);
    let component_count = connected_components(&graph).components.len();
    let (articulation_point_count, bridge_count) = if component_count <= 1 {
        (
            articulation_points(&graph).nodes.len(),
            bridges(&graph).edges.len(),
        )
    } else {
        (0, 0)
    };
    let peak_degree_centrality_permille = compute_centrality_scores(ir)
        .degree
        .values()
        .map(|score| score.raw() / 10)
        .max()
        .unwrap_or(0) as u16;

    Some(FnxLayoutSelectionSignals {
        component_count,
        articulation_point_count,
        bridge_count,
        peak_degree_centrality_permille,
    })
}

#[cfg(not(all(feature = "fnx-integration", not(target_arch = "wasm32"))))]
fn compute_fnx_layout_selection_signals(
    _: &MermaidDiagramIr,
    _: &LayoutConfig,
) -> Option<FnxLayoutSelectionSignals> {
    None
}

fn fnx_tree_loss_bonus_permille(metrics: GraphMetrics, signals: FnxLayoutSelectionSignals) -> u32 {
    let is_hub_spoke_candidate = metrics.node_count >= 8
        && metrics.back_edge_count == 0
        && metrics.root_count == 1
        && metrics.edge_to_node_ratio <= 1.25
        && signals.peak_degree_centrality_permille >= 550
        && signals.bridge_count >= 3;
    if is_hub_spoke_candidate { 450 } else { 0 }
}

fn fnx_force_loss_bonus_permille(metrics: GraphMetrics, signals: FnxLayoutSelectionSignals) -> u32 {
    let is_fragmented_cyclic_mesh = metrics.node_count >= 8
        && metrics.back_edge_count > 0
        && signals.component_count >= 3
        && signals.articulation_point_count == 0
        && signals.bridge_count == 0
        && signals.peak_degree_centrality_permille <= 350;
    if is_fragmented_cyclic_mesh { 220 } else { 0 }
}

const fn algorithm_available_for_diagram(
    diagram_type: DiagramType,
    algorithm: LayoutAlgorithm,
) -> bool {
    match algorithm {
        LayoutAlgorithm::Auto
        | LayoutAlgorithm::Sugiyama
        | LayoutAlgorithm::Force
        | LayoutAlgorithm::Tree => true,
        LayoutAlgorithm::Radial => matches!(diagram_type, DiagramType::Mindmap),
        LayoutAlgorithm::Timeline => matches!(diagram_type, DiagramType::Timeline),
        LayoutAlgorithm::Gantt => matches!(diagram_type, DiagramType::Gantt),
        LayoutAlgorithm::XyChart => matches!(diagram_type, DiagramType::XyChart),
        LayoutAlgorithm::Sankey => matches!(diagram_type, DiagramType::Sankey),
        LayoutAlgorithm::Kanban => {
            matches!(diagram_type, DiagramType::Journey | DiagramType::Kanban)
        }
        LayoutAlgorithm::Grid => matches!(diagram_type, DiagramType::BlockBeta),
        LayoutAlgorithm::Sequence => matches!(diagram_type, DiagramType::Sequence),
        LayoutAlgorithm::Pie => matches!(diagram_type, DiagramType::Pie),
        LayoutAlgorithm::Quadrant => matches!(diagram_type, DiagramType::QuadrantChart),
        LayoutAlgorithm::GitGraph => matches!(diagram_type, DiagramType::GitGraph),
        LayoutAlgorithm::Packet => matches!(diagram_type, DiagramType::PacketBeta),
        LayoutAlgorithm::Architecture => matches!(diagram_type, DiagramType::ArchitectureBeta),
    }
}

fn general_graph_posterior_permille(metrics: GraphMetrics) -> (u16, u16, u16) {
    if metrics.is_tree_like && metrics.node_count > 10 {
        return (930, 10, 60);
    }

    let tree_score = 40_i32
        + if metrics.is_tree_like { 980 } else { 0 }
        + if metrics.root_count == 1 { 70 } else { 0 }
        + if metrics.back_edge_count == 0 { 30 } else { 0 }
        - if metrics.is_dense { 180 } else { 0 }
        - (metrics.back_edge_count.min(6) as i32 * 45)
        - (metrics.max_scc_size.saturating_sub(1).min(4) as i32 * 20);

    let dense_ratio_bonus =
        ((metrics.edge_to_node_ratio - 1.2_f32).max(0.0) * 220.0_f32).round() as i32;
    let dense_score = 50_i32
        + dense_ratio_bonus.min(620)
        + if metrics.is_dense { 260 } else { 0 }
        + (metrics.back_edge_count.min(8) as i32 * 18)
        + (metrics.scc_count.min(4) as i32 * 22)
        + if metrics.node_count > 30 { 70 } else { 0 };

    let layered_score = 160_i32
        + if metrics.is_tree_like { 0 } else { 110 }
        + if metrics.is_dense { 0 } else { 90 }
        + if metrics.back_edge_count <= 5 { 70 } else { 25 }
        + if (0.8..=2.2).contains(&metrics.edge_to_node_ratio) {
            120
        } else {
            20
        }
        + if metrics.root_count > 0 { 25 } else { 0 };

    normalize_three_scores_permille(tree_score, dense_score, layered_score)
}

fn normalize_three_scores_permille(a: i32, b: i32, c: i32) -> (u16, u16, u16) {
    let raw = [a.max(1) as u32, b.max(1) as u32, c.max(1) as u32];
    let total = raw.iter().sum::<u32>().max(1);
    let mut normalized = [
        (raw[0] * 1000) / total,
        (raw[1] * 1000) / total,
        (raw[2] * 1000) / total,
    ];
    let assigned = normalized.iter().sum::<u32>();
    let remainder = 1000_u32.saturating_sub(assigned);
    let max_index = raw
        .iter()
        .enumerate()
        .max_by_key(|(_, value)| *value)
        .map_or(2, |(index, _)| index);
    normalized[max_index] = normalized[max_index].saturating_add(remainder);
    (
        normalized[0] as u16,
        normalized[1] as u16,
        normalized[2] as u16,
    )
}

fn expected_loss_permille(
    ir: &MermaidDiagramIr,
    algorithm: LayoutAlgorithm,
    tree_like: u16,
    dense_graph: u16,
    layered_general: u16,
) -> u32 {
    let (loss_tree_like, loss_dense_graph, loss_layered_general) = match algorithm {
        LayoutAlgorithm::Sugiyama => (240_u32, 620_u32, 120_u32),
        LayoutAlgorithm::Tree => (70_u32, 920_u32, 700_u32),
        LayoutAlgorithm::Force => (560_u32, 140_u32, 500_u32),
        _ => (500_u32, 500_u32, 500_u32),
    };

    let weighted_quality_loss = (loss_tree_like * u32::from(tree_like)
        + loss_dense_graph * u32::from(dense_graph)
        + loss_layered_general * u32::from(layered_general))
        / 1000;
    let compute_penalty = estimate_layout_cost(ir, algorithm).time_ms as u32 / 20;
    weighted_quality_loss.saturating_add(compute_penalty)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct LayoutCostEstimate {
    time_ms: usize,
    iterations: usize,
    route_ops: usize,
}

impl LayoutCostEstimate {
    #[must_use]
    const fn exceeds(self, guardrails: LayoutGuardrails) -> (bool, bool, bool) {
        (
            self.time_ms > guardrails.max_layout_time_ms,
            self.iterations > guardrails.max_layout_iterations,
            self.route_ops > guardrails.max_route_ops,
        )
    }

    #[must_use]
    const fn score(self) -> usize {
        self.time_ms
            .saturating_mul(16)
            .saturating_add(self.iterations.saturating_mul(4))
            .saturating_add(self.route_ops)
    }
}

fn estimate_layout_cost(ir: &MermaidDiagramIr, algorithm: LayoutAlgorithm) -> LayoutCostEstimate {
    let nodes = ir.nodes.len();
    let edges = ir.edges.len();
    let ranks_hint = nodes.max(1).div_ceil(4);
    match algorithm {
        LayoutAlgorithm::Sugiyama => LayoutCostEstimate {
            time_ms: nodes
                .saturating_mul(edges.max(1))
                .div_ceil(50)
                .saturating_add(ranks_hint.saturating_mul(5))
                .saturating_add(10),
            iterations: ranks_hint.saturating_mul(10).saturating_add(24),
            route_ops: edges
                .saturating_mul(24)
                .saturating_add(nodes.saturating_mul(4)),
        },
        LayoutAlgorithm::Force => {
            let iterations = force_iteration_budget(nodes);
            LayoutCostEstimate {
                time_ms: nodes
                    .saturating_mul(nodes.max(1))
                    .saturating_mul(iterations.max(1))
                    / 40
                    + 20,
                iterations,
                route_ops: edges
                    .saturating_mul(16)
                    .saturating_add(nodes.saturating_mul(6)),
            }
        }
        LayoutAlgorithm::Tree => LayoutCostEstimate {
            // A directed path has a unique tree order. The tree implementation lays it out in
            // linear passes, so charging the generic four-milliseconds-per-node estimate can
            // incorrectly push it back through Sugiyama's cycle, rank, crossing, and coordinate
            // pipeline. Keep the conservative generic estimate for branching trees, but price the
            // path specialization by its actual linear work.
            time_ms: if is_directed_path(ir) {
                nodes
                    .div_ceil(16)
                    .saturating_add(edges.div_ceil(16))
                    .saturating_add(1)
            } else {
                nodes
                    .saturating_mul(4)
                    .saturating_add(edges.saturating_mul(2))
                    .saturating_add(8)
            },
            iterations: nodes.saturating_add(4),
            route_ops: edges.saturating_mul(8).saturating_add(nodes),
        },
        // Radial is a cheap single-pass tree placement: angle assignment plus
        // straight-line edges, with no obstacle-aware routing or iterative
        // refinement. The prior estimate made it pricier than `Tree`, which is
        // backwards for large mindmaps because `Tree` pays dense obstacle-routing
        // costs that radial skips. Keeping radial's estimate below tree's keeps
        // mindmaps on their only correct specialized layout under guardrails.
        LayoutAlgorithm::Radial => LayoutCostEstimate {
            time_ms: nodes
                .saturating_mul(3)
                .saturating_add(edges)
                .saturating_add(8),
            iterations: nodes.saturating_add(4),
            route_ops: edges.saturating_mul(2).saturating_add(nodes),
        },
        LayoutAlgorithm::Timeline
        | LayoutAlgorithm::Gantt
        | LayoutAlgorithm::XyChart
        | LayoutAlgorithm::Kanban
        | LayoutAlgorithm::Grid
        | LayoutAlgorithm::Sequence
        | LayoutAlgorithm::Pie
        | LayoutAlgorithm::Quadrant
        | LayoutAlgorithm::GitGraph
        | LayoutAlgorithm::Architecture
        | LayoutAlgorithm::Packet => LayoutCostEstimate {
            time_ms: nodes
                .saturating_mul(3)
                .saturating_add(edges.saturating_mul(2))
                .saturating_add(6),
            iterations: nodes.saturating_add(2),
            route_ops: edges.saturating_mul(6).saturating_add(nodes),
        },
        LayoutAlgorithm::Sankey => LayoutCostEstimate {
            time_ms: nodes
                .saturating_mul(8)
                .saturating_add(edges.saturating_mul(6))
                .saturating_add(20),
            iterations: nodes.saturating_mul(2).saturating_add(8),
            route_ops: edges
                .saturating_mul(18)
                .saturating_add(nodes.saturating_mul(4)),
        },
        LayoutAlgorithm::Auto => LayoutCostEstimate {
            time_ms: 0,
            iterations: 0,
            route_ops: 0,
        },
    }
}

fn is_directed_path(ir: &MermaidDiagramIr) -> bool {
    directed_path_order(ir).is_some()
}

fn directed_path_order(ir: &MermaidDiagramIr) -> Option<Vec<usize>> {
    let node_count = ir.nodes.len();
    if node_count < 3 {
        return None;
    }
    if ir.edges.len() != node_count - 1 {
        return None;
    }

    let mut next = vec![None; node_count];
    let mut in_degree = vec![0_u8; node_count];
    for edge in &ir.edges {
        let (Some(source), Some(target)) = (
            endpoint_node_index(ir, edge.from),
            endpoint_node_index(ir, edge.to),
        ) else {
            return None;
        };
        if next[source].replace(target).is_some() {
            return None;
        }
        in_degree[target] = in_degree[target].saturating_add(1);
        if in_degree[target] > 1 {
            return None;
        }
    }
    let mut roots = in_degree
        .iter()
        .enumerate()
        .filter_map(|(index, &degree)| (degree == 0).then_some(index));
    let mut cursor = roots.next()?;
    if roots.next().is_some() {
        return None;
    }
    let mut order = Vec::with_capacity(node_count);
    for visited in 1..=node_count {
        order.push(cursor);
        match next[cursor] {
            Some(successor) if visited < node_count => cursor = successor,
            None if visited == node_count => return Some(order),
            _ => return None,
        }
    }
    None
}

fn fallback_candidates(ir: &MermaidDiagramIr, selected: LayoutAlgorithm) -> Vec<LayoutAlgorithm> {
    let mut candidates = vec![selected];
    let preferred = match ir.diagram_type {
        DiagramType::BlockBeta => [
            LayoutAlgorithm::Grid,
            LayoutAlgorithm::Tree,
            LayoutAlgorithm::Sugiyama,
        ],
        DiagramType::Mindmap => [
            LayoutAlgorithm::Radial,
            LayoutAlgorithm::Tree,
            LayoutAlgorithm::Sugiyama,
        ],
        DiagramType::Timeline => [
            LayoutAlgorithm::Timeline,
            LayoutAlgorithm::Tree,
            LayoutAlgorithm::Sugiyama,
        ],
        DiagramType::XyChart => [
            LayoutAlgorithm::XyChart,
            LayoutAlgorithm::Grid,
            LayoutAlgorithm::Sugiyama,
        ],
        DiagramType::Gantt => [
            LayoutAlgorithm::Gantt,
            LayoutAlgorithm::Grid,
            LayoutAlgorithm::Sugiyama,
        ],
        DiagramType::Sankey => [
            LayoutAlgorithm::Sankey,
            LayoutAlgorithm::Tree,
            LayoutAlgorithm::Sugiyama,
        ],
        DiagramType::Journey | DiagramType::Kanban => [
            LayoutAlgorithm::Kanban,
            LayoutAlgorithm::Grid,
            LayoutAlgorithm::Sugiyama,
        ],
        DiagramType::Sequence => [
            LayoutAlgorithm::Sequence,
            LayoutAlgorithm::Grid,
            LayoutAlgorithm::Sugiyama,
        ],
        DiagramType::Pie => [
            LayoutAlgorithm::Pie,
            LayoutAlgorithm::Grid,
            LayoutAlgorithm::Sugiyama,
        ],
        DiagramType::QuadrantChart => [
            LayoutAlgorithm::Quadrant,
            LayoutAlgorithm::Grid,
            LayoutAlgorithm::Sugiyama,
        ],
        DiagramType::GitGraph => [
            LayoutAlgorithm::GitGraph,
            LayoutAlgorithm::Tree,
            LayoutAlgorithm::Sugiyama,
        ],
        DiagramType::PacketBeta => [
            LayoutAlgorithm::Packet,
            LayoutAlgorithm::Grid,
            LayoutAlgorithm::Sugiyama,
        ],
        _ => [selected, LayoutAlgorithm::Tree, LayoutAlgorithm::Sugiyama],
    };

    for candidate in preferred {
        if candidate != LayoutAlgorithm::Auto
            && algorithm_available_for_diagram(ir.diagram_type, candidate)
            && !candidates.contains(&candidate)
        {
            candidates.push(candidate);
        }
    }

    for candidate in [
        LayoutAlgorithm::Tree,
        LayoutAlgorithm::Sugiyama,
        LayoutAlgorithm::Grid,
    ] {
        if candidate != LayoutAlgorithm::Auto
            && algorithm_available_for_diagram(ir.diagram_type, candidate)
            && !candidates.contains(&candidate)
        {
            candidates.push(candidate);
        }
    }

    candidates
}

const fn guardrail_reason(
    time_budget_exceeded: bool,
    iteration_budget_exceeded: bool,
    route_budget_exceeded: bool,
    fallback_applied: bool,
    within_budget_candidate_found: bool,
) -> &'static str {
    match (
        time_budget_exceeded,
        iteration_budget_exceeded,
        route_budget_exceeded,
        fallback_applied,
        within_budget_candidate_found,
    ) {
        (false, false, false, false, _) => "within_budget",
        (true, false, false, true, true) => "guardrail_fallback_time_budget",
        (false, true, false, true, true) => "guardrail_fallback_iteration_budget",
        (false, false, true, true, true) => "guardrail_fallback_route_budget",
        (_, _, _, true, true) => "guardrail_fallback_multi_budget",
        (true, false, false, true, false) => "guardrail_forced_time_budget",
        (false, true, false, true, false) => "guardrail_forced_iteration_budget",
        (false, false, true, true, false) => "guardrail_forced_route_budget",
        _ => "guardrail_forced_multi_budget",
    }
}

fn evaluate_layout_guardrails(
    ir: &MermaidDiagramIr,
    selected: LayoutAlgorithm,
    guardrails: LayoutGuardrails,
) -> LayoutGuardDecision {
    let initial_estimate = estimate_layout_cost(ir, selected);
    let (time_budget_exceeded, iteration_budget_exceeded, route_budget_exceeded) =
        initial_estimate.exceeds(guardrails);

    if !(time_budget_exceeded || iteration_budget_exceeded || route_budget_exceeded) {
        return LayoutGuardDecision {
            initial_algorithm: selected,
            selected_algorithm: selected,
            estimated_layout_time_ms: initial_estimate.time_ms,
            estimated_layout_iterations: initial_estimate.iterations,
            estimated_route_ops: initial_estimate.route_ops,
            selected_estimated_layout_time_ms: initial_estimate.time_ms,
            selected_estimated_layout_iterations: initial_estimate.iterations,
            selected_estimated_route_ops: initial_estimate.route_ops,
            reason: "within_budget",
            ..LayoutGuardDecision::default()
        };
    }

    let mut selected_algorithm = selected;
    let mut selected_estimate = initial_estimate;
    let mut within_budget_candidate_found = false;

    for candidate in fallback_candidates(ir, selected).into_iter().skip(1) {
        let estimate = estimate_layout_cost(ir, candidate);
        if !estimate.exceeds(guardrails).0
            && !estimate.exceeds(guardrails).1
            && !estimate.exceeds(guardrails).2
        {
            selected_algorithm = candidate;
            selected_estimate = estimate;
            within_budget_candidate_found = true;
            break;
        }

        if estimate.score() < selected_estimate.score() {
            selected_algorithm = candidate;
            selected_estimate = estimate;
        }
    }

    let guard = LayoutGuardDecision {
        initial_algorithm: selected,
        selected_algorithm,
        estimated_layout_time_ms: initial_estimate.time_ms,
        estimated_layout_iterations: initial_estimate.iterations,
        estimated_route_ops: initial_estimate.route_ops,
        selected_estimated_layout_time_ms: selected_estimate.time_ms,
        selected_estimated_layout_iterations: selected_estimate.iterations,
        selected_estimated_route_ops: selected_estimate.route_ops,
        time_budget_exceeded,
        iteration_budget_exceeded,
        route_budget_exceeded,
        fallback_applied: selected_algorithm != selected,
        reason: guardrail_reason(
            time_budget_exceeded,
            iteration_budget_exceeded,
            route_budget_exceeded,
            selected_algorithm != selected,
            within_budget_candidate_found,
        ),
    };

    if guard.fallback_applied {
        warn!(
            initial_algorithm = guard.initial_algorithm.as_str(),
            selected_algorithm = guard.selected_algorithm.as_str(),
            estimated_time_ms = guard.estimated_layout_time_ms,
            reason = guard.reason,
            "layout.guardrail.fallback"
        );
    } else {
        debug!(
            algorithm = guard.selected_algorithm.as_str(),
            estimated_time_ms = guard.estimated_layout_time_ms,
            reason = guard.reason,
            "layout.guardrail.ok"
        );
    }

    guard
}

fn layout_diagram_sugiyama_traced_with_config(
    ir: &MermaidDiagramIr,
    config: LayoutConfig,
) -> TracedLayout {
    let mut trace = LayoutTrace::default();
    let spacing = spacing_with_source_hints(config.spacing, ir);
    let metrics = config
        .font_metrics
        .clone()
        .unwrap_or_else(fm_core::FontMetrics::default_metrics);
    let node_sizes = compute_node_sizes(ir, &metrics);
    // Node id-order priorities are a pure function of `ir` (an O(N log N) String-memcmp sort of node ids).
    // `cycle_removal`, `rank_assignment`, and `build_cycle_cluster_map` each recomputed it — hoist to ONE
    // computation and thread it through. Byte-identical (same Vec); removes 1-2 redundant sorts per layout.
    let node_priority = stable_node_priorities(ir);
    let cycle_result = cycle_removal(ir, config.cycle_strategy, &node_priority);
    push_snapshot(
        &mut trace,
        "cycle_removal",
        ir.nodes.len(),
        ir.edges.len(),
        cycle_result.reversed_edge_indexes.len(),
        0,
    );

    let collapse_map = if config.collapse_cycle_clusters {
        Some(build_cycle_cluster_map(ir, &cycle_result, &node_priority))
    } else {
        None
    };

    let mut ranks = rank_assignment(ir, &cycle_result, &node_priority);
    if config.lp_relaxation_layers
        && ir.diagram_type == DiagramType::Flowchart
        && ir.nodes.len() <= LP_RELAXATION_LAYER_NODE_LIMIT
        && ir.constraints.is_empty()
        && let Some(relaxed_ranks) = lp_relaxation_layer_assignment(ir, &cycle_result, &ranks)
    {
        ranks = relaxed_ranks;
    }
    apply_ir_constraints(ir, &mut ranks);
    push_snapshot(
        &mut trace,
        "rank_assignment",
        ir.nodes.len(),
        ir.edges.len(),
        cycle_result.reversed_edge_indexes.len(),
        0,
    );

    let (crossing_count_before, ordering_by_rank) = crossing_minimization(ir, &ranks, &config);
    push_snapshot(
        &mut trace,
        "crossing_minimization",
        ir.nodes.len(),
        ir.edges.len(),
        cycle_result.reversed_edge_indexes.len(),
        crossing_count_before,
    );

    // Refinement: transpose + sifting heuristics.
    let (crossing_count, ordering_by_rank) =
        crossing_refinement(ir, &ranks, ordering_by_rank, crossing_count_before);
    push_snapshot(
        &mut trace,
        "crossing_refinement",
        ir.nodes.len(),
        ir.edges.len(),
        cycle_result.reversed_edge_indexes.len(),
        crossing_count,
    );

    let mut nodes = coordinate_assignment(ir, &node_sizes, &ranks, &ordering_by_rank, spacing);
    apply_subgraph_direction_overrides(ir, &node_sizes, &mut nodes, spacing);
    separate_disjoint_subgraphs(ir, &mut nodes, spacing);
    apply_constraint_solver(ir, &mut nodes, spacing, &config);
    // Clusters are built BEFORE edge routing, not after. `build_cluster_boxes` is a pure function of
    // the already-positioned `nodes`, so the boxes are identical either way — but a composite state
    // has to become its container before its transitions are routed, or they attach to the plain box
    // instead of the container (bd-9w54). Nothing between here and the old call site mutates
    // `nodes`; the cycle-collapse pass that does runs after both, exactly as it did before.
    let mut clusters = build_cluster_boxes(ir, &nodes, spacing, &metrics);
    anchor_composite_state_nodes(ir, &mut nodes, &clusters);
    let mut edges = build_edge_paths(
        ir,
        &nodes,
        &cycle_result.highlighted_edge_indexes,
        edge_routing_with_source_hints(config.edge_routing, ir),
    );
    bundle_parallel_edges(ir, &mut edges);
    let cluster_dividers = build_state_cluster_dividers(ir, &nodes, &clusters);
    let mut cycle_clusters = Vec::new();

    // If cycle clusters are collapsed, group member nodes within their cluster head's bounds.
    let collapsed_count = if let Some(ref collapse_map) = collapse_map {
        let count = collapse_map.cluster_heads.len();
        cycle_clusters =
            build_cycle_cluster_results(collapse_map, &mut nodes, &mut clusters, spacing);
        count
    } else {
        0
    };

    let bounds = compute_bounds(&nodes, &clusters, &edges, spacing);

    push_snapshot(
        &mut trace,
        "post_processing",
        ir.nodes.len(),
        ir.edges.len(),
        cycle_result.reversed_edge_indexes.len(),
        crossing_count,
    );

    let (total_edge_length, measured_reversed_edge_total_length) =
        compute_edge_length_metrics(&edges);
    let reversed_edges = if matches!(config.cycle_strategy, CycleStrategy::CycleAware) {
        0
    } else {
        cycle_result.reversed_edge_indexes.len()
    };
    let reversed_edge_total_length = if matches!(config.cycle_strategy, CycleStrategy::CycleAware) {
        0.0
    } else {
        measured_reversed_edge_total_length
    };

    let stats = LayoutStats {
        node_count: ir.nodes.len(),
        edge_count: ir.edges.len(),
        crossing_count,
        crossing_count_before_refinement: crossing_count_before,
        reversed_edges,
        cycle_count: cycle_result.summary.cycle_count,
        cycle_node_count: cycle_result.summary.cycle_node_count,
        max_cycle_size: cycle_result.summary.max_cycle_size,
        collapsed_clusters: collapsed_count,
        reversed_edge_total_length,
        total_edge_length,
        phase_iterations: trace.snapshots.len(),
    };

    // Compute centrality tiers for semantic styling (FNX-enabled builds).
    let node_centrality = compute_layout_centrality_tiers(ir, &config);

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters,
            cycle_clusters,
            edges,
            bounds,
            stats,
            extensions: LayoutExtensions {
                cluster_dividers,
                node_centrality,
                ..LayoutExtensions::default()
            },
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

/// Lay out a diagram using force-directed (Fruchterman-Reingold) algorithm.
///
/// Suitable for diagrams without a natural hierarchy: ER diagrams, architecture
/// diagrams, generic graphs with no clear flow direction.
#[must_use]
pub fn layout_diagram_force(ir: &MermaidDiagramIr) -> DiagramLayout {
    Arc::unwrap_or_clone(layout_diagram_force_traced(ir).layout)
}

/// Lay out with force-directed algorithm and return tracing information.
#[must_use]
pub fn layout_diagram_force_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let mut trace = LayoutTrace::default();
    let spacing = LayoutSpacing::default();
    let metrics = fm_core::FontMetrics::default_metrics();
    let node_sizes = compute_node_sizes(ir, &metrics);
    let n = ir.nodes.len();

    if n == 0 {
        return TracedLayout {
            layout: Arc::new(DiagramLayout {
                nodes: vec![],
                clusters: vec![],
                cycle_clusters: vec![],
                edges: vec![],
                bounds: LayoutRect {
                    x: 0.0,
                    y: 0.0,
                    width: 0.0,
                    height: 0.0,
                },
                stats: LayoutStats::default(),
                extensions: LayoutExtensions::default(),
                dirty_regions: Vec::new(),
            }),
            trace,
        };
    }

    // Deterministic initial placement using hash of node IDs.
    let mut positions = force_initial_positions(ir, &node_sizes, &spacing);

    push_snapshot(&mut trace, "force_init", n, ir.edges.len(), 0, 0);

    // Build adjacency list for attractive forces.
    let adjacency = force_build_adjacency(ir);

    // Build cluster membership for cluster-aware forces.
    let cluster_membership = force_cluster_membership(ir);

    // Fruchterman-Reingold iterations.
    let area = (n as f32) * spacing.node_spacing * spacing.rank_spacing;
    let k = (area / n as f32).sqrt(); // Optimal distance between nodes
    let max_iterations = force_iteration_budget(n);
    let convergence_threshold = 0.5;

    for iteration in 0..max_iterations {
        let temperature = force_temperature(iteration, max_iterations, k);
        if temperature < convergence_threshold {
            break;
        }

        let displacements = force_compute_displacements(
            &positions,
            &node_sizes,
            &adjacency,
            &cluster_membership,
            k,
            n,
        );

        // Apply displacements clamped by temperature.
        let mut max_displacement: f32 = 0.0;
        for i in 0..n {
            let (dx, dy) = displacements[i];
            let magnitude = dx.hypot(dy).max(f32::EPSILON);
            let clamped_mag = magnitude.min(temperature);
            let scale = clamped_mag / magnitude;
            positions[i].0 = dx.mul_add(scale, positions[i].0);
            positions[i].1 = dy.mul_add(scale, positions[i].1);
            max_displacement = max_displacement.max(clamped_mag);
        }

        if max_displacement < convergence_threshold {
            break;
        }
    }

    push_snapshot(&mut trace, "force_simulation", n, ir.edges.len(), 0, 0);

    // Overlap removal post-processing.
    force_remove_overlaps(&mut positions, &node_sizes, &spacing);

    push_snapshot(&mut trace, "force_overlap_removal", n, ir.edges.len(), 0, 0);

    // Normalize positions so all coordinates are non-negative.
    force_normalize_positions(&mut positions, &node_sizes);

    // Build layout output.
    let nodes = force_build_node_boxes(ir, &positions, &node_sizes);
    let edges = force_build_edge_paths(ir, &nodes);
    let clusters = build_cluster_boxes(ir, &nodes, spacing, &metrics);
    let bounds = compute_bounds(&nodes, &clusters, &edges, spacing);

    let (total_edge_length, reversed_edge_total_length) = compute_edge_length_metrics(&edges);

    push_snapshot(&mut trace, "force_post_processing", n, ir.edges.len(), 0, 0);

    let stats = LayoutStats {
        node_count: n,
        edge_count: ir.edges.len(),
        crossing_count: 0, // Not computed for force-directed
        crossing_count_before_refinement: 0,
        reversed_edges: 0,
        cycle_count: 0,
        cycle_node_count: 0,
        max_cycle_size: 0,
        collapsed_clusters: 0,
        reversed_edge_total_length,
        total_edge_length,
        phase_iterations: trace.snapshots.len(),
    };

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters,
            cycle_clusters: vec![],
            edges,
            bounds,
            stats,
            extensions: LayoutExtensions::default(),
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

/// Lay out a diagram using a deterministic tidy-tree algorithm.
#[must_use]
pub fn layout_diagram_tree(ir: &MermaidDiagramIr) -> DiagramLayout {
    Arc::unwrap_or_clone(layout_diagram_tree_traced(ir).layout)
}

/// Lay out using the tree algorithm and return tracing information.
#[must_use]
pub fn layout_diagram_tree_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let mut trace = LayoutTrace::default();
    let spacing = LayoutSpacing::default();
    let node_sizes = compute_node_sizes(ir, &fm_core::FontMetrics::default_metrics());
    let node_count = ir.nodes.len();

    if node_count == 0 {
        return TracedLayout {
            layout: Arc::new(DiagramLayout {
                nodes: Vec::new(),
                clusters: Vec::new(),
                cycle_clusters: Vec::new(),
                edges: Vec::new(),
                bounds: LayoutRect {
                    x: 0.0,
                    y: 0.0,
                    width: 0.0,
                    height: 0.0,
                },
                stats: LayoutStats::default(),
                extensions: LayoutExtensions::default(),
                dirty_regions: Vec::new(),
            }),
            trace,
        };
    }

    if let Some(path_order) = directed_path_order(ir) {
        return layout_directed_path_tree_traced(ir, path_order, node_sizes, spacing, trace);
    }

    let tree = build_tree_layout_structure(ir);
    push_snapshot(
        &mut trace,
        "tree_structure",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    let span_sizes: Vec<f32> = node_sizes
        .iter()
        .map(|(width, height)| {
            if tree.horizontal_depth_axis {
                *height
            } else {
                *width
            }
        })
        .collect();

    let mut span_memo = vec![None; node_count];
    compute_tree_subtree_spans(
        &tree.roots,
        &tree.children,
        &span_sizes,
        spacing,
        &mut span_memo,
    );
    let subtree_spans: Vec<f32> = span_memo
        .into_iter()
        .map(|span| span.unwrap_or(0.0))
        .collect();

    let mut span_centers = vec![0.0_f32; node_count];
    compute_all_tree_span_centers(
        &tree.roots,
        &tree.children,
        &subtree_spans,
        spacing,
        &mut span_centers,
    );

    let depth_level_sizes = tree_depth_level_sizes(&tree, &node_sizes);
    let depth_centers = depth_level_centers(&depth_level_sizes, spacing.rank_spacing);

    let mut centers = vec![(0.0_f32, 0.0_f32); node_count];
    for node_index in 0..node_count {
        let logical_depth = tree.depth[node_index];
        let mapped_depth = if tree.reverse_depth_axis {
            tree.max_depth.saturating_sub(logical_depth)
        } else {
            logical_depth
        };
        let depth_center = depth_centers[mapped_depth];
        let span_center = span_centers[node_index];
        centers[node_index] = if tree.horizontal_depth_axis {
            (depth_center, span_center)
        } else {
            (span_center, depth_center)
        };
    }
    normalize_center_positions(&mut centers, &node_sizes);

    let order_by_rank = rank_orders_from_key(ir, &tree.depth, &span_centers);
    let nodes = node_boxes_from_centers(ir, &node_sizes, &tree.depth, &order_by_rank, &centers);
    let edges =
        build_directed_path_edge_paths(ir, &nodes, &BTreeSet::new(), EdgeRouting::default())
            .unwrap_or_else(|| {
                build_edge_paths(ir, &nodes, &BTreeSet::new(), EdgeRouting::default())
            });
    // Same metrics this function's node sizes were computed with: every caller on these
    // specialized paths uses `FontMetrics::default_metrics()` (verified at lib.rs:4791, 5453,
    // 6271, 6378), so binding it here introduces no layout/render measurement mismatch.
    let metrics = fm_core::FontMetrics::default_metrics();
    let clusters = build_cluster_boxes(ir, &nodes, spacing, &metrics);
    let bounds = compute_bounds(&nodes, &clusters, &edges, spacing);
    let (total_edge_length, reversed_edge_total_length) = compute_edge_length_metrics(&edges);

    push_snapshot(
        &mut trace,
        "tree_post_processing",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    let stats = LayoutStats {
        node_count,
        edge_count: ir.edges.len(),
        crossing_count: 0,
        crossing_count_before_refinement: 0,
        reversed_edges: 0,
        cycle_count: 0,
        cycle_node_count: 0,
        max_cycle_size: 0,
        collapsed_clusters: 0,
        reversed_edge_total_length,
        total_edge_length,
        phase_iterations: trace.snapshots.len(),
    };

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters,
            cycle_clusters: Vec::new(),
            edges,
            bounds,
            stats,
            extensions: LayoutExtensions::default(),
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

fn layout_directed_path_tree_traced(
    ir: &MermaidDiagramIr,
    path_order: Vec<usize>,
    node_sizes: Vec<(f32, f32)>,
    spacing: LayoutSpacing,
    mut trace: LayoutTrace,
) -> TracedLayout {
    let node_count = ir.nodes.len();
    let horizontal_depth_axis = matches!(ir.direction, GraphDirection::LR | GraphDirection::RL);
    let reverse_depth_axis = matches!(ir.direction, GraphDirection::RL | GraphDirection::BT);
    let max_depth = node_count.saturating_sub(1);

    push_snapshot(
        &mut trace,
        "tree_structure",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    let mut depth = vec![0_usize; node_count];
    let mut depth_level_sizes = vec![0.0_f32; node_count];
    let mut subtree_spans = vec![0.0_f32; node_count];
    let mut running_span = 0.0_f32;
    for (logical_depth, &node_index) in path_order.iter().enumerate().rev() {
        depth[node_index] = logical_depth;
        let (width, height) = node_sizes[node_index];
        let depth_size = if horizontal_depth_axis { width } else { height };
        let span_size = if horizontal_depth_axis { height } else { width };
        depth_level_sizes[logical_depth] = depth_size.max(1.0);
        running_span = span_size.max(1.0).max(running_span);
        subtree_spans[node_index] = running_span;
    }

    // A path has one child at each non-leaf depth. Reproduce the generic tree center recurrence
    // exactly, but without child adjacency, BFS queues, or per-rank buckets.
    let mut span_centers = vec![0.0_f32; node_count];
    let mut span_start = 0.0_f32;
    for (logical_depth, &node_index) in path_order.iter().enumerate() {
        let subtree_span = subtree_spans[node_index];
        span_centers[node_index] = span_start + (subtree_span / 2.0);
        if let Some(&child) = path_order.get(logical_depth + 1) {
            let child_span = subtree_spans[child];
            span_start += (subtree_span - child_span) / 2.0;
        }
    }

    let depth_centers = depth_level_centers(&depth_level_sizes, spacing.rank_spacing);
    let mut centers = vec![(0.0_f32, 0.0_f32); node_count];
    for node_index in 0..node_count {
        let logical_depth = depth[node_index];
        let mapped_depth = if reverse_depth_axis {
            max_depth.saturating_sub(logical_depth)
        } else {
            logical_depth
        };
        let depth_center = depth_centers[mapped_depth];
        let span_center = span_centers[node_index];
        centers[node_index] = if horizontal_depth_axis {
            (depth_center, span_center)
        } else {
            (span_center, depth_center)
        };
    }
    normalize_center_positions(&mut centers, &node_sizes);

    let order_by_rank = vec![0_usize; node_count];
    let nodes = node_boxes_from_centers(ir, &node_sizes, &depth, &order_by_rank, &centers);
    let edges = build_directed_path_edge_paths_unchecked(
        ir,
        &nodes,
        &BTreeSet::new(),
        EdgeRouting::default(),
    )
    .expect("validated directed path endpoints");
    // Same metrics this function's node sizes were computed with: every caller on these
    // specialized paths uses `FontMetrics::default_metrics()` (verified at lib.rs:4791, 5453,
    // 6271, 6378), so binding it here introduces no layout/render measurement mismatch.
    let metrics = fm_core::FontMetrics::default_metrics();
    let clusters = build_cluster_boxes(ir, &nodes, spacing, &metrics);
    let bounds = compute_bounds(&nodes, &clusters, &edges, spacing);
    let (total_edge_length, reversed_edge_total_length) = compute_edge_length_metrics(&edges);

    push_snapshot(
        &mut trace,
        "tree_post_processing",
        node_count,
        ir.edges.len(),
        0,
        0,
    );
    let stats = LayoutStats {
        node_count,
        edge_count: ir.edges.len(),
        crossing_count: 0,
        crossing_count_before_refinement: 0,
        reversed_edges: 0,
        cycle_count: 0,
        cycle_node_count: 0,
        max_cycle_size: 0,
        collapsed_clusters: 0,
        reversed_edge_total_length,
        total_edge_length,
        phase_iterations: trace.snapshots.len(),
    };

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters,
            cycle_clusters: Vec::new(),
            edges,
            bounds,
            stats,
            extensions: LayoutExtensions::default(),
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

/// Certify that a parser-provided leading slice has suffix-independent geometry in an LR path.
///
/// Certification is intentionally narrow. LR paths grow to the right, so an appended node cannot
/// move an earlier rank; requiring the suffix node heights not to exceed the prefix maximum also
/// proves that vertical normalization is unchanged. Other directions and non-sequential path IRs
/// fall back to the ordinary layout pipeline.
#[must_use]
pub fn certify_directed_path_layout_prefix(
    ir: &MermaidDiagramIr,
    layout: &DiagramLayout,
    node_count: usize,
    edge_count: usize,
) -> Option<DirectedPathLayoutPrefix> {
    if ir.direction != GraphDirection::LR
        || node_count == 0
        || edge_count.checked_add(1) != Some(node_count)
        || ir.edges.len().checked_add(1) != Some(ir.nodes.len())
        || layout.nodes.len() != ir.nodes.len()
        || layout.edges.len() != ir.edges.len()
        || node_count > layout.nodes.len()
        || edge_count > layout.edges.len()
    {
        return None;
    }

    let path_order = directed_path_order(ir)?;
    if !path_order
        .iter()
        .enumerate()
        .all(|(logical_depth, &node_index)| logical_depth == node_index)
        || !ir.edges.iter().enumerate().all(|(edge_index, edge)| {
            endpoint_node_index(ir, edge.from) == Some(edge_index)
                && endpoint_node_index(ir, edge.to) == Some(edge_index + 1)
        })
        || !layout.nodes.iter().enumerate().all(|(node_index, node)| {
            node.node_index == node_index && node.rank == node_index && node.order == 0
        })
        || !layout
            .edges
            .iter()
            .enumerate()
            .all(|(edge_index, edge)| edge.edge_index == edge_index)
    {
        return None;
    }

    let max_node_height = layout.nodes[..node_count]
        .iter()
        .map(|node| node.bounds.height)
        .fold(0.0_f32, f32::max);
    let rank_spacing = LayoutSpacing::default().rank_spacing;
    let depth_cursor = layout.nodes[..node_count]
        .iter()
        .fold(0.0_f32, |cursor, node| {
            cursor + (node.bounds.width.max(1.0) + rank_spacing)
        });
    if !max_node_height.is_finite()
        || max_node_height <= 0.0
        || !depth_cursor.is_finite()
        || layout.nodes[node_count..]
            .iter()
            .any(|node| node.bounds.height > max_node_height)
    {
        return None;
    }

    // A sequential IR path can still have reached us through another layout algorithm. Prove
    // that this is specifically the tree path specialization before preserving its arithmetic
    // cursor: suffix transplantation must reproduce the exact floating-point operation order,
    // not merely an algebraically equivalent geometry.
    let center_y = (max_node_height / 2.0) + 20.0;
    let mut cursor = 0.0_f32;
    for node in &layout.nodes {
        let width = node.bounds.width;
        let height = node.bounds.height;
        if !width.is_finite() || !height.is_finite() || width <= 0.0 || height <= 0.0 {
            return None;
        }
        let center_x = (cursor + (width.max(1.0) / 2.0)) + 20.0;
        let expected_x = center_x - (width / 2.0);
        let expected_y = center_y - (height / 2.0);
        if expected_x.to_bits() != node.bounds.x.to_bits()
            || expected_y.to_bits() != node.bounds.y.to_bits()
        {
            return None;
        }
        cursor += width.max(1.0) + rank_spacing;
    }

    Some(DirectedPathLayoutPrefix {
        node_count,
        edge_count,
        max_node_height,
        depth_cursor,
    })
}

/// Replace only the appended tail of a previously certified LR directed-path layout.
///
/// The caller must pair `prefix` with the exact unchanged IR prefix that produced `layout` (for
/// example, a pointer-stable parser batch certificate). Every fallible check runs before mutation,
/// so `false` leaves the supplied layout untouched and the caller can safely use a full fallback.
pub fn try_relayout_directed_path_suffix(
    ir: &MermaidDiagramIr,
    layout: &mut DiagramLayout,
    prefix: &DirectedPathLayoutPrefix,
) -> bool {
    let suffix_node_count = ir.nodes.len().saturating_sub(prefix.node_count);
    if ir.direction != GraphDirection::LR
        || prefix.node_count == 0
        || prefix.edge_count.checked_add(1) != Some(prefix.node_count)
        || prefix.node_count > ir.nodes.len()
        || prefix.edge_count > ir.edges.len()
        || prefix.node_count > layout.nodes.len()
        || prefix.edge_count > layout.edges.len()
        || ir.edges.len().checked_add(1) != Some(ir.nodes.len())
        || ir.edges.len().saturating_sub(prefix.edge_count) != suffix_node_count
    {
        return false;
    }

    for (suffix_offset, edge) in ir.edges[prefix.edge_count..].iter().enumerate() {
        let target = prefix.node_count + suffix_offset;
        let source = target.saturating_sub(1);
        if endpoint_node_index(ir, edge.from) != Some(source)
            || endpoint_node_index(ir, edge.to) != Some(target)
        {
            return false;
        }
    }

    let metrics = fm_core::FontMetrics::default_metrics();
    let suffix_sizes = ir.nodes[prefix.node_count..]
        .iter()
        .map(|node| compute_node_size(ir, node, &metrics))
        .collect::<Vec<_>>();
    if suffix_sizes
        .iter()
        .any(|&(_, height)| height > prefix.max_node_height)
    {
        return false;
    }

    let spacing = LayoutSpacing::default();
    let center_y = (prefix.max_node_height / 2.0) + 20.0;
    let mut depth_cursor = prefix.depth_cursor;

    layout.nodes.truncate(prefix.node_count);
    layout.nodes.reserve(suffix_node_count);
    for (suffix_offset, (&(width, height), node)) in suffix_sizes
        .iter()
        .zip(&ir.nodes[prefix.node_count..])
        .enumerate()
    {
        let node_index = prefix.node_count + suffix_offset;
        // Preserve the full path layout's exact floating-point operation order. Reconstructing
        // `x` from the preceding rendered box is algebraically equivalent but can differ by one
        // hundredth after SVG formatting because it changes rounding associativity.
        let center_x = depth_cursor + (width.max(1.0) / 2.0) + 20.0;
        let x = center_x - (width / 2.0);
        layout.nodes.push(LayoutNodeBox {
            node_index,
            node_id: node.id.clone(),
            rank: node_index,
            order: 0,
            span: node.span_primary,
            bounds: LayoutRect {
                x,
                y: center_y - (height / 2.0),
                width,
                height,
            },
        });
        depth_cursor += width.max(1.0) + spacing.rank_spacing;
    }

    layout.edges.truncate(prefix.edge_count);
    layout.edges.reserve(suffix_node_count);
    for (edge_index, edge) in ir.edges.iter().enumerate().skip(prefix.edge_count) {
        let source = edge_index;
        let target = edge_index + 1;
        let Some((source_box, target_box)) = layout.nodes.get(source).zip(layout.nodes.get(target))
        else {
            return false;
        };
        let (source_anchor, target_anchor) = edge_anchors(
            source_box,
            target_box,
            true,
            node_shape_at(ir, source_box),
            node_shape_at(ir, target_box),
        );
        let points =
            route_edge_points_with_obstacle_index(source_anchor, target_anchor, true, &[], None);
        layout.edges.push(LayoutEdgePath {
            edge_index,
            span: edge.span,
            points,
            reversed: false,
            is_self_loop: false,
            parallel_offset: 0.0,
            bundle_count: 1,
            bundled: false,
        });
    }

    layout.clusters = build_cluster_boxes(ir, &layout.nodes, spacing, &metrics);
    layout.bounds = compute_bounds(&layout.nodes, &layout.clusters, &layout.edges, spacing);
    let (total_edge_length, reversed_edge_total_length) =
        compute_edge_length_metrics(&layout.edges);
    let phase_iterations = layout.stats.phase_iterations;
    layout.stats = LayoutStats {
        node_count: ir.nodes.len(),
        edge_count: ir.edges.len(),
        crossing_count: 0,
        crossing_count_before_refinement: 0,
        reversed_edges: 0,
        cycle_count: 0,
        cycle_node_count: 0,
        max_cycle_size: 0,
        collapsed_clusters: 0,
        reversed_edge_total_length,
        total_edge_length,
        phase_iterations,
    };
    layout.cycle_clusters.clear();
    layout.dirty_regions.clear();
    true
}

/// Lay out a diagram using a deterministic radial tree variant.
#[must_use]
pub fn layout_diagram_radial(ir: &MermaidDiagramIr) -> DiagramLayout {
    Arc::unwrap_or_clone(layout_diagram_radial_traced(ir).layout)
}

/// Lay out using the radial tree algorithm and return tracing information.
#[must_use]
pub fn layout_diagram_radial_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let mut trace = LayoutTrace::default();
    let spacing = LayoutSpacing::default();
    let node_sizes = compute_node_sizes(ir, &fm_core::FontMetrics::default_metrics());
    let node_count = ir.nodes.len();

    if node_count == 0 {
        return TracedLayout {
            layout: Arc::new(DiagramLayout {
                nodes: Vec::new(),
                clusters: Vec::new(),
                cycle_clusters: Vec::new(),
                edges: Vec::new(),
                bounds: LayoutRect {
                    x: 0.0,
                    y: 0.0,
                    width: 0.0,
                    height: 0.0,
                },
                stats: LayoutStats::default(),
                extensions: LayoutExtensions::default(),
                dirty_regions: Vec::new(),
            }),
            trace,
        };
    }

    let tree = build_tree_layout_structure(ir);
    push_snapshot(
        &mut trace,
        "tree_structure",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    let depth_offset = usize::from(tree.roots.len() > 1);
    let effective_max_depth = tree.max_depth + depth_offset;
    let mut ring_level_sizes = vec![0.0_f32; effective_max_depth + 1];
    for (node_index, (width, height)) in node_sizes.iter().copied().enumerate() {
        let level = tree.depth[node_index] + depth_offset;
        ring_level_sizes[level] = ring_level_sizes[level].max(width.max(height));
    }

    let mut radii = vec![0.0_f32; effective_max_depth + 1];
    for level in 1..=effective_max_depth {
        let prev = ring_level_sizes[level - 1].max(1.0);
        let current = ring_level_sizes[level].max(1.0);
        radii[level] = radii[level - 1] + (prev / 2.0) + spacing.rank_spacing + (current / 2.0);
    }

    let mut leaf_memo = vec![None; node_count];
    for root in &tree.roots {
        let _ = radial_leaf_count(*root, &tree.children, &mut leaf_memo);
    }
    let leaf_counts: Vec<usize> = leaf_memo
        .into_iter()
        .map(|count| count.unwrap_or(1))
        .collect();

    let mut angles = vec![0.0_f32; node_count];
    if tree.roots.len() == 1 && depth_offset == 0 {
        assign_radial_angles(
            tree.roots[0],
            -PI,
            PI,
            &tree,
            &leaf_counts,
            &node_sizes,
            &radii,
            depth_offset,
            spacing,
            &mut angles,
        );
    } else {
        let total_leaves: usize = tree.roots.iter().map(|root| leaf_counts[*root]).sum();
        let total_leaves = total_leaves.max(1);
        let mut cursor = -PI;
        for (root_index, root) in tree.roots.iter().enumerate() {
            let weight = leaf_counts[*root] as f32 / total_leaves as f32;
            let mut span = (2.0 * PI) * weight;
            if root_index + 1 == tree.roots.len() {
                span = PI - cursor;
            }
            assign_radial_angles(
                *root,
                cursor,
                cursor + span,
                &tree,
                &leaf_counts,
                &node_sizes,
                &radii,
                depth_offset,
                spacing,
                &mut angles,
            );
            cursor += span;
        }
    }

    let mut centers = vec![(0.0_f32, 0.0_f32); node_count];
    for node_index in 0..node_count {
        let level = tree.depth[node_index] + depth_offset;
        let radius = radii[level];
        let angle = angles[node_index];
        centers[node_index] = (radius * angle.cos(), radius * angle.sin());
    }
    normalize_center_positions(&mut centers, &node_sizes);

    let order_by_rank = rank_orders_from_key(ir, &tree.depth, &angles);
    let nodes = node_boxes_from_centers(ir, &node_sizes, &tree.depth, &order_by_rank, &centers);
    let edges = force_build_edge_paths(ir, &nodes);
    // Same metrics this function's node sizes were computed with: every caller on these
    // specialized paths uses `FontMetrics::default_metrics()` (verified at lib.rs:4791, 5453,
    // 6271, 6378), so binding it here introduces no layout/render measurement mismatch.
    let metrics = fm_core::FontMetrics::default_metrics();
    let clusters = build_cluster_boxes(ir, &nodes, spacing, &metrics);
    let bounds = compute_bounds(&nodes, &clusters, &edges, spacing);
    let (total_edge_length, reversed_edge_total_length) = compute_edge_length_metrics(&edges);

    push_snapshot(
        &mut trace,
        "radial_post_processing",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    let stats = LayoutStats {
        node_count,
        edge_count: ir.edges.len(),
        crossing_count: 0,
        crossing_count_before_refinement: 0,
        reversed_edges: 0,
        cycle_count: 0,
        cycle_node_count: 0,
        max_cycle_size: 0,
        collapsed_clusters: 0,
        reversed_edge_total_length,
        total_edge_length,
        phase_iterations: trace.snapshots.len(),
    };

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters,
            cycle_clusters: Vec::new(),
            edges,
            bounds,
            stats,
            extensions: LayoutExtensions::default(),
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

fn mindmap_subtree_heights(
    tree: &TreeLayoutStructure,
    node_sizes: &[(f32, f32)],
    v_gap: f32,
) -> Vec<f32> {
    let mut heights: Vec<f32> = node_sizes
        .iter()
        .map(|(_, height)| height.max(38.0))
        .collect();
    let mut state = vec![0_u8; node_sizes.len()];

    // Mindmaps are untrusted input and can be thousands of levels deep. Keep the postorder walk on
    // the heap instead of the call stack; the state guard also makes malformed cyclic structures
    // terminate rather than repeatedly expanding the same node.
    for start in tree.roots.iter().copied().chain(0..node_sizes.len()) {
        if state[start] == 2 {
            continue;
        }
        let mut work = vec![(start, false)];
        while let Some((node, children_visited)) = work.pop() {
            if children_visited {
                let children = tree.children.of(node);
                if !children.is_empty() {
                    let child_height: f32 = children.iter().map(|child| heights[*child]).sum();
                    let gaps = children.len().saturating_sub(1) as f32 * v_gap;
                    heights[node] = (child_height + gaps).max(heights[node]);
                }
                state[node] = 2;
                continue;
            }
            if state[node] != 0 {
                continue;
            }
            state[node] = 1;
            work.push((node, true));
            for child in tree.children.of(node).iter().rev() {
                if state[*child] == 0 {
                    work.push((*child, false));
                }
            }
        }
    }

    heights
}

#[allow(clippy::too_many_arguments)]
fn mindmap_place_subtree(
    node: usize,
    x_parent: f32,
    y_center: f32,
    is_left: bool,
    tree: &TreeLayoutStructure,
    node_sizes: &[(f32, f32)],
    subtree_heights: &[f32],
    h_gap: f32,
    v_gap: f32,
    positions: &mut [(f32, f32)],
    is_left_arr: &mut [bool],
) {
    let mut work = vec![(node, x_parent, y_center, is_left)];
    while let Some((node, x_parent, y_center, is_left)) = work.pop() {
        let (node_width, node_height) = node_sizes[node];
        let x = if is_left {
            x_parent - h_gap - node_width
        } else {
            x_parent + h_gap
        };
        positions[node] = (x, y_center - node_height * 0.5);
        is_left_arr[node] = is_left;

        let children = tree.children.of(node);
        if children.is_empty() {
            continue;
        }
        let total_children_height: f32 = children
            .iter()
            .map(|child| subtree_heights[*child])
            .sum::<f32>()
            + children.len().saturating_sub(1) as f32 * v_gap;
        let next_x_parent = if is_left { x } else { x + node_width };
        let mut next_y = y_center + total_children_height * 0.5;

        // Reverse insertion preserves the recursive routine's source-order traversal when popped.
        for child in children.iter().rev() {
            let child_height = subtree_heights[*child];
            let child_center_y = next_y - child_height * 0.5;
            work.push((*child, next_x_parent, child_center_y, is_left));
            next_y -= child_height + v_gap;
        }
    }
}

/// Experimental bilateral mindmap layout. The default radial dispatch remains authoritative until
/// this geometry is admitted by the committed layout and renderer equivalence gates.
#[must_use]
pub fn layout_diagram_mindmap_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let mut trace = LayoutTrace::default();
    let metrics = fm_core::FontMetrics::default_metrics();
    let node_sizes = compute_node_sizes(ir, &metrics);
    let node_count = ir.nodes.len();
    let spacing = LayoutSpacing::default();

    if node_count == 0 {
        return TracedLayout {
            layout: Arc::new(DiagramLayout {
                nodes: Vec::new(),
                clusters: Vec::new(),
                cycle_clusters: Vec::new(),
                edges: Vec::new(),
                bounds: LayoutRect {
                    x: 0.0,
                    y: 0.0,
                    width: 0.0,
                    height: 0.0,
                },
                stats: LayoutStats::default(),
                extensions: LayoutExtensions::default(),
                dirty_regions: Vec::new(),
            }),
            trace,
        };
    }

    let tree = build_tree_layout_structure(ir);
    let root_idx = tree.roots.first().copied().unwrap_or(0);
    let mut root_branches = tree.children.of(root_idx).to_vec();
    root_branches.extend(tree.roots.iter().copied().filter(|root| *root != root_idx));
    let subtree_heights = mindmap_subtree_heights(&tree, &node_sizes, 22.0);

    let num_branches = root_branches.len();
    let right_count = num_branches.div_ceil(2);
    let right_branches = &root_branches[..right_count];
    let left_branches = &root_branches[right_count..];

    let v_gap = 22.0_f32;
    let h_gap = 52.0_f32;

    let mut node_positions = vec![(0.0_f32, 0.0_f32); node_count];
    let mut node_is_left = vec![false; node_count];

    let right_total_h: f32 = right_branches
        .iter()
        .map(|branch| subtree_heights[*branch])
        .sum::<f32>()
        + (right_branches.len().saturating_sub(1) as f32 * v_gap);

    let left_total_h: f32 = left_branches
        .iter()
        .map(|branch| subtree_heights[*branch])
        .sum::<f32>()
        + (left_branches.len().saturating_sub(1) as f32 * v_gap);

    let max_side_h = right_total_h.max(left_total_h);

    let (rw, rh) = node_sizes[root_idx];
    let root_x = 0.0_f32;
    let root_y = (max_side_h - rh) * 0.5;
    node_positions[root_idx] = (root_x, root_y);
    node_is_left[root_idx] = false;

    // Place right branches
    let mut curr_y = (max_side_h - right_total_h) * 0.5;
    for branch in right_branches {
        let bh = subtree_heights[*branch];
        let b_center_y = curr_y + bh * 0.5;
        mindmap_place_subtree(
            *branch,
            root_x + rw,
            b_center_y,
            false,
            &tree,
            &node_sizes,
            &subtree_heights,
            h_gap,
            v_gap,
            &mut node_positions,
            &mut node_is_left,
        );
        curr_y += bh + v_gap;
    }

    // Place left branches
    let mut curr_y = (max_side_h - left_total_h) * 0.5;
    for branch in left_branches {
        let bh = subtree_heights[*branch];
        let b_center_y = curr_y + bh * 0.5;
        mindmap_place_subtree(
            *branch,
            root_x,
            b_center_y,
            true,
            &tree,
            &node_sizes,
            &subtree_heights,
            h_gap,
            v_gap,
            &mut node_positions,
            &mut node_is_left,
        );
        curr_y += bh + v_gap;
    }

    let min_x = node_positions
        .iter()
        .map(|(x, _)| *x)
        .fold(f32::INFINITY, f32::min);
    let min_y = node_positions
        .iter()
        .map(|(_, y)| *y)
        .fold(f32::INFINITY, f32::min);
    let offset_x = 60.0 - min_x;
    let offset_y = 60.0 - min_y;

    let mut nodes = Vec::with_capacity(node_count);
    for (i, node) in ir.nodes.iter().enumerate() {
        let (w, h) = node_sizes[i];
        let (x, y) = node_positions[i];
        nodes.push(LayoutNodeBox {
            node_index: i,
            node_id: node.id.clone(),
            span: node.span_primary,
            bounds: LayoutRect {
                x: x + offset_x,
                y: y + offset_y,
                width: w,
                height: h,
            },
            rank: tree.depth.get(i).copied().unwrap_or(0),
            order: i,
        });
    }

    let edges: Vec<LayoutEdgePath> = ir
        .edges
        .iter()
        .enumerate()
        .filter_map(|(ei, edge)| {
            let from_idx = endpoint_node_index(ir, edge.from)?;
            let to_idx = endpoint_node_index(ir, edge.to)?;
            if from_idx >= nodes.len() || to_idx >= nodes.len() {
                return None;
            }
            let from_box = &nodes[from_idx];
            let to_box = &nodes[to_idx];
            let is_left = node_is_left[to_idx];

            let (from_pt, to_pt) = if is_left {
                (
                    LayoutPoint {
                        x: from_box.bounds.x,
                        y: from_box.bounds.y + from_box.bounds.height * 0.5,
                    },
                    LayoutPoint {
                        x: to_box.bounds.x + to_box.bounds.width,
                        y: to_box.bounds.y + to_box.bounds.height * 0.5,
                    },
                )
            } else {
                (
                    LayoutPoint {
                        x: from_box.bounds.x + from_box.bounds.width,
                        y: from_box.bounds.y + from_box.bounds.height * 0.5,
                    },
                    LayoutPoint {
                        x: to_box.bounds.x,
                        y: to_box.bounds.y + to_box.bounds.height * 0.5,
                    },
                )
            };

            let dx = (to_pt.x - from_pt.x).abs() * 0.5;
            let cp1 = if is_left {
                LayoutPoint {
                    x: from_pt.x - dx,
                    y: from_pt.y,
                }
            } else {
                LayoutPoint {
                    x: from_pt.x + dx,
                    y: from_pt.y,
                }
            };
            let cp2 = if is_left {
                LayoutPoint {
                    x: to_pt.x + dx,
                    y: to_pt.y,
                }
            } else {
                LayoutPoint {
                    x: to_pt.x - dx,
                    y: to_pt.y,
                }
            };

            let points = smallvec::smallvec![from_pt, cp1, cp2, to_pt];

            Some(LayoutEdgePath {
                edge_index: ei,
                span: edge.span,
                points,
                reversed: false,
                is_self_loop: false,
                parallel_offset: 0.0,
                bundle_count: 1,
                bundled: false,
            })
        })
        .collect();

    let clusters = build_cluster_boxes(ir, &nodes, spacing, &metrics);
    let bounds = compute_bounds(&nodes, &clusters, &edges, spacing);
    let (total_edge_length, reversed_edge_total_length) = compute_edge_length_metrics(&edges);
    push_snapshot(&mut trace, "mindmap_layout", node_count, edges.len(), 0, 0);
    let stats = LayoutStats {
        node_count,
        edge_count: edges.len(),
        reversed_edge_total_length,
        total_edge_length,
        phase_iterations: trace.snapshots.len(),
        ..LayoutStats::default()
    };

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters,
            cycle_clusters: Vec::new(),
            edges,
            bounds,
            stats,
            extensions: LayoutExtensions::default(),
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

#[must_use]
pub fn layout_diagram_timeline(ir: &MermaidDiagramIr) -> DiagramLayout {
    Arc::unwrap_or_clone(layout_diagram_timeline_traced(ir).layout)
}

#[must_use]
pub fn layout_diagram_timeline_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let node_count = ir.nodes.len();
    let node_sizes = compute_node_sizes(ir, &fm_core::FontMetrics::default_metrics());
    let mut trace = LayoutTrace::default();
    push_snapshot(
        &mut trace,
        "timeline_layout",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    let spacing = LayoutSpacing::default();
    let mut rank_by_node = vec![0_usize; node_count];
    let mut order_by_node = vec![0_usize; node_count];
    let mut centers = vec![(0.0_f32, 0.0_f32); node_count];

    let mut period_indexes: Vec<usize> = ir
        .nodes
        .iter()
        .enumerate()
        .filter(|(_, node)| matches!(node.shape, fm_core::NodeShape::Rect))
        .map(|(node_index, _)| node_index)
        .collect();
    if period_indexes.is_empty() {
        period_indexes = (0..node_count).collect();
    }
    period_indexes.sort_by(|left, right| compare_node_indices(ir, *left, *right));

    // `period_set` / `events_by_period` are read by membership/key only (never iterated for output
    // order — the layout order comes from `period_indexes` below), so `FxHash*` replaces the
    // `BTreeSet`/`BTreeMap`'s O(log N) inserts/lookups + per-node B-tree allocations (the `BTreeMap<usize,
    // …>::insert` was ~9% of timeline layout) with O(1) hashing. `values_mut()` only sorts each Vec
    // independently, so iteration order there is irrelevant. Byte-identical output.
    let period_set: FxHashSet<usize> = period_indexes.iter().copied().collect();
    let mut events_by_period: FxHashMap<usize, Vec<usize>> = FxHashMap::default();
    for edge in &ir.edges {
        let Some(source) = endpoint_node_index(ir, edge.from) else {
            continue;
        };
        let Some(target) = endpoint_node_index(ir, edge.to) else {
            continue;
        };
        if period_set.contains(&source) && !period_set.contains(&target) {
            events_by_period.entry(source).or_default().push(target);
        }
    }
    for targets in events_by_period.values_mut() {
        targets.sort_by(|left, right| compare_node_indices(ir, *left, *right));
        targets.dedup();
    }

    let period_gap_x = spacing.rank_spacing + 104.0;
    let event_gap_y = spacing.node_spacing + 22.0;
    // Membership set (`.insert` returns the same newly-inserted bool, `.contains` the same result); never
    // iterated, so `FxHashSet` is byte-identical and skips the BTreeSet's O(log N) inserts + node allocs.
    let mut assigned: FxHashSet<usize> = FxHashSet::default();

    for (period_order, period_index) in period_indexes.iter().enumerate() {
        let x = period_order as f32 * period_gap_x;
        centers[*period_index] = (x, 0.0);
        rank_by_node[*period_index] = 0;
        order_by_node[*period_index] = period_order;
        assigned.insert(*period_index);

        let mut event_row = 1_usize;
        if let Some(targets) = events_by_period.get(period_index) {
            for target in targets {
                if assigned.insert(*target) {
                    centers[*target] = (x, (event_row as f32).mul_add(event_gap_y, 48.0));
                    rank_by_node[*target] = event_row;
                    order_by_node[*target] = period_order;
                    event_row = event_row.saturating_add(1);
                }
            }
        }
    }

    let period_count = period_indexes.len().max(1);
    let mut spill = 0_usize;
    let mut leftovers: Vec<usize> = (0..node_count)
        .filter(|node_index| !assigned.contains(node_index))
        .collect();
    leftovers.sort_by(|left, right| compare_node_indices(ir, *left, *right));
    for node_index in leftovers {
        let col = spill % period_count;
        let row = spill / period_count;
        centers[node_index] = (col as f32 * period_gap_x, (4.0 + row as f32) * event_gap_y);
        rank_by_node[node_index] = row.saturating_add(1);
        order_by_node[node_index] = col;
        spill = spill.saturating_add(1);
    }

    let mut traced = finalize_specialized_layout(
        ir,
        &node_sizes,
        &rank_by_node,
        &order_by_node,
        centers,
        trace,
        true,
    );
    // Axis tick x-positions via a node_index -> center_x map (was a linear `layout.nodes.iter().find`
    // PER period_index — and the timeline gives most events a distinct period, so `period_indexes ≈ nodes`,
    // making this O(N²), ~half of timeline layout). One O(N) pass builds the map; owned `f32` values so the
    // subsequent `traced.layout.extensions` write doesn't conflict with a borrow of `traced.layout.nodes`.
    // Byte-identical: same center_x per node_index, same label, same `period_indexes` order (a node_index
    // absent from the map — i.e. not in `layout.nodes` — is dropped, exactly like the old `find`'s `None`).
    let center_x_by_index: FxHashMap<usize, f32> = traced
        .layout
        .nodes
        .iter()
        .map(|node| (node.node_index, node.bounds.center().x))
        .collect();
    // Freshly built by `finalize_specialized_layout` (refcount 1), so `make_mut` is a
    // clone-free borrow that lets us attach the timeline extensions in place.
    let layout = Arc::make_mut(&mut traced.layout);
    layout.extensions.axis_ticks = period_indexes
        .into_iter()
        .filter_map(|node_index| {
            let position = *center_x_by_index.get(&node_index)?;
            Some(LayoutAxisTick {
                label: layout_label_text(ir, node_index).to_string(),
                position,
            })
        })
        .collect();
    layout.extensions.bands = layout
        .clusters
        .iter()
        .filter_map(|cluster| {
            let title = ir
                .clusters
                .get(cluster.cluster_index)
                .and_then(|cluster| cluster.title)
                .and_then(|label_id| ir.labels.get(label_id.0))
                .map(|label| label.text.clone())?;
            Some(LayoutBand {
                kind: LayoutBandKind::Section,
                label: title,
                bounds: cluster.bounds,
            })
        })
        .collect();
    traced
}

// ---------------------------------------------------------------------------
// Sequence diagram layout
// ---------------------------------------------------------------------------

/// Lay out a sequence diagram with participants arranged horizontally and
/// messages stacked vertically in declaration order.
#[must_use]
pub fn layout_diagram_sequence(ir: &MermaidDiagramIr) -> DiagramLayout {
    Arc::unwrap_or_clone(layout_diagram_sequence_traced(ir).layout)
}

#[must_use]
pub fn layout_diagram_sequence_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let node_count = ir.nodes.len();
    let node_sizes = compute_node_sizes(ir, &fm_core::FontMetrics::default_metrics());
    let mut trace = LayoutTrace::default();
    push_snapshot(
        &mut trace,
        "sequence_layout",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    if node_count == 0 {
        return TracedLayout {
            layout: Arc::new(DiagramLayout {
                nodes: Vec::new(),
                clusters: Vec::new(),
                cycle_clusters: Vec::new(),
                edges: Vec::new(),
                bounds: LayoutRect {
                    x: 0.0,
                    y: 0.0,
                    width: 0.0,
                    height: 0.0,
                },
                stats: LayoutStats::default(),
                extensions: LayoutExtensions::default(),
                dirty_regions: Vec::new(),
            }),
            trace,
        };
    }

    let spacing = LayoutSpacing::default();

    // ── Phase 1: identify participants (declaration order) ──────────────
    // Participants are the nodes; edges are messages between them.
    // Preserve the declaration order from the parser which already sorted
    // participants by first appearance.
    let participant_gap = spacing.node_spacing + spacing.sequence_participant_gap_extra;
    let message_gap = spacing.rank_spacing.max(spacing.sequence_min_message_gap);
    let header_y = 0.0_f32;
    let mirror_actors_enabled = ir.meta.init.config.sequence_mirror_actors.unwrap_or(false)
        && !ir
            .sequence_meta
            .as_ref()
            .is_some_and(|meta| meta.hide_footbox);

    // Build participant index → horizontal position mapping.
    // Each participant is centered at (participant_order * gap, header_y).
    let mut rank_by_node = vec![0_usize; node_count];
    let mut order_by_node = vec![0_usize; node_count];
    let mut centers = vec![(0.0_f32, 0.0_f32); node_count];

    // Compute cumulative x positions accounting for individual node widths.
    let mut x_cursor = 0.0_f32;
    let mut participant_x_centers: Vec<f32> = Vec::with_capacity(node_count);
    for (participant_order, (width, _height)) in node_sizes.iter().copied().enumerate() {
        let half_width = width / 2.0;
        let cx = x_cursor + half_width;
        participant_x_centers.push(cx);
        centers[participant_order] = (cx, header_y);
        rank_by_node[participant_order] = 0;
        order_by_node[participant_order] = participant_order;
        x_cursor = cx + half_width + participant_gap;
        let _ = participant_order; // suppress unused
    }

    // ── Phase 2: compute message (edge) row positions ──────────────────
    // Each edge occupies a vertical row below the participant header.
    // The y-position increases with each message in declaration order.
    // Edges reference node indices for from/to; the x-coordinate of each
    // endpoint is determined by the participant's center x.
    //
    // For self-messages (from == to), we add extra vertical space.
    let first_message_y =
        header_y + node_sizes.iter().map(|(_, h)| *h).fold(0.0_f32, f32::max) + message_gap;

    let mut message_y_positions: Vec<f32> = Vec::with_capacity(ir.edges.len());
    let mut y_cursor = first_message_y;
    for edge in &ir.edges {
        message_y_positions.push(y_cursor);
        let is_self = match (
            endpoint_node_index(ir, edge.from),
            endpoint_node_index(ir, edge.to),
        ) {
            (Some(s), Some(t)) => s == t,
            _ => false,
        };
        // Self-messages need more vertical space for the loop.
        let row_height = if is_self {
            message_gap * 1.5
        } else {
            message_gap
        };
        y_cursor += row_height;
    }

    // Total sequence content height before optional mirrored participant headers.
    let lifeline_bottom = message_gap.mul_add(0.5, y_cursor);

    // ── Phase 3: build layout nodes (participant boxes at the top) ──────
    let nodes: Vec<LayoutNodeBox> = (0..node_count)
        .map(|participant_order| {
            let (width, height) = node_sizes[participant_order];
            let cx = participant_x_centers[participant_order];
            LayoutNodeBox {
                node_index: participant_order,
                node_id: ir.nodes[participant_order].id.clone(),
                rank: 0,
                order: participant_order,
                span: ir.nodes[participant_order].span_primary,
                bounds: LayoutRect {
                    x: cx - width / 2.0,
                    y: header_y,
                    width,
                    height,
                },
            }
        })
        .collect();

    // ── Phase 4: build edge paths ──────────────────────────────────────
    // Each message is a horizontal arrow from sender lifeline to receiver
    // lifeline at the corresponding y-position.
    let edges: Vec<LayoutEdgePath> = ir
        .edges
        .iter()
        .enumerate()
        .map(|(edge_index, edge)| {
            let y = message_y_positions[edge_index];
            let source_index = endpoint_node_index(ir, edge.from).unwrap_or(0);
            let target_index = endpoint_node_index(ir, edge.to).unwrap_or(0);
            let source_x = participant_x_centers
                .get(source_index)
                .copied()
                .unwrap_or(0.0);
            let target_x = participant_x_centers
                .get(target_index)
                .copied()
                .unwrap_or(0.0);
            let is_self_loop = source_index == target_index;

            let points = if is_self_loop {
                // Self-message: draw a loop to the right and back.
                let loop_width = spacing.sequence_self_loop_width;
                let loop_height = message_gap * 0.6;
                smallvec![
                    LayoutPoint { x: source_x, y },
                    LayoutPoint {
                        x: source_x + loop_width,
                        y,
                    },
                    LayoutPoint {
                        x: source_x + loop_width,
                        y: y + loop_height,
                    },
                    LayoutPoint {
                        x: source_x,
                        y: y + loop_height,
                    },
                ]
            } else {
                smallvec![
                    LayoutPoint { x: source_x, y },
                    LayoutPoint { x: target_x, y },
                ]
            };

            LayoutEdgePath {
                edge_index,
                span: edge.span,
                points,
                reversed: false,
                is_self_loop,
                parallel_offset: 0.0,
                bundle_count: 1,
                bundled: false,
            }
        })
        .collect();

    // ── Phase 5: compute bounds and extensions ─────────────────────────
    let total_width = if node_count > 0 {
        let last_cx = participant_x_centers[node_count - 1];
        let last_half_w = node_sizes[node_count - 1].0 / 2.0;
        last_cx + last_half_w
    } else {
        0.0
    };

    push_snapshot(
        &mut trace,
        "sequence_post_processing",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    let (total_edge_length, reversed_edge_total_length) = compute_edge_length_metrics(&edges);

    let stats = LayoutStats {
        node_count,
        edge_count: ir.edges.len(),
        crossing_count: 0,
        crossing_count_before_refinement: 0,
        reversed_edges: 0,
        cycle_count: 0,
        cycle_node_count: 0,
        max_cycle_size: 0,
        collapsed_clusters: 0,
        reversed_edge_total_length,
        total_edge_length,
        phase_iterations: trace.snapshots.len(),
    };

    // Build lifeline bands: one vertical band per participant from header bottom
    // to diagram bottom, useful for renderers that draw dashed lifelines.
    let mut lifeline_start_y = vec![0.0_f32; node_count];
    let max_header_height = node_sizes.iter().map(|(_, h)| *h).fold(0.0_f32, f32::max);
    let mirror_header_gap = if mirror_actors_enabled {
        message_gap * 0.35
    } else {
        0.0
    };
    let mirror_header_y = lifeline_bottom + mirror_header_gap;
    let diagram_bottom = if mirror_actors_enabled {
        mirror_header_y + max_header_height
    } else {
        lifeline_bottom
    };
    let mut lifeline_end_y = vec![
        if mirror_actors_enabled {
            mirror_header_y
        } else {
            lifeline_bottom
        };
        node_count
    ];
    for participant_order in 0..node_count {
        let (_, header_height) = node_sizes[participant_order];
        lifeline_start_y[participant_order] = header_y + header_height;
    }

    let mut destroy_marker_participants = vec![false; node_count];
    if let Some(meta) = &ir.sequence_meta {
        for event in &meta.lifecycle_events {
            let participant_index = event.participant.0;
            if participant_x_centers.get(participant_index).is_none() {
                continue;
            }
            let event_y =
                message_y_positions
                    .get(event.at_edge)
                    .copied()
                    .unwrap_or(match event.kind {
                        fm_core::LifecycleEventKind::Create => first_message_y,
                        fm_core::LifecycleEventKind::Destroy => lifeline_bottom,
                    });

            match event.kind {
                fm_core::LifecycleEventKind::Create => {
                    if let Some(start_y) = lifeline_start_y.get_mut(participant_index) {
                        *start_y = (*start_y).max(event_y);
                    }
                }
                fm_core::LifecycleEventKind::Destroy => {
                    if let Some(end_y) = lifeline_end_y.get_mut(participant_index) {
                        *end_y = (*end_y).min(event_y);
                        destroy_marker_participants[participant_index] = true;
                    }
                }
            }
        }
    }

    for participant_order in 0..node_count {
        if lifeline_end_y[participant_order] < lifeline_start_y[participant_order] {
            lifeline_end_y[participant_order] = lifeline_start_y[participant_order];
        }
    }

    let mut lifecycle_markers = Vec::new();
    for participant_order in 0..node_count {
        if !destroy_marker_participants[participant_order] {
            continue;
        }
        let cx = participant_x_centers[participant_order];
        lifecycle_markers.push(LayoutSequenceLifecycleMarker {
            participant_index: participant_order,
            kind: LayoutSequenceLifecycleMarkerKind::Destroy,
            center: LayoutPoint {
                x: cx,
                y: lifeline_end_y[participant_order],
            },
            size: 12.0,
        });
    }

    let lifeline_bands: Vec<LayoutBand> = (0..node_count)
        .map(|participant_order| {
            let cx = participant_x_centers[participant_order];
            let start_y = lifeline_start_y[participant_order];
            let end_y = lifeline_end_y[participant_order];
            LayoutBand {
                kind: LayoutBandKind::Lane,
                label: layout_label_text(ir, participant_order).to_string(),
                bounds: LayoutRect {
                    x: cx - 1.0,
                    y: start_y,
                    width: 2.0,
                    height: (end_y - start_y).max(0.0),
                },
            }
        })
        .collect();

    // Build activation bars from sequence metadata.
    let activation_bars: Vec<LayoutActivationBar> = ir
        .sequence_meta
        .as_ref()
        .map(|meta| {
            meta.activations
                .iter()
                .filter_map(|activation| {
                    let participant_index = activation.participant.0;
                    let cx = participant_x_centers.get(participant_index).copied()?;
                    let start_y = message_y_positions
                        .get(activation.start_edge)
                        .copied()
                        .unwrap_or(first_message_y);
                    let end_y = message_y_positions
                        .get(activation.end_edge)
                        .copied()
                        .unwrap_or(lifeline_bottom);
                    let bar_width = spacing.sequence_activation_width;
                    let depth_offset = activation.depth as f32 * 4.0;
                    Some(LayoutActivationBar {
                        participant_index,
                        depth: activation.depth,
                        bounds: LayoutRect {
                            x: cx - bar_width / 2.0 + depth_offset,
                            y: start_y,
                            width: bar_width,
                            height: (end_y - start_y).max(message_gap * 0.3),
                        },
                    })
                })
                .collect()
        })
        .unwrap_or_default();

    let participant_group_clusters: Vec<LayoutClusterBox> = ir
        .sequence_meta
        .as_ref()
        .map(|meta| {
            meta.participant_groups
                .iter()
                .enumerate()
                .filter_map(|(group_index, group)| {
                    let member_indexes: Vec<usize> = group
                        .participants
                        .iter()
                        .map(|participant| participant.0)
                        .collect();
                    let first_member = member_indexes.first().copied()?;
                    let last_member = member_indexes.last().copied()?;
                    let first_box = nodes.get(first_member)?;
                    let last_box = nodes.get(last_member)?;

                    let x_padding = spacing.cluster_padding * 0.45;
                    let top_padding = spacing.cluster_padding * 0.7;
                    let bottom_padding = spacing.cluster_padding * 0.3;
                    let min_x = first_box.bounds.x - x_padding;
                    let max_x = last_box.bounds.x + last_box.bounds.width + x_padding;
                    let min_y = header_y - top_padding;
                    let max_y = diagram_bottom + bottom_padding;

                    Some(LayoutClusterBox {
                        cluster_index: group_index,
                        span: Span::default(),
                        title: (!group.label.is_empty()).then_some(group.label.clone()),
                        color: group.color.clone(),
                        bounds: LayoutRect {
                            x: min_x,
                            y: min_y,
                            width: max_x - min_x,
                            height: max_y - min_y,
                        },
                    })
                })
                .collect()
        })
        .unwrap_or_default();

    let cluster_bounds =
        participant_group_clusters
            .iter()
            .fold(None::<(f32, f32, f32, f32)>, |acc, cluster| {
                let cluster_max_x = cluster.bounds.x + cluster.bounds.width;
                let cluster_max_y = cluster.bounds.y + cluster.bounds.height;
                Some(match acc {
                    Some((min_x, min_y, max_x, max_y)) => (
                        min_x.min(cluster.bounds.x),
                        min_y.min(cluster.bounds.y),
                        max_x.max(cluster_max_x),
                        max_y.max(cluster_max_y),
                    ),
                    None => (
                        cluster.bounds.x,
                        cluster.bounds.y,
                        cluster_max_x,
                        cluster_max_y,
                    ),
                })
            });

    let bounds = if let Some((cluster_min_x, cluster_min_y, cluster_max_x, cluster_max_y)) =
        cluster_bounds
    {
        let min_x = cluster_min_x.min(0.0);
        let min_y = cluster_min_y.min(0.0);
        LayoutRect {
            x: min_x,
            y: min_y,
            width: total_width.max(cluster_max_x) - min_x,
            height: diagram_bottom.max(cluster_max_y) - min_y,
        }
    } else {
        LayoutRect {
            x: 0.0,
            y: 0.0,
            width: total_width,
            height: diagram_bottom,
        }
    };

    let sequence_mirror_headers: Vec<LayoutNodeBox> = if mirror_actors_enabled {
        (0..node_count)
            .map(|participant_order| {
                let (width, height) = node_sizes[participant_order];
                let cx = participant_x_centers[participant_order];
                LayoutNodeBox {
                    node_index: participant_order,
                    node_id: ir.nodes[participant_order].id.clone(),
                    rank: 1,
                    order: participant_order,
                    span: ir.nodes[participant_order].span_primary,
                    bounds: LayoutRect {
                        x: cx - width / 2.0,
                        y: mirror_header_y,
                        width,
                        height,
                    },
                }
            })
            .collect()
    } else {
        Vec::new()
    };

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters: participant_group_clusters,
            cycle_clusters: Vec::new(),
            edges,
            bounds,
            stats,
            extensions: LayoutExtensions {
                bands: lifeline_bands,
                gantt_day_axis: None,
                axis_ticks: Vec::new(),
                gantt_axis_rows: Vec::new(),
                cluster_dividers: Vec::new(),
                activation_bars,
                sequence_notes: build_sequence_note_geometry(
                    ir,
                    &participant_x_centers,
                    &node_sizes,
                    &message_y_positions,
                    first_message_y,
                    message_gap,
                ),
                sequence_fragments: build_sequence_fragment_geometry(
                    ir,
                    &participant_x_centers,
                    &node_sizes,
                    &message_y_positions,
                    first_message_y,
                    diagram_bottom,
                    message_gap,
                ),
                sequence_lifecycle_markers: lifecycle_markers,
                sequence_mirror_headers,
                node_centrality: Vec::new(),
                gantt_task_labels: Vec::new(),
                packet_field_continuations: Vec::new(),
                state_notes: Vec::new(),
            },
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

fn build_sequence_note_geometry(
    ir: &MermaidDiagramIr,
    participant_x_centers: &[f32],
    node_sizes: &[(f32, f32)],
    message_y_positions: &[f32],
    first_message_y: f32,
    message_gap: f32,
) -> Vec<LayoutSequenceNote> {
    let Some(meta) = &ir.sequence_meta else {
        return Vec::new();
    };
    let default_note_width = 120.0_f32;
    let note_line_height = 16.0_f32;
    let note_vertical_padding = 12.0_f32;
    let base_note_height = message_gap * 0.7;
    // Average character width estimate for note sizing (matches FontMetrics default sans-serif).
    let avg_char_w = 8.25_f32;

    meta.notes
        .iter()
        .map(|note| {
            let line_count = note.text.lines().count().max(1) as f32;
            let note_height = if line_count <= 1.0 {
                base_note_height
            } else {
                (line_count - 1.0).mul_add(note_line_height, base_note_height)
                    + note_vertical_padding
            };
            // Adaptive note width from content: use the widest line + padding.
            let max_line_chars = note
                .text
                .lines()
                .map(|line| line.chars().count())
                .max()
                .unwrap_or(0);
            let note_width = (max_line_chars as f32)
                .mul_add(avg_char_w, 24.0)
                .clamp(80.0, default_note_width * 2.5);

            // Position the note at the edge after which it appears.
            let y = message_y_positions
                .get(note.after_edge)
                .copied()
                .unwrap_or((note.after_edge as f32).mul_add(message_gap, first_message_y));

            // Determine x position based on participants and note position.
            let first_pid = note.participants.first().map_or(0, |p| p.0);
            let last_pid = note.participants.last().map_or(first_pid, |p| p.0);
            let first_cx = participant_x_centers.get(first_pid).copied().unwrap_or(0.0);
            let last_cx = participant_x_centers
                .get(last_pid)
                .copied()
                .unwrap_or(first_cx);
            let first_half_w = node_sizes.get(first_pid).map_or(50.0, |(w, _)| w / 2.0);

            let x = match note.position {
                fm_core::NotePosition::LeftOf => first_cx - first_half_w - note_width - 10.0,
                fm_core::NotePosition::RightOf => {
                    let last_half_w = node_sizes.get(last_pid).map_or(50.0, |(w, _)| w / 2.0);
                    last_cx + last_half_w + 10.0
                }
                fm_core::NotePosition::Over => {
                    let span_width = (last_cx - first_cx).abs() + note_width;
                    let center = f32::midpoint(first_cx, last_cx);
                    center - span_width / 2.0
                }
            };

            let w = match note.position {
                fm_core::NotePosition::Over if first_pid != last_pid => {
                    (last_cx - first_cx).abs() + note_width
                }
                _ => note_width,
            };

            LayoutSequenceNote {
                position: note.position,
                text: note.text.clone(),
                bounds: LayoutRect {
                    x,
                    y: y - note_height / 2.0,
                    width: w,
                    height: note_height,
                },
            }
        })
        .collect()
}

fn build_sequence_fragment_geometry(
    ir: &MermaidDiagramIr,
    participant_x_centers: &[f32],
    node_sizes: &[(f32, f32)],
    message_y_positions: &[f32],
    first_message_y: f32,
    diagram_bottom: f32,
    message_gap: f32,
) -> Vec<LayoutSequenceFragment> {
    let Some(meta) = &ir.sequence_meta else {
        return Vec::new();
    };

    let total_width = if participant_x_centers.is_empty() {
        200.0
    } else {
        let last_idx = participant_x_centers.len() - 1;
        let last_cx = participant_x_centers[last_idx];
        let last_half_w = node_sizes.get(last_idx).map_or(50.0, |(w, _)| w / 2.0);
        last_cx + last_half_w
    };

    meta.fragments
        .iter()
        .map(|fragment| {
            let start_y = message_y_positions
                .get(fragment.start_edge)
                .copied()
                .unwrap_or(first_message_y);
            let end_y = message_y_positions
                .get(fragment.end_edge)
                .copied()
                .unwrap_or(message_gap.mul_add(-0.5, diagram_bottom));

            let padding = message_gap * 0.35;
            LayoutSequenceFragment {
                kind: fragment.kind,
                label: fragment.label.clone(),
                color: fragment.color.clone(),
                bounds: LayoutRect {
                    x: -padding,
                    y: message_gap.mul_add(-0.3, start_y),
                    width: total_width + padding * 2.0,
                    height: message_gap
                        .mul_add(0.6, end_y - start_y)
                        .max(message_gap * 0.5),
                },
            }
        })
        .collect()
}

#[must_use]
pub fn layout_diagram_gantt(ir: &MermaidDiagramIr) -> DiagramLayout {
    Arc::unwrap_or_clone(layout_diagram_gantt_traced(ir).layout)
}

#[must_use]
pub fn layout_diagram_gantt_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    if let Some(gantt_meta) = ir.gantt_meta.as_ref().filter(|meta| !meta.tasks.is_empty()) {
        return layout_diagram_gantt_from_meta(ir, gantt_meta);
    }

    layout_diagram_gantt_fallback(ir)
}

fn layout_diagram_gantt_fallback(ir: &MermaidDiagramIr) -> TracedLayout {
    let node_count = ir.nodes.len();
    let mut node_sizes = compute_node_sizes(ir, &fm_core::FontMetrics::default_metrics());
    let mut trace = LayoutTrace::default();
    push_snapshot(&mut trace, "gantt_layout", node_count, ir.edges.len(), 0, 0);

    for size in &mut node_sizes {
        size.0 = size.0.max(156.0);
        size.1 = size.1.max(40.0);
    }

    let mut section_to_nodes: BTreeMap<String, Vec<usize>> = BTreeMap::new();
    let mut order_hint_by_node: BTreeMap<usize, usize> = BTreeMap::new();
    for node_index in 0..node_count {
        let label = layout_label_text(ir, node_index);
        let section = label
            .split_once(':')
            .map(|(prefix, _)| prefix.trim())
            .filter(|prefix| !prefix.is_empty())
            .unwrap_or("Backlog")
            .to_string();
        section_to_nodes
            .entry(section)
            .or_default()
            .push(node_index);
        order_hint_by_node.insert(
            node_index,
            parse_order_hint(&ir.nodes[node_index].id, node_index),
        );
    }

    for nodes in section_to_nodes.values_mut() {
        nodes.sort_by(|left, right| {
            order_hint_by_node[left]
                .cmp(&order_hint_by_node[right])
                .then_with(|| compare_node_indices(ir, *left, *right))
        });
    }

    let mut ordered_hints: Vec<usize> = order_hint_by_node.values().copied().collect();
    ordered_hints.sort_unstable();
    ordered_hints.dedup();
    let slot_by_hint: BTreeMap<usize, usize> = ordered_hints
        .iter()
        .copied()
        .enumerate()
        .map(|(slot, hint)| (hint, slot))
        .collect();

    let spacing = LayoutSpacing::default();
    let mut rank_by_node = vec![0_usize; node_count];
    let mut order_by_node = vec![0_usize; node_count];
    let mut centers = vec![(0.0_f32, 0.0_f32); node_count];

    let col_gap = spacing.rank_spacing + 144.0;
    let row_gap = spacing.node_spacing.mul_add(0.72, 24.0);
    let mut section_base_y = 0.0_f32;

    for (section_index, (_section, nodes)) in section_to_nodes.iter().enumerate() {
        for (row_index, node_index) in nodes.iter().enumerate() {
            let slot = slot_by_hint[&order_hint_by_node[node_index]];
            centers[*node_index] = (
                slot as f32 * col_gap,
                (row_index as f32).mul_add(row_gap, section_base_y),
            );
            rank_by_node[*node_index] = slot;
            order_by_node[*node_index] = row_index + section_index * 128;
        }
        section_base_y += (nodes.len().max(1) as f32).mul_add(row_gap, 56.0);
    }

    let mut traced = finalize_specialized_layout(
        ir,
        &node_sizes,
        &rank_by_node,
        &order_by_node,
        centers,
        trace,
        true,
    );
    // Freshly built by `finalize_specialized_layout` (refcount 1) ⇒ clone-free `make_mut`.
    let layout = Arc::make_mut(&mut traced.layout);
    layout.extensions.axis_ticks = ordered_hints
        .iter()
        .enumerate()
        .filter_map(|(slot, hint)| {
            let node = layout.nodes.iter().find(|node| node.rank == slot)?;
            Some(LayoutAxisTick {
                label: hint.to_string(),
                position: node.bounds.center().x,
            })
        })
        .collect();
    layout.extensions.bands = section_to_nodes
        .iter()
        .filter_map(|(section, node_indexes)| {
            let bounds = layout_bounds_for_nodes(&*layout, node_indexes, 24.0)?;
            Some(LayoutBand {
                kind: LayoutBandKind::Section,
                label: section.clone(),
                bounds,
            })
        })
        .collect();
    let gantt_metrics = fm_core::FontMetrics::default_metrics();
    layout.extensions.gantt_task_labels = gantt_task_label_placements(ir, layout, &gantt_metrics);
    // A label placed outside its bar sits outside the node boxes `compute_bounds` measured, so the
    // canvas has to grow to hold it or it is clipped at the viewBox edge — which is exactly what made
    // the first attempt at this unshippable.
    extend_bounds_for_gantt_labels(layout);
    layout_gantt_axis_rows(layout, false);
    traced
}

fn layout_diagram_gantt_from_meta(ir: &MermaidDiagramIr, gantt_meta: &IrGanttMeta) -> TracedLayout {
    let node_count = ir.nodes.len();
    let mut node_sizes = compute_node_sizes(ir, &fm_core::FontMetrics::default_metrics());
    let mut trace = LayoutTrace::default();
    push_snapshot(&mut trace, "gantt_layout", node_count, ir.edges.len(), 0, 0);

    for size in &mut node_sizes {
        size.0 = size.0.max(156.0);
        size.1 = size.1.max(40.0);
    }

    let spacing = LayoutSpacing::default();
    let base_col_width = 48.0_f32;
    let row_gap = spacing.node_spacing.mul_add(0.72, 24.0);
    let section_gap = 56.0_f32;

    let mut rank_by_node = vec![0_usize; node_count];
    let mut order_by_node = vec![0_usize; node_count];
    let mut centers = vec![(0.0_f32, 0.0_f32); node_count];
    let mut section_to_nodes: BTreeMap<String, Vec<usize>> = BTreeMap::new();

    let task_count = gantt_meta.tasks.len();
    let mut explicit_starts = vec![None; task_count];
    let mut durations = vec![1_i32; task_count];
    let mut milestones = vec![false; task_count];
    // Lookup-only (built once below, read via `.get` for dependency resolution; never iterated — the
    // resolved order comes from the task list). An `FxHashMap` replaces the `BTreeMap<String, _>`'s
    // O(log N) String-comparison (memcmp) inserts/lookups with O(1) hashing — memcmp was ~25% of gantt
    // layout on the fixture's `after t{n-1}` dependency chain. Presized to task_count to avoid rehashing.
    // Keys BORROW from `gantt_meta` (which outlives this call) rather than owning per-task `String`
    // clones — the clone showed as ~3.5% of gantt layout. Byte-identical output.
    let mut task_id_to_idx: FxHashMap<&str, usize> =
        FxHashMap::with_capacity_and_hasher(task_count, Default::default());
    let excluded_dates = expand_gantt_excluded_dates(gantt_meta);
    let skip_weekends = gantt_meta
        .excludes
        .iter()
        .any(|exclude| matches!(exclude, GanttExclude::Weekends));
    let inclusive_end_dates = gantt_meta.inclusive_end_dates;

    for (task_idx, task) in gantt_meta.tasks.iter().enumerate() {
        explicit_starts[task_idx] = gantt_task_absolute_start(task);
        durations[task_idx] = gantt_task_duration_days(task, inclusive_end_dates);
        milestones[task_idx] = matches!(task.flags.primary_type(), GanttTaskType::Milestone)
            || durations[task_idx] == 0;
        if let Some(task_id) = task.task_id.as_ref() {
            task_id_to_idx.entry(task_id.as_str()).or_insert(task_idx);
        }
    }

    let base_start_day = explicit_starts.iter().flatten().copied().min().unwrap_or(0);
    let section_count = gantt_meta.sections.len().max(1);
    let mut start_days = vec![base_start_day; task_count];
    let mut end_exclusive_days = vec![base_start_day; task_count];

    // Resolve each task's primary-dependency task index ONCE. The fixpoint below is O(task_count)
    // iterations, and its inner loop previously did a `task_id_to_idx` (BTreeMap<String, _>) lookup per
    // task per iteration — O(task_count^2 log) string comparisons (memcmp was ~22% of gantt layout on a
    // dependency chain). `task_id_to_idx` is fully built above and never mutated, so the resolved index
    // is loop-invariant; hoist it. Byte-identical: `dep_idx_by_task[i]` is `Some` exactly when the old
    // `.get(after_id)` succeeded, and both the "no dependency" and "unresolved dependency" cases fell
    // through to `section_end` before.
    let dep_idx_by_task: Vec<Option<usize>> = gantt_meta
        .tasks
        .iter()
        .map(|task| {
            gantt_task_primary_dependency(task).and_then(|id| task_id_to_idx.get(id).copied())
        })
        .collect();

    for _ in 0..=task_count {
        let mut changed = false;
        let mut section_end = vec![base_start_day; section_count];

        for (task_idx, task) in gantt_meta.tasks.iter().enumerate() {
            let section_idx = task.section_idx.min(section_count.saturating_sub(1));
            let start = if let Some(explicit) = explicit_starts[task_idx] {
                explicit
            } else if let Some(dep_idx) = dep_idx_by_task[task_idx] {
                end_exclusive_days
                    .get(dep_idx)
                    .copied()
                    .unwrap_or(section_end[section_idx])
            } else {
                section_end[section_idx]
            };
            let start = advance_gantt_start_day(start, skip_weekends, &excluded_dates);
            let end_exclusive = advance_gantt_end_day(
                start,
                durations[task_idx].max(0),
                skip_weekends,
                &excluded_dates,
            );

            if start_days[task_idx] != start {
                start_days[task_idx] = start;
                changed = true;
            }
            if end_exclusive_days[task_idx] != end_exclusive {
                end_exclusive_days[task_idx] = end_exclusive;
                changed = true;
            }
            section_end[section_idx] = end_exclusive;
        }

        if !changed {
            break;
        }
    }

    let min_start_day = start_days.iter().copied().min().unwrap_or(base_start_day);
    // ⚠️ THE AXIS RUNS TO THE CHART'S END BOUNDARY, NOT TO THE LAST OCCUPIED DAY (bd-pqp2f).
    // `max_last_day` is `start + duration - 1`, the last day a bar covers, which is the right
    // quantity for the BARS and one short for the AXIS. mermaid draws a tick on the exclusive end:
    // `Design 2026-01-01, 3d` then `Build after a1, 4d` ends on 2026-01-08, and mermaid labels it
    // while we stopped at 2026-01-07.
    //
    // `total_span_days` reaches exactly two places — the published `last_day` and the tick range
    // below — so widening it moves the axis and nothing else; bar geometry is derived from
    // `start_days`/`durations` directly.
    //
    // The `.max(1)` floor is why a ONE-DAY task already drew two ticks: its occupied span is 0 and
    // the floor lifted it to 1, which happens to equal the end boundary. That case was right by
    // accident and stays right by construction now.
    let max_end_day = start_days
        .iter()
        .copied()
        .zip(durations.iter().copied())
        .map(|(start, duration)| start.saturating_add(duration.max(1)))
        .max()
        .unwrap_or(min_start_day);
    let total_span_days = usize::try_from((max_end_day - min_start_day).max(1)).unwrap_or(1);

    let mut section_base_y = 0.0_f32;
    let mut per_section_counts = vec![0_usize; section_count];
    for (task_idx, task) in gantt_meta.tasks.iter().enumerate() {
        let node_index = task.node.0;
        if node_index >= node_count {
            continue;
        }

        let section_idx = task.section_idx.min(section_count.saturating_sub(1));
        let section_label: &str = gantt_meta
            .sections
            .get(section_idx)
            .map_or("Backlog", |section| section.name.as_str());

        while section_to_nodes.len() <= section_idx {
            let idx = section_to_nodes.len();
            let label = gantt_meta.sections.get(idx).map_or_else(
                || format!("Section {}", idx + 1),
                |section| section.name.clone(),
            );
            section_to_nodes.entry(label).or_default();
        }

        let row_index = per_section_counts[section_idx];
        let start_offset_days = (start_days[task_idx] - min_start_day).max(0) as f32;
        let duration_days = durations[task_idx].max(1) as f32;
        // A gantt bar's position and length ARE the data: where it starts is its start date and how
        // long it is is its duration. Both were wrong (bd-h9gx).
        //
        // The width used to be `max(label_width, duration * col, 156)`, so a long task NAME lengthened
        // the bar — a 1-day task with a 68-character name measured 524.10px against a 10-day task's
        // 480.00px, inverting the one comparison a gantt chart exists to support. Width is now purely
        // temporal, and the 156px floor goes with it: `durations` is clamped to >= 1 above, so the
        // narrowest task bar is one column (48px), visible without lying about length.
        //
        // The centre used to be `start_offset_days * col`, and `node_boxes_from_centers` derives
        // `bounds.x = center_x - width / 2`, so every bar straddled its start date, beginning half a
        // bar-width BEFORE the day it starts on. Offsetting the centre by half the width puts the LEFT
        // EDGE on the start day, which is what a reader measures from.
        //
        // A milestone is an instant, not a span, so it keeps a fixed marker width and stays centred ON
        // its day — correct geometry for a point event, not an exception.
        //
        // The task name no longer sizes the bar; it is placed by `gantt_task_label_placements` below,
        // mirroring mermaid-js.
        let (bar_width, bar_center_x) = if milestones[task_idx] {
            (72.0, start_offset_days * base_col_width)
        } else {
            let width = duration_days * base_col_width;
            (
                width,
                start_offset_days.mul_add(base_col_width, width / 2.0),
            )
        };
        node_sizes[node_index].0 = bar_width;

        let x = bar_center_x;
        let y = (row_index as f32).mul_add(row_gap, section_base_y);
        centers[node_index] = (x, y);
        rank_by_node[node_index] =
            usize::try_from((start_days[task_idx] - min_start_day).max(0)).unwrap_or(0);
        order_by_node[node_index] = row_index + section_idx * 128;
        // The pre-populate loop above already inserted every present section, so `entry` would clone
        // `section_label` only to drop it on the (common) hit. Borrow-lookup first; allocate a key
        // just on the rare miss — the empty-sections `"Backlog"` case, exactly as the original did.
        // Byte-identical map contents.
        if let Some(nodes) = section_to_nodes.get_mut(section_label) {
            nodes.push(node_index);
        } else {
            section_to_nodes
                .entry(section_label.to_string())
                .or_default()
                .push(node_index);
        }
        per_section_counts[section_idx] += 1;

        let next_is_new_section = gantt_meta
            .tasks
            .get(task_idx + 1)
            .is_none_or(|next| next.section_idx != section_idx);
        if next_is_new_section {
            section_base_y +=
                (per_section_counts[section_idx].max(1) as f32).mul_add(row_gap, section_gap);
        }
    }

    // The left edge of the first bar in RAW day-space, captured before `centers` is consumed.
    // `finalize_specialized_layout` normalizes every centre by one uniform translation, so raw
    // day-space (day 0 at x = 0) is not the space the placed bars end up in.
    let raw_first_left_edge = centers
        .first()
        .zip(node_sizes.first())
        .map(|(&(center_x, _), &(width, _))| center_x - width / 2.0);

    let mut traced = finalize_specialized_layout(
        ir,
        &node_sizes,
        &rank_by_node,
        &order_by_node,
        centers,
        trace,
        true,
    );

    // Freshly built by `finalize_specialized_layout` (refcount 1) ⇒ clone-free `make_mut`.
    let layout = Arc::make_mut(&mut traced.layout);
    // Ticks used to be emitted at `day_offset * base_col_width`, i.e. in raw day-space, while the
    // bars they index were shifted right by normalization (>= 20px, more when the earliest task is a
    // milestone, whose marker extends half a width left of its day). Nothing caught it because no
    // renderer drew the axis (bd-trsd): the misalignment only becomes visible the moment it does.
    // An axis offset from its own bars is worse than no axis — it reads as authoritative and lies
    // about which day a bar starts on, which is the whole failure family bd-h9gx opened.
    //
    // The shift is RECOVERED from a placed node rather than by re-deriving the normalization
    // formula, so there is one source of truth: if normalization changes, the ticks follow it
    // instead of silently drifting apart again.
    let day_zero_x = match (layout.nodes.first(), raw_first_left_edge) {
        (Some(first_node), Some(raw_left)) => first_node.bounds.x - raw_left,
        _ => 0.0,
    };
    // `axisFormat`, `tickInterval` and `weekday` are read HERE and nowhere else (bd-w3pw). All
    // three describe the axis, and the axis tick label is built in layout, not in any renderer, so
    // this is the only place they can take effect. Until bd-trsd drew the axis at all they were
    // unimplementable: there was no label to format and no tick row whose density to control.
    //
    // A tick is emitted only on an interval boundary, so `tickInterval 1month` on a year-long chart
    // gives twelve ticks instead of three hundred and sixty five overlapping ones — the density
    // problem is the whole reason mermaid has the directive.
    let tick_interval = gantt_meta.tick_interval.unwrap_or(GanttTickInterval::Day);
    // mermaid's `weekday` default is sunday, which is also the parser's encoding for 0.
    let weekday_start = gantt_meta.weekday_start.unwrap_or(0);
    let axis_format = gantt_meta.axis_format.as_deref();
    let tick_at = |day: i32| LayoutAxisTick {
        label: format_gantt_axis_label(day, axis_format),
        position: ((day - min_start_day) as f32).mul_add(base_col_width, day_zero_x),
    };
    // Publish the same mapping the ticks are built from, so anything placed at a DATE agrees with
    // the axis by construction rather than by a second derivation (bd-j0va).
    layout.extensions.gantt_day_axis = Some(LayoutGanttDayAxis {
        first_day: min_start_day,
        last_day: min_start_day.saturating_add(i32::try_from(total_span_days).unwrap_or(i32::MAX)),
        day_width: base_col_width,
        origin_x: day_zero_x,
    });
    let mut axis_ticks: Vec<LayoutAxisTick> = (0..=total_span_days)
        .map(|day_offset| min_start_day.saturating_add(day_offset as i32))
        .filter(|&day| gantt_day_starts_interval(day, tick_interval, weekday_start))
        .map(&tick_at)
        .collect();
    // A short chart with a coarse interval can contain no boundary at all — `tickInterval 1month`
    // over six days crosses no first-of-month. Falling back to the first day keeps an axis the
    // reader can anchor on; emitting nothing would silently undo bd-trsd for exactly the documents
    // that asked for a coarser axis.
    if axis_ticks.is_empty() {
        axis_ticks.push(tick_at(min_start_day));
    }
    layout.extensions.axis_ticks = axis_ticks;
    layout.extensions.bands = section_to_nodes
        .iter()
        .filter_map(|(section, node_indexes)| {
            let bounds = layout_bounds_for_nodes(&*layout, node_indexes, 24.0)?;
            Some(LayoutBand {
                kind: LayoutBandKind::Section,
                label: section.clone(),
                bounds,
            })
        })
        .collect();
    let gantt_metrics = fm_core::FontMetrics::default_metrics();
    layout.extensions.gantt_task_labels = gantt_task_label_placements(ir, layout, &gantt_metrics);
    // A label placed outside its bar sits outside the node boxes `compute_bounds` measured, so the
    // canvas has to grow to hold it or it is clipped at the viewBox edge — which is exactly what made
    // the first attempt at this unshippable.
    extend_bounds_for_gantt_labels(layout);
    layout_gantt_axis_rows(layout, gantt_meta.top_axis);
    traced
}

/// Estimated rendered width of a gantt task name.
///
/// The renderer draws it at `config.font_size * 0.8`, so the estimate is scaled by the same factor;
/// `metrics` measures at its own base size.
fn gantt_label_width(text: &str, metrics: &fm_core::FontMetrics) -> f32 {
    metrics.estimate_dimensions(text).0 * 0.8
}

/// Decide where each gantt task's name is drawn, reproducing pinned mermaid-js 11.15.0's policy.
///
/// mermaid picks `taskText` (inside the bar), `taskTextOutsideRight` or `taskTextOutsideLeft`, and
/// never truncates in any branch. Its right/left choice exists because its canvas is a fixed width: it
/// goes left only when going right would run off the chart. We keep that preference order, measuring
/// "off the chart" against the extent of the bars, then grow the canvas for whichever side was chosen —
/// so the text is always fully rendered, which truncating it to the bar would not be.
fn gantt_task_label_placements(
    ir: &MermaidDiagramIr,
    layout: &DiagramLayout,
    metrics: &fm_core::FontMetrics,
) -> Vec<LayoutGanttTaskLabel> {
    /// Gap between a bar edge and a label placed outside it.
    const GAP: f32 = 8.0;
    /// Slack demanded inside the bar before a label counts as fitting.
    const INSIDE_PAD: f32 = 8.0;

    let chart_left = layout
        .nodes
        .iter()
        .map(|node| node.bounds.x)
        .fold(f32::INFINITY, f32::min);
    let chart_right = layout
        .nodes
        .iter()
        .map(|node| node.bounds.x + node.bounds.width)
        .fold(f32::NEG_INFINITY, f32::max);

    layout
        .nodes
        .iter()
        .filter_map(|node| {
            let text = layout_label_text(ir, node.node_index);
            if text.trim().is_empty() {
                return None;
            }
            let width = gantt_label_width(text, metrics);
            let bar_left = node.bounds.x;
            let bar_right = node.bounds.x + node.bounds.width;

            let placement = if width + INSIDE_PAD <= node.bounds.width {
                GanttLabelPlacement::Inside
            } else if bar_right + GAP + width <= chart_right || bar_left - GAP - width < chart_left
            {
                // Prefer the right, as mermaid does; fall back to it when the left has no room either,
                // since growing the canvas rightwards is the harmless direction.
                GanttLabelPlacement::OutsideRight
            } else {
                GanttLabelPlacement::OutsideLeft
            };

            let x = match placement {
                GanttLabelPlacement::Inside => bar_left + node.bounds.width / 2.0,
                GanttLabelPlacement::OutsideRight => bar_right + GAP,
                GanttLabelPlacement::OutsideLeft => bar_left - GAP,
            };

            Some(LayoutGanttTaskLabel {
                node_index: node.node_index,
                x,
                width,
                placement,
            })
        })
        .collect()
}

/// Grow `layout.bounds` so every outside-placed gantt label is inside the canvas.
fn extend_bounds_for_gantt_labels(layout: &mut DiagramLayout) {
    let mut min_x = layout.bounds.x;
    let mut max_x = layout.bounds.x + layout.bounds.width;
    for label in &layout.extensions.gantt_task_labels {
        let (left, right) = match label.placement {
            GanttLabelPlacement::Inside => continue,
            GanttLabelPlacement::OutsideRight => (label.x, label.x + label.width),
            GanttLabelPlacement::OutsideLeft => (label.x - label.width, label.x),
        };
        min_x = min_x.min(left);
        max_x = max_x.max(right);
    }
    layout.bounds.x = min_x;
    layout.bounds.width = max_x - min_x;
}

/// Publish Gantt axis baselines after task geometry and horizontal label extents are final.
///
/// Mermaid 11.15 always appends the bottom grid. `gantt.topAxis` adds a second grid above the task
/// rows; it does not relocate the first one. The coordinates belong here because renderers must not
/// infer chart extents independently and disagree about whether `+12` or `-12` is inside the SVG.
fn layout_gantt_axis_rows(layout: &mut DiagramLayout, top_axis: bool) {
    let Some(first) = layout.nodes.first() else {
        return;
    };
    let (task_top, task_bottom) = layout.nodes.iter().fold(
        (first.bounds.y, first.bounds.y + first.bounds.height),
        |(top, bottom), node| {
            (
                top.min(node.bounds.y),
                bottom.max(node.bounds.y + node.bounds.height),
            )
        },
    );

    // The pinned reference puts the top baseline immediately above the first task row and the
    // bottom baseline immediately below the last. Reserve the lower tick depth in bounds so neither
    // the canvas nor SVG clips the unconditional bottom labels.
    let bottom_y = task_bottom + 4.0;
    let required_bottom = bottom_y + 16.0;
    let current_bottom = layout.bounds.y + layout.bounds.height;
    if required_bottom > current_bottom {
        layout.bounds.height = required_bottom - layout.bounds.y;
    }

    layout.extensions.gantt_axis_rows.push(LayoutGanttAxisRow {
        placement: LayoutGanttAxisPlacement::Bottom,
        y: bottom_y,
    });
    if top_axis {
        layout.extensions.gantt_axis_rows.push(LayoutGanttAxisRow {
            placement: LayoutGanttAxisPlacement::Top,
            y: task_top - 8.0,
        });
    }
}

#[must_use]
pub fn layout_diagram_xychart(ir: &MermaidDiagramIr) -> DiagramLayout {
    Arc::unwrap_or_clone(layout_diagram_xychart_traced(ir).layout)
}

#[must_use]
pub fn layout_diagram_xychart_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    if let Some(xy_chart_meta) = ir
        .xy_chart_meta
        .as_ref()
        .filter(|meta| !meta.series.is_empty())
    {
        return layout_diagram_xychart_from_meta(ir, xy_chart_meta);
    }

    let mut trace = LayoutTrace::default();
    push_snapshot(
        &mut trace,
        "xychart_layout_empty",
        ir.nodes.len(),
        ir.edges.len(),
        0,
        0,
    );
    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes: Vec::new(),
            clusters: Vec::new(),
            cycle_clusters: Vec::new(),
            edges: Vec::new(),
            bounds: LayoutRect {
                x: 0.0,
                y: 0.0,
                width: 320.0,
                height: 240.0,
            },
            stats: LayoutStats {
                node_count: 0,
                edge_count: 0,
                crossing_count: 0,
                crossing_count_before_refinement: 0,
                reversed_edges: 0,
                cycle_count: 0,
                cycle_node_count: 0,
                max_cycle_size: 0,
                collapsed_clusters: 0,
                reversed_edge_total_length: 0.0,
                total_edge_length: 0.0,
                phase_iterations: trace.snapshots.len(),
            },
            extensions: LayoutExtensions::default(),
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

fn layout_diagram_xychart_from_meta(
    ir: &MermaidDiagramIr,
    xy_chart_meta: &IrXyChartMeta,
) -> TracedLayout {
    let mut trace = LayoutTrace::default();
    push_snapshot(
        &mut trace,
        "xychart_layout",
        ir.nodes.len(),
        ir.edges.len(),
        0,
        0,
    );

    const LEFT_MARGIN: f32 = 88.0;
    const TOP_MARGIN: f32 = 84.0;
    const RIGHT_MARGIN: f32 = 36.0;
    const LEGEND_RIGHT_MARGIN: f32 = 136.0;
    const BOTTOM_MARGIN: f32 = 76.0;
    const PLOT_HEIGHT: f32 = 320.0;
    const MIN_PLOT_WIDTH: f32 = 240.0;
    const CATEGORY_STEP: f32 = 88.0;
    const POINT_DIAMETER: f32 = 12.0;

    let category_count = xy_chart_category_count(xy_chart_meta).max(1);
    let plot_width = (category_count as f32 * CATEGORY_STEP).max(MIN_PLOT_WIDTH);
    let right_margin = if xy_chart_meta
        .series
        .iter()
        .any(|series| series.name.is_some())
    {
        LEGEND_RIGHT_MARGIN
    } else {
        RIGHT_MARGIN
    };
    let plot_bounds = LayoutRect {
        x: LEFT_MARGIN,
        y: TOP_MARGIN,
        width: plot_width,
        height: PLOT_HEIGHT,
    };
    let bounds = LayoutRect {
        x: 0.0,
        y: 0.0,
        width: LEFT_MARGIN + plot_width + right_margin,
        height: TOP_MARGIN + PLOT_HEIGHT + BOTTOM_MARGIN,
    };

    let (y_min, y_max) = resolve_xychart_y_domain(xy_chart_meta);
    let baseline_value = y_min.min(0.0).max(y_max.min(0.0));
    let baseline_y = xychart_value_to_y(baseline_value, y_min, y_max, plot_bounds);
    let band_width = plot_bounds.width / category_count as f32;
    let bar_series_count = xy_chart_meta
        .series
        .iter()
        .filter(|series| matches!(series.kind, IrXySeriesKind::Bar))
        .count()
        .max(1);

    let mut nodes = Vec::with_capacity(ir.nodes.len());
    let mut edges = Vec::new();
    let mut bar_slot = 0_usize;

    for (series_index, series) in xy_chart_meta.series.iter().enumerate() {
        let is_bar = matches!(series.kind, IrXySeriesKind::Bar);
        let local_bar_slot = if is_bar {
            let slot = bar_slot;
            bar_slot = bar_slot.saturating_add(1);
            slot
        } else {
            0
        };

        for (point_index, node_id) in series.nodes.iter().copied().enumerate() {
            let Some(&value) = series.values.get(point_index) else {
                continue;
            };
            let x_band_start = (point_index as f32).mul_add(band_width, plot_bounds.x);
            let x_center = x_band_start + band_width / 2.0;
            let value_y = xychart_value_to_y(value, y_min, y_max, plot_bounds);
            let node_bounds = if is_bar {
                let bar_width = (band_width * 0.72 / bar_series_count as f32)
                    .clamp(10.0, (band_width * 0.78).max(10.0));
                let group_width = bar_width * bar_series_count as f32;
                let group_start = x_band_start + (band_width - group_width) / 2.0;
                let x = (local_bar_slot as f32).mul_add(bar_width, group_start);
                let y = value_y.min(baseline_y);
                let height = (baseline_y - value_y).abs().max(1.0);
                LayoutRect {
                    x,
                    y,
                    width: bar_width,
                    height,
                }
            } else {
                LayoutRect {
                    x: x_center - POINT_DIAMETER / 2.0,
                    y: value_y - POINT_DIAMETER / 2.0,
                    width: POINT_DIAMETER,
                    height: POINT_DIAMETER,
                }
            };

            nodes.push(LayoutNodeBox {
                node_index: node_id.0,
                node_id: ir.nodes[node_id.0].id.clone(),
                rank: point_index,
                order: series_index,
                span: ir.nodes[node_id.0].span_primary,
                bounds: node_bounds,
            });
        }

        if matches!(series.kind, IrXySeriesKind::Line | IrXySeriesKind::Area) {
            // Was O(series × edges × nodes): the `series.nodes.iter().any` membership filter AND the two
            // `nodes.iter().find` endpoint lookups were LINEAR scans PER edge, and a line series has one
            // edge per point (edges ≈ nodes) ⇒ O(N²). Build a series-membership `FxHashSet` and a
            // node_index -> center `FxHashMap` once, then O(1) per edge. Byte-identical: `contains` matches
            // `any`, and the map's center for `node_index` equals the (unique) node the `find` returned;
            // edges are `sort_by_key`ed by `edge_index` below, so push order is irrelevant anyway.
            let series_members: FxHashSet<usize> = series.nodes.iter().map(|node| node.0).collect();
            let center_by_index: FxHashMap<usize, _> = nodes
                .iter()
                .map(|node| (node.node_index, node.bounds.center()))
                .collect();
            for (edge_index, edge) in ir.edges.iter().enumerate() {
                let Some(source) = endpoint_node_index(ir, edge.from) else {
                    continue;
                };
                let Some(target) = endpoint_node_index(ir, edge.to) else {
                    continue;
                };
                if !series_members.contains(&source) || !series_members.contains(&target) {
                    continue;
                }
                let Some(&source_center) = center_by_index.get(&source) else {
                    continue;
                };
                let Some(&target_center) = center_by_index.get(&target) else {
                    continue;
                };
                edges.push(LayoutEdgePath {
                    edge_index,
                    span: edge.span,
                    points: smallvec![source_center, target_center],
                    reversed: false,
                    is_self_loop: false,
                    parallel_offset: 0.0,
                    bundle_count: 1,
                    bundled: false,
                });
            }
        }
    }

    nodes.sort_by_key(|node| node.node_index);
    edges.sort_by_key(|edge| edge.edge_index);
    push_snapshot(
        &mut trace,
        "xychart_geometry",
        nodes.len(),
        edges.len(),
        0,
        0,
    );
    let (total_edge_length, reversed_edge_total_length) = compute_edge_length_metrics(&edges);

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters: Vec::new(),
            cycle_clusters: Vec::new(),
            edges,
            bounds,
            stats: LayoutStats {
                node_count: ir.nodes.len(),
                edge_count: ir.edges.len(),
                crossing_count: 0,
                crossing_count_before_refinement: 0,
                reversed_edges: 0,
                cycle_count: 0,
                cycle_node_count: 0,
                max_cycle_size: 0,
                collapsed_clusters: 0,
                reversed_edge_total_length,
                total_edge_length,
                phase_iterations: trace.snapshots.len(),
            },
            extensions: LayoutExtensions::default(),
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

fn xy_chart_category_count(xy_chart_meta: &IrXyChartMeta) -> usize {
    xy_chart_meta.x_axis.categories.len().max(
        xy_chart_meta
            .series
            .iter()
            .map(|series| series.values.len())
            .max()
            .unwrap_or(0),
    )
}

fn resolve_xychart_y_domain(xy_chart_meta: &IrXyChartMeta) -> (f32, f32) {
    let mut min_value = xy_chart_meta.y_axis.min.unwrap_or(f32::INFINITY);
    let mut max_value = xy_chart_meta.y_axis.max.unwrap_or(f32::NEG_INFINITY);

    if xy_chart_meta.y_axis.min.is_none() || xy_chart_meta.y_axis.max.is_none() {
        for value in xy_chart_meta
            .series
            .iter()
            .flat_map(|series| series.values.iter().copied())
        {
            min_value = min_value.min(value);
            max_value = max_value.max(value);
        }
    }

    if !min_value.is_finite() || !max_value.is_finite() {
        return (0.0, 1.0);
    }
    if xy_chart_meta.y_axis.min.is_none() && min_value > 0.0 {
        min_value = 0.0;
    }
    if xy_chart_meta.y_axis.max.is_none() && max_value < 0.0 {
        max_value = 0.0;
    }
    if (max_value - min_value).abs() < f32::EPSILON {
        max_value += 1.0;
    }
    (min_value, max_value)
}

fn xychart_value_to_y(value: f32, y_min: f32, y_max: f32, plot_bounds: LayoutRect) -> f32 {
    let range = (y_max - y_min).max(f32::EPSILON);
    let ratio = ((value - y_min) / range).clamp(0.0, 1.0);
    plot_bounds.y + plot_bounds.height - (ratio * plot_bounds.height)
}

/// Epoch day number for an ISO `YYYY-MM-DD` date, or `None` if it is not a real calendar date.
///
/// Public because the renderer needs to place a marker at a date in the SAME day space the layout
/// used; a second copy of this arithmetic in another crate is how the marker and the axis would come
/// to disagree about which day is which (bd-j0va).
#[must_use]
pub fn parse_iso_day_number(value: &str) -> Option<i32> {
    let value = value.trim();
    let bytes = value.as_bytes();
    if bytes.len() != 10 || bytes[4] != b'-' || bytes[7] != b'-' || !value.is_ascii() {
        return None;
    }

    let year: i32 = value[0..4].parse().ok()?;
    let month: u8 = value[5..7].parse().ok()?;
    let day: u8 = value[8..10].parse().ok()?;
    if !is_valid_iso_calendar_date(year, month, day) {
        return None;
    }

    let month_i32 = i32::from(month);
    let day_i32 = i32::from(day);
    let adjusted_year = year - i32::from(month_i32 <= 2);
    let era = if adjusted_year >= 0 {
        adjusted_year
    } else {
        adjusted_year - 399
    } / 400;
    let year_of_era = adjusted_year - era * 400;
    let month_prime = month_i32 + if month_i32 > 2 { -3 } else { 9 };
    let day_of_year = (153 * month_prime + 2) / 5 + day_i32 - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    Some(era * 146_097 + day_of_era - 719_468)
}

fn is_valid_iso_calendar_date(year: i32, month: u8, day: u8) -> bool {
    let Some(max_day) = iso_days_in_month(year, month) else {
        return false;
    };
    (1..=max_day).contains(&day)
}

const fn iso_days_in_month(year: i32, month: u8) -> Option<u8> {
    let max_day = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if is_iso_leap_year(year) {
                29
            } else {
                28
            }
        }
        _ => return None,
    };
    Some(max_day)
}

const fn is_iso_leap_year(year: i32) -> bool {
    (year.rem_euclid(4) == 0 && year.rem_euclid(100) != 0) || year.rem_euclid(400) == 0
}

fn gantt_task_absolute_start(task: &fm_core::IrGanttTask) -> Option<i32> {
    match task.start.as_ref() {
        Some(GanttDate::Absolute(value)) => parse_iso_day_number(value),
        _ => None,
    }
}

fn gantt_task_primary_dependency(task: &fm_core::IrGanttTask) -> Option<&str> {
    if let Some(GanttDate::AfterTask(dependency)) = task.start.as_ref() {
        return Some(dependency.as_str());
    }
    task.depends_on.first().map(String::as_str)
}

fn gantt_task_duration_days(task: &fm_core::IrGanttTask, inclusive_end_dates: bool) -> i32 {
    match task.end.as_ref() {
        Some(GanttDate::DurationDays(days)) => i32::try_from(*days).unwrap_or(i32::MAX),
        Some(GanttDate::Absolute(end)) => {
            let Some(start) = gantt_task_absolute_start(task) else {
                return 1;
            };
            let Some(end) = parse_iso_day_number(end) else {
                return 1;
            };
            let span = end.saturating_sub(start);
            if inclusive_end_dates {
                span.saturating_add(1).max(0)
            } else {
                span.max(0)
            }
        }
        Some(GanttDate::AfterTask(_)) => 1,
        None => i32::from(!matches!(
            task.flags.primary_type(),
            GanttTaskType::Milestone
        )),
    }
}

fn expand_gantt_excluded_dates(gantt_meta: &IrGanttMeta) -> BTreeSet<i32> {
    let mut excluded = BTreeSet::new();
    for exclude in &gantt_meta.excludes {
        if let GanttExclude::Dates(values) = exclude {
            for value in values {
                if let Some(day) = parse_iso_day_number(value) {
                    excluded.insert(day);
                }
            }
        }
    }
    excluded
}

fn advance_gantt_start_day(
    mut day: i32,
    skip_weekends: bool,
    excluded_dates: &BTreeSet<i32>,
) -> i32 {
    while gantt_day_is_excluded(day, skip_weekends, excluded_dates) {
        day = day.saturating_add(1);
    }
    day
}

fn advance_gantt_end_day(
    start: i32,
    duration_days: i32,
    skip_weekends: bool,
    excluded_dates: &BTreeSet<i32>,
) -> i32 {
    if duration_days <= 0 {
        return start;
    }

    let mut day = start;
    let mut scheduled = 0_i32;
    while scheduled < duration_days {
        if !gantt_day_is_excluded(day, skip_weekends, excluded_dates) {
            scheduled += 1;
        }
        day = day.saturating_add(1);
    }
    day
}

fn gantt_day_is_excluded(day: i32, skip_weekends: bool, excluded_dates: &BTreeSet<i32>) -> bool {
    excluded_dates.contains(&day) || (skip_weekends && is_weekend_day_number(day))
}

const fn is_weekend_day_number(day: i32) -> bool {
    matches!(day.rem_euclid(7), 0 | 6)
}

/// Civil `(year, month, day)` from a days-since-epoch count (Howard Hinnant's `civil_from_days`).
///
/// Extracted from `format_gantt_axis_tick` unchanged so the tick-interval predicate and the
/// `axisFormat` writer read the same calendar the ISO label always has. Two independent copies of
/// this arithmetic is how an axis comes to disagree with itself about what month a tick is in.
const fn gantt_civil_from_days(days_since_epoch: i32) -> (i32, i32, i32) {
    let z = days_since_epoch + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let day_of_era = z - era * 146_097;
    let year_of_era =
        (day_of_era - day_of_era / 1460 + day_of_era / 36_524 - day_of_era / 146_096) / 365;
    let year = year_of_era + era * 400;
    let day_of_year = day_of_era - (365 * year_of_era + year_of_era / 4 - year_of_era / 100);
    let month_prime = (5 * day_of_year + 2) / 153;
    let day = day_of_year - (153 * month_prime + 2) / 5 + 1;
    let month = month_prime + if month_prime < 10 { 3 } else { -9 };
    let year = year + if month <= 2 { 1 } else { 0 };
    (year, month, day)
}

/// Day of the week, `0` = Sunday, matching the parser's `weekday` encoding.
///
/// 1970-01-01 was a Thursday, hence the `+ 4`; `rem_euclid` so pre-epoch dates do not wrap
/// negative.
fn gantt_weekday(days_since_epoch: i32) -> u8 {
    (days_since_epoch + 4).rem_euclid(7) as u8
}

/// Does this day begin a `tickInterval` period?
fn gantt_day_starts_interval(
    days_since_epoch: i32,
    interval: GanttTickInterval,
    weekday_start: u8,
) -> bool {
    let (_, month, day) = gantt_civil_from_days(days_since_epoch);
    match interval {
        GanttTickInterval::Day => true,
        GanttTickInterval::Week => gantt_weekday(days_since_epoch) == weekday_start,
        GanttTickInterval::Month => day == 1,
        GanttTickInterval::Quarter => day == 1 && matches!(month, 1 | 4 | 7 | 10),
        GanttTickInterval::Year => day == 1 && month == 1,
    }
}

const GANTT_MONTH_NAMES: [(&str, &str); 12] = [
    ("Jan", "January"),
    ("Feb", "February"),
    ("Mar", "March"),
    ("Apr", "April"),
    ("May", "May"),
    ("Jun", "June"),
    ("Jul", "July"),
    ("Aug", "August"),
    ("Sep", "September"),
    ("Oct", "October"),
    ("Nov", "November"),
    ("Dec", "December"),
];

const GANTT_DAY_NAMES: [(&str, &str); 7] = [
    ("Sun", "Sunday"),
    ("Mon", "Monday"),
    ("Tue", "Tuesday"),
    ("Wed", "Wednesday"),
    ("Thu", "Thursday"),
    ("Fri", "Friday"),
    ("Sat", "Saturday"),
];

/// Render one axis tick, honouring `axisFormat` when the document declared one.
///
/// mermaid formats gantt axis labels with d3's `timeFormat`, so the directive is a strftime-style
/// template. Only the date specifiers can mean anything here — the IR carries whole days with no
/// time-of-day — so `%H`/`%M`/`%S` render as `00` rather than being dropped, which keeps a template
/// like `%d/%m %H:%M` structurally intact instead of collapsing it into something unreadable.
///
/// An UNKNOWN specifier is emitted verbatim, percent included. Silently swallowing it would turn a
/// typo into a mysteriously missing piece of every label; leaving it visible points at the typo.
fn format_gantt_axis_label(days_since_epoch: i32, axis_format: Option<&str>) -> String {
    let Some(format) = axis_format.filter(|format| !format.is_empty()) else {
        return format_gantt_axis_tick(days_since_epoch);
    };
    let (year, month, day) = gantt_civil_from_days(days_since_epoch);
    let month_names = GANTT_MONTH_NAMES[(month.clamp(1, 12) - 1) as usize];
    let day_names = GANTT_DAY_NAMES[gantt_weekday(days_since_epoch) as usize];
    let day_of_year = days_since_epoch - gantt_days_from_civil(year, 1, 1) + 1;

    let mut out = String::with_capacity(format.len() + 8);
    let mut chars = format.chars();
    while let Some(ch) = chars.next() {
        if ch != '%' {
            out.push(ch);
            continue;
        }
        // `%-d` / `%-m` are d3's "no zero padding" forms.
        let mut unpadded = false;
        let Some(mut spec) = chars.next() else {
            out.push('%');
            break;
        };
        if spec == '-' {
            unpadded = true;
            match chars.next() {
                Some(next) => spec = next,
                None => {
                    out.push_str("%-");
                    break;
                }
            }
        }
        match spec {
            'Y' => out.push_str(&format!("{year:04}")),
            'y' => out.push_str(&format!("{:02}", year.rem_euclid(100))),
            'm' if unpadded => out.push_str(&month.to_string()),
            'm' => out.push_str(&format!("{month:02}")),
            'd' if unpadded => out.push_str(&day.to_string()),
            'd' => out.push_str(&format!("{day:02}")),
            'e' => out.push_str(&format!("{day:2}")),
            'b' | 'h' => out.push_str(month_names.0),
            'B' => out.push_str(month_names.1),
            'a' => out.push_str(day_names.0),
            'A' => out.push_str(day_names.1),
            'j' => out.push_str(&format!("{day_of_year:03}")),
            'H' | 'M' | 'S' => out.push_str("00"),
            '%' => out.push('%'),
            other => {
                out.push('%');
                if unpadded {
                    out.push('-');
                }
                out.push(other);
            }
        }
    }
    out
}

/// Days since epoch from a civil `(year, month, day)` — the inverse of [`gantt_civil_from_days`],
/// used only to find January 1st for `%j`.
const fn gantt_days_from_civil(year: i32, month: i32, day: i32) -> i32 {
    let year = year - if month <= 2 { 1 } else { 0 };
    let era = if year >= 0 { year } else { year - 399 } / 400;
    let year_of_era = year - era * 400;
    let day_of_year = (153 * (month + if month > 2 { -3 } else { 9 }) + 2) / 5 + day - 1;
    let day_of_era = year_of_era * 365 + year_of_era / 4 - year_of_era / 100 + day_of_year;
    era * 146_097 + day_of_era - 719_468
}

fn format_gantt_axis_tick(days_since_epoch: i32) -> String {
    let (year, month, day) = gantt_civil_from_days(days_since_epoch);
    // Fast path: write the fixed 10-byte `YYYY-MM-DD` directly instead of `format!`'s
    // `Formatter`/`pad_integral` zero-pad machinery — this runs once per axis-tick DAY (the entire
    // timeline span) and was ~30% of gantt layout (format_inner + fmt::write + i32 Display + pad_integral).
    // Gated so every field is exactly its padded width: year 4 digits (0..10000), month/day 2 digits
    // (0..100 — always true for the 1..=12 / 1..=31 the civil-date algorithm above yields). Byte-identical
    // to the `format!` fallback on this range; wider/negative years (unreachable for real gantt dates) keep
    // `format!`. Mirrors the parser's `normalize_gantt_date_with_format` fast path.
    if (0..10_000).contains(&year) && (0..100).contains(&month) && (0..100).contains(&day) {
        let y = year as u32;
        let m = month as u32;
        let d = day as u32;
        let mut b = [b'-'; 10];
        b[0] = b'0' + (y / 1000) as u8;
        b[1] = b'0' + (y / 100 % 10) as u8;
        b[2] = b'0' + (y / 10 % 10) as u8;
        b[3] = b'0' + (y % 10) as u8;
        b[5] = b'0' + (m / 10) as u8;
        b[6] = b'0' + (m % 10) as u8;
        b[8] = b'0' + (d / 10) as u8;
        b[9] = b'0' + (d % 10) as u8;
        return String::from_utf8(b.to_vec()).expect("ascii date digits");
    }
    format!("{year:04}-{month:02}-{day:02}")
}

#[must_use]
pub fn layout_diagram_sankey(ir: &MermaidDiagramIr) -> DiagramLayout {
    Arc::unwrap_or_clone(layout_diagram_sankey_traced(ir).layout)
}

#[must_use]
pub fn layout_diagram_sankey_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let node_count = ir.nodes.len();
    let mut node_sizes = compute_node_sizes(ir, &fm_core::FontMetrics::default_metrics());
    let mut trace = LayoutTrace::default();
    push_snapshot(
        &mut trace,
        "sankey_layout",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    let mut in_flow = vec![0.0_f32; node_count];
    let mut out_flow = vec![0.0_f32; node_count];
    for edge in &ir.edges {
        let Some(source) = endpoint_node_index(ir, edge.from) else {
            continue;
        };
        let Some(target) = endpoint_node_index(ir, edge.to) else {
            continue;
        };
        if source == target || source >= node_count || target >= node_count {
            continue;
        }

        let flow_val = edge
            .label
            .and_then(|label_id| ir.labels.get(label_id.0))
            .and_then(|label| label.text.parse::<f32>().ok())
            .unwrap_or(1.0);

        out_flow[source] += flow_val;
        in_flow[target] += flow_val;
    }

    for (node_index, size) in node_sizes.iter_mut().enumerate() {
        let flow = in_flow[node_index].max(out_flow[node_index]).max(1.0);
        size.0 = size.0.max(108.0);
        size.1 = size.1.max(30.0 + (flow * 14.0));
    }

    let ranks = layered_ranks(ir);
    let mut nodes_by_rank: BTreeMap<usize, Vec<usize>> = BTreeMap::new();
    for (node_index, rank) in ranks.iter().copied().enumerate() {
        nodes_by_rank.entry(rank).or_default().push(node_index);
    }
    for nodes in nodes_by_rank.values_mut() {
        nodes.sort_by(|left, right| compare_node_indices(ir, *left, *right));
    }

    let spacing = LayoutSpacing::default();
    let mut rank_by_node = vec![0_usize; node_count];
    let mut order_by_node = vec![0_usize; node_count];
    let mut centers = vec![(0.0_f32, 0.0_f32); node_count];
    let col_gap = spacing.rank_spacing + 136.0;
    let row_gap = spacing.node_spacing.mul_add(0.45, 18.0);

    for (rank, nodes) in &nodes_by_rank {
        let mut cursor_y = 0.0_f32;
        for (order_index, node_index) in nodes.iter().enumerate() {
            let height = node_sizes[*node_index].1;
            centers[*node_index] = (*rank as f32 * col_gap, cursor_y + (height / 2.0));
            rank_by_node[*node_index] = *rank;
            order_by_node[*node_index] = order_index;
            cursor_y += height + row_gap;
        }
    }

    let mut traced = finalize_specialized_layout(
        ir,
        &node_sizes,
        &rank_by_node,
        &order_by_node,
        centers,
        trace,
        true,
    );
    // Freshly built by `finalize_specialized_layout` (refcount 1) ⇒ clone-free `make_mut`.
    let layout = Arc::make_mut(&mut traced.layout);
    layout.extensions.bands = nodes_by_rank
        .keys()
        .copied()
        .filter_map(|rank| {
            // ⚠️ THE COLUMN BANDS CARRY NO CAPTION. `column 1` / `column 2` was a name this function
            // INVENTED from the rank index — nothing the author wrote, and nothing mermaid draws.
            // A sankey's columns are a consequence of the flow graph, not a labelled axis, so a
            // generated positional name is a machine-facing token dressed as a heading.
            //
            // Measured against the pinned bundle in Chromium: the three `column N` runs were surplus
            // on our side with no counterpart. The BANDS stay — they tint each rank — only the
            // generated caption goes. Same shape as the block-beta group id and the journey section
            // repeat.
            layout_band_for_rank(&*layout, rank, LayoutBandKind::Column, String::new(), 20.0)
        })
        .collect();
    traced
}

#[must_use]
pub fn layout_diagram_grid(ir: &MermaidDiagramIr) -> DiagramLayout {
    Arc::unwrap_or_clone(layout_diagram_grid_traced(ir).layout)
}

#[must_use]
pub fn layout_diagram_grid_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let node_count = ir.nodes.len();
    let mut node_sizes = compute_node_sizes(ir, &fm_core::FontMetrics::default_metrics());
    let mut trace = LayoutTrace::default();
    push_snapshot(&mut trace, "grid_layout", node_count, ir.edges.len(), 0, 0);

    let spacing = LayoutSpacing::default();
    let mut rank_by_node = vec![0_usize; node_count];
    let mut order_by_node = vec![0_usize; node_count];
    let mut centers = vec![(0.0_f32, 0.0_f32); node_count];

    let base_max_width = node_sizes
        .iter()
        .map(|(width, _)| *width)
        .fold(84.0_f32, f32::max);
    let max_height = node_sizes
        .iter()
        .map(|(_, height)| *height)
        .fold(44.0_f32, f32::max);

    let mut column_count = if ir.diagram_type == DiagramType::BlockBeta {
        ir.meta.block_beta_columns.unwrap_or(0)
    } else {
        0
    };
    if column_count == 0 {
        column_count = (node_count as f32).sqrt().ceil() as usize;
    }
    let column_count = column_count.max(1);
    let cell_width = base_max_width + spacing.node_spacing;
    let cell_height = spacing.rank_spacing.mul_add(0.6, max_height);

    if ir.diagram_type == DiagramType::BlockBeta {
        for (node_index, node) in ir.nodes.iter().enumerate() {
            let span = block_beta_node_span(node).min(column_count).max(1);
            if span > 1 {
                node_sizes[node_index].0 = node_sizes[node_index].0.max(
                    spacing
                        .node_spacing
                        .mul_add((span - 1) as f32, base_max_width * span as f32),
                );
            }
        }
    }

    let mut sorted_nodes: Vec<usize> = (0..node_count).collect();
    if ir.diagram_type == DiagramType::BlockBeta {
        sorted_nodes.sort_by(|left, right| compare_block_beta_grid_node_indices(ir, *left, *right));
    } else {
        sorted_nodes.sort_by(|left, right| compare_node_indices(ir, *left, *right));
    }

    if ir.diagram_type == DiagramType::BlockBeta
        && layout_block_beta_grouped_items(
            ir,
            column_count,
            cell_width,
            cell_height,
            spacing.node_spacing,
            &mut node_sizes,
            &mut rank_by_node,
            &mut order_by_node,
            &mut centers,
        )
    {
        // Grouped placement already populated node centers/ranks/orders.
    } else {
        let mut row = 0_usize;
        let mut col = 0_usize;
        for node_index in sorted_nodes {
            let span = if ir.diagram_type == DiagramType::BlockBeta {
                block_beta_node_span(&ir.nodes[node_index])
                    .min(column_count)
                    .max(1)
            } else {
                1
            };

            if col != 0 && col + span > column_count {
                row += 1;
                col = 0;
            }

            centers[node_index] = (
                (col as f32).mul_add(cell_width, (span - 1) as f32 * cell_width / 2.0),
                row as f32 * cell_height,
            );

            if matches!(ir.direction, GraphDirection::LR | GraphDirection::RL) {
                rank_by_node[node_index] = col;
                order_by_node[node_index] = row;
            } else {
                rank_by_node[node_index] = row;
                order_by_node[node_index] = col;
            }

            if col + span >= column_count {
                row += 1;
                col = 0;
            } else {
                col += span;
            }
        }
    }

    finalize_specialized_layout(
        ir,
        &node_sizes,
        &rank_by_node,
        &order_by_node,
        centers,
        trace,
        matches!(ir.direction, GraphDirection::LR | GraphDirection::RL),
    )
}

/// Width, in px, of a single bit. A field spanning `n` bits is exactly `n * PACKET_BIT_WIDTH`
/// wide — the pinned mermaid-js 11.15.0 `packet` config is
/// `{rowHeight: 32, bitWidth: 32, bitsPerRow: 32, showBits: true, paddingX: 5, paddingY: 5}`.
///
/// Note we do NOT reproduce mermaid's `width = bits * bitWidth - paddingX` inter-block gap: that
/// term makes width affine rather than proportional in the bit count (a 32-bit field would be
/// 2.0099x a 16-bit one, not 2x), which is exactly the encoding this bead exists to make exact.
/// Adjacent fields therefore share an edge, which is how a packet layout diagram is normally drawn.
const PACKET_BIT_WIDTH: f32 = 32.0;

/// Bits per row before wrapping, matching the pinned incumbent's `bitsPerRow`.
const PACKET_BITS_PER_ROW: u32 = 32;

/// Minimum row height, matching the pinned incumbent's `rowHeight`. The actual row height is the
/// larger of this and what a two-line field label needs — our field labels carry the bit range on
/// a second line (`"Source Port\n[0-15]"`), which mermaid draws as separate `packetByte` text
/// above the block instead. Two lines is a constant of the diagram type, not of any label's text,
/// so row height stays independent of what the fields are called.
const PACKET_ROW_HEIGHT_MIN: f32 = 32.0;

/// Vertical gap between rows: the incumbent's `paddingY` (5) plus the 10 its `getConfig` adds when
/// `showBits` is on, which is the default.
const PACKET_ROW_GAP: f32 = 15.0;

/// Lay out a `packet-beta` diagram as a bit ruler.
///
/// Every geometric quantity comes from the declared bit range and nothing else:
///
/// * `width  = bit_count * PACKET_BIT_WIDTH` — so equal bit counts are equal widths, and a 32-bit
///   field is exactly twice a 16-bit one;
/// * `x      = (start_bit % PACKET_BITS_PER_ROW) * PACKET_BIT_WIDTH` — a field begins at its start
///   bit's offset within its row;
/// * `row    = start_bit / PACKET_BITS_PER_ROW` — rows wrap every 32 bits.
///
/// Label text is read for nothing, so renaming a field cannot move anything (bd-51tz). Before
/// this existed, packet-beta fell through to `layout_diagram_grid_traced`, which sizes boxes from
/// their labels: the fixture's three 16-bit fields rendered 148.72 / 176.77 / 154.50 wide and its
/// 4-bit field rendered WIDER than its 6-bit one.
///
/// KNOWN DIVERGENCE (bd-8vr0): a field that straddles a row boundary is drawn as one box at its
/// start bit and overflows its row to the right. mermaid splits such a block into one box per row
/// (`getNextFittingBlock`), which needs a second box for one IR node and therefore a layout
/// extension the renderer draws; that is filed separately rather than approximated here.
fn layout_diagram_packet_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let Some(packet) = ir.packet_meta.as_ref().filter(|m| !m.fields.is_empty()) else {
        // Nothing declared a bit range (e.g. the `A -> B` connection form), so there is no ruler
        // to lay out and the generic grid remains the honest answer.
        return layout_diagram_grid_traced(ir);
    };

    let mut trace = LayoutTrace::default();
    let metrics = fm_core::FontMetrics::default_metrics();
    let node_count = ir.nodes.len();
    let row_height = metrics
        .line_height_px()
        .mul_add(2.0, 10.0)
        .max(PACKET_ROW_HEIGHT_MIN);
    let row_pitch = row_height + PACKET_ROW_GAP;

    // Bit-derived box per declared field, indexed by node so a node interned twice (or a node the
    // fallback parse produced) is handled exactly once below.
    let mut boxes: Vec<Option<LayoutRect>> = vec![None; node_count];
    let mut continuations: Vec<LayoutPacketFieldContinuation> = Vec::new();
    let mut max_row = 0_u32;
    for field in &packet.fields {
        let Some(slot) = boxes.get_mut(field.node.0) else {
            continue;
        };
        if slot.is_some() {
            continue;
        }
        // A field that crosses a row boundary is CUT at it, and the remainder carried to the next
        // row — the same split mermaid-js 11.15.0's `getNextFittingBlock` performs, with every
        // piece keeping the field's label (bd-8vr0). Each piece is `bits * PACKET_BIT_WIDTH` wide,
        // so the pieces still sum to the field's exact bit-proportional width and no piece ever
        // extends past its row.
        let mut cursor = field.start_bit;
        let mut segment = 0_usize;
        while cursor <= field.end_bit {
            let row = cursor / PACKET_BITS_PER_ROW;
            let row_last_bit = (row + 1) * PACKET_BITS_PER_ROW - 1;
            let piece_end = field.end_bit.min(row_last_bit);
            max_row = max_row.max(row);
            let rect = LayoutRect {
                x: (cursor % PACKET_BITS_PER_ROW) as f32 * PACKET_BIT_WIDTH,
                y: row as f32 * row_pitch,
                width: (piece_end - cursor + 1) as f32 * PACKET_BIT_WIDTH,
                height: row_height,
            };
            if segment == 0 {
                // The first row's piece is the field's own node box; the rest are extensions,
                // because a LayoutNodeBox is 1:1 with a node.
                *slot = Some(rect);
            } else {
                continuations.push(LayoutPacketFieldContinuation {
                    node_index: field.node.0,
                    segment,
                    bounds: rect,
                });
            }
            segment += 1;
            cursor = piece_end + 1;
        }
    }

    // Anything the packet grammar did not place (a stray node from the fallback edge/node parse)
    // is stacked in declaration order below the ruler rather than dropped, so no declared content
    // disappears from the picture.
    let mut trailing_row = max_row + 1;
    let mut nodes = Vec::with_capacity(node_count);
    for (node_index, node) in ir.nodes.iter().enumerate() {
        let bounds = boxes[node_index].unwrap_or_else(|| {
            let (label_w, label_h) = metrics.estimate_dimensions(display_node_label_ref(ir, node));
            let rect = LayoutRect {
                x: 0.0,
                y: trailing_row as f32 * row_pitch,
                width: label_w + 24.0,
                height: label_h.max(row_height),
            };
            trailing_row += 1;
            rect
        });
        nodes.push(LayoutNodeBox {
            node_index,
            node_id: node.id.clone(),
            span: node.span_primary,
            bounds,
            rank: (bounds.y / row_pitch) as usize,
            order: node_index,
        });
    }

    push_snapshot(
        &mut trace,
        "packet_layout",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    // Bounds must contain the continuations too, or a split field's second half is clipped.
    let mut bounds = compute_bounds(&nodes, &[], &[], LayoutSpacing::default());
    for continuation in &continuations {
        let right = continuation.bounds.x + continuation.bounds.width;
        let bottom = continuation.bounds.y + continuation.bounds.height;
        bounds.width = bounds.width.max(right - bounds.x);
        bounds.height = bounds.height.max(bottom - bounds.y);
    }

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters: Vec::new(),
            cycle_clusters: Vec::new(),
            // The parser chains fields with sequential edges so the generic grid could order them.
            // A bit ruler already carries that order in its geometry, and the incumbent draws no
            // connectors between packet fields, so none are routed here.
            edges: Vec::new(),
            bounds,
            stats: LayoutStats {
                node_count,
                ..LayoutStats::default()
            },
            extensions: LayoutExtensions {
                packet_field_continuations: continuations,
                ..LayoutExtensions::default()
            },
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

#[must_use]
/// Lay out a pie chart: compute wedge angles and position label nodes around
/// the perimeter.  Each node in the IR corresponds to one slice.
fn layout_diagram_pie_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let mut trace = LayoutTrace::default();
    let metrics = fm_core::FontMetrics::default_metrics();
    let spacing = LayoutSpacing::default();
    let node_count = ir.nodes.len();

    // Adaptive sizing based on slice count and label dimensions.
    let base_radius = 100.0_f32 + (node_count as f32 * 8.0).min(100.0);
    let radius = base_radius.clamp(80.0, 220.0);
    let label_radius = radius + 50.0;
    let cx = radius + 70.0;
    let cy = radius + 50.0;

    // Compute total value from pie metadata (fall back to equal slices).
    let values: Vec<f32> = if let Some(pie) = &ir.pie_meta {
        pie.slices.iter().map(|s| s.value.max(0.0)).collect()
    } else {
        vec![1.0; node_count]
    };
    let total: f32 = values.iter().sum::<f32>().max(f32::EPSILON);

    // Position each node at the midpoint angle of its wedge.
    let mut nodes = Vec::with_capacity(node_count);
    let mut angle_cursor = -PI / 2.0; // start at 12 o'clock

    for (i, node) in ir.nodes.iter().enumerate() {
        let value = values.get(i).copied().unwrap_or(1.0);
        let sweep = (value / total) * 2.0 * PI;
        let mid_angle = angle_cursor + sweep / 2.0;

        let (label_w, label_h) = metrics.estimate_dimensions(display_node_label_ref(ir, node));
        let node_w = label_w + 24.0;
        let node_h = label_h + 16.0;

        let node_x = cx + label_radius * mid_angle.cos() - node_w / 2.0;
        let node_y = cy + label_radius * mid_angle.sin() - node_h / 2.0;

        nodes.push(LayoutNodeBox {
            node_index: i,
            node_id: node.id.clone(),
            span: node.span_primary,
            bounds: LayoutRect {
                x: node_x,
                y: node_y,
                width: node_w,
                height: node_h,
            },
            rank: 0,
            order: i,
        });

        angle_cursor += sweep;
    }

    push_snapshot(&mut trace, "pie_layout", node_count, ir.edges.len(), 0, 0);

    let mut bounds = compute_bounds(&nodes, &[], &[], LayoutSpacing::default());
    if let Some(pie) = &ir.pie_meta {
        let legend_label_width = pie
            .slices
            .iter()
            .map(|slice| metrics.estimate_dimensions(&slice.label).0)
            .fold(0.0_f32, f32::max);
        let legend_min = spacing.chart_legend_min_width;
        let legend_max = spacing.chart_legend_max_width.max(legend_min);
        let legend_width =
            (legend_label_width + spacing.chart_legend_padding).clamp(legend_min, legend_max);
        let title_height = if pie.title.is_some() {
            spacing.chart_title_height
        } else {
            0.0
        };
        bounds.y -= title_height;
        bounds.height += title_height;
        bounds.width += legend_width + 28.0;
    }

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters: Vec::new(),
            cycle_clusters: Vec::new(),
            edges: Vec::new(),
            bounds,
            stats: LayoutStats {
                node_count,
                ..LayoutStats::default()
            },
            extensions: LayoutExtensions::default(),
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

/// Lay out a quadrant chart: 2D scatter plot on [0,1]² with axes and quadrant labels.
fn layout_diagram_quadrant_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let mut trace = LayoutTrace::default();
    let metrics = fm_core::FontMetrics::default_metrics();
    let node_count = ir.nodes.len();

    // Adaptive sizing: scale chart based on number of data points for readability.
    let base_size = 300.0_f32 + (node_count as f32 * 15.0).min(200.0);
    let chart_w = base_size.clamp(200.0, 600.0);
    let chart_h = chart_w; // Keep square for quadrant symmetry.
    // Compute margins from axis label dimensions.
    let axis_label_width = ir
        .quadrant_meta
        .as_ref()
        .and_then(|m| m.x_axis_left.as_ref())
        .map_or(0.0, |label| metrics.estimate_dimensions(label).0);
    let margin_left = (axis_label_width + 20.0).clamp(50.0, 120.0);
    let margin_top = 60.0_f32;

    let points = ir
        .quadrant_meta
        .as_ref()
        .map(|m| &m.points[..])
        .unwrap_or(&[]);

    let mut nodes = Vec::with_capacity(node_count);

    for (i, node) in ir.nodes.iter().enumerate() {
        let pt = points.get(i);
        let px = pt
            .map(|p| p.x)
            .filter(|v| v.is_finite())
            .unwrap_or(0.5)
            .clamp(0.0, 1.0);
        // Invert Y so higher values are at the top.
        let py = pt
            .map(|p| 1.0 - p.y)
            .filter(|v| v.is_finite())
            .unwrap_or(0.5)
            .clamp(0.0, 1.0);

        let (label_w, label_h) = metrics.estimate_dimensions(display_node_label_ref(ir, node));
        let node_w = (label_w + 20.0).max(12.0);
        let node_h = (label_h + 12.0).max(12.0);

        nodes.push(LayoutNodeBox {
            node_index: i,
            node_id: node.id.clone(),
            span: node.span_primary,
            bounds: LayoutRect {
                x: margin_left + px * chart_w - node_w / 2.0,
                y: margin_top + py * chart_h - node_h / 2.0,
                width: node_w,
                height: node_h,
            },
            rank: 0,
            order: i,
        });
    }

    push_snapshot(&mut trace, "quadrant_layout", node_count, 0, 0, 0);

    let total_w = margin_left + chart_w + 40.0;
    let total_h = margin_top + chart_h + 40.0;

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters: Vec::new(),
            cycle_clusters: Vec::new(),
            edges: Vec::new(),
            bounds: LayoutRect {
                x: 0.0,
                y: 0.0,
                width: total_w,
                height: total_h,
            },
            stats: LayoutStats {
                node_count,
                ..LayoutStats::default()
            },
            extensions: LayoutExtensions::default(),
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

/// Lay out a git graph: lane-based commit positioning with vertical stacking.
fn layout_diagram_gitgraph_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let mut trace = LayoutTrace::default();
    let metrics = fm_core::FontMetrics::default_metrics();
    let node_sizes = compute_node_sizes(ir, &metrics);
    let node_count = ir.nodes.len();
    let spacing = LayoutSpacing::default();

    if node_count == 0 {
        return TracedLayout {
            layout: Arc::new(DiagramLayout {
                nodes: Vec::new(),
                clusters: Vec::new(),
                cycle_clusters: Vec::new(),
                edges: Vec::new(),
                bounds: LayoutRect {
                    x: 0.0,
                    y: 0.0,
                    width: 0.0,
                    height: 0.0,
                },
                stats: LayoutStats::default(),
                extensions: LayoutExtensions::default(),
                dirty_regions: Vec::new(),
            }),
            trace,
        };
    }

    // Assign lanes by cluster membership and position nodes in a single pass.
    let horizontal = matches!(ir.direction, GraphDirection::LR | GraphDirection::RL);
    let lane_width =
        node_sizes.iter().map(|(w, _)| *w).fold(0.0_f32, f32::max) + spacing.node_spacing;
    let row_height = spacing.rank_spacing.mul_add(
        0.6,
        node_sizes.iter().map(|(_, h)| *h).fold(0.0_f32, f32::max),
    );

    let mut lane_map: BTreeMap<usize, usize> = BTreeMap::new();
    let mut next_lane = 0_usize;
    let mut nodes = Vec::with_capacity(node_count);
    for (i, node) in ir.nodes.iter().enumerate() {
        // Branch membership is the lane: distinct lanes are the visual grammar of a gitGraph, and a
        // merge is only legible because it joins two of them. The parser records the branch lane per
        // commit; fall back to cluster membership for git-graph-shaped input that arrives without it.
        let lane = if let Some(meta) = ir.git_graph_meta.as_ref() {
            meta.lane_of(i)
        } else {
            let cluster_id = ir
                .clusters
                .iter()
                .enumerate()
                .find(|(_, c)| c.members.contains(&fm_core::IrNodeId(i)))
                .map_or(usize::MAX, |(ci, _)| ci);
            *lane_map.entry(cluster_id).or_insert_with(|| {
                let l = next_lane;
                next_lane += 1;
                l
            })
        };
        let (w, h) = node_sizes[i];

        // Centre each commit across its lane rather than left-aligning it. Commit boxes are as wide
        // as their labels, so a shared left edge would still put a `merge develop` circle at a
        // different centre from a bare `commit` on the same branch — the lane would be a
        // bookkeeping fact, not a readable column.
        let lane_origin = lane as f32 * lane_width;
        let (x, y) = if horizontal {
            (
                i as f32 * row_height,
                lane_origin + (lane_width - h) * 0.5_f32,
            )
        } else {
            (
                lane_origin + (lane_width - w) * 0.5_f32,
                i as f32 * row_height,
            )
        };

        nodes.push(LayoutNodeBox {
            node_index: i,
            node_id: node.id.clone(),
            span: node.span_primary,
            bounds: LayoutRect {
                x,
                y,
                width: w,
                height: h,
            },
            rank: i,
            order: lane,
        });
    }

    let edges = build_edge_paths(ir, &nodes, &BTreeSet::new(), EdgeRouting::default());
    let clusters = build_cluster_boxes(ir, &nodes, spacing, &metrics);
    let mut bounds = compute_bounds(&nodes, &clusters, &edges, spacing);

    // BRANCH NAMES REACH THE PICTURE (bd-jgco).
    //
    // `git_graph_meta.branches` was written by the parser and read by nothing — no renderer, no
    // layout code — so a gitGraph branch name appeared in no output at all: not SVG, not terminal,
    // not canvas. mermaid 11.15.0 draws them (a `branch-label` class and 78 `branchLabelColor`
    // theme entries in the pinned bundle), so this was a user-visible divergence, not a style
    // choice.
    //
    // One labelled band per lane is the whole fix: all three renderers already draw `band.label`
    // (`write_layout_band_into`, the canvas band loop, and the terminal's `overlay_labels`), so no
    // renderer needs to learn anything about gitGraph.
    //
    // The lane index IS the index into `branches` — the field's own doc says "a name's position is
    // its lane index" — and each placed box already carries its lane in `order`, so the extent is
    // read back from the boxes rather than recomputed from the lane arithmetic above. `.get(lane)`
    // rather than indexing: a malformed meta with fewer names than lanes must drop the label, not
    // panic on a user's input.
    let mut bands: Vec<LayoutBand> = Vec::new();
    if let Some(meta) = ir.git_graph_meta.as_ref()
        && !meta.branches.is_empty()
    {
        // Accumulate each lane's extent in ONE pass over the placed boxes, keyed by `order` (the
        // lane), mirroring how the kanban arm builds its rank bounds.
        let mut lane_bounds: FxHashMap<usize, (f32, f32, f32, f32)> =
            FxHashMap::with_capacity_and_hasher(nodes.len(), Default::default());
        for node_box in &nodes {
            let entry = lane_bounds.entry(node_box.order).or_insert((
                f32::INFINITY,
                f32::INFINITY,
                f32::NEG_INFINITY,
                f32::NEG_INFINITY,
            ));
            entry.0 = entry.0.min(node_box.bounds.x);
            entry.1 = entry.1.min(node_box.bounds.y);
            entry.2 = entry.2.max(node_box.bounds.x + node_box.bounds.width);
            entry.3 = entry.3.max(node_box.bounds.y + node_box.bounds.height);
        }

        // The band opens a strip ABOVE its first commit and the label is drawn into it. Bands are
        // background in every renderer, so a label placed over the lane's own content would be
        // painted over by the first commit box and the name would still be invisible — the exact
        // defect this fixes, reintroduced one layer down. `LABEL_STRIP` exceeds the renderers'
        // label baseline offset (svg draws at band.y + 16) so the text clears the commit.
        const LABEL_STRIP: f32 = 26.0;
        const SIDE_PAD: f32 = 8.0;

        // Sorted so band order is lane order and does not inherit the hash map's iteration order,
        // which would make the emitted SVG differ run to run.
        let mut lanes: Vec<usize> = lane_bounds.keys().copied().collect();
        lanes.sort_unstable();
        for lane in lanes {
            let Some(name) = meta.branches.get(lane) else {
                continue;
            };
            if name.is_empty() {
                continue;
            }
            let (min_x, min_y, max_x, max_y) = lane_bounds[&lane];
            let rect = LayoutRect {
                x: min_x - SIDE_PAD,
                y: min_y - LABEL_STRIP,
                width: (max_x - min_x) + SIDE_PAD * 2.0,
                height: (max_y - min_y) + LABEL_STRIP + SIDE_PAD,
            };
            // Bands are built AFTER `compute_bounds`, which sees only nodes/clusters/edges, so the
            // label strip would sit outside the viewBox and be clipped away — drawn but unseeable.
            // Union it in.
            let right = bounds.x + bounds.width;
            let bottom = bounds.y + bounds.height;
            bounds.x = bounds.x.min(rect.x);
            bounds.y = bounds.y.min(rect.y);
            bounds.width = right.max(rect.x + rect.width) - bounds.x;
            bounds.height = bottom.max(rect.y + rect.height) - bounds.y;

            bands.push(LayoutBand {
                kind: LayoutBandKind::Lane,
                label: name.clone(),
                bounds: rect,
            });
        }
    }

    push_snapshot(
        &mut trace,
        "gitgraph_layout",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters,
            cycle_clusters: Vec::new(),
            edges,
            bounds,
            stats: LayoutStats {
                node_count,
                edge_count: ir.edges.len(),
                ..LayoutStats::default()
            },
            extensions: LayoutExtensions {
                bands,
                ..LayoutExtensions::default()
            },
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

/// Group a kanban board's cards into one column per declared lane, in declaration order.
///
/// Returns `None` for anything that is not a kanban board with lanes, so journey — which shares
/// this layout but ranks by edges — is untouched, and a kanban with no columns at all falls back
/// rather than producing a single degenerate column.
///
/// Order WITHIN a lane is declaration order (`node_index`), not `compare_node_indices`' id sort: a
/// board lists its cards in the order they should be read, and an id sort puts "Task 10" above
/// "Task 2".
fn kanban_lane_columns(ir: &MermaidDiagramIr) -> Option<Vec<Vec<usize>>> {
    if ir.diagram_type != DiagramType::Kanban || ir.clusters.is_empty() {
        return None;
    }

    // First lane that claims a card wins, so a card in two clusters cannot appear in two columns.
    let mut lane_of_node = vec![usize::MAX; ir.nodes.len()];
    for (lane, cluster) in ir.clusters.iter().enumerate() {
        for member in &cluster.members {
            if let Some(slot) = lane_of_node.get_mut(member.0)
                && *slot == usize::MAX
            {
                *slot = lane;
            }
        }
    }

    // A card belonging to no lane still has to be drawn; it goes in a trailing column of its own
    // rather than being silently folded into lane 0.
    let mut columns: Vec<Vec<usize>> = vec![Vec::new(); ir.clusters.len()];
    let mut orphans: Vec<usize> = Vec::new();
    for (node_index, lane) in lane_of_node.iter().copied().enumerate() {
        if lane == usize::MAX {
            orphans.push(node_index);
        } else {
            columns[lane].push(node_index);
        }
    }
    if !orphans.is_empty() {
        columns.push(orphans);
    }

    columns.iter().any(|c| !c.is_empty()).then_some(columns)
}

fn layout_diagram_kanban_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let node_count = ir.nodes.len();
    let mut node_sizes = compute_node_sizes(ir, &fm_core::FontMetrics::default_metrics());
    let mut trace = LayoutTrace::default();
    push_snapshot(
        &mut trace,
        "kanban_layout",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    for size in &mut node_sizes {
        size.0 = size.0.max(144.0);
        size.1 = size.1.max(42.0);
    }

    // A kanban board's columns ARE its grammar — which lane a card sits in is the only thing the
    // diagram exists to say — and the lane is declared as a cluster, never as an edge. Ranking a
    // kanban by `layered_ranks` therefore gave EVERY card rank 0 (no edges to rank by), so all of
    // them stacked in one column at the same x and the lanes degenerated into horizontal bands
    // (bd-eg44). Lane membership is read from the clusters instead; journey, which shares this
    // layout and does rank by edges, keeps the edge-derived path unchanged.
    let lane_columns = kanban_lane_columns(ir);
    let columns_are_declared_lanes = lane_columns.is_some();
    let nodes_by_rank = lane_columns.unwrap_or_else(|| {
        let ranks = layered_ranks(ir);
        // Dense rank index: kanban/journey assign ~a distinct rank per row, so ranks run 0..max densely.
        // A `Vec<Vec>` indexed by rank iterates in the SAME sorted-rank order as the old `BTreeMap<usize,
        // Vec>` (index order == key order) while dropping the per-node O(log) B-tree insert + node allocs
        // and the tree-walk iterations below (`nodes_by_rank` insert + keys-scan was ~13% of journey layout).
        // Byte-identical: a gap (empty) rank produces no `rank_bounds` entry, so the band `filter_map` skips
        // it exactly as an absent BTreeMap key did; and the centre loop's empty inner loop is a no-op there.
        let rank_count = ranks.iter().copied().max().map_or(0, |m| m + 1);
        let mut by_rank: Vec<Vec<usize>> = vec![Vec::new(); rank_count];
        for (node_index, rank) in ranks.iter().copied().enumerate() {
            by_rank[rank].push(node_index);
        }
        for nodes in by_rank.iter_mut() {
            nodes.sort_by(|left, right| compare_node_indices(ir, *left, *right));
        }
        by_rank
    });

    let spacing = LayoutSpacing::default();
    let mut rank_by_node = vec![0_usize; node_count];
    let mut order_by_node = vec![0_usize; node_count];
    let mut centers = vec![(0.0_f32, 0.0_f32); node_count];

    let column_gap = spacing.rank_spacing + 170.0;
    let row_gap = spacing.node_spacing + 22.0;
    for (rank, nodes) in nodes_by_rank.iter().enumerate() {
        for (order_index, node_index) in nodes.iter().enumerate() {
            centers[*node_index] = (rank as f32 * column_gap, order_index as f32 * row_gap);
            rank_by_node[*node_index] = rank;
            order_by_node[*node_index] = order_index;
        }
    }

    let mut traced = finalize_specialized_layout(
        ir,
        &node_sizes,
        &rank_by_node,
        &order_by_node,
        centers,
        trace,
        true,
    );
    if columns_are_declared_lanes {
        // The lanes are already drawn — as cluster boxes carrying their declared titles ("Todo",
        // "In Progress", …). A generic "lane N" band over each column would be a second rectangle
        // around the same cards with a worse label. Journey, which has no lane clusters, still
        // gets its bands from the block below.
        return traced;
    }
    // Lane bands: the per-rank `layout_band_for_rank` re-scanned ALL nodes twice per rank (build the
    // rank's index list + `layout_bounds_for_nodes`' all-nodes membership loop), i.e. O(ranks × nodes) —
    // the kanban/journey layout assigns a distinct rank per row, so ranks ≈ nodes and this was O(N²)
    // (60% of journey layout). Accumulate every rank's min/max in ONE pass over the nodes instead.
    // Byte-identical: same per-rank min/max (over the same nodes, in the same `layout.nodes` order) and
    // the same `min-padding` / `padding.mul_add(2.0, span)` rect as `layout_bounds_for_nodes(.., 20.0)`;
    // ranks with no node produce no bounds entry, exactly like that fn's `None`.
    // Presize to the node count (an upper bound on the distinct-rank count) so the per-node `.entry`
    // inserts below don't grow+rehash the table as ranks accumulate (`RawTable::reserve_rehash` was ~5%
    // of journey/kanban layout). Over-reservation is free (never touches the surplus).
    let mut rank_bounds: FxHashMap<usize, (f32, f32, f32, f32)> =
        FxHashMap::with_capacity_and_hasher(traced.layout.nodes.len(), Default::default());
    for node_box in &traced.layout.nodes {
        let entry = rank_bounds.entry(node_box.rank).or_insert((
            f32::INFINITY,
            f32::INFINITY,
            f32::NEG_INFINITY,
            f32::NEG_INFINITY,
        ));
        entry.0 = entry.0.min(node_box.bounds.x);
        entry.1 = entry.1.min(node_box.bounds.y);
        entry.2 = entry.2.max(node_box.bounds.x + node_box.bounds.width);
        entry.3 = entry.3.max(node_box.bounds.y + node_box.bounds.height);
    }
    // Freshly built by `finalize_specialized_layout` (refcount 1) ⇒ clone-free `make_mut`.
    let layout = Arc::make_mut(&mut traced.layout);
    layout.extensions.bands = (0..nodes_by_rank.len())
        .filter_map(|rank| {
            let (min_x, min_y, max_x, max_y) = *rank_bounds.get(&rank)?;
            Some(LayoutBand {
                kind: LayoutBandKind::Lane,
                // THE BAND CARRIES THE DECLARED COLUMN NAME, not a generated placeholder (bd-u3fo).
                //
                // This was unconditionally `lane 1`, `lane 2`, … so a kanban column the user named
                // `Alpha` reached the band as `lane 1`. The name was not merely undrawn — it never
                // arrived, so no renderer could recover it however carefully it read the band. That
                // is why the visible symptom (terminal draws no column name) has a cause in layout.
                //
                // The kanban parser interns each column header as a SUBGRAPH carrying the declared
                // name (`ensure_subgraph`) and every card in that column is a member, so the name is
                // recoverable from any node in the rank: node -> innermost subgraph -> title label.
                // `last()` takes the innermost enclosing subgraph, matching how ownership is
                // resolved elsewhere in this file.
                //
                // The old placeholder is kept as the FALLBACK for a rank whose nodes sit outside any
                // column, which is what a card declared before the first header looks like. That
                // keeps such a band labelled rather than blank, so this cannot turn a missing name
                // into a missing band. The fallback also preserves the `push_usize_decimal` build
                // that replaced `format!` here for cost reasons — it is byte-identical to the old
                // label and is still the only path that allocates a formatted string.
                label: nodes_by_rank
                    .get(rank)
                    .and_then(|nodes| nodes.first().copied())
                    .and_then(|node_index| ir.graph.nodes.get(node_index))
                    .and_then(|graph_node| graph_node.subgraphs.last().copied())
                    .and_then(|subgraph_id| ir.graph.subgraphs.get(subgraph_id.0))
                    .and_then(|subgraph| subgraph.title)
                    .and_then(|label_id| ir.labels.get(label_id.0))
                    .map_or_else(
                        || {
                            let mut label = String::from("lane ");
                            fm_core::push_usize_decimal(&mut label, rank + 1);
                            label
                        },
                        |label| label.text.clone(),
                    ),
                bounds: LayoutRect {
                    x: min_x - 20.0,
                    y: min_y - 20.0,
                    width: 20.0_f32.mul_add(2.0, max_x - min_x),
                    height: 20.0_f32.mul_add(2.0, max_y - min_y),
                },
            })
        })
        .collect();
    traced
}

fn layout_label_text(ir: &MermaidDiagramIr, node_index: usize) -> &str {
    ir.nodes
        .get(node_index)
        .and_then(|node| node.label)
        .and_then(|label_id| ir.labels.get(label_id.0))
        .map(|label| label.text.as_str())
        .or_else(|| ir.nodes.get(node_index).map(|node| node.id.as_str()))
        .unwrap_or("")
}

fn layout_bounds_for_nodes(
    layout: &DiagramLayout,
    node_indexes: &[usize],
    padding: f32,
) -> Option<LayoutRect> {
    // Membership via a hash set: the old `node_indexes.contains(&idx)` was a LINEAR scan inside the
    // per-node loop, making this O(nodes × node_indexes) — and it's called once PER SECTION for gantt
    // bands (`section_to_nodes.iter().filter_map(..)`), so the fallback was O(N²). Byte-identical:
    // min/max over the same node set is order- and duplicate-independent, so set membership changes
    // nothing about the result.
    let wanted: FxHashSet<usize> = node_indexes.iter().copied().collect();
    let mut min_x = f32::INFINITY;
    let mut min_y = f32::INFINITY;
    let mut max_x = f32::NEG_INFINITY;
    let mut max_y = f32::NEG_INFINITY;

    for node_box in &layout.nodes {
        if !wanted.contains(&node_box.node_index) {
            continue;
        }
        min_x = min_x.min(node_box.bounds.x);
        min_y = min_y.min(node_box.bounds.y);
        max_x = max_x.max(node_box.bounds.x + node_box.bounds.width);
        max_y = max_y.max(node_box.bounds.y + node_box.bounds.height);
    }

    if !min_x.is_finite() {
        return None;
    }

    Some(LayoutRect {
        x: min_x - padding,
        y: min_y - padding,
        width: padding.mul_add(2.0, max_x - min_x),
        height: padding.mul_add(2.0, max_y - min_y),
    })
}

fn layout_band_for_rank(
    layout: &DiagramLayout,
    rank: usize,
    kind: LayoutBandKind,
    label: String,
    padding: f32,
) -> Option<LayoutBand> {
    let node_indexes: Vec<usize> = layout
        .nodes
        .iter()
        .filter(|node| node.rank == rank)
        .map(|node| node.node_index)
        .collect();
    let bounds = layout_bounds_for_nodes(layout, &node_indexes, padding)?;
    Some(LayoutBand {
        kind,
        label,
        bounds,
    })
}

fn parse_order_hint(node_id: &str, fallback: usize) -> usize {
    node_id
        .rsplit('_')
        .next()
        .and_then(|candidate| candidate.parse::<usize>().ok())
        .unwrap_or(fallback.saturating_add(10_000))
}

fn layered_ranks(ir: &MermaidDiagramIr) -> Vec<usize> {
    let node_count = ir.nodes.len();
    if node_count == 0 {
        return Vec::new();
    }

    // Pre-extract node-id sort keys into a contiguous `Vec<&str>` so the two id-ordered sorts
    // below compare packed `&str` slices instead of striding through the large `IrNode` struct
    // array (a cache miss per `ir.nodes[idx].id` deref). Byte-identical (`ids[i]` is exactly
    // `ir.nodes[i].id`). Same lever as `build_tree_layout_structure`.
    let ids: Vec<&str> = ir.nodes.iter().map(|node| node.id.as_str()).collect();
    // Precompute a u64 sort key (first 8 id bytes, big-endian, zero-padded) so each comparison
    // is an inline integer compare instead of a memcmp that chases the `&str` to the string
    // bytes. Provably byte-identical: for text ids (no interior NUL) the packed-key order equals
    // the first-8-byte lexicographic order, and the full `ids` compare stays as a lazy tie-break
    // (runs only on key ties), so `key.cmp().then(ids.cmp()).then(index)` == the original
    // `ids.cmp().then(index)`.
    let id_keys: Vec<u64> = ids.iter().map(|s| pack_id_key(s)).collect();
    let cmp_by_id = |left: &usize, right: &usize| {
        id_keys[*left]
            .cmp(&id_keys[*right])
            .then_with(|| ids[*left].cmp(ids[*right]))
            .then_with(|| left.cmp(right))
    };

    let mut outgoing = vec![Vec::<usize>::new(); node_count];
    let mut indegree = vec![0_usize; node_count];
    for edge in &ir.edges {
        let Some(source) = endpoint_node_index(ir, edge.from) else {
            continue;
        };
        let Some(target) = endpoint_node_index(ir, edge.to) else {
            continue;
        };
        if source >= node_count || target >= node_count || source == target {
            continue;
        }
        outgoing[source].push(target);
        indegree[target] = indegree[target].saturating_add(1);
    }

    for neighbors in &mut outgoing {
        neighbors.sort_by(&cmp_by_id);
        neighbors.dedup();
    }

    let mut sorted_nodes: Vec<usize> = (0..node_count).collect();
    sorted_nodes.sort_by(&cmp_by_id);

    let mut ranks = vec![0_usize; node_count];
    let mut processed = vec![false; node_count];

    // Use BinaryHeap for O(N log N) performance and stable tie-breaking by node ID
    let mut heap = std::collections::BinaryHeap::new();
    for node_index in sorted_nodes.iter().copied() {
        if indegree[node_index] == 0 {
            heap.push(std::cmp::Reverse((&ir.nodes[node_index].id, node_index)));
        }
    }

    while let Some(std::cmp::Reverse((_, node_index))) = heap.pop() {
        if processed[node_index] {
            continue;
        }
        processed[node_index] = true;

        for target in outgoing[node_index].iter().copied() {
            ranks[target] = ranks[target].max(ranks[node_index].saturating_add(1));
            indegree[target] = indegree[target].saturating_sub(1);
            if indegree[target] == 0 {
                heap.push(std::cmp::Reverse((&ir.nodes[target].id, target)));
            }
        }
    }

    // Assign ranks to nodes that were not reached (e.g. part of cycles that weren't fully broken)
    for node_index in sorted_nodes {
        if processed[node_index] {
            continue;
        }
        let mut candidate_rank = 0_usize;
        for edge in &ir.edges {
            let Some(target) = endpoint_node_index(ir, edge.to) else {
                continue;
            };
            if target != node_index {
                continue;
            }
            if let Some(source) = endpoint_node_index(ir, edge.from) {
                candidate_rank = candidate_rank.max(ranks[source].saturating_add(1));
            }
        }
        ranks[node_index] = candidate_rank;
    }

    ranks
}

/// Does any edge in this IR declare an architecture-beta side?
///
/// The gate for dispatching to [`layout_diagram_architecture_traced`]: with no side anywhere there
/// is no direction to honour, and imposing a grid on an undirected architecture diagram would
/// change output that nobody asked to change.
fn architecture_declares_a_side(ir: &MermaidDiagramIr) -> bool {
    ir.edges
        .iter()
        .any(|edge| edge.source_side().is_some() || edge.target_side().is_some())
}

/// One grid step for a declared side. Screen coordinates put +y DOWN, so `T` is negative.
const fn architecture_side_step(side: ArchitectureSide) -> (i32, i32) {
    match side {
        ArchitectureSide::Right => (1, 0),
        ArchitectureSide::Left => (-1, 0),
        ArchitectureSide::Bottom => (0, 1),
        ArchitectureSide::Top => (0, -1),
    }
}

/// The grid step this edge asks for, from whichever end declared one.
///
/// `a:R --> L:b` states the same fact twice, so either end alone determines it: the SOURCE side is
/// the step directly (`R` ⇒ b one cell right of a), and a lone TARGET side is the step to its
/// opposite (`a --> L:b` ⇒ the edge arrives at b's left face ⇒ b is right of a). Preferring the
/// source when both are present matches mermaid, which resolves `sourceDir` first.
fn architecture_edge_step(edge: &fm_core::IrEdge) -> Option<(i32, i32)> {
    edge.source_side()
        .or_else(|| edge.target_side().map(ArchitectureSide::opposite))
        .map(architecture_side_step)
}

/// Claim a grid cell for `node`, fanning out if the wanted cell is already taken.
///
/// Two targets can be sent to the SAME cell (`a:R --> L:b` and `a:R --> L:c`). They fan out along
/// the axis PERPENDICULAR to the step rather than the second one being dropped or stacked on the
/// first: an architecture diagram that says a talks to two things on its right means both are on
/// its right, and overlapping two boxes would render one of them unreadable. Deterministic and
/// monotone — the k-th arrival sits k steps out — so the picture does not depend on iteration luck.
fn architecture_place(
    cell: &mut [Option<(i32, i32)>],
    occupied: &mut BTreeMap<(i32, i32), usize>,
    node: usize,
    want: (i32, i32),
    step: (i32, i32),
) {
    // Perpendicular to the STEP, not to the absolute cell. Deriving it from `want` was wrong and
    // silently so: a rightward step landing on column 2 would have fanned out along x — parallel
    // to its own direction — and pushed the collided service further right instead of beside it.
    let perpendicular = if step.0 == 0 { (1, 0) } else { (0, 1) };
    let mut target = want;
    let mut step = 1_i32;
    while occupied.contains_key(&target) {
        target = (
            want.0 + perpendicular.0 * step,
            want.1 + perpendicular.1 * step,
        );
        step += 1;
    }
    occupied.insert(target, node);
    cell[node] = Some(target);
}

/// Place architecture-beta services from their DECLARED edge directions (bd-zce4).
///
/// `a:R --> L:b` means b sits to the RIGHT of a — R/L/T/B are a placement grammar, which mermaid
/// 11.15.0 models per edge as `sourceDir`/`targetDir`. Ranking these by edge instead (which is
/// what the general Sugiyama path did) throws the grammar away and stacks every service
/// vertically, so `a:R --> L:b` produced byte-identical output to `a:T --> B:b`.
///
/// Reached only when [`architecture_declares_a_side`] holds, so a side-less architecture diagram
/// still takes the general path and is unchanged.
fn layout_diagram_architecture_traced(ir: &MermaidDiagramIr) -> TracedLayout {
    let mut trace = LayoutTrace::default();
    let metrics = fm_core::FontMetrics::default_metrics();
    let node_sizes = compute_node_sizes(ir, &metrics);
    let node_count = ir.nodes.len();
    let spacing = LayoutSpacing::default();

    // Integer grid first, pixels second: placement is a discrete relation between services, and
    // deciding it in cell units keeps "b is right of a" exact rather than a float comparison that
    // a wide label could flip.
    let mut cell: Vec<Option<(i32, i32)>> = vec![None; node_count];
    let mut occupied: BTreeMap<(i32, i32), usize> = BTreeMap::new();

    // Fixed point, not a single pass: an edge may name a service before any edge has placed it,
    // and `b:R --> L:c` written above `a:R --> L:b` must still chain off a.
    loop {
        let mut progressed = false;
        for edge in &ir.edges {
            let (Some(from), Some(to)) = (
                endpoint_node_index(ir, edge.from),
                endpoint_node_index(ir, edge.to),
            ) else {
                continue;
            };
            let Some(step) = architecture_edge_step(edge) else {
                continue;
            };
            match (cell[from], cell[to]) {
                (Some(base), None) => {
                    architecture_place(
                        &mut cell,
                        &mut occupied,
                        to,
                        (base.0 + step.0, base.1 + step.1),
                        step,
                    );
                    progressed = true;
                }
                // The relation is symmetric, so a placed TARGET positions its source too. Without
                // this arm a diagram whose first edge names an already-placed b as its target
                // would leave the source to the unplaced-node sweep and lose its direction.
                (None, Some(base)) => {
                    architecture_place(
                        &mut cell,
                        &mut occupied,
                        from,
                        (base.0 - step.0, base.1 - step.1),
                        step,
                    );
                    progressed = true;
                }
                _ => {}
            }
        }
        if progressed {
            continue;
        }
        // Nothing moved: seed the next component. A diagram with two disconnected direction
        // clusters gets a fresh origin per cluster instead of collapsing both onto (0, 0).
        let seed = ir.edges.iter().find_map(|edge| {
            let from = endpoint_node_index(ir, edge.from)?;
            let to = endpoint_node_index(ir, edge.to)?;
            architecture_edge_step(edge)?;
            (cell[from].is_none() && cell[to].is_none()).then_some(from)
        });
        let Some(seed) = seed else { break };
        let next_row = occupied.keys().map(|c| c.1).max().map_or(0, |row| row + 2);
        // Vertical step ⇒ a second component that also wants this row spreads sideways.
        architecture_place(&mut cell, &mut occupied, seed, (0, next_row), (0, 1));
    }

    // A service no directed edge touches (a bare `service x(cloud)[X]`, or one wired only by an
    // edge with no side) still has to appear. It goes in a trailing row rather than being dropped
    // or piled onto an occupied cell.
    let trailing_row = occupied.keys().map(|c| c.1).max().map_or(0, |row| row + 2);
    for node in 0..node_count {
        if cell[node].is_none() {
            architecture_place(&mut cell, &mut occupied, node, (0, trailing_row), (0, 1));
        }
    }

    // Grid → pixels. One uniform cell size, sized by the widest and tallest service, so a column
    // is a column no matter what the labels do; `finalize_specialized_layout` then translates the
    // whole thing (cells are freely negative up to here) and builds the edge paths.
    let cell_width =
        node_sizes.iter().map(|(w, _)| *w).fold(0.0_f32, f32::max) + spacing.node_spacing;
    let cell_height =
        node_sizes.iter().map(|(_, h)| *h).fold(0.0_f32, f32::max) + spacing.rank_spacing;
    let min_col = cell.iter().flatten().map(|c| c.0).min().unwrap_or(0);
    let min_row = cell.iter().flatten().map(|c| c.1).min().unwrap_or(0);

    let mut centers = vec![(0.0_f32, 0.0_f32); node_count];
    let mut rank_by_node = vec![0_usize; node_count];
    let mut order_by_node = vec![0_usize; node_count];
    for (node, slot) in cell.iter().enumerate() {
        let (col, row) = slot.unwrap_or((min_col, min_row));
        centers[node] = (col as f32 * cell_width, row as f32 * cell_height);
        // Rank/order are consumed as usize row/column indices, so they are rebased off the
        // grid's own minimum rather than clamped — a diagram built entirely leftwards
        // (`a:L --> R:b`) has negative columns and must not collapse them all to rank 0.
        rank_by_node[node] = usize::try_from(row - min_row).unwrap_or(0);
        order_by_node[node] = usize::try_from(col - min_col).unwrap_or(0);
    }

    push_snapshot(
        &mut trace,
        "architecture_direction_placement",
        node_count,
        ir.edges.len(),
        0,
        0,
    );

    finalize_specialized_layout(
        ir,
        &node_sizes,
        &rank_by_node,
        &order_by_node,
        centers,
        trace,
        false,
    )
}

fn finalize_specialized_layout(
    ir: &MermaidDiagramIr,
    node_sizes: &[(f32, f32)],
    rank_by_node: &[usize],
    order_by_node: &[usize],
    mut centers: Vec<(f32, f32)>,
    mut trace: LayoutTrace,
    horizontal_edges: bool,
) -> TracedLayout {
    let spacing = LayoutSpacing::default();

    normalize_center_positions(&mut centers, node_sizes);
    let nodes = node_boxes_from_centers(ir, node_sizes, rank_by_node, order_by_node, &centers);
    let edges = build_edge_paths_with_orientation(
        ir,
        &nodes,
        &BTreeSet::new(),
        horizontal_edges,
        EdgeRouting::default(),
    );
    // Same metrics this function's node sizes were computed with: every caller on these
    // specialized paths uses `FontMetrics::default_metrics()` (verified at lib.rs:4791, 5453,
    // 6271, 6378), so binding it here introduces no layout/render measurement mismatch.
    let metrics = fm_core::FontMetrics::default_metrics();
    let clusters = build_cluster_boxes(ir, &nodes, spacing, &metrics);
    let bounds = compute_bounds(&nodes, &clusters, &edges, spacing);
    let (total_edge_length, reversed_edge_total_length) = compute_edge_length_metrics(&edges);

    push_snapshot(
        &mut trace,
        "specialized_post_processing",
        ir.nodes.len(),
        ir.edges.len(),
        0,
        0,
    );

    let stats = LayoutStats {
        node_count: ir.nodes.len(),
        edge_count: ir.edges.len(),
        crossing_count: 0,
        crossing_count_before_refinement: 0,
        reversed_edges: 0,
        cycle_count: 0,
        cycle_node_count: 0,
        max_cycle_size: 0,
        collapsed_clusters: 0,
        reversed_edge_total_length,
        total_edge_length,
        phase_iterations: trace.snapshots.len(),
    };

    TracedLayout {
        layout: Arc::new(DiagramLayout {
            nodes,
            clusters,
            cycle_clusters: Vec::new(),
            edges,
            bounds,
            stats,
            extensions: LayoutExtensions::default(),
            dirty_regions: Vec::new(),
        }),
        trace,
    }
}

#[derive(Debug, Clone)]
struct TreeLayoutStructure {
    roots: Vec<usize>,
    children: TreeChildren,
    depth: Vec<usize>,
    max_depth: usize,
    horizontal_depth_axis: bool,
    reverse_depth_axis: bool,
}

/// CSR (compressed-sparse-row) adjacency for the layout tree's children: one flat `Vec<usize>` holding
/// every node's children contiguously, plus per-node `start`/`len`, instead of a `Vec<Vec<usize>>` that
/// heap-allocated a separate inner `Vec` per node (one live allocation per node through the whole
/// tree-positioning phase). `of(node)` returns the child slice; all consumers only read it as a slice
/// (`.iter()`/`.len()`/`.is_empty()`/index), so the swap is purely an allocation change. The BFS builds it
/// in the same order the per-node `Vec`s were filled (children pushed contiguously when a node is
/// dequeued, then each segment sorted in place by id), so layout output is byte-identical (golden-pinned).
#[derive(Default, Debug, Clone)]
struct TreeChildren {
    flat: Vec<usize>,
    start: Vec<usize>,
    len: Vec<usize>,
}

impl TreeChildren {
    fn of(&self, node: usize) -> &[usize] {
        let start = self.start[node];
        &self.flat[start..start + self.len[node]]
    }

    fn node_count(&self) -> usize {
        self.start.len()
    }
}

/// Pack the first 8 bytes of an id into a big-endian, zero-padded `u64` so that `u64`
/// comparison reproduces the byte-lexicographic order of those bytes. Zero-padding is
/// order-preserving for text ids (which never contain an interior NUL): a shorter string's
/// implicit trailing zeros sort before any real byte, exactly as a prefix sorts before its
/// extensions. Used as the fast path for id-ordered node sorts; ties fall back to the full
/// `&str` compare, so the overall ordering is unchanged.
#[inline]
fn pack_id_key(s: &str) -> u64 {
    let b = s.as_bytes();
    let mut k = 0u64;
    let mut i = 0;
    while i < 8 {
        k = (k << 8) | u64::from(*b.get(i).unwrap_or(&0));
        i += 1;
    }
    k
}

fn build_tree_layout_structure(ir: &MermaidDiagramIr) -> TreeLayoutStructure {
    let node_count = ir.nodes.len();
    let horizontal_depth_axis = matches!(ir.direction, GraphDirection::LR | GraphDirection::RL);
    let reverse_depth_axis = matches!(ir.direction, GraphDirection::RL | GraphDirection::BT);

    if node_count == 0 {
        return TreeLayoutStructure {
            roots: Vec::new(),
            children: TreeChildren::default(),
            depth: Vec::new(),
            max_depth: 0,
            horizontal_depth_axis,
            reverse_depth_axis,
        };
    }

    // Pre-extract the node-id sort keys into a contiguous `Vec<&str>`. The three sorts below
    // order by node id (then index); reading `ir.nodes[idx].id` for a random `idx` during a
    // sort strides through the large `IrNode` struct array (a cache miss per comparison),
    // whereas a flat `&str` slice is cache-friendly. Byte-identical: `ids[i]` is exactly
    // `ir.nodes[i].id`, so every comparison and tie-break is unchanged.
    let ids: Vec<&str> = ir.nodes.iter().map(|node| node.id.as_str()).collect();
    // Precompute a u64 sort key (first 8 id bytes, big-endian, zero-padded) so each comparison
    // is an inline integer compare instead of a memcmp that chases the `&str` to the string
    // bytes. Provably byte-identical: for text ids (no interior NUL) the packed-key order equals
    // the first-8-byte lexicographic order, and the full `ids` compare stays as a lazy tie-break
    // (runs only on key ties), so `key.cmp().then(ids.cmp()).then(index)` == the original
    // `ids.cmp().then(index)`.
    let id_keys: Vec<u64> = ids.iter().map(|s| pack_id_key(s)).collect();
    let cmp_by_id = |left: &usize, right: &usize| {
        id_keys[*left]
            .cmp(&id_keys[*right])
            .then_with(|| ids[*left].cmp(ids[*right]))
            .then_with(|| left.cmp(right))
    };

    // CSR adjacency: one flat `Vec` of targets + per-source `[out_start[n], out_start[n]+out_len[n])`
    // ranges, instead of a `Vec<Vec<usize>>` that heap-allocated one inner `Vec` per source (~one per
    // node on a chain/tree). Two cheap `endpoint_node_index` passes over the edges (a bounds-checked
    // field read): count raw out-degrees + indegrees, then fill. Each source's segment is sorted and
    // deduped IN PLACE, its post-dedup length recorded in `out_len`. Byte-identical to the old
    // push-then-`sort_by`+`dedup`: same targets, same order, same consecutive-duplicate removal, and
    // `indegree` still counts RAW edges (pre-dedup) exactly as the old push loop did.
    let mut indegree = vec![0_usize; node_count];
    let mut out_start = vec![0_usize; node_count + 1];
    let resolve = |edge: &fm_core::IrEdge| -> Option<(usize, usize)> {
        let source = endpoint_node_index(ir, edge.from)?;
        let target = endpoint_node_index(ir, edge.to)?;
        if source >= node_count || target >= node_count || source == target {
            return None;
        }
        Some((source, target))
    };
    for edge in &ir.edges {
        if let Some((source, target)) = resolve(edge) {
            out_start[source + 1] += 1;
            indegree[target] = indegree[target].saturating_add(1);
        }
    }
    for i in 1..out_start.len() {
        out_start[i] += out_start[i - 1];
    }
    let mut out_flat = vec![0_usize; out_start[node_count]];
    let mut out_len = vec![0_usize; node_count];
    {
        let mut cursor = out_start.clone();
        for edge in &ir.edges {
            if let Some((source, target)) = resolve(edge) {
                out_flat[cursor[source]] = target;
                cursor[source] += 1;
            }
        }
    }
    for node in 0..node_count {
        let segment = &mut out_flat[out_start[node]..out_start[node + 1]];
        // A 0- or 1-element out-edge segment is already sorted and duplicate-free, so skip the `sort_by`
        // machinery and the dedup scan. Chain/tree flowcharts — the common shape — have out-degree ≤ 1
        // per node, so `sort_by` was otherwise invoked on a length-≤1 slice once per node (pure call +
        // driftsort-entry overhead: ~5% of flowchart layout self-time). Byte-identical.
        if segment.len() <= 1 {
            out_len[node] = segment.len();
            continue;
        }
        segment.sort_by(&cmp_by_id);
        // Compact consecutive duplicates to the front (== `Vec::dedup` on the sorted segment).
        let mut len = 0_usize;
        for r in 0..segment.len() {
            if len == 0 || segment[r] != segment[len - 1] {
                segment[len] = segment[r];
                len += 1;
            }
        }
        out_len[node] = len;
    }

    let mut sorted_nodes: Vec<usize> = (0..node_count).collect();
    sorted_nodes.sort_by(&cmp_by_id);

    let mut candidate_roots: Vec<usize> = sorted_nodes
        .iter()
        .copied()
        .filter(|node| indegree[*node] == 0)
        .collect();
    if candidate_roots.is_empty()
        && let Some(first_node) = sorted_nodes.first().copied()
    {
        candidate_roots.push(first_node);
    }

    let mut visited = vec![false; node_count];
    let mut depth = vec![0_usize; node_count];
    let mut children = TreeChildren {
        flat: Vec::new(),
        start: vec![0_usize; node_count],
        len: vec![0_usize; node_count],
    };
    let mut roots = Vec::new();

    for candidate in candidate_roots
        .iter()
        .copied()
        .chain(sorted_nodes.iter().copied())
    {
        if visited[candidate] {
            continue;
        }

        roots.push(candidate);
        visited[candidate] = true;

        let mut queue = vec![candidate];
        let mut queue_index = 0_usize;
        while let Some(node) = queue.get(queue_index).copied() {
            queue_index = queue_index.saturating_add(1);
            let child_depth = depth[node].saturating_add(1);

            // Children are appended contiguously while `node` is being processed, so a single flat `Vec`
            // + per-node start/len reproduces the old per-node `Vec` exactly (CSR).
            children.start[node] = children.flat.len();
            for &child in &out_flat[out_start[node]..out_start[node] + out_len[node]] {
                if visited[child] {
                    continue;
                }
                visited[child] = true;
                depth[child] = child_depth;
                children.flat.push(child);
                queue.push(child);
            }
            children.len[node] = children.flat.len() - children.start[node];
        }
    }

    // No per-node child-segment sort: each node's children are appended from its `out_flat` out-edge
    // segment — which was sorted by `cmp_by_id` above — in order, skipping already-visited nodes. A
    // subsequence of a sequence sorted by a total order (`cmp_by_id`'s final tiebreak is the node index)
    // is itself sorted, so the previous `sort_by(&cmp_by_id)` here was re-sorting already-sorted data.
    // The `debug_assert` guards the invariant (held across all 439 layout tests incl. the random-edit /
    // equivalence / determinism suites + goldens); it compiles out of release builds.
    #[cfg(debug_assertions)]
    for node in 0..node_count {
        let start = children.start[node];
        let end = start + children.len[node];
        debug_assert!(
            children.flat[start..end]
                .windows(2)
                .all(|w| cmp_by_id(&w[0], &w[1]) != std::cmp::Ordering::Greater),
            "children segment already sorted (appended from sorted out_flat)"
        );
    }

    let max_depth = depth.iter().copied().max().unwrap_or(0);
    TreeLayoutStructure {
        roots,
        children,
        depth,
        max_depth,
        horizontal_depth_axis,
        reverse_depth_axis,
    }
}

fn compute_tree_subtree_spans(
    roots: &[usize],
    children: &TreeChildren,
    node_span_sizes: &[f32],
    spacing: LayoutSpacing,
    memo: &mut [Option<f32>],
) {
    let node_count = children.node_count();
    let mut post_order = Vec::with_capacity(node_count);

    let mut state = vec![0_u8; node_count];
    for &start_node in roots {
        if state[start_node] != 0 {
            continue;
        }

        let mut stack = vec![(start_node, 0)];
        state[start_node] = 1;

        while let Some((node, child_idx)) = stack.pop() {
            let node_children = children.of(node);
            if child_idx < node_children.len() {
                stack.push((node, child_idx + 1));
                let child = node_children[child_idx];
                if state[child] == 0 {
                    state[child] = 1;
                    stack.push((child, 0));
                }
            } else {
                state[node] = 2;
                post_order.push(node);
            }
        }
    }

    for &node in &post_order {
        if memo[node].is_some() {
            continue;
        }

        let own_span = node_span_sizes[node].max(1.0);
        let node_children = children.of(node);
        let child_span_total = if node_children.is_empty() {
            0.0
        } else {
            let subtree_span_sum: f32 = node_children
                .iter()
                .map(|child| memo[*child].unwrap_or(0.0))
                .sum();
            let gaps = spacing.node_spacing * (node_children.len().saturating_sub(1) as f32);
            subtree_span_sum + gaps
        };

        let span = own_span.max(child_span_total);
        memo[node] = Some(span);
    }
}

fn compute_all_tree_span_centers(
    roots: &[usize],
    children: &TreeChildren,
    subtree_spans: &[f32],
    spacing: LayoutSpacing,
    out_centers: &mut [f32],
) {
    let mut queue = Vec::new();
    let mut root_cursor = 0.0_f32;
    for &root in roots {
        queue.push((root, root_cursor));
        root_cursor += spacing.node_spacing.mul_add(1.5, subtree_spans[root]);
    }

    let mut queue_idx = 0;
    while let Some(&(node, span_start)) = queue.get(queue_idx) {
        queue_idx += 1;
        let subtree_span = subtree_spans[node];
        out_centers[node] = span_start + (subtree_span / 2.0);

        let node_children = children.of(node);
        if node_children.is_empty() {
            continue;
        }

        let child_total: f32 = spacing.node_spacing.mul_add(
            node_children.len().saturating_sub(1) as f32,
            node_children
                .iter()
                .map(|child| subtree_spans[*child])
                .sum::<f32>(),
        );
        let mut child_cursor = span_start + ((subtree_span - child_total) / 2.0);

        for &child in node_children {
            queue.push((child, child_cursor));
            child_cursor += subtree_spans[child] + spacing.node_spacing;
        }
    }
}

fn tree_depth_level_sizes(tree: &TreeLayoutStructure, node_sizes: &[(f32, f32)]) -> Vec<f32> {
    let mut level_sizes = vec![0.0_f32; tree.max_depth + 1];
    for (node_index, &(width, height)) in node_sizes.iter().enumerate() {
        let depth = tree.depth[node_index];
        let axis_size = if tree.horizontal_depth_axis {
            width
        } else {
            height
        };
        level_sizes[depth] = level_sizes[depth].max(axis_size.max(1.0));
    }
    level_sizes
}

fn depth_level_centers(level_sizes: &[f32], gap: f32) -> Vec<f32> {
    let mut centers = vec![0.0_f32; level_sizes.len()];
    let mut cursor = 0.0_f32;
    for (index, level_size) in level_sizes.iter().copied().enumerate() {
        let bounded_size = level_size.max(1.0);
        centers[index] = cursor + (bounded_size / 2.0);
        cursor += bounded_size + gap;
    }
    centers
}

fn normalize_center_positions(centers: &mut [(f32, f32)], node_sizes: &[(f32, f32)]) {
    if centers.is_empty() {
        return;
    }

    let margin = 20.0_f32;
    let mut min_x = f32::MAX;
    let mut min_y = f32::MAX;
    for (node_index, &(center_x, center_y)) in centers.iter().enumerate() {
        let (width, height) = node_sizes[node_index];
        min_x = min_x.min(center_x - (width / 2.0));
        min_y = min_y.min(center_y - (height / 2.0));
    }

    let offset_x = margin - min_x;
    let offset_y = margin - min_y;
    for (x, y) in centers {
        *x += offset_x;
        *y += offset_y;
    }
}

fn rank_orders_from_key(
    ir: &MermaidDiagramIr,
    rank_by_node: &[usize],
    key_by_node: &[f32],
) -> Vec<usize> {
    // Bucket node indices by rank. Ranks here are tree depths — dense small integers (0..height) —
    // so a flat `Vec`-of-buckets indexed by rank replaces the `BTreeMap`'s O(log R) node-based-tree
    // inserts and cache-unfriendly traversal with O(1) index pushes. The per-rank `order` assignment
    // is independent of rank iteration order (each rank numbers its own nodes 0..k), so bucketing by
    // ascending rank and sorting each bucket by the same key is byte-identical to the BTreeMap form.
    let Some(&max_rank) = rank_by_node.iter().max() else {
        return Vec::new(); // no nodes
    };
    let n = rank_by_node.len();
    // CSR bucketing: one flat `Vec` + per-rank offsets replaces the `Vec<Vec<usize>>` — which heap-
    // allocated one inner `Vec` per rank, i.e. ~one per node on the common deep-chain/tree graph (each
    // rank holds a single node). Counting-sort node indices into rank-ordered `flat`, then sort and
    // order-number each rank's contiguous segment exactly as the per-rank `Vec`s were. Byte-identical:
    // same nodes per rank in the same pre-sort (node-index) order, same (unstable, total-order)
    // comparator, same `0..k` order assignment.
    let mut rank_start = vec![0_usize; max_rank + 2];
    for &rank in rank_by_node {
        rank_start[rank + 1] += 1;
    }
    for i in 1..rank_start.len() {
        rank_start[i] += rank_start[i - 1];
    }
    let mut flat = vec![0_usize; n];
    let mut cursor = rank_start.clone();
    for (node_index, &rank) in rank_by_node.iter().enumerate() {
        flat[cursor[rank]] = node_index;
        cursor[rank] += 1;
    }

    let mut order_by_node = vec![0_usize; n];
    for rank in 0..=max_rank {
        let segment = &mut flat[rank_start[rank]..rank_start[rank + 1]];
        segment.sort_by(|left, right| {
            key_by_node[*left]
                .total_cmp(&key_by_node[*right])
                .then_with(|| compare_node_indices(ir, *left, *right))
        });
        for (order, &node_index) in segment.iter().enumerate() {
            order_by_node[node_index] = order;
        }
    }
    order_by_node
}

fn node_boxes_from_centers(
    ir: &MermaidDiagramIr,
    node_sizes: &[(f32, f32)],
    rank_by_node: &[usize],
    order_by_node: &[usize],
    centers: &[(f32, f32)],
) -> Vec<LayoutNodeBox> {
    ir.nodes
        .iter()
        .enumerate()
        .map(|(node_index, node)| {
            let (center_x, center_y) = centers[node_index];
            let (width, height) = node_sizes[node_index];
            LayoutNodeBox {
                node_index,
                node_id: node.id.clone(),
                rank: rank_by_node[node_index],
                order: order_by_node[node_index],
                span: node.span_primary,
                bounds: LayoutRect {
                    x: center_x - (width / 2.0),
                    y: center_y - (height / 2.0),
                    width,
                    height,
                },
            }
        })
        .collect()
}

fn radial_leaf_count(
    node_index: usize,
    children: &TreeChildren,
    memo: &mut [Option<usize>],
) -> usize {
    if let Some(cached) = memo[node_index] {
        return cached;
    }

    // A mindmap can have a single branch thousands of levels deep.  Compute the
    // post-order leaf totals explicitly so untrusted indentation cannot consume
    // the calling thread's stack.
    let mut work = vec![(node_index, false)];
    while let Some((node, children_visited)) = work.pop() {
        if memo[node].is_some() {
            continue;
        }

        let node_children = children.of(node);
        if node_children.is_empty() {
            memo[node] = Some(1);
        } else if children_visited {
            let count = node_children
                .iter()
                .map(|child| memo[*child].unwrap_or(1))
                .sum::<usize>()
                .max(1);
            memo[node] = Some(count);
        } else {
            work.push((node, true));
            for child in node_children.iter().rev() {
                if memo[*child].is_none() {
                    work.push((*child, false));
                }
            }
        }
    }

    memo[node_index].unwrap_or(1)
}

#[allow(clippy::too_many_arguments)]
fn assign_radial_angles(
    node_index: usize,
    start_angle: f32,
    end_angle: f32,
    tree: &TreeLayoutStructure,
    leaf_counts: &[usize],
    node_sizes: &[(f32, f32)],
    radii: &[f32],
    depth_offset: usize,
    spacing: LayoutSpacing,
    angles: &mut [f32],
) {
    enum AngleWork {
        Assign { node: usize, start: f32, end: f32 },
        Finish { node: usize, start: f32, end: f32 },
    }

    // Keep the recursive algorithm's pre/post-order semantics, but make the
    // call stack explicit.  This keeps radial layout safe for 10k-depth
    // mindmaps while retaining exactly the same child-span calculations.
    let mut work = vec![AngleWork::Assign {
        node: node_index,
        start: start_angle,
        end: end_angle,
    }];
    while let Some(task) = work.pop() {
        match task {
            AngleWork::Finish { node, start, end } => {
                let children = tree.children.of(node);
                let total_child_angle: f32 = children.iter().map(|child| angles[*child]).sum();
                angles[node] = total_child_angle / children.len().max(1) as f32;
                if !angles[node].is_finite() {
                    angles[node] = f32::midpoint(start, end);
                }
            }
            AngleWork::Assign { node, start, end } => {
                let children = tree.children.of(node);
                if children.is_empty() {
                    angles[node] = f32::midpoint(start, end);
                    continue;
                }

                let available = (end - start).max(0.0);
                if available <= f32::EPSILON {
                    angles[node] = start;
                    for child in children.iter().rev() {
                        work.push(AngleWork::Assign {
                            node: *child,
                            start,
                            end: start,
                        });
                    }
                    continue;
                }

                let total_child_leaves: usize =
                    children.iter().map(|child| leaf_counts[*child]).sum();
                let total_child_leaves = total_child_leaves.max(1);
                let child_level = tree.depth[node] + depth_offset + 1;
                let child_radius = radii.get(child_level).copied().unwrap_or(1.0).max(1.0);
                let required_spans: Vec<f32> = children
                    .iter()
                    .map(|child| {
                        let (width, height) = node_sizes[*child];
                        (spacing.node_spacing.mul_add(0.35, width.max(height)) / child_radius)
                            .min(PI)
                    })
                    .collect();
                let required_sum: f32 = required_spans.iter().sum();
                let mut spans = vec![0.0_f32; children.len()];
                if required_sum >= available {
                    for (index, child) in children.iter().enumerate() {
                        let weight = leaf_counts[*child] as f32 / total_child_leaves as f32;
                        spans[index] = available * weight;
                    }
                } else {
                    let extra = available - required_sum;
                    for (index, child) in children.iter().enumerate() {
                        let weight = leaf_counts[*child] as f32 / total_child_leaves as f32;
                        spans[index] = required_spans[index] + (extra * weight);
                    }
                }

                // Fix floating-point drift so child spans cover the requested range exactly.
                let assigned: f32 = spans.iter().sum();
                if let Some(last_span) = spans.last_mut() {
                    *last_span += available - assigned;
                }

                let mut child_ranges = Vec::with_capacity(children.len());
                let mut cursor = start;
                for (index, child) in children.iter().enumerate() {
                    let child_end = if index + 1 == children.len() {
                        end
                    } else {
                        cursor + spans[index]
                    };
                    child_ranges.push((*child, cursor, child_end));
                    cursor = child_end;
                }

                work.push(AngleWork::Finish { node, start, end });
                for (child, child_start, child_end) in child_ranges.into_iter().rev() {
                    work.push(AngleWork::Assign {
                        node: child,
                        start: child_start,
                        end: child_end,
                    });
                }
            }
        }
    }
}

/// Deterministic initial placement using a hash of node IDs.
///
/// Places nodes in a grid pattern with positions offset by a deterministic
/// hash so that the layout doesn't depend on node insertion order.
fn force_initial_positions(
    ir: &MermaidDiagramIr,
    node_sizes: &[(f32, f32)],
    spacing: &LayoutSpacing,
) -> Vec<(f32, f32)> {
    let n = ir.nodes.len();
    let cols = ((n as f32).sqrt().ceil() as usize).max(1);
    let cell_size = spacing.node_spacing + spacing.rank_spacing;

    ir.nodes
        .iter()
        .enumerate()
        .map(|(i, node)| {
            // Deterministic hash: FNV-1a on node ID bytes.
            let hash = fnv1a_hash(node.id.as_bytes());
            // Small perturbation from hash to break symmetry.
            let jitter_x = ((hash & 0xFF) as f32 / 255.0 - 0.5) * cell_size * 0.3;
            let jitter_y = (((hash >> 8) & 0xFF) as f32 / 255.0 - 0.5) * cell_size * 0.3;

            let col = i % cols;
            let row = i / cols;
            let (w, h) = node_sizes[i];
            let x = (col as f32).mul_add(cell_size, jitter_x) + w / 2.0;
            let y = (row as f32).mul_add(cell_size, jitter_y) + h / 2.0;
            (x, y)
        })
        .collect()
}

/// Simple FNV-1a hash for deterministic node placement.
fn fnv1a_hash(bytes: &[u8]) -> u64 {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in bytes {
        hash ^= u64::from(b);
        hash = hash.wrapping_mul(0x0100_0000_01b3);
    }
    hash
}

/// Build adjacency list from edges.
fn force_build_adjacency(ir: &MermaidDiagramIr) -> Vec<Vec<usize>> {
    let n = ir.nodes.len();
    let mut adj = vec![Vec::new(); n];
    for edge in &ir.edges {
        let from = endpoint_node_index(ir, edge.from);
        let to = endpoint_node_index(ir, edge.to);
        if let (Some(f), Some(t)) = (from, to)
            && f != t
            && f < n
            && t < n
        {
            adj[f].push(t);
            adj[t].push(f);
        }
    }
    // Deduplicate.
    for neighbors in &mut adj {
        neighbors.sort_unstable();
        neighbors.dedup();
    }
    adj
}

/// Map each node to its cluster index (if any).
fn force_cluster_membership(ir: &MermaidDiagramIr) -> Vec<Option<usize>> {
    let n = ir.nodes.len();
    let mut membership = vec![None; n];
    for (ci, cluster) in ir.clusters.iter().enumerate() {
        for member in &cluster.members {
            if member.0 < n {
                membership[member.0] = Some(ci);
            }
        }
    }
    membership
}

/// Compute iteration budget based on graph size.
fn force_iteration_budget(n: usize) -> usize {
    // More nodes need more iterations, but cap at 500.
    (50 + n * 2).min(500)
}

/// Cooling schedule: linear decay from initial temperature.
fn force_temperature(iteration: usize, max_iterations: usize, k: f32) -> f32 {
    let t0 = k * 10.0; // Initial temperature
    let progress = iteration as f32 / max_iterations.max(1) as f32;
    t0 * (1.0 - progress)
}

/// Compute force displacements for all nodes.
///
/// Small diagrams use the exact O(n^2) kernel; larger diagrams use a
/// deterministic adaptive Barnes-Hut quadtree.
fn force_compute_displacements(
    positions: &[(f32, f32)],
    node_sizes: &[(f32, f32)],
    adjacency: &[Vec<usize>],
    cluster_membership: &[Option<usize>],
    k: f32,
    n: usize,
) -> Vec<(f32, f32)> {
    let mut displacements = vec![(0.0_f32, 0.0_f32); n];
    let k_sq = k * k;

    if n <= 100 {
        force_direct_repulsion(positions, k_sq, &mut displacements);
    } else {
        // Barnes-Hut grid approximation for large graphs.
        force_barnes_hut_repulsion(positions, k_sq, &mut displacements);
    }

    // Attractive forces along edges (Hooke's law).
    for (i, neighbors) in adjacency.iter().enumerate() {
        for &j in neighbors {
            if j <= i {
                continue; // Process each edge once.
            }
            let dx = positions[i].0 - positions[j].0;
            let dy = positions[i].1 - positions[j].1;
            let dist = dx.hypot(dy).max(1.0);
            // Fruchterman-Reingold attractive force: d^2 / k
            // Vector component: (dx / d) * (d^2 / k) = dx * d / k
            let force_over_d = dist / k;
            let fx = dx * force_over_d;
            let fy = dy * force_over_d;
            displacements[i].0 -= fx;
            displacements[i].1 -= fy;
            displacements[j].0 += fx;
            displacements[j].1 += fy;
        }
    }

    // Cluster cohesion: extra attractive force toward cluster centroid.
    force_cluster_cohesion(
        positions,
        node_sizes,
        cluster_membership,
        k,
        &mut displacements,
    );

    displacements
}

/// Exact Fruchterman-Reingold repulsion, retained as the small-graph control.
fn force_direct_repulsion(positions: &[(f32, f32)], k_sq: f32, displacements: &mut [(f32, f32)]) {
    for (left_index, &(left_x, left_y)) in positions.iter().enumerate() {
        for (right_index, &(right_x, right_y)) in positions.iter().enumerate().skip(left_index + 1)
        {
            let dx = left_x - right_x;
            let dy = left_y - right_y;
            let dist_sq = dy.mul_add(dy, dx * dx).max(1.0);
            let force_over_d = k_sq / dist_sq;
            let fx = dx * force_over_d;
            let fy = dy * force_over_d;
            displacements[left_index].0 += fx;
            displacements[left_index].1 += fy;
            displacements[right_index].0 -= fx;
            displacements[right_index].1 -= fy;
        }
    }
}

const FORCE_QUADTREE_LEAF_CAPACITY: usize = 8;
const FORCE_QUADTREE_MAX_DEPTH: usize = 24;
const FORCE_QUADTREE_OPENING_SQ: f32 = 0.49;

/// A deterministic Barnes-Hut cell. Children are ordered NW, NE, SW, SE.
struct ForceQuadTreeNode {
    center: (f32, f32),
    half_width: f32,
    mass: usize,
    centroid: (f32, f32),
    members: Vec<usize>,
    children: [Option<Box<Self>>; 4],
}

impl ForceQuadTreeNode {
    fn is_leaf(&self) -> bool {
        self.children.iter().all(Option::is_none)
    }
}

fn force_quadrant((x, y): (f32, f32), center: (f32, f32)) -> usize {
    usize::from(x >= center.0) | (usize::from(y >= center.1) << 1)
}

fn force_build_quadtree(
    positions: &[(f32, f32)],
    members: &[usize],
    center: (f32, f32),
    half_width: f32,
    depth: usize,
) -> ForceQuadTreeNode {
    let (sum_x, sum_y) = members
        .iter()
        .fold((0.0_f32, 0.0_f32), |(sum_x, sum_y), &member| {
            (sum_x + positions[member].0, sum_y + positions[member].1)
        });
    let mass = members.len();
    let centroid = (sum_x / mass as f32, sum_y / mass as f32);

    if mass <= FORCE_QUADTREE_LEAF_CAPACITY || depth >= FORCE_QUADTREE_MAX_DEPTH {
        return ForceQuadTreeNode {
            center,
            half_width,
            mass,
            centroid,
            members: members.to_vec(),
            children: std::array::from_fn(|_| None),
        };
    }

    let mut child_members: [Vec<usize>; 4] = std::array::from_fn(|_| Vec::new());
    for &member in members {
        child_members[force_quadrant(positions[member], center)].push(member);
    }
    let child_half_width = half_width * 0.5;
    let children = std::array::from_fn(|quadrant| {
        (!child_members[quadrant].is_empty()).then(|| {
            let child_center = (
                center.0
                    + if quadrant & 1 == 0 {
                        -child_half_width
                    } else {
                        child_half_width
                    },
                center.1
                    + if quadrant & 2 == 0 {
                        -child_half_width
                    } else {
                        child_half_width
                    },
            );
            Box::new(force_build_quadtree(
                positions,
                &child_members[quadrant],
                child_center,
                child_half_width,
                depth + 1,
            ))
        })
    });

    ForceQuadTreeNode {
        center,
        half_width,
        mass,
        centroid,
        members: Vec::new(),
        children,
    }
}

fn force_add_repulsion(
    displacement: &mut (f32, f32),
    from: (f32, f32),
    to: (f32, f32),
    mass: usize,
    k_sq: f32,
) {
    let dx = from.0 - to.0;
    let dy = from.1 - to.1;
    let dist_sq = dy.mul_add(dy, dx * dx).max(1.0);
    let force_over_d = (k_sq * mass as f32) / dist_sq;
    displacement.0 = dx.mul_add(force_over_d, displacement.0);
    displacement.1 = dy.mul_add(force_over_d, displacement.1);
}

fn force_accumulate_quadtree_repulsion(
    node: &ForceQuadTreeNode,
    positions: &[(f32, f32)],
    target: usize,
    k_sq: f32,
    contains_target: bool,
    displacement: &mut (f32, f32),
) {
    if node.is_leaf() {
        for &member in &node.members {
            if member != target {
                force_add_repulsion(displacement, positions[target], positions[member], 1, k_sq);
            }
        }
        return;
    }

    let dx = positions[target].0 - node.centroid.0;
    let dy = positions[target].1 - node.centroid.1;
    let dist_sq = dy.mul_add(dy, dx * dx).max(1.0);
    let cell_width = node.half_width * 2.0;
    if !contains_target && (cell_width * cell_width) / dist_sq < FORCE_QUADTREE_OPENING_SQ {
        force_add_repulsion(
            displacement,
            positions[target],
            node.centroid,
            node.mass,
            k_sq,
        );
        return;
    }

    let target_quadrant = force_quadrant(positions[target], node.center);
    for (quadrant, child) in node.children.iter().enumerate() {
        if let Some(child) = child {
            force_accumulate_quadtree_repulsion(
                child,
                positions,
                target,
                k_sq,
                contains_target && quadrant == target_quadrant,
                displacement,
            );
        }
    }
}

/// Adaptive Barnes-Hut approximation for repulsive forces.
///
/// Unlike the old fixed grid, this traverses only the cells needed for the
/// current node and aggregates well-separated subtrees at their centroid.
fn force_barnes_hut_repulsion(
    positions: &[(f32, f32)],
    k_sq: f32,
    displacements: &mut [(f32, f32)],
) {
    let n = positions.len();
    if n < 2 {
        return;
    }
    // Find bounding box.
    let mut min_x = f32::INFINITY;
    let mut min_y = f32::INFINITY;
    let mut max_x = f32::NEG_INFINITY;
    let mut max_y = f32::NEG_INFINITY;
    for &(x, y) in positions {
        min_x = min_x.min(x);
        min_y = min_y.min(y);
        max_x = max_x.max(x);
        max_y = max_y.max(y);
    }

    let half_width = ((max_x - min_x).max(max_y - min_y) * 0.5).max(1.0);
    let center = ((min_x + max_x) * 0.5, (min_y + max_y) * 0.5);
    let members: Vec<usize> = (0..n).collect();
    let root = force_build_quadtree(positions, &members, center, half_width, 0);

    for (target, displacement) in displacements.iter_mut().enumerate() {
        force_accumulate_quadtree_repulsion(&root, positions, target, k_sq, true, displacement);
    }
}

/// Apply extra attractive force for nodes in the same cluster.
fn force_cluster_cohesion(
    positions: &[(f32, f32)],
    _node_sizes: &[(f32, f32)],
    cluster_membership: &[Option<usize>],
    k: f32,
    displacements: &mut [(f32, f32)],
) {
    // Compute cluster centroids.
    let mut cluster_sum: BTreeMap<usize, (f32, f32, usize)> = BTreeMap::new();
    for (i, &membership) in cluster_membership.iter().enumerate() {
        if let Some(ci) = membership {
            let entry = cluster_sum.entry(ci).or_insert((0.0, 0.0, 0));
            entry.0 += positions[i].0;
            entry.1 += positions[i].1;
            entry.2 += 1;
        }
    }

    let cohesion_strength = 0.3; // Extra pull toward cluster center

    for (i, &membership) in cluster_membership.iter().enumerate() {
        if let Some(ci) = membership
            && let Some(&(sx, sy, count)) = cluster_sum.get(&ci)
            && count > 1
        {
            let centroid_x = sx / count as f32;
            let centroid_y = sy / count as f32;
            let dx = centroid_x - positions[i].0;
            let dy = centroid_y - positions[i].1;
            let dist = dx.hypot(dy).max(1.0);
            let force = dist / k * cohesion_strength;
            displacements[i].0 = (dx / dist).mul_add(force, displacements[i].0);
            displacements[i].1 = (dy / dist).mul_add(force, displacements[i].1);
        }
    }
}

/// Remove node overlaps via iterative projection.
fn force_remove_overlaps(
    positions: &mut [(f32, f32)],
    node_sizes: &[(f32, f32)],
    spacing: &LayoutSpacing,
) {
    let n = positions.len();
    let gap = spacing.node_spacing * 0.25; // Minimum gap between nodes

    for _pass in 0..20 {
        let mut any_overlap = false;
        for i in 0..n {
            for j in (i + 1)..n {
                let (wi, hi) = node_sizes[i];
                let (wj, hj) = node_sizes[j];
                let half_w = f32::midpoint(wi, wj) + gap;
                let half_h = f32::midpoint(hi, hj) + gap;

                let dx = positions[j].0 - positions[i].0;
                let dy = positions[j].1 - positions[i].1;
                let overlap_x = half_w - dx.abs();
                let overlap_y = half_h - dy.abs();

                if overlap_x > 0.0 && overlap_y > 0.0 {
                    any_overlap = true;
                    // Push apart along the axis with less overlap.
                    if overlap_x < overlap_y {
                        let push = overlap_x / 2.0;
                        if dx >= 0.0 {
                            positions[i].0 -= push;
                            positions[j].0 += push;
                        } else {
                            positions[i].0 += push;
                            positions[j].0 -= push;
                        }
                    } else {
                        let push = overlap_y / 2.0;
                        if dy >= 0.0 {
                            positions[i].1 -= push;
                            positions[j].1 += push;
                        } else {
                            positions[i].1 += push;
                            positions[j].1 -= push;
                        }
                    }
                }
            }
        }
        if !any_overlap {
            break;
        }
    }
}

/// Normalize positions so all coordinates are non-negative.
fn force_normalize_positions(positions: &mut [(f32, f32)], node_sizes: &[(f32, f32)]) {
    if positions.is_empty() {
        return;
    }
    let margin = 20.0;
    let mut min_x = f32::MAX;
    let mut min_y = f32::MAX;
    for (i, &(x, y)) in positions.iter().enumerate() {
        if !x.is_finite() || !y.is_finite() {
            continue;
        }
        let (w, h) = node_sizes[i];
        min_x = min_x.min(x - w / 2.0);
        min_y = min_y.min(y - h / 2.0);
    }
    if !min_x.is_finite() || !min_y.is_finite() {
        return;
    }
    let offset_x = margin - min_x;
    let offset_y = margin - min_y;
    for pos in positions.iter_mut() {
        pos.0 += offset_x;
        pos.1 += offset_y;
    }
}

/// Build `LayoutNodeBox` from force-directed positions (center-based).
fn force_build_node_boxes(
    ir: &MermaidDiagramIr,
    positions: &[(f32, f32)],
    node_sizes: &[(f32, f32)],
) -> Vec<LayoutNodeBox> {
    ir.nodes
        .iter()
        .enumerate()
        .map(|(i, node)| {
            let (cx, cy) = positions[i];
            let (w, h) = node_sizes[i];
            LayoutNodeBox {
                node_index: i,
                node_id: node.id.clone(),
                rank: 0,  // No ranks in force-directed layout.
                order: i, // Order by index.
                span: node.span_primary,
                bounds: LayoutRect {
                    x: cx - w / 2.0,
                    y: cy - h / 2.0,
                    width: w,
                    height: h,
                },
            }
        })
        .collect()
}

/// Build straight-line edge paths for force-directed layout.
/// Fan offset per edge index for edges sharing an unordered endpoint pair.
///
/// Same formula the Sugiyama builder uses — a symmetric fan of 12px steps centred on zero — so the
/// two layouts separate parallel edges by the same amount. Returns an empty `Vec` when no pair
/// repeats, which is the common case, so callers skip the work entirely.
///
/// Without this the Force path gave every edge between one pair identical geometry, so an ER model
/// with two relationships between the same entities (`A ||--o{ B : owns` and `A ||--o{ B : rents`)
/// drew one line and silently lost the other.
fn force_parallel_edge_offsets(ir: &MermaidDiagramIr) -> Vec<f32> {
    let mut seen: FxHashSet<(usize, usize)> = FxHashSet::default();
    seen.reserve(ir.edges.len());
    // `fm_core::IrEdge` is not in this module's import list (see the `use fm_core::{…}` at the top),
    // so it is named in full here rather than widening that list for one closure.
    let pair_of = |edge: &fm_core::IrEdge| {
        let source = endpoint_node_index(ir, edge.from).unwrap_or(usize::MAX);
        let target = endpoint_node_index(ir, edge.to).unwrap_or(usize::MAX);
        (source.min(target), source.max(target))
    };
    if ir.edges.iter().all(|edge| seen.insert(pair_of(edge))) {
        return Vec::new();
    }

    let mut count: FxHashMap<(usize, usize), usize> = FxHashMap::default();
    count.reserve(ir.edges.len());
    let mut index = Vec::with_capacity(ir.edges.len());
    for edge in &ir.edges {
        let slot = count.entry(pair_of(edge)).or_insert(0);
        index.push(*slot);
        *slot += 1;
    }
    index
        .iter()
        .zip(ir.edges.iter())
        .map(|(&pair_idx, edge)| {
            let pair_total = count.get(&pair_of(edge)).copied().unwrap_or(1);
            if pair_total > 1 {
                let offset_step = 12.0_f32;
                (pair_idx as f32 - (pair_total - 1) as f32 / 2.0) * offset_step
            } else {
                0.0
            }
        })
        .collect()
}

fn force_build_edge_paths(ir: &MermaidDiagramIr, nodes: &[LayoutNodeBox]) -> Vec<LayoutEdgePath> {
    let parallel_offsets = force_parallel_edge_offsets(ir);
    // Obstacle set for avoidance (bd-h2ze). This builder used to emit a bare `[from, to]` line for
    // every edge, so a node sitting between two connected nodes was simply drawn through -- 30
    // cases across five committed goldens, up to 33.2px into a 66.5px-tall box, i.e. the CENTRE of
    // the node rather than a clipped corner. An edge crossing a node reads as connecting to it, so
    // the picture asserted relationships the source never declared.
    //
    // The avoidance machinery was never overridden here; it was never CALLED. `build_edge_paths`
    // (the Sugiyama path) consults `route_edge_points_with_obstacle_index`, and this one did not,
    // which is why 27 of the 30 cases sit in cycle_* fixtures: cycle-heavy graphs dispatch to
    // force layout and take this builder.
    // `None` for the spatial index: the router falls back to a linear AABB scan, which is the
    // right call here rather than duplicating `build_edge_paths`'s eligibility heuristic. Force
    // layout is chosen for small-to-medium graphs, so the scan is cheap; if a large force graph
    // ever shows up in a profile, the index can be added behind the same threshold.
    let mut obstacle_bounds: Vec<LayoutRect> = nodes.iter().map(|node| node.bounds).collect();
    ir.edges
        .iter()
        .enumerate()
        .filter_map(|(ei, edge)| {
            let parallel_offset = parallel_offsets.get(ei).copied().unwrap_or(0.0);
            let from_idx = endpoint_node_index(ir, edge.from)?;
            let to_idx = endpoint_node_index(ir, edge.to)?;
            if from_idx >= nodes.len() || to_idx >= nodes.len() {
                return None;
            }
            // A self-reference is a real relationship and must be drawn as one. Clipping a
            // centre-to-centre line when both centres are the SAME point yields two identical
            // points — `clip_to_shape_border` returns `from` unchanged for a zero-length direction
            // — so the edge existed in the layout but had no extent and rendered as nothing. The
            // Sugiyama builder already routes these through `route_self_loop`; this path did not,
            // and ER diagrams (`EMPLOYEE ||--o{ EMPLOYEE : manages`) are laid out here.
            if from_idx == to_idx {
                return Some(LayoutEdgePath {
                    edge_index: ei,
                    span: edge.span,
                    // Force layout has no rank orientation, so use the same vertical loop the
                    // Sugiyama path draws for a top-to-bottom graph.
                    points: route_self_loop(&nodes[from_idx], false),
                    reversed: false,
                    is_self_loop: true,
                    parallel_offset: 0.0,
                    bundle_count: 1,
                    bundled: false,
                });
            }

            let from_center = nodes[from_idx].bounds.center();
            let to_center = nodes[to_idx].bounds.center();

            // Clip to the DRAWN outline, not the bounding box: a diagonal approach to a circle or
            // diamond otherwise stops short of the shape and the arrowhead floats.
            let from_shape = ir
                .nodes
                .get(from_idx)
                .map_or(fm_core::NodeShape::Rect, |node| node.shape);
            let to_shape = ir
                .nodes
                .get(to_idx)
                .map_or(fm_core::NodeShape::Rect, |node| node.shape);
            let from_pt =
                clip_to_shape_border(from_center, to_center, &nodes[from_idx].bounds, from_shape);
            let to_pt =
                clip_to_shape_border(to_center, from_center, &nodes[to_idx].bounds, to_shape);

            // An edge must not avoid its OWN endpoints, so park those two boxes far away for the
            // duration of this query and restore them afterwards -- the same technique
            // `build_edge_paths` uses. Restoring matters: the set is shared across every edge, so a
            // parked box left parked would make the next edge blind to that node.
            let saved_from = obstacle_bounds.get(from_idx).copied();
            let saved_to = obstacle_bounds.get(to_idx).copied();
            let parked = LayoutRect {
                x: 1e30,
                y: 1e30,
                width: 0.0,
                height: 0.0,
            };
            if let Some(slot) = obstacle_bounds.get_mut(from_idx) {
                *slot = parked;
            }
            if let Some(slot) = obstacle_bounds.get_mut(to_idx) {
                *slot = parked;
            }
            // `false` for `horizontal_ranks`: force layout has no rank orientation, and this is the
            // same convention the self-loop branch above already uses.
            let mut points = route_edge_points_with_obstacle_index(
                from_pt,
                to_pt,
                false,
                &obstacle_bounds,
                None,
            );
            if let (Some(slot), Some(saved)) = (obstacle_bounds.get_mut(from_idx), saved_from) {
                *slot = saved;
            }
            if let (Some(slot), Some(saved)) = (obstacle_bounds.get_mut(to_idx), saved_to) {
                *slot = saved;
            }
            if parallel_offset.abs() > 0.01 {
                // Same helper and same orientation convention the Sugiyama builder uses, so the two
                // layouts fan a repeated pair identically instead of one of them stacking the edges.
                apply_parallel_offset(&mut points, parallel_offset, false);
            }
            Some(LayoutEdgePath {
                edge_index: ei,
                span: edge.span,
                points,
                reversed: false,
                is_self_loop: from_idx == to_idx,
                parallel_offset,
                bundle_count: 1,
                bundled: false,
            })
        })
        .collect()
}

/// Clip a line from `from` toward `to` to the border of `rect`.
/// Clip a ray from a node's centre to the node's DRAWN outline.
///
/// The bounding box is only the right answer for box-like shapes. A circle or diamond is
/// inscribed in its bounds and touches them at just the four side midpoints, so clipping a
/// diagonal approach to the rectangle leaves the endpoint floating outside the drawn shape — by up
/// to a factor of sqrt(2) for a circle, which reads as an arrowhead detached from its node.
///
/// Only the force-directed path needs this. `edge_anchors`, used by the Sugiyama route, attaches
/// at side midpoints, which is exactly where an inscribed circle or diamond meets its box.
fn clip_to_shape_border(
    from: LayoutPoint,
    to: LayoutPoint,
    rect: &LayoutRect,
    shape: fm_core::NodeShape,
) -> LayoutPoint {
    use fm_core::NodeShape;

    let cx = rect.x + rect.width / 2.0;
    let cy = rect.y + rect.height / 2.0;
    let dx = to.x - from.x;
    let dy = to.y - from.y;

    if dx.abs() < f32::EPSILON && dy.abs() < f32::EPSILON {
        return from;
    }

    let half_w = rect.width / 2.0;
    let half_h = rect.height / 2.0;

    // Parameter along (dx, dy) at which the ray leaves the shape, measured from the centre.
    let t = match shape {
        // Inscribed ellipse: |(t*dx/half_w, t*dy/half_h)| = 1.
        NodeShape::Circle | NodeShape::FilledCircle | NodeShape::DoubleCircle => {
            let nx = dx / half_w.max(f32::EPSILON);
            let ny = dy / half_h.max(f32::EPSILON);
            let norm = nx.hypot(ny);
            if norm < f32::EPSILON {
                return from;
            }
            1.0 / norm
        }
        // Inscribed rhombus: |x|/half_w + |y|/half_h = 1.
        NodeShape::Diamond => {
            let denominator =
                dx.abs() / half_w.max(f32::EPSILON) + dy.abs() / half_h.max(f32::EPSILON);
            if denominator < f32::EPSILON {
                return from;
            }
            1.0 / denominator
        }
        // Everything else keeps the box clip. Stadium/hexagon/trapezoid and friends differ from
        // their box only near the corners, and guessing an outline per shape would risk moving
        // endpoints for shapes nobody has reported wrong.
        _ => {
            let tx = if dx.abs() > f32::EPSILON {
                half_w / dx.abs()
            } else {
                f32::MAX
            };
            let ty = if dy.abs() > f32::EPSILON {
                half_h / dy.abs()
            } else {
                f32::MAX
            };
            tx.min(ty)
        }
    };

    LayoutPoint {
        x: dx.mul_add(t, cx),
        y: dy.mul_add(t, cy),
    }
}

#[must_use]
pub fn compute_node_sizes(
    ir: &MermaidDiagramIr,
    metrics: &fm_core::FontMetrics,
) -> Vec<(f32, f32)> {
    ACTIVE_INCREMENTAL_STATE.with(|slot| {
        let mut state = slot.borrow_mut();
        let Some(state) = state.as_mut() else {
            return ir
                .nodes
                .iter()
                .map(|node| compute_node_size(ir, node, metrics))
                .collect();
        };

        let start = Instant::now();
        let total_nodes = ir.nodes.len();
        let mut recomputed_nodes = 0_usize;
        let sizes = ir
            .nodes
            .iter()
            .map(|node| {
                let cache_key = node_size_cache_key(ir, node, metrics);
                if let Some(entry) = state.node_size_cache.get(&node.id)
                    && entry.key == cache_key
                {
                    return entry.size;
                }

                recomputed_nodes = recomputed_nodes.saturating_add(1);
                debug!(
                    query_type = "node_sizes",
                    node_id = %node.id,
                    "incremental.cache_miss"
                );
                trace!(
                    query_type = "node_sizes",
                    node_id = %node.id,
                    cache_key,
                    "incremental.dependency_update"
                );
                let size = compute_node_size(ir, node, metrics);
                state.node_size_cache.insert(
                    node.id.clone(),
                    CachedNodeSize {
                        key: cache_key,
                        size,
                    },
                );
                size
            })
            .collect();

        let summary = IncrementalQuerySummary {
            query_type: "node_sizes",
            cache_hit: recomputed_nodes == 0,
            recomputed_nodes,
            total_nodes,
            recompute_duration_us: start.elapsed().as_micros().try_into().unwrap_or(u64::MAX),
        };
        trace!(
            query_type = summary.query_type,
            cache_hit = summary.cache_hit,
            recomputed_nodes = summary.recomputed_nodes,
            total_nodes = summary.total_nodes,
            recompute_duration_us = summary.recompute_duration_us,
            "incremental.recompute"
        );
        state.record_query(summary);
        sizes
    })
}

fn compute_node_size(
    ir: &MermaidDiagramIr,
    node: &IrNode,
    metrics: &fm_core::FontMetrics,
) -> (f32, f32) {
    let text = display_node_label_ref(ir, node);

    match node.shape {
        // ⚠️ ASYMMETRIC SIBLINGS. `DoubleCircle` below already sizes to its text when it has any,
        // and `FilledCircle` was pinned at 20x20 unconditionally — fine while both shapes only ever
        // appeared as label-less state pseudo-states, wrong the moment gitGraph's `type: REVERSE`
        // commits started displaying their ids (bd-3cj8v). The dot stayed 20px and the id was
        // elided to `th…` INSIDE it. Same branch as the sibling, same reason.
        fm_core::NodeShape::FilledCircle => {
            if text.is_empty() {
                (20.0, 20.0)
            } else {
                let (label_width, label_height) = metrics.estimate_dimensions(text);
                (
                    (label_width + 52.0).max(42.0),
                    (label_height + 30.0).max(42.0),
                )
            }
        }
        fm_core::NodeShape::DoubleCircle => {
            if text.is_empty() {
                (24.0, 24.0)
            } else {
                let (label_width, label_height) = metrics.estimate_dimensions(text);
                (
                    (label_width + 52.0).max(42.0),
                    (label_height + 30.0).max(42.0),
                )
            }
        }
        fm_core::NodeShape::HorizontalBar => (72.0, 16.0),
        _ => {
            let text = if text.is_empty() {
                node.id.as_str()
            } else {
                text
            };
            let (label_width, label_height) = metrics.estimate_dimensions(text);
            let (icon_width, icon_height) = icon_dimensions(node, metrics);
            let width = label_width
                .max(icon_width)
                .max(icon_width.mul_add(0.85, label_width))
                + 72.0;
            let height = label_height + icon_height + 44.0;
            let (width, height) = (width.max(100.0), height.max(52.0));
            // A class node's box must also hold its compartment stack. The SVG renderer walks the
            // member rows against the node's own height and `break`s on the first row that would
            // fall outside it, so a box sized from the label alone SILENTLY DROPS members rather
            // than overflowing — see `class_compartment_dimensions`.
            let (width, height) = match class_compartment_dimensions(node, metrics) {
                Some((members_width, members_height)) => {
                    (width.max(members_width), height.max(members_height))
                }
                None => (width, height),
            };
            // An ER entity's box must likewise hold its attribute rows. Unlike the class renderer,
            // the ER renderer does not stop at the box edge — it keeps emitting rows — so a box
            // sized from the entity name alone spills attributes outside it (bd-090g).
            let (width, height) = match er_compartment_dimensions(node, metrics) {
                Some((rows_width, rows_height)) => (width.max(rows_width), height.max(rows_height)),
                None => (width, height),
            };
            // A C4 node's box must hold its WRAPPED description. The renderer clamps the
            // description's first baseline into the box but the `<tspan>` stack then descends from
            // there, so clamping the anchor does not bound the block — a 16-line description drew
            // 220px below its own rectangle (bd-9xjy).
            let (width, height) = match c4_description_height(node, metrics, width) {
                Some(description_height) => (width, height.max(description_height)),
                None => (width, height),
            };
            // ...and it must hold the ROW STACK drawn under the name — `<<type>>`, `[technology]`,
            // description. `c4_description_height` above sizes only for a description that WRAPS,
            // on the reasoning that a single-line one is contained by the SVG renderer's baseline
            // clamp. That reasoning does not reach the canvas, which does not clamp: it walks the
            // rows against the box and `break`s on the first that would fall outside, exactly as the
            // class renderer does. Measured on `Person(alice, "Alice", "A user")`: a 39.6 box, name
            // at 46.2, `<<Person>>` at 55.3, and the description's baseline at 70.42 against a
            // 61.3 limit — so the declared description was DROPPED from the canvas that fm-wasm
            // ships, while the SVG drew it clamped on top of the row above.
            let (width, height) = match c4_row_stack_dimensions(node, metrics) {
                Some((rows_width, rows_height)) => (width.max(rows_width), height.max(rows_height)),
                None => (width, height),
            };
            // A requirement node's box must hold the two rows the renderer draws BESIDE the name:
            // the `«type»` header and the `Risk: … | Verify: …` row. Nothing sized for them at all,
            // so whether a row escaped depended on how long the declared `risk:`/`verifymethod:`
            // strings happened to be — golden/requirement_basic's LoginReq measured 163.37 in a
            // 133.05-wide box, spilling 15.16 past each side (bd-jnc1).
            match requirement_row_dimensions(node, metrics) {
                Some((rows_width, rows_height)) => (width.max(rows_width), height.max(rows_height)),
                None => (width, height),
            }
        }
    }
}

/// Size a requirement node's box needs so the rows drawn beside its name stay inside it.
///
/// `None` when the node is not a requirement node, or when it declares neither a type nor any
/// risk/verify metadata — then only the name is drawn and the base sizing already covers it.
///
/// Mirrors `fm-render-svg`'s `write_requirement_node_fragment_into`: an optional `«{type}»` row and
/// an optional `Risk: …[ | Verify: …]` row (or `Verify: …` alone), both centred on `cx` at
/// `font_size * 0.75`, with the name row between them at full size. Rows advance `font_size * 0.85`
/// from a first baseline at `y + h * 0.25 + font_size * 0.35`.
///
/// Measured at the LAYOUT metrics' font size, which is the full node font; the renderer draws these
/// rows at its own (smaller) detail-tier size, so this over-estimates rather than under-estimates.
/// Over-sizing renders as padding; under-sizing is the defect.
fn requirement_row_dimensions(node: &IrNode, metrics: &fm_core::FontMetrics) -> Option<(f32, f32)> {
    let meta = node.requirement_meta.as_deref()?;

    let font_size = metrics.font_size();
    let subtitle_font = (font_size * 0.75).max(REQUIREMENT_FONT_FLOOR);
    // `estimate_width` measures at `font_size`; these rows are drawn smaller, and width scales with
    // the em size.
    let subtitle_scale = subtitle_font / font_size.max(f32::EPSILON);
    let mut widest = 0.0_f32;
    let mut rows = 1_usize; // the name row, always drawn

    if let Some(req_type) = meta.requirement_type.as_deref() {
        // The renderer wraps the type in guillemets, which are two more glyphs to hold.
        let mut row = String::with_capacity(req_type.len() + 2);
        row.push('\u{00ab}');
        row.push_str(req_type);
        row.push('\u{00bb}');
        widest = widest.max(metrics.estimate_width(&row) * subtitle_scale);
        rows += 1;
    }

    // `ID: …` and `Text: …` rows (bd-f3tc). Widened for, not wrapped: the incumbent's requirement
    // renderer draws each as one unwrapped label and grows the box to its bbox, so wrapping here
    // would diverge from it. A long `text:` therefore makes a wide box, exactly as it does there.
    for (prefix, value) in [
        ("ID: ", meta.req_id.as_deref()),
        ("Text: ", meta.text.as_deref()),
    ] {
        let Some(value) = value else { continue };
        let mut row = String::with_capacity(prefix.len() + value.len());
        row.push_str(prefix);
        row.push_str(value);
        widest = widest.max(metrics.estimate_width(&row) * subtitle_scale);
        rows += 1;
    }

    let metadata_row = match (meta.risk.as_deref(), meta.verify_method.as_deref()) {
        (Some(risk), Some(verify)) => Some(format!("Risk: {risk} | Verify: {verify}")),
        (Some(risk), None) => Some(format!("Risk: {risk}")),
        (None, Some(verify)) => Some(format!("Verify: {verify}")),
        (None, None) => None,
    };
    if let Some(row) = metadata_row.as_deref() {
        widest = widest.max(metrics.estimate_width(row) * subtitle_scale);
        rows += 1;
    }

    if rows == 1 {
        return None;
    }

    // Rows are centred on the box's centre, so the box needs the widest row plus a margin on each
    // side. `REQUIREMENT_ROW_MARGIN` is the total of both sides.
    let width = widest + REQUIREMENT_ROW_MARGIN;
    // Vertical: the last row's baseline sits `0.25h + 0.35font + (rows - 1) * 0.85font` below the
    // box top and needs its descender inside too. Solving `0.75h >= (0.35 + 0.85(rows-1) + 0.3)font`
    // for `h` gives the floor below.
    let height = ((rows - 1) as f32).mul_add(0.85, 0.65) * font_size / 0.75;
    Some((width, height))
}

/// Smallest font the requirement subtitle rows are measured at, mirroring the renderer's
/// `config.min_font_size` clamp on `font_size * 0.75`.
const REQUIREMENT_FONT_FLOOR: f32 = 8.0;

/// Horizontal breathing room a requirement box adds around its widest subtitle row, split evenly
/// between the two sides.
const REQUIREMENT_ROW_MARGIN: f32 = 24.0;

/// Height a C4 node needs so its wrapped description stays inside the box. `None` when the node has
/// no C4 description, or when the description fits on one line — the single-line case is already
/// contained by the renderer's own baseline clamp, so growing it would move committed goldens for no
/// correctness gain.
///
/// Mirrors `fm-render-svg`'s `write_c4_node_into` cursor advance: a type-label row at
/// `small_font * 1.25`, a name row `line_h * 0.95` below it, then `line_h * 0.9` to the description,
/// whose first baseline is pushed down a further `min(block_height, h * 0.35)` and whose lines then
/// stack one `description_font * line_height` apart.
///
/// The `min(block_height, h * 0.35)` shift depends on `h`, which is what we are solving for. Rather
/// than iterate to a fixed point, this uses `block_height` as the bound — always valid because
/// `min(a, b) <= a` — so the result is an over-estimate for tall boxes. Over-sizing renders as
/// padding, and it keeps the arithmetic auditable.
/// Size a C4 node's box needs so the metadata rows drawn UNDER its name stay inside it.
///
/// `None` when the node is not a C4 node, or when it declares no metadata row at all — then only
/// the name is drawn and the base sizing already covers it.
///
/// Mirrors `fm-render-canvas`'s C4 branch, which is the stricter of the two renderers and therefore
/// the one that must fit: a name baseline at `font_size * 1.3`, a `* 0.65` step to the first row,
/// then one row per declared `<<type>>` / `[technology]` / description at `font_size * 0.9`,
/// advancing `member_font * 1.2` and kept only while the baseline stays within
/// `y + h - member_font * 0.5`. fm-render-svg lays the same three strings out differently but
/// clamps rather than drops, so a box that satisfies the canvas satisfies it too.
///
/// This is the same defect the class, ER and requirement siblings above were each filed for: sizing
/// read the node's LABEL and the renderer drew more than the label. The C4 entry existed but
/// measured only the wrapped description, so the row stack that sits above the description was
/// never counted.
fn c4_row_stack_dimensions(node: &IrNode, metrics: &fm_core::FontMetrics) -> Option<(f32, f32)> {
    let meta = node.c4_meta.as_deref()?;

    // Renderer order, and only the rows it actually pushes.
    let mut rows: Vec<&str> = Vec::with_capacity(3);
    if !meta.element_type.is_empty() {
        rows.push(meta.element_type.as_str());
    }
    if let Some(technology) = meta.technology.as_deref().filter(|t| !t.trim().is_empty()) {
        rows.push(technology);
    }
    if let Some(description) = meta.description.as_deref().filter(|d| !d.trim().is_empty()) {
        rows.push(description);
    }
    let last = rows.len().checked_sub(1)?;

    let font_size = metrics.font_size();
    let line_h = font_size * 1.3;
    let member_font = font_size * 0.9;

    // Cursor offsets from the top of the box, in renderer order.
    let mut height = line_h; // `cursor_y = y + line_h` (name baseline)
    height += line_h * 0.5; // name -> first metadata row
    height += member_font * 1.2 * last as f32; // advance to the LAST row's baseline
    height += member_font * 0.5; // the slack the renderer's own keep-test demands
    // Mirroring the cursor arithmetic exactly leaves the last row sitting ON the boundary, where f32
    // rounding — or a render font size that does not match `metrics` — drops it again. Half a row of
    // margin costs a few pixels of padding and takes the decision off the knife edge. Same reasoning,
    // same constant, as `class_compartment_dimensions`.
    height += member_font * 0.6;

    // Rows are left-anchored at `x + 6.0`; mirror that padding on the right so the widest row stays
    // inside the box. `metrics` measures at full size and the rows are drawn at `* 0.9`. The
    // `<<…>>` and `[…]` decorations are drawn too, so they are measured — a bare `element_type`
    // would under-count by four characters.
    let widest = rows
        .iter()
        .enumerate()
        .map(|(index, text)| {
            let decorated = match (index, meta.element_type.is_empty()) {
                (0, false) => format!("<<{text}>>"),
                _ if Some(*text) == meta.technology.as_deref() => format!("[{text}]"),
                _ => (*text).to_string(),
            };
            metrics.estimate_dimensions(&decorated).0 * 0.9
        })
        .fold(0.0_f32, f32::max);

    Some((widest + 12.0, height))
}

fn c4_description_height(node: &IrNode, metrics: &fm_core::FontMetrics, width: f32) -> Option<f32> {
    let description = node.c4_meta.as_deref()?.description.as_deref()?;
    if description.trim().is_empty() {
        return None;
    }

    let font_size = metrics.font_size();
    let line_h = metrics.line_height_px();
    let small_font = (font_size * 0.78).max(C4_FONT_FLOOR);
    let description_font = (font_size * 0.72).max(C4_FONT_FLOOR);

    // Renderer: `available_width = (w - 20.0).max(32.0)` wrapped at `config.avg_char_width * 0.92`.
    // The 0.92 is mirrored rather than dropped. Assuming a wider character would over-count lines,
    // which is the safe direction for containment but grows boxes for descriptions that actually fit
    // on one line — `c4_basic`'s "A customer" counted as two, moving a golden for no correctness
    // gain. Matching the renderer keeps the counts equal whenever layout's metrics and the render
    // config agree, and the disagreement case is absorbed by a line of margin below instead.
    let available_width = (width - 20.0).max(32.0);
    let lines = wrapped_line_count(
        description,
        available_width,
        metrics.avg_char_width() * 0.92,
    );
    if lines <= 1 {
        return None;
    }

    // `description_height` in the renderer: the stack's total descent below its first baseline. One
    // extra line of margin covers layout's metrics disagreeing with the render config's
    // `avg_char_width` by enough to add a wrap — under-counting is what spills rows.
    let per_line = description_font * (line_h / font_size).max(1.0);
    let block_height = lines as f32 * per_line;
    let header = small_font.mul_add(1.25, line_h * 0.95) + line_h * 0.9;
    // header + shift(<= block) + stack + half a glyph below the last baseline.
    Some(header + block_height * 2.0 + description_font * 0.5)
}

/// Lower bound on the renderer's clamped C4 font sizes — `SvgRenderConfig::min_font_size`'s default.
/// The clamp only raises a size, and a raised size means a taller block, so assuming the floor
/// applies errs toward over-sizing.
const C4_FONT_FLOOR: f32 = 8.0;

/// Number of lines `text` wraps to, mirroring `fm-render-svg`'s `wrap_text_to_lines` without
/// building the lines: greedy whitespace wrapping at `floor(max_width / avg_char_width).max(8)`
/// characters, counting a word longer than the limit as occupying its own single line exactly as
/// that function does.
fn wrapped_line_count(text: &str, max_width: f32, avg_char_width: f32) -> usize {
    if text.trim().is_empty() {
        return 0;
    }
    let max_chars = if avg_char_width > 0.0 {
        ((max_width / avg_char_width).floor() as usize).max(8)
    } else {
        8
    };

    let mut lines = 0_usize;
    let mut current = 0_usize;
    for word in text.split_whitespace() {
        let word_chars = word.chars().count();
        let next = if current == 0 {
            word_chars
        } else {
            current + 1 + word_chars
        };
        if next > max_chars && current > 0 {
            lines += 1;
            current = word_chars;
        } else {
            current = next;
        }
    }
    if current > 0 {
        lines += 1;
    }
    lines
}

/// Space a class node needs for its compartment stack (stereotype, name, separators, and one row per
/// attribute and method). `None` for any node that is not a class node or that declares no members.
///
/// This mirrors `fm-render-svg`'s `write_class_compartments_into` cursor advance exactly, because that
/// renderer drops any member row landing below `y + h - line_h * 0.5` instead of growing the box:
/// under-sizing here deletes content from the output, so the arithmetic below must stay in step with
/// the renderer's. Over-sizing is harmless (the extra space renders as padding), so every term is
/// rounded up rather than fitted tight.
fn class_compartment_dimensions(
    node: &IrNode,
    metrics: &fm_core::FontMetrics,
) -> Option<(f32, f32)> {
    let meta = node.class_meta.as_deref()?;
    // A STEREOTYPE ALONE is enough to need a compartment stack (bd-d48wi). A marker interface —
    // `class Shape { <<interface>> }` with no members — is idiomatic mermaid, and the pinned
    // incumbent gates its annotation row on `annotations.length > 0` with no member requirement.
    // Returning `None` here left the box sized from the class name alone, and every backend then
    // declined to draw the stereotype at all rather than draw it into an unsized box.
    if meta.attributes.is_empty() && meta.methods.is_empty() && meta.stereotype.is_none() {
        return None;
    }

    let line_h = metrics.line_height_px();
    // Renderer: `member_font_size * config.line_height * 0.9` with `member_font_size = font_size * 0.9`,
    // i.e. `line_height_px * 0.81`.
    let row_h = line_h * 0.81;

    // Cursor offsets from the top of the box, in renderer order.
    let mut height = line_h; // initial `cursor_y = y + line_h` (name baseline)
    if meta.stereotype.is_some() {
        height += line_h; // stereotype occupies the first row, name moves down one
    }
    height += line_h * 0.5; // name -> separator
    height += line_h * 0.3; // separator -> first member row
    height += row_h * meta.attributes.len() as f32;
    if !meta.attributes.is_empty() && !meta.methods.is_empty() {
        height += line_h * 0.6; // attribute/method separator (0.3 before + 0.3 after)
    }
    height += row_h * meta.methods.len() as f32;
    // The renderer keeps a row only while `cursor_y <= y + h - line_h * 0.5`, so the box needs that
    // much slack past the last row's baseline.
    height += line_h * 0.5;
    // Mirroring the cursor arithmetic exactly leaves the last row sitting ON the boundary, where f32
    // rounding — or a render font size that does not match `metrics` — drops it again. Half a row of
    // margin costs a few pixels of padding and takes the decision off the knife edge.
    height += row_h * 0.5;

    // Member rows are left-anchored at `x + 8.0`; mirror that padding on the right so the widest row
    // stays inside the box.
    let member_width = meta
        .attributes
        .iter()
        .map(|attr| class_member_row_width(attr, false, metrics))
        .chain(
            meta.methods
                .iter()
                .map(|method| class_member_row_width(method, true, metrics)),
        )
        .fold(0.0_f32, f32::max);

    // The STEREOTYPE row is drawn in this box too, so it has to be measured in it. It was not:
    // width came from the member rows alone, and the caller's other term is the CLASS NAME, so
    // `class A { <<interface>> }` sized a box to fit `A` and then drew a string four times wider.
    // Height had always counted this row; only the width forgot it — the asymmetry that made the
    // omission survive, since a too-narrow box overflows visibly rather than dropping content.
    // Renderers draw it at `font_size * 0.85`, and `metrics` measures at full size.
    let stereotype_width = meta.stereotype.as_ref().map_or(0.0, |stereotype| {
        metrics.estimate_dimensions(stereotype.label()).0 * 0.85
    });

    Some((member_width.max(stereotype_width) + 16.0, height))
}

/// Space an ER entity needs for its attribute rows. `None` for any node that declares no `members`.
///
/// The ER sibling of [`class_compartment_dimensions`], and it was missing: entity boxes were sized
/// from the entity name alone, so the box stayed a constant height however many attributes were
/// declared and rows from the fourth onward rendered OUTSIDE their own rectangle (bd-090g).
///
/// This mirrors `fm-render-svg`'s `write_er_entity_into` cursor advance, with one important
/// difference from the class case: that renderer DROPS a row falling outside the box, whereas the ER
/// renderer keeps emitting rows at a fixed pitch. So under-sizing here does not delete content, it
/// spills attributes into the diagram — and past enough rows, into whatever is laid out below.
/// Over-sizing renders as padding, so every term is rounded up.
fn er_compartment_dimensions(node: &IrNode, metrics: &fm_core::FontMetrics) -> Option<(f32, f32)> {
    if node.members.is_empty() {
        return None;
    }

    // Renderer: `node_font_size = detail.node_font_size` and
    // `attr_font_size = clamp_font_size(node_font_size * 0.8, config.min_font_size)`.
    //
    // `metrics.font_size()` is layout's stand-in for `node_font_size`. Two ways the renderer's row
    // pitch can come out LARGER than a naive `font_size * 0.8` here, and under-sizing spills rows:
    //   * `min_font_size` (default 8.0) clamps `attr_font_size` UP whenever `node_font_size < 10`;
    //   * layout's metrics and the render config's `font_size` need not agree at all.
    // So take the clamp floor into account rather than assuming the nominal factor wins.
    let node_font_size = metrics.font_size();
    let attr_font_size = (node_font_size * 0.8).max(ER_ATTR_FONT_FLOOR);
    let header_height = node_font_size * 1.5;
    let row_pitch = attr_font_size * 1.3;

    // Cursor offsets from the top of the box, in renderer order: header, then the first row's
    // baseline at `header_height + attr_font_size * 0.9`, then one pitch per subsequent row.
    let rows = node.members.len() as f32;
    let mut height = header_height + attr_font_size * 0.9 + row_pitch * (rows - 1.0);
    // Past the LAST baseline the glyph still descends, and the box must not end on that baseline.
    // Half a row of slack keeps the decision off the knife edge when the render font size does not
    // match `metrics` — the same margin `class_compartment_dimensions` takes, for the same reason.
    height += row_pitch;

    // Rows are left-anchored at `x + 8.0`; mirror that padding on the right so the widest row stays
    // inside the box.
    // ⚠️ THE BOX IS SIZED FROM THE COLUMN GEOMETRY, NOT FROM THE WIDEST FUSED ROW. The renderers draw
    // one cell per field at columns built from the widest cell in each column ACROSS EVERY
    // ATTRIBUTE, so an entity whose widest type and widest name belong to different attributes lays
    // out wider than any single row measures. Measured on
    // `T { verylongtypename a / t verylongattributename PK }` while this still folded row widths: the
    // box ended at x=250.56 and `PK` was drawn at x=310.20 — sixty pixels outside its own entity.
    let scale = if node_font_size > 0.0 {
        attr_font_size / node_font_size
    } else {
        1.0
    };
    let (_offsets, row_width) = fm_core::er_cell_columns(
        &node.members,
        metrics,
        scale,
        fm_core::er_cell_gutter(attr_font_size),
    );

    Some((row_width + 16.0, height))
}

/// Lower bound on the renderer's ER attribute font size — `SvgRenderConfig::min_font_size`'s default.
/// Layout cannot see the render config, and the clamp only ever raises the size (raising the row
/// pitch), so assuming the floor applies is the direction that over-sizes rather than spills.
const ER_ATTR_FONT_FLOOR: f32 = 8.0;

/// Width of one rendered member row. Mirrors the renderer's row text: a visibility symbol, the member
/// name, a `*`/`$` suffix for abstract/static methods, and a `": {return_type}"` tail.
fn class_member_row_width(
    member: &fm_core::IrClassMember,
    is_method: bool,
    metrics: &fm_core::FontMetrics,
) -> f32 {
    let mut row = String::with_capacity(member.name.len() + 8);
    row.push_str(match member.visibility {
        fm_core::ClassVisibility::Unmarked => "",
        fm_core::ClassVisibility::Public => "+",
        fm_core::ClassVisibility::Private => "-",
        fm_core::ClassVisibility::Protected => "#",
        fm_core::ClassVisibility::Package => "~",
    });
    // The renderers draw generics rewritten (`List~int~` -> `List<int>`), so measure the rewritten
    // row: the substitution is character-for-character but `<`/`>` and `~` are not the same width.
    row.push_str(&fm_core::class_member_display_name(&member.name, is_method));
    // ⚠️ NO CLASSIFIER CHARACTER (bd-r2gll). The renderers carry a method's `$`/`*` as a STYLE —
    // `text-decoration:underline` / `font-style:italic`, as mermaid does — not as a byte in the row
    // text, so measuring one here would size every static and abstract row one character too wide.
    // This string and the drawn string move together or the box stops matching its contents.
    if let Some(ref return_type) = member.return_type {
        // ` : ` matches what the renderers draw (bd-ci658). This string is what the BOX IS SIZED
        // FROM, so it has to move in the same commit as they do or the row is measured one
        // character narrower than it is drawn.
        row.push_str(" : ");
        row.push_str(&fm_core::parse_generic_types(return_type));
    }
    // Rows render at `font_size * 0.9`; `metrics` measures at full size, so scale the estimate down.
    metrics.estimate_dimensions(&row).0 * 0.9
}

fn node_size_cache_key(
    ir: &MermaidDiagramIr,
    node: &IrNode,
    metrics: &fm_core::FontMetrics,
) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    hash_str(&mut hash, &node.id);
    hash_u64(&mut hash, node.shape as u64);
    hash_str(&mut hash, display_node_label_ref(ir, node));
    hash_str(&mut hash, node.icon().unwrap_or_default());
    hash_u64(&mut hash, u64::from(metrics.font_size().to_bits()));
    hash_u64(&mut hash, u64::from(metrics.avg_char_width().to_bits()));
    hash_u64(&mut hash, u64::from(metrics.line_height_px().to_bits()));
    // Class members feed `compute_node_size` via `class_compartment_dimensions`, so they belong in the
    // key: editing a class body without touching its label would otherwise serve the cached size from
    // before the edit and silently truncate the new members.
    if let Some(meta) = node.class_meta.as_deref() {
        hash_u64(&mut hash, meta.attributes.len() as u64);
        hash_u64(&mut hash, meta.methods.len() as u64);
        hash_u64(&mut hash, u64::from(meta.stereotype.is_some()));
        for member in meta.attributes.iter().chain(meta.methods.iter()) {
            hash_str(&mut hash, &member.name);
            hash_str(&mut hash, member.return_type.as_deref().unwrap_or_default());
            hash_u64(&mut hash, member.visibility as u64);
            hash_u64(&mut hash, u64::from(member.is_static));
            hash_u64(&mut hash, u64::from(member.is_abstract));
        }
    }
    // ER attributes feed `compute_node_size` via `er_compartment_dimensions` for exactly the same
    // reason class members do, so they belong in the key too: adding an attribute without touching
    // the entity name would otherwise serve the size from before the edit, and the new rows would
    // render outside the stale box (bd-090g).
    hash_u64(&mut hash, node.members.len() as u64);
    for attr in &node.members {
        hash_str(&mut hash, &attr.data_type);
        hash_str(&mut hash, &attr.name);
        // EVERY key, and the COUNT (bd-nryyc). Key modifiers are a list (`string a PK, FK`);
        // the count guards against ambiguity in the flat hash stream and ensures composite keys
        // invalidate size caches appropriately.
        hash_u64(&mut hash, attr.keys.len() as u64);
        for key in &attr.keys {
            hash_u64(&mut hash, *key as u64);
        }
        // The comment became a DRAWN, MEASURED part of the row in bd-jerh, so it sizes the box and
        // belongs in the key — exactly as `c4_meta.description` and the requirement strings below
        // do. Without it, two entities differing only in a comment share a cached size and the
        // second renders in the first's box.
        hash_str(&mut hash, attr.comment.as_deref().unwrap_or_default());
    }
    // A C4 description feeds `compute_node_size` through `c4_description_height`, so editing it
    // without touching the node's label must not serve the pre-edit size (bd-9xjy) — the same
    // coupling `class_meta` and `node.members` above have, for the same reason.
    if let Some(meta) = node.c4_meta.as_deref() {
        hash_str(&mut hash, meta.description.as_deref().unwrap_or_default());
    }
    // The requirement type / risk / verifymethod strings feed `compute_node_size` through
    // `requirement_row_dimensions`, so lengthening a `verifymethod:` without touching the node's
    // label must not serve the pre-edit size and put the row back outside the box (bd-jnc1).
    if let Some(meta) = node.requirement_meta.as_deref() {
        hash_str(
            &mut hash,
            meta.requirement_type.as_deref().unwrap_or_default(),
        );
        hash_str(&mut hash, meta.risk.as_deref().unwrap_or_default());
        hash_str(&mut hash, meta.verify_method.as_deref().unwrap_or_default());
        // `id:` and `text:` became drawn rows in bd-f3tc, so they size the box too.
        hash_str(&mut hash, meta.req_id.as_deref().unwrap_or_default());
        hash_str(&mut hash, meta.text.as_deref().unwrap_or_default());
    }
    hash
}

fn icon_dimensions(node: &IrNode, metrics: &fm_core::FontMetrics) -> (f32, f32) {
    let Some(icon) = node.icon().map(str::trim).filter(|icon| !icon.is_empty()) else {
        return (0.0, 0.0);
    };

    let looks_like_glyph = icon.chars().count() <= 4 && !icon.is_ascii();
    if looks_like_glyph {
        let (width, height) = metrics.estimate_dimensions(icon);
        (width.max(metrics.font_size()), height + 10.0)
    } else {
        let icon_size = (metrics.font_size() * 1.35).max(18.0);
        (icon_size + 12.0, icon_size + 12.0)
    }
}

fn display_node_label(ir: &MermaidDiagramIr, node: &IrNode) -> String {
    display_node_label_ref(ir, node).to_string()
}

/// Borrowing core of [`display_node_label`]: the displayed label text is always either the IR label
/// text, the node id, or empty — all borrowable from `ir`/`node` — so callers that only READ it (text
/// measurement, hashing) need not clone. Byte-identical content to `display_node_label`; the owning
/// version just `.to_string()`s this for callers that store the result.
///
/// ⚠️ THE RULE ITSELF LIVES IN `fm_core` and is shared with fm-render-svg on purpose (bd-3cj8v).
/// Layout SIZES the box from this string and the renderer PAINTS from it; a local copy here drifted
/// from the renderer's and dropped explicit labels on filled circles, so a tagged `type: REVERSE`
/// commit was measured empty and drawn with text.
fn display_node_label_ref<'a>(ir: &'a MermaidDiagramIr, node: &'a IrNode) -> &'a str {
    ir.node_display_text(node)
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CycleRemovalResult {
    reversed_edge_indexes: BTreeSet<usize>,
    highlighted_edge_indexes: BTreeSet<usize>,
    summary: CycleSummary,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
struct CycleSummary {
    cycle_count: usize,
    cycle_node_count: usize,
    max_cycle_size: usize,
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
struct CycleDetection {
    components: Vec<Vec<usize>>,
    node_to_component: Vec<Option<usize>>,
    cyclic_component_indexes: BTreeSet<usize>,
    summary: CycleSummary,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct CycleClusterMap {
    /// For each original node index, the representative node index (self if not collapsed).
    node_representative: Vec<usize>,
    /// The set of representative node indexes that are cycle cluster heads.
    cluster_heads: BTreeSet<usize>,
    /// For each cluster head, the list of member node indexes (including the head).
    cluster_members: BTreeMap<usize, Vec<usize>>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct OrientedEdge {
    source: usize,
    target: usize,
    edge_index: usize,
}

fn default_cycle_strategy() -> CycleStrategy {
    std::env::var("FM_CYCLE_STRATEGY")
        .ok()
        .as_deref()
        .and_then(CycleStrategy::parse)
        .unwrap_or_default()
}

fn cycle_removal(
    ir: &MermaidDiagramIr,
    cycle_strategy: CycleStrategy,
    node_priority: &[usize],
) -> CycleRemovalResult {
    let node_count = ir.nodes.len();
    if node_count == 0 {
        return CycleRemovalResult {
            reversed_edge_indexes: BTreeSet::new(),
            highlighted_edge_indexes: BTreeSet::new(),
            summary: CycleSummary::default(),
        };
    }

    let edges = resolved_edges(ir);
    if edges.is_empty() {
        return CycleRemovalResult {
            reversed_edge_indexes: BTreeSet::new(),
            highlighted_edge_indexes: BTreeSet::new(),
            summary: CycleSummary::default(),
        };
    }

    let dfs_back_edges = cycle_removal_dfs_back(node_count, &edges, node_priority);
    // A directed graph is acyclic iff a DFS finds no back edge. When the graph is
    // acyclic there are no cyclic components and the cycle summary is empty, so the
    // (otherwise unconditional) strongly-connected-components pass is pure waste — the
    // common case for flowcharts. The only fields a full run would additionally populate
    // (per-node singleton components) feed MFAS-approx, which reverses nothing when there
    // are no cyclic components, so skipping the pass is output-identical.
    let cycle_detection = if dfs_back_edges.is_empty() {
        CycleDetection::default()
    } else {
        detect_cycle_components(node_count, &edges, node_priority)
    };

    let reversed_edge_indexes = match cycle_strategy {
        CycleStrategy::Greedy => cycle_removal_greedy(node_count, &edges, node_priority),
        CycleStrategy::DfsBack => dfs_back_edges.clone(),
        CycleStrategy::MfasApprox => {
            cycle_removal_mfas_approx(node_count, &edges, node_priority, &cycle_detection)
        }
        CycleStrategy::CycleAware => {
            // For CycleAware, we still want to break cycles for the ranking phase
            // to ensure a high-quality topological baseline, but we keep the
            // original orientation for other phases that handle cycles explicitly.
            dfs_back_edges.clone()
        }
    };

    let highlighted_edge_indexes = if matches!(cycle_strategy, CycleStrategy::CycleAware) {
        dfs_back_edges
    } else {
        reversed_edge_indexes.clone()
    };

    let result = CycleRemovalResult {
        reversed_edge_indexes,
        highlighted_edge_indexes,
        summary: cycle_detection.summary,
    };
    if result.summary.cycle_count > 0 {
        info!(
            strategy = cycle_strategy.as_str(),
            cycle_count = result.summary.cycle_count,
            cycle_node_count = result.summary.cycle_node_count,
            max_cycle_size = result.summary.max_cycle_size,
            reversed_edges = result.reversed_edge_indexes.len(),
            "layout.cycle_removal"
        );
    } else {
        trace!(
            strategy = cycle_strategy.as_str(),
            "layout.cycle_removal.acyclic"
        );
    }
    result
}

fn detect_cycle_components(
    node_count: usize,
    edges: &[OrientedEdge],
    node_priority: &[usize],
) -> CycleDetection {
    struct TarjanState<'a> {
        index: usize,
        indices: Vec<Option<usize>>,
        lowlink: Vec<usize>,
        stack: Vec<usize>,
        on_stack: Vec<bool>,
        components: Vec<Vec<usize>>,
        outgoing_edge_slots: &'a [Vec<usize>],
        edges: &'a [OrientedEdge],
        node_priority: &'a [usize],
    }

    impl TarjanState<'_> {
        fn strong_connect(&mut self, start_node: usize) {
            let mut call_stack = vec![(start_node, 0_usize)];

            self.indices[start_node] = Some(self.index);
            self.lowlink[start_node] = self.index;
            self.index = self.index.saturating_add(1);
            self.stack.push(start_node);
            self.on_stack[start_node] = true;

            while let Some((node, edge_idx)) = call_stack.pop() {
                let outgoing = &self.outgoing_edge_slots[node];

                if edge_idx < outgoing.len() {
                    call_stack.push((node, edge_idx + 1));

                    let edge_slot = outgoing[edge_idx];
                    let next = self.edges[edge_slot].target;

                    if self.indices[next].is_none() {
                        self.indices[next] = Some(self.index);
                        self.lowlink[next] = self.index;
                        self.index = self.index.saturating_add(1);
                        self.stack.push(next);
                        self.on_stack[next] = true;
                        call_stack.push((next, 0));
                    } else if self.on_stack[next] {
                        self.lowlink[node] = self.lowlink[node]
                            .min(self.indices[next].unwrap_or(self.lowlink[node]));
                    }
                } else {
                    if self.lowlink[node] == self.indices[node].unwrap_or(self.lowlink[node]) {
                        let mut component = Vec::new();
                        while let Some(top) = self.stack.pop() {
                            self.on_stack[top] = false;
                            component.push(top);
                            if top == node {
                                break;
                            }
                        }
                        component.sort_by(|left, right| {
                            compare_priority(*left, *right, self.node_priority)
                        });
                        self.components.push(component);
                    }

                    if let Some(&(parent, _)) = call_stack.last() {
                        self.lowlink[parent] = self.lowlink[parent].min(self.lowlink[node]);
                    }
                }
            }
        }
    }

    let outgoing_edge_slots = sorted_outgoing_edge_slots(node_count, edges, node_priority);
    let mut tarjan = TarjanState {
        index: 0,
        indices: vec![None; node_count],
        lowlink: vec![0_usize; node_count],
        stack: Vec::new(),
        on_stack: vec![false; node_count],
        components: Vec::new(),
        outgoing_edge_slots: &outgoing_edge_slots,
        edges,
        node_priority,
    };

    let mut node_visit_order: Vec<usize> = (0..node_count).collect();
    node_visit_order.sort_by(|left, right| compare_priority(*left, *right, node_priority));
    for node in node_visit_order {
        if tarjan.indices[node].is_none() {
            tarjan.strong_connect(node);
        }
    }

    let mut node_to_component = vec![None; node_count];
    for (component_index, component_nodes) in tarjan.components.iter().enumerate() {
        for node in component_nodes {
            node_to_component[*node] = Some(component_index);
        }
    }

    let mut cyclic_component_indexes = BTreeSet::new();
    let mut cycle_node_count = 0_usize;
    let mut max_cycle_size = 0_usize;
    for (component_index, component_nodes) in tarjan.components.iter().enumerate() {
        let is_cyclic = if component_nodes.len() > 1 {
            true
        } else {
            let node = component_nodes[0];
            edges
                .iter()
                .any(|edge| edge.source == node && edge.target == node)
        };

        if is_cyclic {
            cyclic_component_indexes.insert(component_index);
            cycle_node_count = cycle_node_count.saturating_add(component_nodes.len());
            max_cycle_size = max_cycle_size.max(component_nodes.len());
        }
    }

    CycleDetection {
        components: tarjan.components,
        node_to_component,
        cyclic_component_indexes: cyclic_component_indexes.clone(),
        summary: CycleSummary {
            cycle_count: cyclic_component_indexes.len(),
            cycle_node_count,
            max_cycle_size,
        },
    }
}

fn cycle_removal_dfs_back(
    node_count: usize,
    edges: &[OrientedEdge],
    node_priority: &[usize],
) -> BTreeSet<usize> {
    let outgoing_edge_slots = sorted_outgoing_edge_slots(node_count, edges, node_priority);
    let mut state = vec![0_u8; node_count];
    let mut reversed_edge_indexes = BTreeSet::new();

    let mut node_visit_order: Vec<usize> = (0..node_count).collect();
    node_visit_order.sort_by(|left, right| compare_priority(*left, *right, node_priority));

    for start_node in node_visit_order {
        if state[start_node] != 0 {
            continue;
        }

        let mut stack = vec![(start_node, 0)];
        state[start_node] = 1;

        while let Some((node, edge_idx)) = stack.pop() {
            let slots = &outgoing_edge_slots[node];
            if edge_idx < slots.len() {
                stack.push((node, edge_idx + 1));
                let edge = edges[slots[edge_idx]];
                match state[edge.target] {
                    0 => {
                        state[edge.target] = 1;
                        stack.push((edge.target, 0));
                    }
                    1 => {
                        reversed_edge_indexes.insert(edge.edge_index);
                    }
                    _ => {}
                }
            } else {
                state[node] = 2;
            }
        }
    }

    reversed_edge_indexes
}

fn cycle_removal_mfas_approx(
    node_count: usize,
    edges: &[OrientedEdge],
    node_priority: &[usize],
    cycle_detection: &CycleDetection,
) -> BTreeSet<usize> {
    if cycle_detection.summary.cycle_count == 0 {
        return BTreeSet::new();
    }

    let mut reversed_edge_indexes = BTreeSet::new();

    for component_index in &cycle_detection.cyclic_component_indexes {
        let component_nodes = cycle_detection
            .components
            .get(*component_index)
            .cloned()
            .unwrap_or_default();
        if component_nodes.is_empty() {
            continue;
        }

        let mut in_degree = vec![0_usize; node_count];
        let mut out_degree = vec![0_usize; node_count];

        for edge in edges {
            if cycle_detection.node_to_component[edge.source] == Some(*component_index)
                && cycle_detection.node_to_component[edge.target] == Some(*component_index)
            {
                out_degree[edge.source] = out_degree[edge.source].saturating_add(1);
                in_degree[edge.target] = in_degree[edge.target].saturating_add(1);
            }
        }

        let mut component_order = component_nodes;
        component_order.sort_by(|left, right| {
            let left_score = out_degree[*left] as isize - in_degree[*left] as isize;
            let right_score = out_degree[*right] as isize - in_degree[*right] as isize;
            right_score
                .cmp(&left_score)
                .then_with(|| compare_priority(*left, *right, node_priority))
        });

        let mut position = BTreeMap::<usize, usize>::new();
        for (index, node) in component_order.into_iter().enumerate() {
            position.insert(node, index);
        }

        for edge in edges {
            if cycle_detection.node_to_component[edge.source] == Some(*component_index)
                && cycle_detection.node_to_component[edge.target] == Some(*component_index)
                && position.get(&edge.source).copied().unwrap_or(0)
                    > position.get(&edge.target).copied().unwrap_or(0)
            {
                reversed_edge_indexes.insert(edge.edge_index);
            }
        }
    }

    if reversed_edge_indexes.is_empty() {
        return cycle_removal_dfs_back(node_count, edges, node_priority);
    }

    reversed_edge_indexes
}

fn sorted_outgoing_edge_slots(
    node_count: usize,
    edges: &[OrientedEdge],
    node_priority: &[usize],
) -> Vec<Vec<usize>> {
    let mut outgoing_edge_slots = vec![Vec::new(); node_count];
    for (edge_slot, edge) in edges.iter().enumerate() {
        outgoing_edge_slots[edge.source].push(edge_slot);
    }

    for slots in &mut outgoing_edge_slots {
        slots.sort_by(|left, right| {
            let left_edge = edges[*left];
            let right_edge = edges[*right];
            compare_priority(left_edge.target, right_edge.target, node_priority)
                .then_with(|| left_edge.edge_index.cmp(&right_edge.edge_index))
        });
    }

    outgoing_edge_slots
}

fn cycle_removal_greedy(
    node_count: usize,
    edges: &[OrientedEdge],
    node_priority: &[usize],
) -> BTreeSet<usize> {
    let mut active_nodes: BTreeSet<usize> = (0..node_count).collect();
    let mut in_degree = vec![0_usize; node_count];
    let mut out_degree = vec![0_usize; node_count];
    let mut incoming = vec![Vec::new(); node_count];
    let mut outgoing = vec![Vec::new(); node_count];

    for (edge_slot, edge) in edges.iter().enumerate() {
        in_degree[edge.target] = in_degree[edge.target].saturating_add(1);
        out_degree[edge.source] = out_degree[edge.source].saturating_add(1);
        incoming[edge.target].push(edge_slot);
        outgoing[edge.source].push(edge_slot);
    }

    let mut left_order = Vec::with_capacity(node_count);
    let mut right_order = Vec::with_capacity(node_count);

    while !active_nodes.is_empty() {
        let mut sinks: Vec<usize> = active_nodes
            .iter()
            .copied()
            .filter(|node| out_degree[*node] == 0)
            .collect();
        if !sinks.is_empty() {
            sinks.sort_by(|left, right| compare_priority(*right, *left, node_priority));
            for node in sinks {
                remove_node(
                    node,
                    &mut active_nodes,
                    &incoming,
                    &outgoing,
                    edges,
                    &mut in_degree,
                    &mut out_degree,
                );
                right_order.push(node);
            }
            continue;
        }

        let mut sources: Vec<usize> = active_nodes
            .iter()
            .copied()
            .filter(|node| in_degree[*node] == 0)
            .collect();
        if !sources.is_empty() {
            sources.sort_by(|left, right| compare_priority(*left, *right, node_priority));
            for node in sources {
                remove_node(
                    node,
                    &mut active_nodes,
                    &incoming,
                    &outgoing,
                    edges,
                    &mut in_degree,
                    &mut out_degree,
                );
                left_order.push(node);
            }
            continue;
        }

        let Some(candidate) = active_nodes.iter().copied().max_by(|left, right| {
            let left_score = out_degree[*left] as isize - in_degree[*left] as isize;
            let right_score = out_degree[*right] as isize - in_degree[*right] as isize;
            left_score
                .cmp(&right_score)
                .then_with(|| compare_priority(*right, *left, node_priority))
        }) else {
            break;
        };

        remove_node(
            candidate,
            &mut active_nodes,
            &incoming,
            &outgoing,
            edges,
            &mut in_degree,
            &mut out_degree,
        );
        left_order.push(candidate);
    }

    left_order.extend(right_order.into_iter().rev());
    let mut position = vec![0_usize; node_count];
    for (order, node_index) in left_order.into_iter().enumerate() {
        position[node_index] = order;
    }

    edges
        .iter()
        .filter_map(|edge| {
            (position[edge.source] > position[edge.target]).then_some(edge.edge_index)
        })
        .collect()
}

/// Apply IR constraints (`SameRank`, `MinLength`) to adjust rank assignments.
fn apply_ir_constraints(ir: &MermaidDiagramIr, ranks: &mut BTreeMap<usize, usize>) {
    use fm_core::IrConstraint;

    // The overwhelmingly common case (flowchart/block/wide/subgraph — anything without explicit
    // `SameRank`/`MinLength` directives) has no constraints, and nothing below the `id_to_index` build
    // mutates `ranks` unless the constraint loop runs. Bail before building the O(N log N)
    // `BTreeMap<&str, usize>` of every node id (its sorted-collect + per-lookup memcmp was pure waste on
    // constraint-free graphs). Byte-identical: an empty constraint list leaves `ranks` untouched either way.
    if ir.constraints.is_empty() {
        return;
    }

    // Build node-id-to-index lookup.
    let id_to_index: BTreeMap<&str, usize> = ir
        .nodes
        .iter()
        .enumerate()
        .map(|(i, node)| (node.id.as_str(), i))
        .collect();

    for constraint in &ir.constraints {
        match constraint {
            IrConstraint::SameRank { node_ids, .. } => {
                // Force all named nodes to share the same rank (the minimum among them).
                let target_rank = node_ids
                    .iter()
                    .filter_map(|id| id_to_index.get(id.as_str()))
                    .filter_map(|idx| ranks.get(idx).copied())
                    .min();
                if let Some(target) = target_rank {
                    for id in node_ids {
                        if let Some(&idx) = id_to_index.get(id.as_str()) {
                            ranks.insert(idx, target);
                        }
                    }
                }
            }
            IrConstraint::MinLength {
                from_id,
                to_id,
                min_len,
                ..
            } => {
                // Ensure the target node is at least min_len ranks below the source.
                if let (Some(&from_idx), Some(&to_idx)) = (
                    id_to_index.get(from_id.as_str()),
                    id_to_index.get(to_id.as_str()),
                ) {
                    let from_rank = ranks.get(&from_idx).copied().unwrap_or(0);
                    let to_rank = ranks.get(&to_idx).copied().unwrap_or(0);
                    let required = from_rank.saturating_add(*min_len);
                    if to_rank < required {
                        ranks.insert(to_idx, required);
                    }
                }
            }
            IrConstraint::Pin { .. }
            | IrConstraint::OrderInRank { .. }
            | IrConstraint::NonOverlap { .. } => {
                // Pin, OrderInRank, and NonOverlap are applied during coordinate assignment,
                // not during rank assignment.
            }
        }
    }
}

fn rank_assignment(
    ir: &MermaidDiagramIr,
    cycles: &CycleRemovalResult,
    node_priority: &[usize],
) -> BTreeMap<usize, usize> {
    let node_count = ir.nodes.len();
    let edges = oriented_edges(ir, &cycles.reversed_edge_indexes);

    let mut ranks = vec![0_usize; node_count];
    let mut in_degree = vec![0_usize; node_count];
    let mut outgoing: Vec<Vec<usize>> = vec![Vec::new(); node_count];

    for edge in &edges {
        if edge.source == edge.target {
            continue;
        }
        in_degree[edge.target] = in_degree[edge.target].saturating_add(1);
        outgoing[edge.source].push(edge.target);
    }

    for targets in &mut outgoing {
        targets.sort_by(|left, right| compare_priority(*left, *right, node_priority));
    }

    let mut heap: BinaryHeap<Reverse<(usize, usize)>> = BinaryHeap::new();
    for node_index in 0..node_count {
        if in_degree[node_index] == 0 {
            heap.push(Reverse((node_priority[node_index], node_index)));
        }
    }

    let mut visited = 0_usize;
    while let Some(Reverse((_priority, node_index))) = heap.pop() {
        visited = visited.saturating_add(1);
        let source_rank = ranks[node_index];

        for target in outgoing[node_index].iter().copied() {
            let candidate_rank = source_rank.saturating_add(1);
            if candidate_rank > ranks[target] {
                ranks[target] = candidate_rank;
            }
            in_degree[target] = in_degree[target].saturating_sub(1);
            if in_degree[target] == 0 {
                heap.push(Reverse((node_priority[target], target)));
            }
        }
    }

    if visited < node_count {
        // Residual cyclic components fallback to bounded longest-path relaxation.
        // We use node_count as the guard because the longest possible path in a DAG
        // has node_count - 1 edges. If we iterate more, we are definitely in a cycle.
        let guard = node_count;
        for _ in 0..guard {
            let mut changed = false;
            for edge in &edges {
                if edge.source == edge.target {
                    continue;
                }
                let candidate_rank = ranks[edge.source].saturating_add(1);
                if candidate_rank > ranks[edge.target] {
                    ranks[edge.target] = candidate_rank;
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }
    }

    // Compact disconnected components along the rank axis so each component
    // gets an independent band instead of sharing rank-0/rank-1 globally.
    // This avoids pathological ultra-wide layouts for many disconnected chains.
    let mut components = weakly_connected_components(node_count, &edges);
    components.sort_by_key(|component| {
        component
            .iter()
            .map(|node_index| node_priority[*node_index])
            .min()
            .unwrap_or(usize::MAX)
    });

    if components.len() > 1 {
        let mut compacted_ranks = ranks.clone();
        let mut rank_cursor = 0_usize;
        let mut isolated_singletons = Vec::new();

        let mut incident_edge_count = vec![0_usize; node_count];
        for edge in &edges {
            if edge.source < node_count {
                incident_edge_count[edge.source] =
                    incident_edge_count[edge.source].saturating_add(1);
            }
            if edge.target < node_count {
                incident_edge_count[edge.target] =
                    incident_edge_count[edge.target].saturating_add(1);
            }
        }

        for component in components {
            if component.is_empty() {
                continue;
            }

            // Treat isolated singletons specially: they will be grouped in a single rank band at the end
            if component.len() == 1 && incident_edge_count[component[0]] == 0 {
                isolated_singletons.push(component[0]);
                continue;
            }

            let mut min_rank = usize::MAX;
            let mut max_rank = 0_usize;
            for &node_index in &component {
                let rank = ranks[node_index];
                min_rank = min_rank.min(rank);
                max_rank = max_rank.max(rank);
            }

            if min_rank == usize::MAX {
                continue;
            }

            let span = max_rank.saturating_sub(min_rank).saturating_add(1);
            for &node_index in &component {
                compacted_ranks[node_index] = ranks[node_index]
                    .saturating_sub(min_rank)
                    .saturating_add(rank_cursor);
            }

            rank_cursor = rank_cursor.saturating_add(span).saturating_add(1);
        }

        // Place all isolated singletons in the next available rank band
        if !isolated_singletons.is_empty() {
            for node_index in isolated_singletons {
                compacted_ranks[node_index] = rank_cursor;
            }
        }

        ranks = compacted_ranks;
    }

    (0..node_count).map(|index| (index, ranks[index])).collect()
}

/// The largest graph admitted to the optional LP layer-assignment pass.
///
/// Layer inequalities form a totally-unimodular system, so an optimal basic solution is integral.
/// Keeping this initial path bounded makes its solver cost and failure mode explicit while the
/// default Sugiyama rank pass remains the production default.
const LP_RELAXATION_LAYER_NODE_LIMIT: usize = 50;

/// Re-solve the existing flowchart layer inequalities as a continuous LP.
///
/// The heuristic rank bands anchor each weak component, preserving its deliberate disconnected
/// component packing. Within each component the LP minimizes total layer index subject to one
/// layer per oriented edge, yielding the canonical longest-path layering when HiGHS proves optimal.
/// Any non-optimal, non-integral, or failed result is rejected by returning `None`.
#[cfg(not(target_arch = "wasm32"))]
fn lp_relaxation_layer_assignment(
    ir: &MermaidDiagramIr,
    cycles: &CycleRemovalResult,
    fallback: &BTreeMap<usize, usize>,
) -> Option<BTreeMap<usize, usize>> {
    if ir.nodes.len() > LP_RELAXATION_LAYER_NODE_LIMIT {
        return None;
    }

    let edges = oriented_edges(ir, &cycles.reversed_edge_indexes);
    let mut variables = good_lp::ProblemVariables::new();
    let rank_vars: Vec<_> = ir
        .nodes
        .iter()
        .map(|_| variables.add(variable().min(0.0)))
        .collect();
    let objective = rank_vars
        .iter()
        .fold(Expression::from(0.0), |sum, rank| sum + *rank);
    let mut model = variables.minimise(objective).using(default_solver);

    for edge in &edges {
        if edge.source != edge.target {
            model = model.with(constraint!(
                rank_vars[edge.target] - rank_vars[edge.source] >= 1.0
            ));
        }
    }

    for component in weakly_connected_components(ir.nodes.len(), &edges) {
        let minimum_rank = component
            .iter()
            .filter_map(|node_index| fallback.get(node_index).copied())
            .min()?;
        for node_index in component {
            if fallback.get(&node_index).copied() == Some(minimum_rank) {
                model = model.with(constraint!(rank_vars[node_index] == minimum_rank as f64));
            }
        }
    }

    let solution = model.solve().ok()?;
    if !constraint_solution_is_usable(solution.status()) {
        return None;
    }

    ir.nodes
        .iter()
        .enumerate()
        .map(|(node_index, _)| {
            let value = solution.value(rank_vars[node_index]);
            let rounded = value.round();
            ((value - rounded).abs() <= 1e-6 && rounded >= 0.0)
                .then_some((node_index, rounded as usize))
        })
        .collect()
}

#[cfg(target_arch = "wasm32")]
fn lp_relaxation_layer_assignment(
    _ir: &MermaidDiagramIr,
    _cycles: &CycleRemovalResult,
    _fallback: &BTreeMap<usize, usize>,
) -> Option<BTreeMap<usize, usize>> {
    None
}

fn weakly_connected_components(node_count: usize, edges: &[OrientedEdge]) -> Vec<Vec<usize>> {
    if node_count == 0 {
        return Vec::new();
    }

    let mut adjacency: Vec<BTreeSet<usize>> = vec![BTreeSet::new(); node_count];
    for edge in edges {
        if edge.source >= node_count || edge.target >= node_count {
            continue;
        }
        adjacency[edge.source].insert(edge.target);
        adjacency[edge.target].insert(edge.source);
    }

    let mut visited = vec![false; node_count];
    let mut components = Vec::new();

    for start in 0..node_count {
        if visited[start] {
            continue;
        }

        let mut stack = vec![start];
        visited[start] = true;
        let mut component = Vec::new();

        while let Some(node_index) = stack.pop() {
            component.push(node_index);
            for &neighbor in adjacency[node_index].iter().rev() {
                if visited[neighbor] {
                    continue;
                }
                visited[neighbor] = true;
                stack.push(neighbor);
            }
        }

        component.sort_unstable();
        components.push(component);
    }

    components
}

fn resolved_edges(ir: &MermaidDiagramIr) -> Vec<OrientedEdge> {
    let node_count = ir.nodes.len();
    // Presize to `ir.edges.len()` (the max; `filter_map` only drops unresolved/out-of-range edges)
    // so the `Vec` fills without `filter_map().collect()`'s growth reallocs — `filter_map`'s 0 lower
    // size-hint gives `collect` no capacity. `edges.len()` is O(1); byte-identical (same order).
    // `resolved_edges` runs per layout (GraphMetrics::from_ir algorithm selection + cycle removal).
    let mut edges = Vec::with_capacity(ir.edges.len());
    edges.extend(
        ir.edges
            .iter()
            .enumerate()
            .filter_map(|(edge_index, edge)| {
                let source = endpoint_node_index(ir, edge.from)?;
                let target = endpoint_node_index(ir, edge.to)?;
                if source >= node_count || target >= node_count {
                    return None;
                }
                Some(OrientedEdge {
                    source,
                    target,
                    edge_index,
                })
            }),
    );
    edges
}

fn oriented_edges(
    ir: &MermaidDiagramIr,
    reversed_edge_indexes: &BTreeSet<usize>,
) -> Vec<OrientedEdge> {
    resolved_edges(ir)
        .into_iter()
        .map(|mut edge| {
            if reversed_edge_indexes.contains(&edge.edge_index) {
                std::mem::swap(&mut edge.source, &mut edge.target);
            }
            edge
        })
        .collect()
}

fn stable_node_priorities(ir: &MermaidDiagramIr) -> Vec<usize> {
    let mut node_indexes: Vec<usize> = (0..ir.nodes.len()).collect();
    node_indexes.sort_by(|left, right| compare_node_indices(ir, *left, *right));

    let mut priorities = vec![0_usize; ir.nodes.len()];
    for (priority, node_index) in node_indexes.into_iter().enumerate() {
        priorities[node_index] = priority;
    }
    priorities
}

fn compare_block_beta_grid_node_indices(
    ir: &MermaidDiagramIr,
    left: usize,
    right: usize,
) -> std::cmp::Ordering {
    let left_path = block_beta_group_identity_path(ir, left);
    let right_path = block_beta_group_identity_path(ir, right);

    left_path
        .is_empty()
        .cmp(&right_path.is_empty())
        .then_with(|| left_path.cmp(&right_path))
        // Declaration order, not id order — see `block_beta_item_anchor` (bd-7ute).
        .then_with(|| left.cmp(&right))
}

fn block_beta_group_identity_path(ir: &MermaidDiagramIr, node_index: usize) -> Vec<usize> {
    let Some(graph_node) = ir.graph.nodes.get(node_index) else {
        return Vec::new();
    };
    let Some(mut current_subgraph) = graph_node.subgraphs.last().copied() else {
        return Vec::new();
    };

    let mut path = Vec::new();
    while let Some(subgraph) = ir.graph.subgraphs.get(current_subgraph.0) {
        path.push(subgraph.id.0);

        let Some(parent) = subgraph.parent else {
            break;
        };
        current_subgraph = parent;
    }
    path.reverse();
    path
}

fn block_beta_node_span(node: &IrNode) -> usize {
    node.classes
        .iter()
        .find_map(|class_name| {
            class_name
                .strip_prefix("block-beta-span-")
                .and_then(|value| value.parse::<usize>().ok())
        })
        .unwrap_or(1)
}

#[allow(clippy::too_many_arguments)]
fn layout_block_beta_grouped_items(
    ir: &MermaidDiagramIr,
    column_count: usize,
    cell_width: f32,
    cell_height: f32,
    node_spacing: f32,
    node_sizes: &mut [(f32, f32)],
    rank_by_node: &mut [usize],
    order_by_node: &mut [usize],
    centers: &mut [(f32, f32)],
) -> bool {
    let items = block_beta_direct_items(ir, None);
    if items.is_empty() {
        return false;
    }

    place_block_beta_items(
        ir,
        &items,
        column_count,
        0.0,
        0,
        0,
        cell_width,
        cell_height,
        node_spacing,
        node_sizes,
        rank_by_node,
        order_by_node,
        centers,
    );
    true
}

fn block_beta_direct_items(
    ir: &MermaidDiagramIr,
    parent: Option<fm_core::IrSubgraphId>,
) -> Vec<BlockBetaGridItem> {
    let mut items = Vec::new();

    if let Some(parent_id) = parent {
        if let Some(subgraph) = ir.graph.subgraph(parent_id) {
            items.extend(
                subgraph
                    .children
                    .iter()
                    .copied()
                    .map(BlockBetaGridItem::Group),
            );
        }
    } else {
        items.extend(
            ir.graph
                .root_subgraphs()
                .into_iter()
                .map(|subgraph| BlockBetaGridItem::Group(subgraph.id)),
        );
    }

    items.extend(
        ir.graph
            .nodes
            .iter()
            .enumerate()
            .filter_map(
                |(node_index, graph_node)| match graph_node.subgraphs.last().copied() {
                    Some(subgraph_id) if Some(subgraph_id) == parent => {
                        Some(BlockBetaGridItem::Node(node_index))
                    }
                    None if parent.is_none() => Some(BlockBetaGridItem::Node(node_index)),
                    _ => None,
                },
            ),
    );

    items.sort_by(|left, right| compare_block_beta_items(ir, *left, *right));
    items
}

fn compare_block_beta_items(
    ir: &MermaidDiagramIr,
    left: BlockBetaGridItem,
    right: BlockBetaGridItem,
) -> std::cmp::Ordering {
    let left_anchor = block_beta_item_anchor(ir, left);
    let right_anchor = block_beta_item_anchor(ir, right);

    left_anchor
        .cmp(&right_anchor)
        .then_with(|| match (left, right) {
            (BlockBetaGridItem::Node(left), BlockBetaGridItem::Node(right)) => left.cmp(&right),
            (BlockBetaGridItem::Group(left), BlockBetaGridItem::Group(right)) => {
                left.0.cmp(&right.0)
            }
            (BlockBetaGridItem::Group(_), BlockBetaGridItem::Node(_)) => std::cmp::Ordering::Less,
            (BlockBetaGridItem::Node(_), BlockBetaGridItem::Group(_)) => {
                std::cmp::Ordering::Greater
            }
        })
}

/// Where an item sits in the SOURCE, which is the only order a block-beta grid may be read in.
///
/// This used to key on the node's id STRING, so the grid was alphabetised: `space` — whose
/// generated id sorts after ordinary ids — was pushed to the end of the grid, taking the gap the
/// author asked for with it and shifting every later cell one place earlier (bd-7ute). Interning
/// order (`node_index`) is declaration order, so it is what the anchor reads now. An empty group
/// has no member to anchor on and falls back to its own declaration index, which is still a source
/// position rather than a name.
fn block_beta_item_anchor(ir: &MermaidDiagramIr, item: BlockBetaGridItem) -> usize {
    match item {
        BlockBetaGridItem::Node(node_index) => node_index,
        BlockBetaGridItem::Group(subgraph_id) => ir
            .graph
            .subgraph_members_recursive(subgraph_id)
            .into_iter()
            .map(|node_id| node_id.0)
            .min()
            .unwrap_or(usize::MAX - subgraph_id.0),
    }
}

fn block_beta_item_span(
    ir: &MermaidDiagramIr,
    item: BlockBetaGridItem,
    available_columns: usize,
) -> usize {
    match item {
        BlockBetaGridItem::Node(node_index) => block_beta_node_span(&ir.nodes[node_index]),
        BlockBetaGridItem::Group(subgraph_id) => ir
            .graph
            .subgraph(subgraph_id)
            .map_or(1, |subgraph| subgraph.grid_span),
    }
    .min(available_columns)
    .max(1)
}

fn block_beta_item_rows(
    ir: &MermaidDiagramIr,
    item: BlockBetaGridItem,
    available_columns: usize,
) -> usize {
    match item {
        BlockBetaGridItem::Node(_) => 1,
        BlockBetaGridItem::Group(subgraph_id) => {
            let group_columns = block_beta_item_span(ir, item, available_columns);
            let children = block_beta_direct_items(ir, Some(subgraph_id));
            if children.is_empty() {
                1
            } else {
                block_beta_rows_required(ir, &children, group_columns)
            }
        }
    }
}

fn block_beta_rows_required(
    ir: &MermaidDiagramIr,
    items: &[BlockBetaGridItem],
    available_columns: usize,
) -> usize {
    let mut row_offset = 0_usize;
    let mut col = 0_usize;
    let mut row_height = 1_usize;

    for &item in items {
        let span = block_beta_item_span(ir, item, available_columns);
        let item_rows = block_beta_item_rows(ir, item, span);

        if col != 0 && col + span > available_columns {
            row_offset += row_height;
            col = 0;
            row_height = 1;
        }

        row_height = row_height.max(item_rows);

        if col + span >= available_columns {
            row_offset += row_height;
            col = 0;
            row_height = 1;
        } else {
            col += span;
        }
    }

    if col == 0 {
        row_offset
    } else {
        row_offset + row_height
    }
}

#[allow(clippy::too_many_arguments)]
/// Columns a group's children actually consume in their widest row.
///
/// A container declaring `block:name:3` reserves three columns whether or not its children fill
/// them. mermaid resolves the difference by GROWING the children to fit the container
/// (`setBlockSizes`' "growing to fit" branch divides the parent's settled width among its
/// children), which is why a `block:wide:3` holding one short-labelled node is three columns wide
/// there and was 100px here (bd-7ute). This returns the denominator for that division.
fn block_beta_group_used_columns(
    ir: &MermaidDiagramIr,
    items: &[BlockBetaGridItem],
    available_columns: usize,
) -> usize {
    let mut widest = 0_usize;
    let mut col = 0_usize;
    for &item in items {
        let span = block_beta_item_span(ir, item, available_columns);
        if col != 0 && col + span > available_columns {
            col = 0;
        }
        col += span;
        widest = widest.max(col);
        if col >= available_columns {
            col = 0;
        }
    }
    widest.clamp(1, available_columns.max(1))
}

/// Width a node occupies when it spans `span` cells of pitch `cell_width`.
///
/// Inverse of the cell pitch: one cell is a box plus one `node_spacing` gutter, so `span` cells are
/// `span * cell_width` minus the single trailing gutter. Matches the widening the ungrouped path
/// applies at the top level, so a node's width means the same thing inside and outside a container.
fn block_beta_span_width(span: usize, cell_width: f32, node_spacing: f32) -> f32 {
    (span as f32).mul_add(cell_width, -node_spacing)
}

#[allow(clippy::too_many_arguments)]
fn place_block_beta_items(
    ir: &MermaidDiagramIr,
    items: &[BlockBetaGridItem],
    available_columns: usize,
    base_x: f32,
    base_col: usize,
    start_row: usize,
    cell_width: f32,
    cell_height: f32,
    node_spacing: f32,
    node_sizes: &mut [(f32, f32)],
    rank_by_node: &mut [usize],
    order_by_node: &mut [usize],
    centers: &mut [(f32, f32)],
) -> usize {
    let mut row_offset = 0_usize;
    let mut col = 0_usize;
    let mut row_height = 1_usize;

    for &item in items {
        let span = block_beta_item_span(ir, item, available_columns);
        let item_rows = block_beta_item_rows(ir, item, span);

        if col != 0 && col + span > available_columns {
            row_offset += row_height;
            col = 0;
            row_height = 1;
        }

        let item_x = (col as f32).mul_add(cell_width, base_x);
        let item_col = base_col + col;
        let item_row = start_row + row_offset;

        match item {
            BlockBetaGridItem::Node(node_index) => {
                centers[node_index] = (
                    (span - 1) as f32 * cell_width / 2.0 + item_x,
                    item_row as f32 * cell_height,
                );
                node_sizes[node_index].0 = node_sizes[node_index].0.max(block_beta_span_width(
                    span,
                    cell_width,
                    node_spacing,
                ));
                if matches!(ir.direction, GraphDirection::LR | GraphDirection::RL) {
                    rank_by_node[node_index] = item_col;
                    order_by_node[node_index] = item_row;
                } else {
                    rank_by_node[node_index] = item_row;
                    order_by_node[node_index] = item_col;
                }
            }
            BlockBetaGridItem::Group(subgraph_id) => {
                let child_items = block_beta_direct_items(ir, Some(subgraph_id));
                if !child_items.is_empty() {
                    // The container owns `span` columns of the OUTER grid. Its children divide
                    // that width between the columns they actually use, so a container's declared
                    // span reaches its contents instead of evaporating when they under-fill it.
                    let used = block_beta_group_used_columns(ir, &child_items, span);
                    let inner_cell_width = span as f32 * cell_width / used as f32;
                    // `item_x` is the CENTRE of the container's first outer cell, and these
                    // coordinates are cell centres throughout (a box is `centre ± width/2`). The
                    // children's first cell is wider, so its centre is not the container's: shift
                    // from the container's region centre back by half the inner run. Passing
                    // `item_x` straight through left-aligned the children's centres to the outer
                    // grid and pushed a 3-cell child 1.5 cells left of the row below it.
                    let inner_base_x = (span - 1) as f32 * cell_width / 2.0
                        - (used - 1) as f32 * inner_cell_width / 2.0
                        + item_x;
                    place_block_beta_items(
                        ir,
                        &child_items,
                        used,
                        inner_base_x,
                        item_col,
                        item_row,
                        inner_cell_width,
                        cell_height,
                        node_spacing,
                        node_sizes,
                        rank_by_node,
                        order_by_node,
                        centers,
                    );
                }
            }
        }

        row_height = row_height.max(item_rows);

        if col + span >= available_columns {
            row_offset += row_height;
            col = 0;
            row_height = 1;
        } else {
            col += span;
        }
    }

    if col == 0 {
        row_offset
    } else {
        row_offset + row_height
    }
}

fn compare_node_indices(ir: &MermaidDiagramIr, left: usize, right: usize) -> std::cmp::Ordering {
    ir.nodes[left]
        .id
        .cmp(&ir.nodes[right].id)
        .then_with(|| left.cmp(&right))
}

fn compare_priority(left: usize, right: usize, node_priority: &[usize]) -> std::cmp::Ordering {
    node_priority[left]
        .cmp(&node_priority[right])
        .then_with(|| left.cmp(&right))
}

fn remove_node(
    node: usize,
    active_nodes: &mut BTreeSet<usize>,
    incoming: &[Vec<usize>],
    outgoing: &[Vec<usize>],
    edges: &[OrientedEdge],
    in_degree: &mut [usize],
    out_degree: &mut [usize],
) {
    if !active_nodes.remove(&node) {
        return;
    }

    for edge_slot in outgoing[node].iter().copied() {
        let target = edges[edge_slot].target;
        if active_nodes.contains(&target) {
            in_degree[target] = in_degree[target].saturating_sub(1);
        }
    }

    for edge_slot in incoming[node].iter().copied() {
        let source = edges[edge_slot].source;
        if active_nodes.contains(&source) {
            out_degree[source] = out_degree[source].saturating_sub(1);
        }
    }
}

fn crossing_minimization(
    ir: &MermaidDiagramIr,
    ranks: &BTreeMap<usize, usize>,
    config: &LayoutConfig,
) -> (usize, BTreeMap<usize, Vec<usize>>) {
    crossing_minimization_impl::<true, true, true, true>(ir, ranks, config)
}

/// Compile-time switches keep the certified production path and all live reference arms in one body:
/// `DENSE_RANK` selects packed node-rank lookup, while `SINGLE_PASS` selects the reusable packed
/// position/slot frontier and one edge pass per rank reorder. `FLAT_CSR` replaces that full edge pass
/// with a build-once packed incidence index. `PACKED_CROSSINGS` destructively reuses that index after
/// the final sweep as normalized adjacency plus a word-packed Fenwick frontier.
fn crossing_minimization_impl<
    const DENSE_RANK: bool,
    const SINGLE_PASS: bool,
    const FLAT_CSR: bool,
    const PACKED_CROSSINGS: bool,
>(
    ir: &MermaidDiagramIr,
    ranks: &BTreeMap<usize, usize>,
    config: &LayoutConfig,
) -> (usize, BTreeMap<usize, Vec<usize>>) {
    let ordering_by_rank = nodes_by_rank(ir.nodes.len(), ranks);
    if ordering_by_rank.len() <= 1 {
        return (0, ordering_by_rank);
    }

    // Fast path: if no rank holds two or more nodes, no crossings are possible and the
    // barycenter sweeps cannot reorder anything within a rank — the ordering is already
    // final. Skips centrality construction, the four sweep rounds, and the crossing count
    // for the common linear-flowchart case (every rank one node). Output-identical: the
    // full path returns this same ordering with zero crossings.
    if ordering_by_rank.values().all(|nodes| nodes.len() <= 1) {
        return (0, ordering_by_rank);
    }

    let centrality = build_centrality_assist(ir, config);

    // The rank assignment is bounded by node count in normal layout. Keep an exact fallback for an
    // externally constructed pathological map whose rank cannot fit the packed word.
    let dense_node_rank = if DENSE_RANK {
        let mut dense = Vec::with_capacity(ir.nodes.len());
        for node_index in 0..ir.nodes.len() {
            let rank = ranks.get(&node_index).copied().unwrap_or(0);
            let Ok(rank) = u32::try_from(rank) else {
                return crossing_minimization_sweeps::<
                    false,
                    SINGLE_PASS,
                    FLAT_CSR,
                    PACKED_CROSSINGS,
                >(ir, ranks, &[], ordering_by_rank, centrality);
            };
            dense.push(rank);
        }
        dense
    } else {
        Vec::new()
    };

    crossing_minimization_sweeps::<DENSE_RANK, SINGLE_PASS, FLAT_CSR, PACKED_CROSSINGS>(
        ir,
        ranks,
        &dense_node_rank,
        ordering_by_rank,
        centrality,
    )
}

fn crossing_minimization_sweeps<
    const DENSE_RANK: bool,
    const SINGLE_PASS: bool,
    const FLAT_CSR: bool,
    const PACKED_CROSSINGS: bool,
>(
    ir: &MermaidDiagramIr,
    ranks: &BTreeMap<usize, usize>,
    dense_node_rank: &[u32],
    mut ordering_by_rank: BTreeMap<usize, Vec<usize>>,
    centrality: CentralityAssist,
) -> (usize, BTreeMap<usize, Vec<usize>>) {
    // Allocated once per crossing minimization and reused by every sweep call; empty for the
    // `!SINGLE_PASS` arm, which never reads it. The packed arm falls back to the certified
    // thresholded implementation if a node index cannot fit in u32.
    let mut scratch = BarycenterScratch::new::<SINGLE_PASS, FLAT_CSR>(ir);

    // Deterministic barycenter sweeps: top-down then bottom-up.
    let rank_keys: Vec<usize> = ordering_by_rank.keys().copied().collect();
    for _ in 0..4 {
        for index in 1..rank_keys.len() {
            let rank = rank_keys[index];
            let upper_rank = rank_keys[index - 1];
            reorder_rank_by_barycenter::<DENSE_RANK, SINGLE_PASS, FLAT_CSR>(
                ir,
                (ranks, dense_node_rank),
                &mut scratch,
                &mut ordering_by_rank,
                rank,
                upper_rank,
                true,
                &centrality,
            );
        }

        for index in (0..rank_keys.len().saturating_sub(1)).rev() {
            let rank = rank_keys[index];
            let lower_rank = rank_keys[index + 1];
            reorder_rank_by_barycenter::<DENSE_RANK, SINGLE_PASS, FLAT_CSR>(
                ir,
                (ranks, dense_node_rank),
                &mut scratch,
                &mut ordering_by_rank,
                rank,
                lower_rank,
                false,
                &centrality,
            );
        }
    }

    let barycenter_crossing_count = if PACKED_CROSSINGS {
        total_crossings_packed(ir, ranks, &ordering_by_rank, &mut scratch)
            .unwrap_or_else(|| total_crossings(ir, ranks, &ordering_by_rank))
    } else {
        total_crossings(ir, ranks, &ordering_by_rank)
    };
    let crossing_count = if barycenter_crossing_count == 0 {
        0
    } else {
        apply_egraph_ordering_pass::<PACKED_CROSSINGS>(
            ir,
            ranks,
            &mut ordering_by_rank,
            barycenter_crossing_count,
            &mut scratch,
        )
    };
    debug!(
        crossings_after_barycenter = barycenter_crossing_count,
        crossings_after_egraph = crossing_count,
        ranks = ordering_by_rank.len(),
        "layout.crossing_minimization"
    );
    (crossing_count, ordering_by_rank)
}

/// Apply transpose and sifting refinement heuristics to reduce crossings
/// beyond what barycenter achieves alone.
fn crossing_refinement(
    ir: &MermaidDiagramIr,
    ranks: &BTreeMap<usize, usize>,
    mut ordering_by_rank: BTreeMap<usize, Vec<usize>>,
    mut best_crossings: usize,
) -> (usize, BTreeMap<usize, Vec<usize>>) {
    if best_crossings == 0 {
        return (0, ordering_by_rank);
    }

    // A transpose/sift confined to rank `r` changes only the `(r-1, r)` and `(r, r+1)` pair
    // crossings, so we precompute the adjacent-rank edge buckets once and compare just those
    // affected pairs per trial — instead of recomputing the whole graph's crossings
    // (`total_crossings`) tens of thousands of times. Accepting iff the affected pairs strictly
    // decrease is exactly equivalent to the full-total comparison, so the resulting ordering (and
    // `best_crossings`) is identical to the naive version, just far cheaper to reach.
    let pair_edges = build_pair_node_edges(ir, ranks);

    // Both refinement phases perturb ONE rank at a time while its two neighbours stand still:
    // transpose tries every adjacent swap in the rank, sifting tries every node at every position.
    // Each trial called `pair_crossings` twice, and each of those rebuilt two node-id-domain-sized
    // position arrays, re-sorted the pair's edges and ran an allocating recursive merge sort -- so
    // the neighbour-derived half of that work was recomputed O(n) or O(n^2) times per rank for
    // orderings that never changed. `RankNeighbourCrossings` bucket the pair's edges against the
    // fixed neighbour once per rank visit, exactly as `FixedLayerCrossings` does for the e-graph
    // search, leaving each trial a single allocation-free Fenwick sweep.
    let mut neighbours = RankNeighbourCrossings::default();

    // Phase 1: Transpose — swap adjacent nodes in each rank if it reduces crossings.
    let mut improved = true;
    for _pass in 0..10 {
        if !improved {
            break;
        }
        improved = false;
        let rank_keys: Vec<usize> = ordering_by_rank.keys().copied().collect();
        for &rank in &rank_keys {
            let n = ordering_by_rank.get(&rank).map_or(0, Vec::len);
            if n < 2 {
                continue;
            }
            neighbours.rebuild(rank, &ordering_by_rank, &pair_edges);
            let mut current = neighbours.count(rank, &ordering_by_rank, &pair_edges);
            for i in 0..n - 1 {
                // Try swapping positions i and i+1 in-place.
                if let Some(rank_order) = ordering_by_rank.get_mut(&rank) {
                    rank_order.swap(i, i + 1);
                }
                let trial = neighbours.count(rank, &ordering_by_rank, &pair_edges);
                if trial < current {
                    best_crossings = best_crossings.saturating_sub(current - trial);
                    current = trial;
                    improved = true;
                    if best_crossings == 0 {
                        return (0, ordering_by_rank);
                    }
                } else if let Some(rank_order) = ordering_by_rank.get_mut(&rank) {
                    // Swap back if not improved.
                    rank_order.swap(i, i + 1);
                }
            }
        }
    }

    // Phase 2: Sifting — for each node in each rank, try every position in that rank.
    let rank_keys: Vec<usize> = ordering_by_rank.keys().copied().collect();
    for &rank in &rank_keys {
        let order = match ordering_by_rank.get(&rank) {
            Some(o) if o.len() >= 3 => o.clone(),
            _ => continue,
        };
        let n = order.len();
        neighbours.rebuild(rank, &ordering_by_rank, &pair_edges);
        let mut current = neighbours.count(rank, &ordering_by_rank, &pair_edges);
        for node in order {
            // Find current position of node in the (potentially modified) rank order.
            let mut current_pos = match ordering_by_rank.get(&rank) {
                Some(o) => match o.iter().position(|&ni| ni == node) {
                    Some(pos) => pos,
                    None => continue,
                },
                None => continue,
            };

            for target_pos in 0..n {
                if target_pos == current_pos {
                    continue;
                }

                // Move node from current_pos to target_pos in-place.
                if let Some(rank_order) = ordering_by_rank.get_mut(&rank) {
                    let element = rank_order.remove(current_pos);
                    rank_order.insert(target_pos, element);
                }

                let trial = neighbours.count(rank, &ordering_by_rank, &pair_edges);
                if trial < current {
                    best_crossings = best_crossings.saturating_sub(current - trial);
                    current = trial;
                    current_pos = target_pos;
                    if best_crossings == 0 {
                        return (0, ordering_by_rank);
                    }
                } else if let Some(rank_order) = ordering_by_rank.get_mut(&rank) {
                    // Move back if not improved.
                    let element = rank_order.remove(target_pos);
                    rank_order.insert(current_pos, element);
                }
            }
        }
    }

    (best_crossings, ordering_by_rank)
}

// ---------------------------------------------------------------------------
// Brandes-Köpf coordinate assignment (2001)
//
// Computes secondary-axis (within-rank) coordinates by running four alignment
// passes (upper-left, upper-right, lower-left, lower-right) and taking the
// median of the four positions for each node.  This aligns connected nodes
// across ranks, reducing edge bends compared to simple sequential placement.
// ---------------------------------------------------------------------------

/// For each node, collect its neighbours in the specified adjacent rank.
/// Uses pre-built adjacency for O(1) neighbour lookup per node.
/// Sentinel in [`bk_pos_of`]: node is not present in any rank ordering (so the original per-rank
/// `pos_map.get(&n)` returned `None`). `usize::MAX` can never be a real position (bounded by rank width).
const BK_POS_ABSENT: usize = usize::MAX;

fn bk_upper_neighbours(
    adjacency: &[FxHashSet<usize>],
    dense_node_rank: &[usize],
    pos_of: &[usize],
    node_index: usize,
    node_rank: usize,
    upper: bool,
) -> Vec<(usize, usize)> {
    let adjacent_rank = if upper {
        if node_rank == 0 {
            return Vec::new();
        }
        node_rank - 1
    } else {
        node_rank + 1
    };

    let mut neighbours = Vec::new();
    if let Some(nodes) = adjacency.get(node_index) {
        for &n in nodes {
            // `dense_node_rank[n]` == the old `ranks.get(&n).copied().unwrap_or(0)`; `pos_of[n]` == the old
            // `pos_map.get(&n)` for `n`'s rank, or `BK_POS_ABSENT` where that returned `None`. The rank check
            // plus the sentinel guard reproduce the old `rank == adjacent_rank && Some(pos)` condition exactly
            // (including the `adjacent_rank == 0` + unranked-node case, where the rank test passed but the
            // per-rank `pos_map` had no entry).
            if dense_node_rank.get(n).copied().unwrap_or(0) == adjacent_rank {
                let pos = pos_of.get(n).copied().unwrap_or(BK_POS_ABSENT);
                if pos != BK_POS_ABSENT {
                    neighbours.push((n, pos));
                }
            }
        }
    }

    neighbours.sort_by_key(|&(_, pos)| pos);
    // No `dedup()`: `neighbours` is collected by iterating `adjacency[node_index]`, a `FxHashSet<usize>`, so each
    // neighbour index `n` is pushed at most once — no two `(n, pos)` entries can be equal, making `dedup()` an
    // unconditional no-op (it depends only on set uniqueness, not on the sort). Dropping it removes an O(len)
    // pass from the hottest BK inner call (per node, per pass). Byte-identical.
    neighbours
}

/// Brandes-Köpf vertical alignment for one of the four directions.
///
/// Returns `(root, align)` arrays indexed by `node_index`.
/// - `root[v]` is the root of the block containing v.
/// - `align[v]` is the next node in the block chain; `align[v] == v` at the terminal.
#[allow(clippy::too_many_arguments)]
fn bk_vertical_alignment(
    n: usize,
    adjacency: &[FxHashSet<usize>],
    dense_node_rank: &[usize],
    pos_of: &[usize],
    ordering_by_rank: &BTreeMap<usize, Vec<usize>>,
    ordered_ranks: &[usize],
    rank_exists: &[bool],
    top_to_bottom: bool,
    left_to_right: bool,
) -> (Vec<usize>, Vec<usize>) {
    let mut root: Vec<usize> = (0..n).collect();
    let mut align: Vec<usize> = (0..n).collect();

    // Process ranks in the specified vertical order.
    let rank_iter: Vec<usize> = if top_to_bottom {
        ordered_ranks.to_vec()
    } else {
        ordered_ranks.iter().copied().rev().collect()
    };

    for &rank in &rank_iter {
        let Some(rank_nodes) = ordering_by_rank.get(&rank) else {
            continue;
        };

        // Track the rightmost (or leftmost) aligned position to prevent conflicts.
        let mut threshold: i64 = if left_to_right { -1 } else { i64::MAX };

        let node_iter: Vec<usize> = if left_to_right {
            rank_nodes.clone()
        } else {
            rank_nodes.iter().copied().rev().collect()
        };

        for v in node_iter {
            let v_rank = dense_node_rank.get(v).copied().unwrap_or(0);
            let adjacent_rank = if top_to_bottom {
                if v_rank == 0 {
                    continue;
                }
                v_rank - 1
            } else {
                v_rank + 1
            };

            // Existence guard for `adjacent_rank`. `rank_exists[r]` == `ordering_by_rank.contains_key(&r)` for
            // in-range `r`, and `.get` reads an out-of-range index as absent — byte-identical to the old B-tree
            // probe, but an O(1) branchless slice load instead of a per-node pointer-chase.
            if !rank_exists.get(adjacent_rank).copied().unwrap_or(false) {
                continue;
            }

            let neighbours =
                bk_upper_neighbours(adjacency, dense_node_rank, pos_of, v, v_rank, top_to_bottom);

            if neighbours.is_empty() {
                continue;
            }

            // Compute median neighbour(s).  For even count, try both medians.
            let median_indices = if neighbours.len() % 2 == 1 {
                vec![neighbours.len() / 2]
            } else {
                vec![neighbours.len() / 2 - 1, neighbours.len() / 2]
            };

            let candidates: Vec<usize> = if left_to_right {
                median_indices
            } else {
                median_indices.into_iter().rev().collect()
            };

            for mi in candidates {
                let (u, u_pos) = neighbours[mi];
                // Only align if:
                // 1. u is not yet aligned with any successor (align[u] == u).
                // 2. The neighbour position doesn't conflict with a previously aligned neighbour in the rank.
                if align[u] != u {
                    continue;
                }
                let u_pos_i64 = u_pos as i64;
                let no_conflict = if left_to_right {
                    u_pos_i64 > threshold
                } else {
                    u_pos_i64 < threshold
                };
                if no_conflict {
                    align[u] = v;
                    root[v] = root[u];
                    threshold = u_pos_i64;
                    break;
                }
            }
        }
    }

    (root, align)
}

/// Brandes-Köpf horizontal compaction for one alignment.
///
/// Returns secondary-axis coordinates indexed by `node_index`.
#[allow(clippy::too_many_arguments)]
fn bk_horizontal_compaction(
    node_count: usize,
    node_sizes: &[(f32, f32)],
    ordering_by_rank: &BTreeMap<usize, Vec<usize>>,
    root: &[usize],
    align: &[usize],
    // `pred_in_rank` (each node's left neighbour in its rank) depends only on `ordering_by_rank`, which
    // is identical across all four BK alignment passes — so it's built ONCE by the caller and shared
    // here instead of being rebuilt per pass.
    pred_in_rank: &[Option<usize>],
    node_spacing: f32,
    horizontal_ranks: bool,
) -> Vec<f32> {
    let mut x = vec![f32::NEG_INFINITY; node_count];
    let mut sink: Vec<usize> = (0..node_count).collect();
    let mut shift = vec![f32::INFINITY; node_count];

    /// Minimum separation between two adjacent nodes in the same rank.
    fn delta(
        u: usize,
        w: usize,
        node_sizes: &[(f32, f32)],
        node_spacing: f32,
        horizontal_ranks: bool,
    ) -> f32 {
        let u_extent =
            node_sizes.get(u).map_or(
                84.0,
                |&(width, height)| if horizontal_ranks { height } else { width },
            );
        let w_extent =
            node_sizes.get(w).map_or(
                84.0,
                |&(width, height)| if horizontal_ranks { height } else { width },
            );
        (u_extent / 2.0) + node_spacing + (w_extent / 2.0)
    }

    // Place blocks.  We use an explicit work stack to ensure predecessor block
    // roots are placed before the blocks that depend on them (the original BK
    // algorithm handles this via recursion in `place_block`).
    let mut ordered_roots: Vec<usize> = Vec::new();
    // Iterate `values()` directly: the old `keys()` + `get(rank_key)` did a redundant per-rank BTreeMap probe
    // (pointer-chasing, cache-missy) on each of the four BK compaction passes. `values()` yields the same rank
    // node-lists in the same sorted-key order, so this is byte-identical — it just drops the O(log ranks) lookup.
    for nodes in ordering_by_rank.values() {
        for &v in nodes {
            if v < node_count && root[v] == v {
                ordered_roots.push(v);
            }
        }
    }

    /// Place a single block root and all predecessor blocks it depends on.
    /// Recurses into unplaced predecessors; terminates because each block
    /// root sets `x[block_root] = 0.0` on entry, preventing re-entry.
    #[allow(clippy::too_many_arguments)]
    fn place_block(
        block_root: usize,
        x: &mut [f32],
        sink: &mut [usize],
        shift: &mut [f32],
        root: &[usize],
        align: &[usize],
        pred_in_rank: &[Option<usize>],
        node_sizes: &[(f32, f32)],
        node_spacing: f32,
        horizontal_ranks: bool,
    ) {
        if x[block_root] > f32::NEG_INFINITY {
            return; // Already placed.
        }
        x[block_root] = 0.0;

        // Walk the block chain: block_root -> align[block_root] -> ...
        let mut w = block_root;
        loop {
            if let Some(pred) = pred_in_rank[w] {
                let pred_root = root[pred];
                // Ensure predecessor block is placed first (recursive in
                // original algorithm; bounded by number of block roots).
                if x[pred_root] <= f32::NEG_INFINITY {
                    // Recurse into predecessor.  Depth is bounded by the
                    // number of distinct block roots, which is ≤ node_count.
                    place_block(
                        pred_root,
                        x,
                        sink,
                        shift,
                        root,
                        align,
                        pred_in_rank,
                        node_sizes,
                        node_spacing,
                        horizontal_ranks,
                    );
                }
                if sink[block_root] == block_root {
                    sink[block_root] = sink[pred_root];
                }
                let sep = delta(pred, w, node_sizes, node_spacing, horizontal_ranks);
                if sink[block_root] == sink[pred_root] {
                    x[block_root] = x[block_root].max(x[pred_root] + sep);
                } else {
                    shift[sink[pred_root]] =
                        shift[sink[pred_root]].min(x[block_root] - x[pred_root] - sep);
                }
            }
            let next = align[w];
            if next == w {
                break; // End of block chain (self-referencing terminal).
            }
            w = next;
        }
    }

    for &br in &ordered_roots {
        place_block(
            br,
            &mut x,
            &mut sink,
            &mut shift,
            root,
            align,
            pred_in_rank,
            node_sizes,
            node_spacing,
            horizontal_ranks,
        );
    }

    // Apply class shifts to block roots.
    for v in 0..node_count {
        if root[v] == v {
            let s = shift[sink[v]];
            if s < f32::INFINITY {
                x[v] += s;
            }
        }
    }

    // Propagate (shifted) block root coordinates to all block members.
    for v in 0..node_count {
        x[v] = x[root[v]];
    }

    x
}

/// Run Brandes-Köpf algorithm: four alignment passes, then take the median.
fn brandes_kopf_secondary_coords(
    ir: &MermaidDiagramIr,
    node_sizes: &[(f32, f32)],
    ranks: &BTreeMap<usize, usize>,
    ordering_by_rank: &BTreeMap<usize, Vec<usize>>,
    spacing: LayoutSpacing,
    horizontal_ranks: bool,
) -> Vec<f32> {
    let n = ir.nodes.len();
    if n == 0 {
        return Vec::new();
    }

    let ordered_ranks: Vec<usize> = ordering_by_rank.keys().copied().collect();

    // Dense rank-existence table, built ONCE and shared by all four alignment passes, replacing the per-node
    // `ordering_by_rank.contains_key(&adjacent_rank)` B-tree probe (a pointer-chase per node per pass) in
    // `bk_vertical_alignment`'s inner loop with an O(1) branchless slice load. `rank_exists[r]` is true iff `r`
    // is a key of `ordering_by_rank`; an out-of-range `adjacent_rank` (via `.get`) reads as absent, exactly like
    // `contains_key`. (A `binary_search` on `ordered_ranks` was rejected — branch mispredicts on the small
    // sorted array; a dense bool table is O(1) and branchless.)
    let max_rank = ordered_ranks.iter().copied().max().unwrap_or(0);
    let mut rank_exists = vec![false; max_rank + 1];
    for &r in &ordered_ranks {
        rank_exists[r] = true;
    }

    // Pre-build undirected adjacency for O(1) neighbour lookup. `FxHashSet` (was `BTreeSet<usize>`)
    // keeps the same set semantics — unique neighbours, membership — but swaps the per-insert O(log deg)
    // B-tree node allocation for O(1) hashing (the `BTreeSet<usize>` insert + build was ~14% of Sugiyama
    // layout: `place_block`/`nodes_by_rank`-adjacent). Iteration order is irrelevant: the sole consumer
    // (`bk_upper_neighbours`) re-sorts the collected neighbours by position, and distinct same-rank nodes
    // have distinct positions, so the sorted order is fully determined regardless of set iteration order.
    let mut adjacency: Vec<FxHashSet<usize>> = vec![FxHashSet::default(); n];
    for edge in &ir.edges {
        if let Some(s) = endpoint_node_index(ir, edge.from)
            && let Some(t) = endpoint_node_index(ir, edge.to)
            && s < n
            && t < n
            && s != t
        {
            adjacency[s].insert(t);
            adjacency[t].insert(s);
        }
    }

    // Dense node-indexed lookups, built ONCE and reused by all four alignment passes, replacing the
    // per-neighbour `ranks: &BTreeMap` and per-rank `pos_map: &BTreeMap` probes that dominated the BK
    // vertical-alignment inner loop (measured `BTreeMap<usize,usize>::get` ≈ 3.76% of the `cyclic_scc_100`
    // pipeline). Same primitive as the certified barycenter dense-rank win. `dense_node_rank[v]` reproduces
    // `ranks.get(&v).copied().unwrap_or(0)`; `pos_of[v]` reproduces the position `v` had in its rank's
    // `pos_map`, or `BK_POS_ABSENT` where that map had no entry (node absent from every rank ordering).
    let mut dense_node_rank = vec![0_usize; n];
    for (&node, &rank) in ranks {
        if let Some(slot) = dense_node_rank.get_mut(node) {
            *slot = rank;
        }
    }
    let mut pos_of = vec![BK_POS_ABSENT; n];
    for nodes in ordering_by_rank.values() {
        for (pos, &node) in nodes.iter().enumerate() {
            if let Some(slot) = pos_of.get_mut(node) {
                *slot = pos;
            }
        }
    }

    // Each node's left neighbour in its rank — a pure function of `ordering_by_rank`, identical across all
    // four alignment passes. Build it ONCE here instead of rebuilding it inside each `bk_horizontal_
    // compaction` call (3 of 4 builds were pure waste). Byte-identical (same values, same order).
    let mut pred_in_rank: Vec<Option<usize>> = vec![None; n];
    for nodes in ordering_by_rank.values() {
        for i in 1..nodes.len() {
            if nodes[i] < n && nodes[i - 1] < n {
                pred_in_rank[nodes[i]] = Some(nodes[i - 1]);
            }
        }
    }

    // Four alignment passes: (top_to_bottom, left_to_right).
    let directions = [
        (true, true),   // upper-left
        (true, false),  // upper-right
        (false, true),  // lower-left
        (false, false), // lower-right
    ];

    let mut all_coords: Vec<Vec<f32>> = Vec::with_capacity(4);

    for &(top_to_bottom, left_to_right) in &directions {
        let (root, align) = bk_vertical_alignment(
            n,
            &adjacency,
            &dense_node_rank,
            &pos_of,
            ordering_by_rank,
            &ordered_ranks,
            &rank_exists,
            top_to_bottom,
            left_to_right,
        );

        let coords = bk_horizontal_compaction(
            n,
            node_sizes,
            ordering_by_rank,
            &root,
            &align,
            &pred_in_rank,
            spacing.node_spacing,
            horizontal_ranks,
        );

        all_coords.push(coords);
    }

    // Normalize each pass so that the minimum coordinate is 0.
    for coords in &mut all_coords {
        let min_val = coords
            .iter()
            .copied()
            .filter(|v| v.is_finite())
            .fold(f32::INFINITY, f32::min);
        if min_val.is_finite() {
            for c in coords.iter_mut() {
                *c -= min_val;
            }
        }
    }

    // Median of four positions for each node.
    let mut result = vec![0.0_f32; n];
    for v in 0..n {
        let mut vals: Vec<f32> = all_coords.iter().map(|c| c[v]).collect();
        vals.sort_by(f32::total_cmp);
        // Median of 4 values: average of the two middle values.
        result[v] = f32::midpoint(vals[1], vals[2]);
    }

    result
}

/// Overlay the source's spacing hints (`ir.meta.node_spacing` / `rank_spacing`) on `spacing`.
///
/// A caller's `LayoutConfig` still wins where the source says nothing, so this only fills in what the
/// diagram itself asked for. Hints are whole layout units; DOT's inch measurements are converted in
/// the parser, which is the only place that knows the source dialect's units.
/// Overlay the source's edge-routing request (`ir.meta.edge_routing`) on `routing`.
///
/// Same contract as [`spacing_with_source_hints`]: the caller's `LayoutConfig` stands where the
/// source says nothing.
fn edge_routing_with_source_hints(routing: EdgeRouting, ir: &MermaidDiagramIr) -> EdgeRouting {
    match ir.meta.edge_routing {
        Some(fm_core::MermaidEdgeRoutingHint::Orthogonal) => EdgeRouting::Orthogonal,
        Some(fm_core::MermaidEdgeRoutingHint::Curved) => EdgeRouting::Spline,
        None => routing,
    }
}

fn spacing_with_source_hints(mut spacing: LayoutSpacing, ir: &MermaidDiagramIr) -> LayoutSpacing {
    if let Some(units) = ir.meta.node_spacing {
        spacing.node_spacing = units as f32;
    }
    if let Some(units) = ir.meta.rank_spacing {
        spacing.rank_spacing = units as f32;
    }
    spacing
}

fn coordinate_assignment(
    ir: &MermaidDiagramIr,
    node_sizes: &[(f32, f32)],
    ranks: &BTreeMap<usize, usize>,
    ordering_by_rank: &BTreeMap<usize, Vec<usize>>,
    spacing: LayoutSpacing,
) -> Vec<LayoutNodeBox> {
    let fallback_nodes_by_rank = nodes_by_rank(ir.nodes.len(), ranks);
    let horizontal_ranks = matches!(ir.direction, GraphDirection::LR | GraphDirection::RL);
    let reverse_ranks = matches!(ir.direction, GraphDirection::RL | GraphDirection::BT);
    let ordered_ranks: Vec<usize> = fallback_nodes_by_rank.keys().copied().collect();

    let rank_to_index: BTreeMap<usize, usize> = ordered_ranks
        .iter()
        .enumerate()
        .map(|(index, rank)| (*rank, index))
        .collect();

    // Compute primary offsets (rank positions) — unchanged from before.
    let mut rank_span = vec![0.0_f32; ordered_ranks.len()];
    for (rank_index, rank) in ordered_ranks.iter().copied().enumerate() {
        let node_indexes = ordering_by_rank
            .get(&rank)
            .cloned()
            .or_else(|| fallback_nodes_by_rank.get(&rank).cloned())
            .unwrap_or_default();

        let mut span = 0.0_f32;
        for node_index in node_indexes {
            let (width, height) = node_sizes.get(node_index).copied().unwrap_or((84.0, 44.0));
            let primary_extent = if horizontal_ranks { width } else { height };
            span = span.max(primary_extent);
        }
        rank_span[rank_index] = span.max(1.0);
    }

    let mut primary_offsets = vec![0.0_f32; ordered_ranks.len()];
    let mut primary_cursor = 0.0_f32;
    let iter_order: Vec<usize> = if reverse_ranks {
        (0..ordered_ranks.len()).rev().collect()
    } else {
        (0..ordered_ranks.len()).collect()
    };
    for rank_index in iter_order {
        primary_offsets[rank_index] = primary_cursor;
        primary_cursor += rank_span[rank_index] + spacing.rank_spacing;
    }

    // Compute secondary coordinates using Brandes-Köpf 4-way alignment.
    let secondary_coords = brandes_kopf_secondary_coords(
        ir,
        node_sizes,
        ranks,
        ordering_by_rank,
        spacing,
        horizontal_ranks,
    );

    // Build output using primary offsets and Brandes-Köpf secondary coordinates.
    let mut output = Vec::with_capacity(ir.nodes.len());
    for (rank, fallback_node_indexes) in &fallback_nodes_by_rank {
        let Some(rank_index) = rank_to_index.get(rank).copied() else {
            continue;
        };

        let node_indexes = ordering_by_rank
            .get(rank)
            .cloned()
            .unwrap_or_else(|| fallback_node_indexes.clone());

        let primary = primary_offsets.get(rank_index).copied().unwrap_or(0.0);
        for (order, node_index) in node_indexes.into_iter().enumerate() {
            let (width, height) = node_sizes.get(node_index).copied().unwrap_or((84.0, 44.0));
            let secondary = secondary_coords.get(node_index).copied().unwrap_or(0.0);

            let (x, y) = if horizontal_ranks {
                (primary, secondary)
            } else {
                (secondary, primary)
            };
            let node_id = ir
                .nodes
                .get(node_index)
                .map(|node| node.id.clone())
                .unwrap_or_default();

            output.push(LayoutNodeBox {
                node_index,
                node_id,
                rank: *rank,
                order,
                span: ir
                    .nodes
                    .get(node_index)
                    .map_or(Span::default(), |node| node.span_primary),
                bounds: LayoutRect {
                    x,
                    y,
                    width,
                    height,
                },
            });
        }
    }

    output.sort_by_key(|node| node.node_index);
    output
}

fn apply_subgraph_direction_overrides(
    ir: &MermaidDiagramIr,
    node_sizes: &[(f32, f32)],
    nodes: &mut [LayoutNodeBox],
    spacing: LayoutSpacing,
) {
    if ir.diagram_type != DiagramType::Flowchart || ir.graph.subgraphs.is_empty() {
        return;
    }

    let mut overridden_subgraphs: Vec<_> = ir
        .graph
        .subgraphs
        .iter()
        .filter_map(|subgraph| {
            subgraph
                .direction
                .map(|direction| (subgraph_depth(ir, subgraph.id), subgraph.id, direction))
        })
        .collect();

    overridden_subgraphs
        .sort_by(|left, right| left.0.cmp(&right.0).then_with(|| left.1.0.cmp(&right.1.0)));

    for (_depth, subgraph_id, direction) in overridden_subgraphs {
        apply_subgraph_direction_override(ir, subgraph_id, direction, node_sizes, nodes, spacing);
    }
}

fn subgraph_depth(ir: &MermaidDiagramIr, subgraph_id: fm_core::IrSubgraphId) -> usize {
    let mut depth = 0usize;
    let mut current = ir
        .graph
        .subgraph(subgraph_id)
        .and_then(|subgraph| subgraph.parent);
    while let Some(parent) = current {
        depth = depth.saturating_add(1);
        current = ir
            .graph
            .subgraph(parent)
            .and_then(|subgraph| subgraph.parent);
    }
    depth
}

fn apply_subgraph_direction_override(
    ir: &MermaidDiagramIr,
    subgraph_id: fm_core::IrSubgraphId,
    direction: GraphDirection,
    node_sizes: &[(f32, f32)],
    nodes: &mut [LayoutNodeBox],
    spacing: LayoutSpacing,
) {
    let mut member_indexes: Vec<_> = ir
        .graph
        .subgraph_members_recursive(subgraph_id)
        .into_iter()
        .map(|node_id| node_id.0)
        .collect();
    member_indexes.sort_unstable();
    member_indexes.dedup();

    if member_indexes.len() < 2 {
        return;
    }

    let Some(previous_bounds) = layout_bounds_for_members(&member_indexes, nodes) else {
        return;
    };
    let Some(local_layout) =
        build_subgraph_local_layout(ir, &member_indexes, direction, node_sizes, nodes, spacing)
    else {
        return;
    };
    let Some(local_bounds) = layout_bounds_for_entries(&local_layout) else {
        return;
    };

    let dx = previous_bounds.center().x - local_bounds.center().x;
    let dy = previous_bounds.center().y - local_bounds.center().y;

    for (node_index, bounds, rank, order) in local_layout {
        let Some(node_box) = nodes.get_mut(node_index) else {
            continue;
        };
        node_box.bounds.x = bounds.x + dx;
        node_box.bounds.y = bounds.y + dy;
        node_box.rank = rank;
        node_box.order = order;
    }
}

fn separate_disjoint_subgraphs(
    ir: &MermaidDiagramIr,
    nodes: &mut [LayoutNodeBox],
    spacing: LayoutSpacing,
) {
    if ir.graph.subgraphs.len() < 2 || nodes.is_empty() {
        return;
    }

    let is_horizontal = matches!(ir.direction, GraphDirection::LR | GraphDirection::RL);

    // Collect all top-level (root) subgraphs that have members in `nodes`.
    let root_subgraphs: Vec<_> = ir
        .graph
        .subgraphs
        .iter()
        .filter(|s| s.parent.is_none())
        .filter_map(|s| {
            let members: Vec<usize> = ir
                .graph
                .subgraph_members_recursive(s.id)
                .into_iter()
                .map(|id| id.0)
                .collect();
            if members.is_empty() {
                None
            } else {
                Some((s.id, members))
            }
        })
        .collect();

    if root_subgraphs.len() < 2 {
        return;
    }

    let padding = spacing.cluster_padding.max(24.0);

    // Helper to compute bounding box of a list of member node indices
    let compute_bounds =
        |members: &[usize], node_list: &[LayoutNodeBox]| -> Option<(f32, f32, f32, f32)> {
            let mut min_x = f32::INFINITY;
            let mut min_y = f32::INFINITY;
            let mut max_x = f32::NEG_INFINITY;
            let mut max_y = f32::NEG_INFINITY;
            for &m in members {
                if let Some(nb) = node_list.iter().find(|n| n.node_index == m) {
                    min_x = min_x.min(nb.bounds.x);
                    min_y = min_y.min(nb.bounds.y);
                    max_x = max_x.max(nb.bounds.x + nb.bounds.width);
                    max_y = max_y.max(nb.bounds.y + nb.bounds.height);
                }
            }
            if min_x.is_finite() && min_y.is_finite() && max_x.is_finite() && max_y.is_finite() {
                Some((min_x, min_y, max_x, max_y))
            } else {
                None
            }
        };

    // For vertical layouts (TB/TD), sibling subgraphs spanning the same vertical levels must not overlap horizontally.
    // For horizontal layouts (LR/RL), sibling subgraphs spanning the same horizontal levels must not overlap vertically.
    for i in 0..root_subgraphs.len() {
        for j in (i + 1)..root_subgraphs.len() {
            let Some((min_x_i, min_y_i, max_x_i, max_y_i)) =
                compute_bounds(&root_subgraphs[i].1, nodes)
            else {
                continue;
            };
            let Some((min_x_j, min_y_j, max_x_j, max_y_j)) =
                compute_bounds(&root_subgraphs[j].1, nodes)
            else {
                continue;
            };

            if is_horizontal {
                let x_overlap = min_x_i < max_x_j && min_x_j < max_x_i;
                if x_overlap {
                    let y_target = max_y_i + 2.0 * padding;
                    if min_y_j < y_target {
                        let shift_y = y_target - min_y_j;
                        for &m in &root_subgraphs[j].1 {
                            if let Some(nb) = nodes.iter_mut().find(|n| n.node_index == m) {
                                nb.bounds.y += shift_y;
                            }
                        }
                    }
                }
            } else {
                let y_overlap = min_y_i < max_y_j && min_y_j < max_y_i;
                if y_overlap {
                    let x_target = max_x_i + 2.0 * padding;
                    if min_x_j < x_target {
                        let shift_x = x_target - min_x_j;
                        for &m in &root_subgraphs[j].1 {
                            if let Some(nb) = nodes.iter_mut().find(|n| n.node_index == m) {
                                nb.bounds.x += shift_x;
                            }
                        }
                    }
                }
            }
        }
    }
}

fn apply_constraint_solver(
    ir: &MermaidDiagramIr,
    nodes: &mut [LayoutNodeBox],
    spacing: LayoutSpacing,
    config: &LayoutConfig,
) {
    if config.constraint_solver == ConstraintSolverMode::Disabled || ir.constraints.is_empty() {
        return;
    }

    if nodes.is_empty() {
        return;
    }

    match solve_constraint_coordinates(
        ir,
        nodes,
        spacing,
        config.constraint_solver_wall_clock_valve_ms,
    ) {
        Ok(applied) if applied > 0 => {
            info!(
                constraint_count = applied,
                "layout.constraint_solver.applied"
            );
        }
        Ok(_) => {}
        Err(error) => {
            warn!(%error, "layout.constraint_solver.fallback");
        }
    }
}

/// Counted stop for the constraint LP, as a pure function of the problem's size (bd-4q4d).
///
/// The wall-clock valve is a liveness backstop and nothing more: whether a solve fits inside it
/// depends on the machine, so if it is the only bound then which branch the caller takes — proven
/// optimum or heuristic fallback — is still decided by host load. A simplex iteration is the same
/// unit of work on every machine, so bounding iterations makes the stopping point identical
/// everywhere, and `constraint_solution_is_usable` then turns a stop into the same deterministic
/// fallback on every machine.
///
/// Shape of the model: 6 variables per node, and 4 displacement rows per node plus roughly one row
/// per declared constraint. Simplex on a problem this shape converges in O(rows), so 64x the row
/// count is headroom no correct solve uses. The clamp keeps the value inside `i32` for HiGHS
/// without ever making the bound depend on anything but the input.
#[cfg(not(target_arch = "wasm32"))]
const fn constraint_lp_iteration_limit(node_count: usize, constraint_count: usize) -> i32 {
    const HEADROOM: usize = 64;
    const CEILING: usize = 2_000_000;
    let rows = node_count
        .saturating_mul(4)
        .saturating_add(constraint_count);
    let limit = rows.saturating_mul(HEADROOM);
    // `min` is not const-callable on usize in this position, so the clamp is written out.
    if limit > CEILING {
        CEILING as i32
    } else {
        limit as i32
    }
}

/// May this LP result be written into node coordinates? (bd-9xwk)
///
/// Only a PROVEN optimum may. `model.solve()` returning `Ok` is not that: good_lp's HiGHS backend
/// maps `ReachedTimeLimit`, `ReachedIterationLimit`, `ReachedSolutionLimit`, `ReachedInterrupt` and
/// `ReachedMemoryLimit` onto `SolutionStatus::TimeLimit` and still returns `Ok(solution)` whenever a
/// feasible primal point exists. Writing such a point out makes the rendered geometry a function of
/// how much clock the solver happened to get.
///
/// This is a free function rather than an inline `matches!` so the decision is testable on its own.
/// The end-to-end layout probe cannot reach it: to make HiGHS stop with a feasible-but-suboptimal
/// point you have to interrupt it mid-phase-2, which is a race, and a valve short enough to be
/// deterministic stops it before feasibility, where good_lp returns `Err` and the caller would fall
/// back anyway. So the probe alone proves nothing about this branch — `constraint_lp_result_is_used_
/// only_when_proven_optimal` is what pins it.
#[cfg(not(target_arch = "wasm32"))]
const fn constraint_solution_is_usable(status: SolutionStatus) -> bool {
    matches!(status, SolutionStatus::Optimal)
}

#[cfg(not(target_arch = "wasm32"))]
fn solve_constraint_coordinates(
    ir: &MermaidDiagramIr,
    nodes: &mut [LayoutNodeBox],
    spacing: LayoutSpacing,
    wall_clock_valve_ms: u64,
) -> Result<usize, String> {
    let horizontal_ranks = matches!(ir.direction, GraphDirection::LR | GraphDirection::RL);
    let id_to_index: BTreeMap<&str, usize> = nodes
        .iter()
        .enumerate()
        .map(|(index, node)| (node.node_id.as_str(), index))
        .collect();
    let ordered_nodes: BTreeSet<_> = ir
        .constraints
        .iter()
        .filter_map(|constraint| match constraint {
            fm_core::IrConstraint::OrderInRank { node_ids, .. } => Some(node_ids),
            _ => None,
        })
        .flatten()
        .filter_map(|node_id| id_to_index.get(node_id.as_str()).copied())
        .collect();
    let non_overlap_pairs = collect_non_overlap_pairs(ir, &id_to_index, nodes.len());

    let mut variables = good_lp::ProblemVariables::new();
    let x_vars: Vec<_> = nodes.iter().map(|_| variables.add(variable())).collect();
    let y_vars: Vec<_> = nodes.iter().map(|_| variables.add(variable())).collect();
    let dx_pos: Vec<_> = nodes
        .iter()
        .map(|_| variables.add(variable().min(0.0)))
        .collect();
    let dx_neg: Vec<_> = nodes
        .iter()
        .map(|_| variables.add(variable().min(0.0)))
        .collect();
    let dy_pos: Vec<_> = nodes
        .iter()
        .map(|_| variables.add(variable().min(0.0)))
        .collect();
    let dy_neg: Vec<_> = nodes
        .iter()
        .map(|_| variables.add(variable().min(0.0)))
        .collect();
    // Four binary selectors encode the four allowed relative placements for each rectangle pair.
    // Exactly one is not required: at least one active side is enough, and it avoids needlessly
    // rejecting a pair that is separated on both axes.
    let non_overlap_selectors: Vec<_> = non_overlap_pairs
        .iter()
        .map(|_| {
            [
                variables.add(variable().binary()),
                variables.add(variable().binary()),
                variables.add(variable().binary()),
                variables.add(variable().binary()),
            ]
        })
        .collect();

    let objective = (0..nodes.len()).fold(Expression::from(0.0), |mut expr, index| {
        expr += dx_pos[index] + dx_neg[index] + dy_pos[index] + dy_neg[index];
        expr
    });

    let mut model = variables
        .minimise(objective)
        .using(default_solver)
        // bd-4q4d. The OPERATIVE bound is counted, so the solver stops at the same place on every
        // machine; the clock below is only a liveness backstop. Naming the HiGHS option means
        // naming the backend, which this crate already pins (`good_lp` with only the `highs`
        // feature, so `default_solver` IS `highs`).
        .set_option(
            "simplex_iteration_limit",
            constraint_lp_iteration_limit(nodes.len(), ir.constraints.len()),
        )
        // A valve of 0 means "spend no clock here" and is honoured as such. It used to be clamped
        // up to 1 ms, which made "no optimization" unrequestable and left no way to exercise the
        // fail-closed path without racing the solver (bd-9xwk).
        .with_time_limit((wall_clock_valve_ms as f64) / 1000.0);

    for (index, node) in nodes.iter().enumerate() {
        let base_x = f64::from(node.bounds.x);
        let base_y = f64::from(node.bounds.y);
        model = model
            .with(constraint!(x_vars[index] - base_x <= dx_pos[index]))
            .with(constraint!(base_x - x_vars[index] <= dx_neg[index]))
            .with(constraint!(y_vars[index] - base_y <= dy_pos[index]))
            .with(constraint!(base_y - y_vars[index] <= dy_neg[index]));
    }

    let mut nodes_by_rank: BTreeMap<usize, Vec<usize>> = BTreeMap::new();
    for (node_index, node) in nodes.iter().enumerate() {
        nodes_by_rank.entry(node.rank).or_default().push(node_index);
    }
    for node_indexes in nodes_by_rank.values_mut() {
        node_indexes.sort_by_key(|node_index| nodes[*node_index].order);
        for pair in node_indexes.windows(2) {
            let current = pair[0];
            let next = pair[1];
            if ordered_nodes.contains(&current) || ordered_nodes.contains(&next) {
                continue;
            }
            let gap = in_rank_gap(&nodes[current], spacing, horizontal_ranks);
            model = if horizontal_ranks {
                model.with(constraint!(y_vars[next] - y_vars[current] >= gap))
            } else {
                model.with(constraint!(x_vars[next] - x_vars[current] >= gap))
            };
        }
    }

    let mut applied = 0_usize;
    for constraint in &ir.constraints {
        match constraint {
            fm_core::IrConstraint::SameRank { node_ids, .. } => {
                let resolved = resolve_constraint_nodes(node_ids, &id_to_index);
                if let Some((&anchor, rest)) = resolved.split_first() {
                    for &node_index in rest {
                        model = if horizontal_ranks {
                            model.with(constraint!(x_vars[node_index] == x_vars[anchor]))
                        } else {
                            model.with(constraint!(y_vars[node_index] == y_vars[anchor]))
                        };
                    }
                    applied = applied.saturating_add(1);
                }
            }
            fm_core::IrConstraint::MinLength {
                from_id,
                to_id,
                min_len,
                ..
            } => {
                let Some(&from_index) = id_to_index.get(from_id.as_str()) else {
                    warn!(
                        node_id = from_id,
                        "layout.constraint_solver.unknown_from_id"
                    );
                    continue;
                };
                let Some(&to_index) = id_to_index.get(to_id.as_str()) else {
                    warn!(node_id = to_id, "layout.constraint_solver.unknown_to_id");
                    continue;
                };
                let gap = min_length_gap(&nodes[from_index], *min_len, spacing, horizontal_ranks);
                model = if horizontal_ranks {
                    model.with(constraint!(x_vars[to_index] - x_vars[from_index] >= gap))
                } else {
                    model.with(constraint!(y_vars[to_index] - y_vars[from_index] >= gap))
                };
                applied = applied.saturating_add(1);
            }
            fm_core::IrConstraint::Pin { node_id, x, y, .. } => {
                let Some(&node_index) = id_to_index.get(node_id.as_str()) else {
                    warn!(node_id, "layout.constraint_solver.unknown_pin_id");
                    continue;
                };
                model = model
                    .with(constraint!(x_vars[node_index] == *x))
                    .with(constraint!(y_vars[node_index] == *y));
                applied = applied.saturating_add(1);
            }
            fm_core::IrConstraint::OrderInRank { node_ids, .. } => {
                let resolved = resolve_constraint_nodes(node_ids, &id_to_index);
                for pair in resolved.windows(2) {
                    let current = pair[0];
                    let next = pair[1];
                    let gap = in_rank_gap(&nodes[current], spacing, horizontal_ranks);
                    model = if horizontal_ranks {
                        model.with(constraint!(y_vars[next] - y_vars[current] >= gap))
                    } else {
                        model.with(constraint!(x_vars[next] - x_vars[current] >= gap))
                    };
                }
                if resolved.len() > 1 {
                    applied = applied.saturating_add(1);
                }
            }
            fm_core::IrConstraint::NonOverlap { .. } => {
                // Lowered in one deterministic pass below so overlapping declarations are merged
                // by pair and use their largest requested gap.
            }
        }
    }

    let big_m = non_overlap_big_m(nodes, &non_overlap_pairs);
    for ((left, right, gap), selectors) in non_overlap_pairs.iter().zip(&non_overlap_selectors) {
        let left_width = f64::from(nodes[*left].bounds.width);
        let left_height = f64::from(nodes[*left].bounds.height);
        let right_width = f64::from(nodes[*right].bounds.width);
        let right_height = f64::from(nodes[*right].bounds.height);
        model = model
            .with(constraint!(
                x_vars[*left] + (left_width / 2.0) + *gap
                    <= x_vars[*right] - (right_width / 2.0) + big_m * (1.0 - selectors[0])
            ))
            .with(constraint!(
                x_vars[*right] + (right_width / 2.0) + *gap
                    <= x_vars[*left] - (left_width / 2.0) + big_m * (1.0 - selectors[1])
            ))
            .with(constraint!(
                y_vars[*left] + (left_height / 2.0) + *gap
                    <= y_vars[*right] - (right_height / 2.0) + big_m * (1.0 - selectors[2])
            ))
            .with(constraint!(
                y_vars[*right] + (right_height / 2.0) + *gap
                    <= y_vars[*left] - (left_height / 2.0) + big_m * (1.0 - selectors[3])
            ))
            .with(constraint!(
                selectors[0] + selectors[1] + selectors[2] + selectors[3] >= 1
            ));
    }
    if !non_overlap_pairs.is_empty() {
        applied = applied.saturating_add(non_overlap_pairs.len());
    }

    if applied == 0 {
        return Ok(0);
    }

    let solution = model.solve().map_err(|error| error.to_string())?;
    // bd-9xwk. `Ok` is NOT "solved". HiGHS answers a budget stop with `ReachedTimeLimit` (or
    // `ReachedIterationLimit`/`ReachedMemoryLimit`) and, whenever a feasible primal point exists,
    // good_lp returns it as `Ok` carrying `SolutionStatus::TimeLimit`. Writing that point out puts
    // a partially-optimized geometry into the render, chosen by how busy the machine was — the
    // same defect class as bd-9a1t and bd-giej, one level closer to the output because these are
    // coordinates rather than an algorithm choice.
    //
    // So the result is failed CLOSED: anything other than a proven optimum is refused here, the
    // caller takes its `layout.constraint_solver.fallback` branch, and the deterministic heuristic
    // coordinates stay. A fired valve costs the optimization; it never changes it.
    if !constraint_solution_is_usable(solution.status()) {
        return Err(format!(
            "constraint LP stopped at {:?} rather than a proven optimum; keeping heuristic \
             coordinates so geometry does not depend on host load",
            solution.status()
        ));
    }
    for (index, node) in nodes.iter_mut().enumerate() {
        node.bounds.x = solution.value(x_vars[index]) as f32;
        node.bounds.y = solution.value(y_vars[index]) as f32;
    }
    recompute_in_rank_orders(nodes, horizontal_ranks);

    Ok(applied)
}

#[cfg(target_arch = "wasm32")]
fn solve_constraint_coordinates(
    _ir: &MermaidDiagramIr,
    _nodes: &mut [LayoutNodeBox],
    _spacing: LayoutSpacing,
    _wall_clock_valve_ms: u64,
) -> Result<usize, String> {
    Err(String::from(
        "constraint solver is unavailable on wasm32 builds and falls back to heuristic layout",
    ))
}

fn resolve_constraint_nodes(
    node_ids: &[String],
    id_to_index: &BTreeMap<&str, usize>,
) -> Vec<usize> {
    node_ids
        .iter()
        .filter_map(|node_id| match id_to_index.get(node_id.as_str()) {
            Some(index) => Some(*index),
            None => {
                warn!(node_id, "layout.constraint_solver.unknown_constraint_id");
                None
            }
        })
        .collect()
}

/// Expand explicit and all-node non-overlap declarations into unique rectangle pairs.
///
/// Multiple declarations for a pair compose by taking the largest gap. A `BTreeMap` gives the MIP
/// columns a stable order and makes the resulting coordinate tie-breaking reproducible.
fn collect_non_overlap_pairs(
    ir: &MermaidDiagramIr,
    id_to_index: &BTreeMap<&str, usize>,
    node_count: usize,
) -> Vec<(usize, usize, f64)> {
    let mut pairs = BTreeMap::<(usize, usize), f64>::new();
    for constraint in &ir.constraints {
        let fm_core::IrConstraint::NonOverlap { node_ids, gap, .. } = constraint else {
            continue;
        };
        let selected = if node_ids.is_empty() {
            (0..node_count).collect()
        } else {
            resolve_constraint_nodes(node_ids, id_to_index)
        };
        for (offset, &left) in selected.iter().enumerate() {
            for &right in selected.iter().skip(offset + 1) {
                let pair = if left < right {
                    (left, right)
                } else {
                    (right, left)
                };
                pairs
                    .entry(pair)
                    .and_modify(|current| *current = current.max(*gap))
                    .or_insert(*gap);
            }
        }
    }
    pairs
        .into_iter()
        .map(|((left, right), gap)| (left, right, gap))
        .collect()
}

/// A conservative finite relaxation value for every inactive non-overlap branch.
///
/// The displacement objective chooses coordinates near the heuristic placement, so the sum of all
/// rectangle extents and requested gaps bounds every useful move from that placement. Scaling that
/// finite envelope leaves inactive branches non-binding without smuggling a machine-dependent stop
/// or a magic diagram-size constant into the MIP.
fn non_overlap_big_m(nodes: &[LayoutNodeBox], pairs: &[(usize, usize, f64)]) -> f64 {
    let coordinate_extent = nodes.iter().fold(1.0_f64, |extent, node| {
        extent
            .max(f64::from(node.bounds.x).abs())
            .max(f64::from(node.bounds.y).abs())
    });
    let rectangle_extent = nodes.iter().fold(0.0_f64, |total, node| {
        total + f64::from(node.bounds.width.abs()) + f64::from(node.bounds.height.abs())
    });
    let gap_extent = pairs.iter().map(|(_, _, gap)| *gap).sum::<f64>();
    let envelope = coordinate_extent + rectangle_extent + gap_extent + 1.0;
    (envelope * 4.0).max(1.0)
}

fn in_rank_gap(node: &LayoutNodeBox, spacing: LayoutSpacing, horizontal_ranks: bool) -> f64 {
    let extent = if horizontal_ranks {
        node.bounds.height
    } else {
        node.bounds.width
    };
    f64::from(extent + spacing.node_spacing)
}

fn min_length_gap(
    node: &LayoutNodeBox,
    min_len: usize,
    spacing: LayoutSpacing,
    horizontal_ranks: bool,
) -> f64 {
    let primary_extent = if horizontal_ranks {
        node.bounds.width
    } else {
        node.bounds.height
    };
    let base_gap = primary_extent + spacing.rank_spacing;
    f64::from(base_gap * min_len.max(1) as f32)
}

fn recompute_in_rank_orders(nodes: &mut [LayoutNodeBox], horizontal_ranks: bool) {
    let mut by_rank: BTreeMap<usize, Vec<usize>> = BTreeMap::new();
    for node in nodes.iter() {
        by_rank.entry(node.rank).or_default().push(node.node_index);
    }

    for node_indexes in by_rank.values_mut() {
        node_indexes.sort_by(|left, right| {
            let left_coord = if horizontal_ranks {
                nodes[*left].bounds.y
            } else {
                nodes[*left].bounds.x
            };
            let right_coord = if horizontal_ranks {
                nodes[*right].bounds.y
            } else {
                nodes[*right].bounds.x
            };
            left_coord
                .total_cmp(&right_coord)
                .then_with(|| left.cmp(right))
        });

        for (order, node_index) in node_indexes.iter().copied().enumerate() {
            nodes[node_index].order = order;
        }
    }
}

fn layout_bounds_for_members(
    member_indexes: &[usize],
    nodes: &[LayoutNodeBox],
) -> Option<LayoutRect> {
    let mut min_x = f32::INFINITY;
    let mut min_y = f32::INFINITY;
    let mut max_x = f32::NEG_INFINITY;
    let mut max_y = f32::NEG_INFINITY;

    for &node_index in member_indexes {
        let Some(node_box) = nodes.get(node_index) else {
            continue;
        };
        min_x = min_x.min(node_box.bounds.x);
        min_y = min_y.min(node_box.bounds.y);
        max_x = max_x.max(node_box.bounds.x + node_box.bounds.width);
        max_y = max_y.max(node_box.bounds.y + node_box.bounds.height);
    }

    (min_x.is_finite() && min_y.is_finite() && max_x.is_finite() && max_y.is_finite()).then_some(
        LayoutRect {
            x: min_x,
            y: min_y,
            width: max_x - min_x,
            height: max_y - min_y,
        },
    )
}

fn layout_bounds_for_entries(entries: &[(usize, LayoutRect, usize, usize)]) -> Option<LayoutRect> {
    let mut min_x = f32::INFINITY;
    let mut min_y = f32::INFINITY;
    let mut max_x = f32::NEG_INFINITY;
    let mut max_y = f32::NEG_INFINITY;

    for (_, bounds, _, _) in entries {
        min_x = min_x.min(bounds.x);
        min_y = min_y.min(bounds.y);
        max_x = max_x.max(bounds.x + bounds.width);
        max_y = max_y.max(bounds.y + bounds.height);
    }

    (min_x.is_finite() && min_y.is_finite() && max_x.is_finite() && max_y.is_finite()).then_some(
        LayoutRect {
            x: min_x,
            y: min_y,
            width: max_x - min_x,
            height: max_y - min_y,
        },
    )
}

fn build_subgraph_local_layout(
    ir: &MermaidDiagramIr,
    member_indexes: &[usize],
    direction: GraphDirection,
    node_sizes: &[(f32, f32)],
    nodes: &[LayoutNodeBox],
    spacing: LayoutSpacing,
) -> Option<Vec<(usize, LayoutRect, usize, usize)>> {
    let horizontal_ranks = matches!(direction, GraphDirection::LR | GraphDirection::RL);
    let reverse_ranks = matches!(direction, GraphDirection::RL | GraphDirection::BT);
    let member_set: BTreeSet<_> = member_indexes.iter().copied().collect();

    let mut indegree: BTreeMap<usize, usize> = member_indexes.iter().map(|&idx| (idx, 0)).collect();
    let mut outgoing: BTreeMap<usize, Vec<usize>> = member_indexes
        .iter()
        .map(|&idx| (idx, Vec::new()))
        .collect();
    let mut local_rank: BTreeMap<usize, usize> =
        member_indexes.iter().map(|&idx| (idx, 0)).collect();

    for edge in &ir.edges {
        let Some(source) = endpoint_node_index(ir, edge.from) else {
            continue;
        };
        let Some(target) = endpoint_node_index(ir, edge.to) else {
            continue;
        };
        if !member_set.contains(&source) || !member_set.contains(&target) || source == target {
            continue;
        }

        outgoing.entry(source).or_default().push(target);
        if let Some(value) = indegree.get_mut(&target) {
            *value = value.saturating_add(1);
        }
    }

    for targets in outgoing.values_mut() {
        targets.sort_by(|left, right| {
            subgraph_position_key(*left, nodes, horizontal_ranks).cmp(&subgraph_position_key(
                *right,
                nodes,
                horizontal_ranks,
            ))
        });
        targets.dedup();
    }

    let mut scheduled = BTreeSet::new();
    let mut topological_order = Vec::with_capacity(member_indexes.len());

    while topological_order.len() < member_indexes.len() {
        let mut ready: Vec<_> = indegree
            .iter()
            .filter(|(node_index, degree)| **degree == 0 && !scheduled.contains(*node_index))
            .map(|(node_index, _)| *node_index)
            .collect();

        if ready.is_empty() {
            ready.extend(
                member_indexes
                    .iter()
                    .copied()
                    .filter(|node_index| !scheduled.contains(node_index)),
            );
        }

        ready.sort_by(|left, right| {
            subgraph_position_key(*left, nodes, horizontal_ranks).cmp(&subgraph_position_key(
                *right,
                nodes,
                horizontal_ranks,
            ))
        });

        let node_index = ready[0];
        scheduled.insert(node_index);
        topological_order.push(node_index);

        let base_rank = local_rank.get(&node_index).copied().unwrap_or(0);
        if let Some(targets) = outgoing.get(&node_index) {
            for &target in targets {
                if let Some(value) = indegree.get_mut(&target) {
                    *value = value.saturating_sub(1);
                }
                if let Some(rank) = local_rank.get_mut(&target) {
                    *rank = (*rank).max(base_rank.saturating_add(1));
                }
            }
        }
    }

    let mut nodes_by_rank: BTreeMap<usize, Vec<usize>> = BTreeMap::new();
    for node_index in topological_order {
        let rank = local_rank.get(&node_index).copied().unwrap_or(0);
        nodes_by_rank.entry(rank).or_default().push(node_index);
    }

    for rank_nodes in nodes_by_rank.values_mut() {
        rank_nodes.sort_by(|left, right| {
            subgraph_secondary_key(*left, nodes, horizontal_ranks).cmp(&subgraph_secondary_key(
                *right,
                nodes,
                horizontal_ranks,
            ))
        });
    }

    let mut ordered_ranks: Vec<_> = nodes_by_rank.keys().copied().collect();
    if reverse_ranks {
        ordered_ranks.reverse();
    }

    let mut entries = Vec::with_capacity(member_indexes.len());
    let mut primary_cursor = 0.0_f32;

    for (display_rank, rank) in ordered_ranks.into_iter().enumerate() {
        let rank_nodes = nodes_by_rank.get(&rank)?;
        let primary_span = rank_nodes
            .iter()
            .map(|&node_index| {
                let (width, height) = node_sizes.get(node_index).copied().unwrap_or((84.0, 44.0));
                if horizontal_ranks { width } else { height }
            })
            .fold(0.0_f32, f32::max)
            .max(1.0);

        let mut secondary_cursor = 0.0_f32;
        for (order, &node_index) in rank_nodes.iter().enumerate() {
            let (width, height) = node_sizes.get(node_index).copied().unwrap_or((84.0, 44.0));
            let bounds = if horizontal_ranks {
                let rect = LayoutRect {
                    x: primary_cursor,
                    y: secondary_cursor,
                    width,
                    height,
                };
                secondary_cursor += height + spacing.node_spacing;
                rect
            } else {
                let rect = LayoutRect {
                    x: secondary_cursor,
                    y: primary_cursor,
                    width,
                    height,
                };
                secondary_cursor += width + spacing.node_spacing;
                rect
            };

            entries.push((node_index, bounds, display_rank, order));
        }

        primary_cursor += primary_span + spacing.rank_spacing;
    }

    Some(entries)
}

fn subgraph_position_key(
    node_index: usize,
    nodes: &[LayoutNodeBox],
    horizontal_ranks: bool,
) -> (i32, i32, usize) {
    let Some(node_box) = nodes.get(node_index) else {
        return (0, 0, node_index);
    };
    if horizontal_ranks {
        (
            (node_box.bounds.x * 100.0).round() as i32,
            (node_box.bounds.y * 100.0).round() as i32,
            node_index,
        )
    } else {
        (
            (node_box.bounds.y * 100.0).round() as i32,
            (node_box.bounds.x * 100.0).round() as i32,
            node_index,
        )
    }
}

fn subgraph_secondary_key(
    node_index: usize,
    nodes: &[LayoutNodeBox],
    horizontal_ranks: bool,
) -> (i32, usize) {
    let Some(node_box) = nodes.get(node_index) else {
        return (0, node_index);
    };
    let secondary = if horizontal_ranks {
        node_box.bounds.y
    } else {
        node_box.bounds.x
    };
    (((secondary * 100.0).round() as i32), node_index)
}

fn nodes_by_rank(node_count: usize, ranks: &BTreeMap<usize, usize>) -> BTreeMap<usize, Vec<usize>> {
    // Materialise the per-node rank into a dense Vec via ONE ordered walk of `ranks`, instead of a random
    // `ranks.get(&node_index)` BTreeMap tree-descent per node (O(N) sequential vs O(N log N) cache-missy
    // probes). Byte-identical: unranked nodes keep rank 0 — the Vec's init value equals the old
    // `.unwrap_or(0)` default — and the per-rank push order (node_index 0..N) is unchanged.
    let mut rank_of = vec![0_usize; node_count];
    for (&node_index, &rank) in ranks {
        if node_index < node_count {
            rank_of[node_index] = rank;
        }
    }
    let mut nodes_by_rank: BTreeMap<usize, Vec<usize>> = BTreeMap::new();
    for (node_index, &rank) in rank_of.iter().enumerate() {
        nodes_by_rank.entry(rank).or_default().push(node_index);
    }
    nodes_by_rank
}

/// Every adjacent-rank pair's layer edges, bucketed in ONE pass over `ir.edges`.
///
/// This replaces a per-rank-pair full scan. `egraph_optimized_order_for_rank` asked for the
/// `(rank - 1, rank)` and `(rank, rank + 1)` edge lists separately, and each request walked all of
/// `ir.edges` doing two `endpoint_node_index` resolutions and two `ranks` B-tree probes per edge
/// before discarding everything outside the one pair it wanted. `apply_egraph_ordering_pass` runs
/// two passes over every rank, so that is `4 * ranks` full scans — O(ranks · edges) to produce
/// O(edges) of data. On `docs_site_200` the scan measured 6.86% inclusive / 1.94% self.
///
/// Bucketing by `(source_rank, target_rank)` answers every request from one pass, mirroring what
/// [`build_pair_node_edges`] already does for the refinement path. Byte-identical: the filter is
/// unchanged, each bucket is pushed in `ir.edges` order and sorted exactly as before, and a pair
/// with no edges is simply absent from the map — which is what the old empty check produced.
fn layer_edges_by_rank_pair(
    ir: &MermaidDiagramIr,
    ranks: &BTreeMap<usize, usize>,
) -> FxHashMap<(usize, usize), crate::egraph_ordering::LayerEdges> {
    let mut by_pair: FxHashMap<(usize, usize), Vec<(usize, usize)>> = FxHashMap::default();

    for edge in &ir.edges {
        let Some(mut source) = endpoint_node_index(ir, edge.from) else {
            continue;
        };
        let Some(mut target) = endpoint_node_index(ir, edge.to) else {
            continue;
        };
        let Some(mut source_rank) = ranks.get(&source).copied() else {
            continue;
        };
        let Some(mut target_rank) = ranks.get(&target).copied() else {
            continue;
        };

        if source_rank == target_rank {
            continue;
        }
        if source_rank > target_rank {
            std::mem::swap(&mut source, &mut target);
            std::mem::swap(&mut source_rank, &mut target_rank);
        }
        if target_rank != source_rank.saturating_add(1) {
            continue;
        }

        by_pair
            .entry((source_rank, target_rank))
            .or_default()
            .push((source, target));
    }

    by_pair
        .into_iter()
        .map(|(pair, mut edges)| {
            edges.sort_unstable();
            (pair, crate::egraph_ordering::LayerEdges { edges })
        })
        .collect()
}

fn egraph_optimized_order_for_rank(
    layer_edges: &FxHashMap<(usize, usize), crate::egraph_ordering::LayerEdges>,
    ordering_by_rank: &BTreeMap<usize, Vec<usize>>,
    rank: usize,
) -> Option<(usize, crate::egraph_ordering::LayerOptimizationResult)> {
    let current_order = ordering_by_rank.get(&rank)?.clone();
    let current = crate::egraph_ordering::LayerOrdering::new(current_order);

    let upper_ordering = rank.checked_sub(1).and_then(|upper_rank| {
        ordering_by_rank
            .get(&upper_rank)
            .cloned()
            .map(crate::egraph_ordering::LayerOrdering::new)
    });
    let upper_edges = rank
        .checked_sub(1)
        .and_then(|upper_rank| layer_edges.get(&(upper_rank, rank)));

    let lower_ordering = rank.checked_add(1).and_then(|lower_rank| {
        ordering_by_rank
            .get(&lower_rank)
            .cloned()
            .map(crate::egraph_ordering::LayerOrdering::new)
    });
    let lower_edges = rank
        .checked_add(1)
        .and_then(|lower_rank| layer_edges.get(&(rank, lower_rank)));

    if upper_edges.is_none() && lower_edges.is_none() {
        return None;
    }

    if !crate::egraph_ordering::should_optimize_egraph_layer(
        &current,
        upper_ordering.as_ref().zip(upper_edges),
        lower_ordering.as_ref().zip(lower_edges),
    ) {
        return None;
    }

    let local_crossings_before = crate::egraph_ordering::local_crossing_count(
        &current,
        upper_ordering.as_ref().zip(upper_edges),
        lower_ordering.as_ref().zip(lower_edges),
    );
    let result = crate::egraph_ordering::optimize_layer_ordering(
        &current,
        upper_ordering.as_ref().zip(upper_edges),
        lower_ordering.as_ref().zip(lower_edges),
    );

    (result.crossing_count < local_crossings_before).then_some((local_crossings_before, result))
}

fn apply_egraph_ordering_pass<const PACKED_CROSSINGS: bool>(
    ir: &MermaidDiagramIr,
    ranks: &BTreeMap<usize, usize>,
    ordering_by_rank: &mut BTreeMap<usize, Vec<usize>>,
    mut best_crossings: usize,
    scratch: &mut BarycenterScratch,
) -> usize {
    let rank_keys: Vec<usize> = ordering_by_rank.keys().copied().collect();
    // Ranks move within this pass, but an edge's endpoints keep their ranks -- `ranks` is fixed
    // here, only the within-rank ordering changes -- so the adjacent-pair edge buckets are built
    // once for the whole pass instead of rescanning `ir.edges` per rank.
    let layer_edges = layer_edges_by_rank_pair(ir, ranks);
    for _ in 0..2 {
        let mut improved = false;
        for &rank in &rank_keys {
            let Some((local_crossings_before, result)) =
                egraph_optimized_order_for_rank(&layer_edges, ordering_by_rank, rank)
            else {
                continue;
            };

            let Some(original_order) = ordering_by_rank.get(&rank).cloned() else {
                continue;
            };
            let (estimated_egraph_nodes, estimated_egraph_bytes) =
                crate::egraph_ordering::estimate_egraph_size(original_order.len());
            ordering_by_rank.insert(rank, result.ordering.order.clone());
            let total_after = if PACKED_CROSSINGS {
                total_crossings_packed(ir, ranks, ordering_by_rank, scratch)
                    .unwrap_or_else(|| total_crossings(ir, ranks, ordering_by_rank))
            } else {
                total_crossings(ir, ranks, ordering_by_rank)
            };

            if total_after < best_crossings {
                improved = true;
                debug!(
                    rank,
                    local_crossings_before,
                    local_crossings_after = result.crossing_count,
                    total_crossings_before = best_crossings,
                    total_crossings_after = total_after,
                    rewrites_applied = result.rewrites_applied,
                    estimated_egraph_nodes,
                    estimated_egraph_bytes,
                    "layout.crossing_egraph"
                );
                best_crossings = total_after;
                if best_crossings == 0 {
                    return 0;
                }
            } else {
                ordering_by_rank.insert(rank, original_order);
            }
        }

        if !improved {
            break;
        }
    }

    best_crossings
}

#[cfg(all(feature = "fnx-integration", not(target_arch = "wasm32")))]
enum CentralityAssist {
    Enabled(NodeCentralityScores),
    Disabled,
}

#[cfg(not(all(feature = "fnx-integration", not(target_arch = "wasm32"))))]
enum CentralityAssist {
    Disabled,
}

#[cfg(all(feature = "fnx-integration", not(target_arch = "wasm32")))]
fn build_centrality_assist(ir: &MermaidDiagramIr, config: &LayoutConfig) -> CentralityAssist {
    if !config.fnx_enabled {
        return CentralityAssist::Disabled;
    }
    let scores = compute_centrality_scores(ir);
    if scores.computed && !scores.is_empty() {
        CentralityAssist::Enabled(scores)
    } else {
        CentralityAssist::Disabled
    }
}

#[cfg(not(all(feature = "fnx-integration", not(target_arch = "wasm32"))))]
fn build_centrality_assist(_: &MermaidDiagramIr, _: &LayoutConfig) -> CentralityAssist {
    CentralityAssist::Disabled
}

/// Compute centrality tier data for layout extensions (FNX-enabled builds only).
#[cfg(all(feature = "fnx-integration", not(target_arch = "wasm32")))]
fn compute_layout_centrality_tiers(
    ir: &MermaidDiagramIr,
    config: &LayoutConfig,
) -> Vec<NodeCentrality> {
    if !config.fnx_enabled {
        return Vec::new();
    }
    let scores = compute_centrality_scores(ir);
    if scores.computed && !scores.is_empty() {
        crate::fnx_ordering::classify_centrality_tiers(&scores)
    } else {
        Vec::new()
    }
}

/// Stub for non-FNX builds.
#[cfg(not(all(feature = "fnx-integration", not(target_arch = "wasm32"))))]
fn compute_layout_centrality_tiers(_: &MermaidDiagramIr, _: &LayoutConfig) -> Vec<NodeCentrality> {
    Vec::new()
}

#[inline(always)]
fn barycenter_node_rank<const DENSE_RANK: bool>(
    ranks: &BTreeMap<usize, usize>,
    dense_node_rank: &[u32],
    node_index: usize,
) -> usize {
    if DENSE_RANK {
        dense_node_rank
            .get(node_index)
            .copied()
            .and_then(|rank| usize::try_from(rank).ok())
            .unwrap_or(0)
    } else {
        ranks.get(&node_index).copied().unwrap_or(0)
    }
}

/// Node-indexed scratch for the `SINGLE_PASS` barycenter arm, allocated once per
/// `crossing_minimization` and reused by every sweep call.
///
/// It replaces the two per-call `BTreeMap`s (`adjacent_position`, and the wide branch's `local_slot`) with
/// O(1)-indexed `u32` tables. Entries touched by a call are reset in O(rank width) afterwards. The
/// accumulator grows only to the widest observed rank and then reuses that allocation. The `!SINGLE_PASS`
/// arm keeps all three vectors empty.
struct BarycenterScratch {
    /// Position of a node within the adjacent rank's order, or `ABSENT`.
    position_of: Vec<u32>,
    /// Slot of a node within the current rank's order, or `ABSENT`.
    slot_of: Vec<u32>,
    /// `(position_sum, neighbor_count)` per slot of the current rank.
    accumulators: Vec<(usize, usize)>,
    /// Two packed CSR offset tables in one allocation: incoming first, then outgoing. Outgoing
    /// offsets are absolute indexes into `incidence_neighbors`, beginning after all incoming entries.
    incidence_offsets: Vec<u32>,
    /// Incoming neighbors followed by outgoing neighbors, each per-node slice preserving `ir.edges`
    /// order and parallel-edge multiplicity.
    incidence_neighbors: Vec<u32>,
}

impl BarycenterScratch {
    /// Sentinel for "not in the rank currently loaded". The packed arm is enabled only when the node
    /// count fits in `u32`, so `u32::MAX` can never be a valid position or slot.
    const ABSENT: u32 = u32::MAX;

    fn new<const SINGLE_PASS: bool, const FLAT_CSR: bool>(ir: &MermaidDiagramIr) -> Self {
        let node_count = ir.nodes.len();
        if SINGLE_PASS && u32::try_from(node_count).is_ok() {
            let mut scratch = Self {
                position_of: vec![Self::ABSENT; node_count],
                slot_of: vec![Self::ABSENT; node_count],
                accumulators: Vec::new(),
                incidence_offsets: Vec::new(),
                incidence_neighbors: Vec::new(),
            };
            if FLAT_CSR {
                scratch.build_flat_incidence(ir);
            }
            scratch
        } else {
            Self {
                position_of: Vec::new(),
                slot_of: Vec::new(),
                accumulators: Vec::new(),
                incidence_offsets: Vec::new(),
                incidence_neighbors: Vec::new(),
            }
        }
    }

    /// Build incoming and outgoing CSR in two persistent allocations. The already-allocated packed
    /// frontier tables double as fill cursors, avoiding a third temporary vector. Any graph whose
    /// incidence offsets do not fit in `u32` leaves the tables empty and uses the exact full-edge fallback.
    fn build_flat_incidence(&mut self, ir: &MermaidDiagramIr) {
        let node_count = self.position_of.len();
        let Some(direction_width) = node_count.checked_add(1) else {
            return;
        };
        let Some(offset_count) = direction_width.checked_mul(2) else {
            return;
        };
        self.incidence_offsets.resize(offset_count, 0);

        for edge in &ir.edges {
            let Some(source) = endpoint_node_index(ir, edge.from) else {
                continue;
            };
            let Some(target) = endpoint_node_index(ir, edge.to) else {
                continue;
            };
            if source >= node_count || target >= node_count {
                continue;
            }
            let incoming_count = &mut self.incidence_offsets[target + 1];
            let Some(next_incoming) = incoming_count.checked_add(1) else {
                self.incidence_offsets.clear();
                return;
            };
            *incoming_count = next_incoming;

            let outgoing_count = &mut self.incidence_offsets[direction_width + source + 1];
            let Some(next_outgoing) = outgoing_count.checked_add(1) else {
                self.incidence_offsets.clear();
                return;
            };
            *outgoing_count = next_outgoing;
        }

        for index in 1..=node_count {
            let Some(prefix) =
                self.incidence_offsets[index - 1].checked_add(self.incidence_offsets[index])
            else {
                self.incidence_offsets.clear();
                return;
            };
            self.incidence_offsets[index] = prefix;
        }
        self.incidence_offsets[direction_width] = self.incidence_offsets[node_count];
        for node in 0..node_count {
            let index = direction_width + node + 1;
            let Some(prefix) =
                self.incidence_offsets[index - 1].checked_add(self.incidence_offsets[index])
            else {
                self.incidence_offsets.clear();
                return;
            };
            self.incidence_offsets[index] = prefix;
        }

        let total_entries = self.incidence_offsets[direction_width + node_count];
        let Ok(total_entries) = usize::try_from(total_entries) else {
            self.incidence_offsets.clear();
            return;
        };
        self.incidence_neighbors.resize(total_entries, Self::ABSENT);
        for node in 0..node_count {
            self.position_of[node] = self.incidence_offsets[node];
            self.slot_of[node] = self.incidence_offsets[direction_width + node];
        }

        let mut valid = true;
        for edge in &ir.edges {
            let Some(source) = endpoint_node_index(ir, edge.from) else {
                continue;
            };
            let Some(target) = endpoint_node_index(ir, edge.to) else {
                continue;
            };
            if source >= node_count || target >= node_count {
                continue;
            }
            let Ok(source_word) = u32::try_from(source) else {
                valid = false;
                break;
            };
            let Ok(target_word) = u32::try_from(target) else {
                valid = false;
                break;
            };

            let Ok(incoming_cursor) = usize::try_from(self.position_of[target]) else {
                valid = false;
                break;
            };
            let Some(incoming_neighbor) = self.incidence_neighbors.get_mut(incoming_cursor) else {
                valid = false;
                break;
            };
            *incoming_neighbor = source_word;
            self.position_of[target] = self.position_of[target].saturating_add(1);

            let Ok(outgoing_cursor) = usize::try_from(self.slot_of[source]) else {
                valid = false;
                break;
            };
            let Some(outgoing_neighbor) = self.incidence_neighbors.get_mut(outgoing_cursor) else {
                valid = false;
                break;
            };
            *outgoing_neighbor = target_word;
            self.slot_of[source] = self.slot_of[source].saturating_add(1);
        }

        self.position_of.fill(Self::ABSENT);
        self.slot_of.fill(Self::ABSENT);
        if !valid {
            self.incidence_offsets.clear();
            self.incidence_neighbors.clear();
        }
    }
}

/// Deterministic barycenter sweep shared by all A/B arms.
///
/// - `DENSE_RANK` (certified `bd-9w78`, `f8e6ce3`): index the packed node-rank table instead of probing
///   `ranks: &BTreeMap` in the innermost edge loop.
/// - `SINGLE_PASS`: accumulate over `ir.edges` **once per call** instead of once per node of the current
///   rank, using `scratch` in place of the two per-call `BTreeMap`s. This removes the `rank_size` factor:
///   the old narrow branch was `O(rank_size · |E|)` per call, and on `cyclic_scc_100` the rank width is ~4.
/// - `FLAT_CSR`: build packed incoming/outgoing incidence once, then visit only the current rank's incident
///   neighbors per call instead of rescanning every edge. Two flat arrays replace the rejected `Vec<Vec>` shape.
///
/// **`SINGLE_PASS` is output-identical by construction.** The pre-existing code already contained *both*
/// shapes and selected between them by `SINGLE_PASS_RANK_THRESHOLD`, on the explicit premise (see the old
/// comment, and the KEPT `single_pass_barycenter.md`) that they *"compute the identical result (integer
/// position sum divided once by the neighbor count)"*. The threshold existed only because the wide branch's
/// per-call `BTreeMap` setup dominated at small rank widths — and that setup is exactly what `scratch`
/// removes. Each CSR node slice is the same stable `ir.edges` subsequence that fed that node's independent
/// accumulator, so its integer sum/count, resulting `f32` barycenter, and downstream stable sort are bit-for-bit
/// what they were.
#[allow(unused_variables)] // centrality only used with fnx-integration feature
#[allow(clippy::too_many_arguments)] // Keep both A/B arms in one body so ordering logic cannot drift.
fn reorder_rank_by_barycenter<
    const DENSE_RANK: bool,
    const SINGLE_PASS: bool,
    const FLAT_CSR: bool,
>(
    ir: &MermaidDiagramIr,
    rank_lookup: (&BTreeMap<usize, usize>, &[u32]),
    scratch: &mut BarycenterScratch,
    ordering_by_rank: &mut BTreeMap<usize, Vec<usize>>,
    rank: usize,
    adjacent_rank: usize,
    use_incoming: bool,
    centrality: &CentralityAssist,
) {
    let (ranks, dense_node_rank) = rank_lookup;
    // Borrow the rank's order (was `.cloned()`): it is READ-ONLY through `scored_nodes` construction, and the
    // final `ordering_by_rank.insert(rank, …)` runs after that last read (NLL drops the borrow first), so no
    // clone is needed. Removes a per-rank-per-sweep `Vec<usize>` allocation+copy from the barycenter hot loop
    // (`reorder_rank_by_barycenter` ≈ 47% of the cyclic-SCC pipeline). Byte-identical (same values read).
    let Some(current_order) = ordering_by_rank.get(&rank) else {
        return;
    };
    let Some(adjacent_order) = ordering_by_rank.get(&adjacent_rank) else {
        return;
    };

    if SINGLE_PASS && !scratch.position_of.is_empty() {
        for (position, node) in adjacent_order.iter().enumerate() {
            if let Some(entry) = scratch.position_of.get_mut(*node) {
                *entry = u32::try_from(position).unwrap_or(BarycenterScratch::ABSENT);
            }
        }
        scratch.accumulators.clear();
        scratch.accumulators.resize(current_order.len(), (0, 0));

        if FLAT_CSR && !scratch.incidence_offsets.is_empty() {
            let direction_width = scratch.position_of.len() + 1;
            let offset_base = if use_incoming { 0 } else { direction_width };
            for (slot, node) in current_order.iter().copied().enumerate() {
                let Some(start_word) = scratch.incidence_offsets.get(offset_base + node) else {
                    continue;
                };
                let Some(end_word) = scratch.incidence_offsets.get(offset_base + node + 1) else {
                    continue;
                };
                let Ok(start) = usize::try_from(*start_word) else {
                    continue;
                };
                let Ok(end) = usize::try_from(*end_word) else {
                    continue;
                };
                let Some(neighbors) = scratch.incidence_neighbors.get(start..end) else {
                    continue;
                };
                for adjacent_word in neighbors {
                    let Ok(adjacent_node) = usize::try_from(*adjacent_word) else {
                        continue;
                    };
                    if barycenter_node_rank::<DENSE_RANK>(ranks, dense_node_rank, adjacent_node)
                        != adjacent_rank
                    {
                        continue;
                    }
                    let Some(&position) = scratch.position_of.get(adjacent_node) else {
                        continue;
                    };
                    if position == BarycenterScratch::ABSENT {
                        continue;
                    }
                    let Ok(position) = usize::try_from(position) else {
                        continue;
                    };
                    if let Some(accumulator) = scratch.accumulators.get_mut(slot) {
                        accumulator.0 = accumulator.0.saturating_add(position);
                        accumulator.1 = accumulator.1.saturating_add(1);
                    }
                }
            }
        } else {
            for (slot, node) in current_order.iter().enumerate() {
                if let Some(entry) = scratch.slot_of.get_mut(*node) {
                    *entry = u32::try_from(slot).unwrap_or(BarycenterScratch::ABSENT);
                }
            }
            for edge in &ir.edges {
                let Some(source) = endpoint_node_index(ir, edge.from) else {
                    continue;
                };
                let Some(target) = endpoint_node_index(ir, edge.to) else {
                    continue;
                };
                let (node, adjacent_node) = if use_incoming {
                    (target, source)
                } else {
                    (source, target)
                };
                let Some(&slot) = scratch.slot_of.get(node) else {
                    continue;
                };
                if slot == BarycenterScratch::ABSENT {
                    continue;
                }
                let Ok(slot) = usize::try_from(slot) else {
                    continue;
                };
                if barycenter_node_rank::<DENSE_RANK>(ranks, dense_node_rank, adjacent_node)
                    != adjacent_rank
                {
                    continue;
                }
                let Some(&position) = scratch.position_of.get(adjacent_node) else {
                    continue;
                };
                if position == BarycenterScratch::ABSENT {
                    continue;
                }
                let Ok(position) = usize::try_from(position) else {
                    continue;
                };
                if let Some(accumulator) = scratch.accumulators.get_mut(slot) {
                    accumulator.0 = accumulator.0.saturating_add(position);
                    accumulator.1 = accumulator.1.saturating_add(1);
                }
            }
            for node in current_order {
                if let Some(entry) = scratch.slot_of.get_mut(*node) {
                    *entry = BarycenterScratch::ABSENT;
                }
            }
        }

        // Reset only the entries this call touched: O(rank width), not O(node count).
        for node in adjacent_order {
            if let Some(entry) = scratch.position_of.get_mut(*node) {
                *entry = BarycenterScratch::ABSENT;
            }
        }
        let mut scored_nodes: Vec<(usize, Option<f32>, usize)> = current_order
            .iter()
            .enumerate()
            .map(|(stable_idx, node_index)| {
                let (total_position, neighbor_count) = scratch
                    .accumulators
                    .get(stable_idx)
                    .copied()
                    .unwrap_or((0, 0));
                let barycenter = if neighbor_count == 0 {
                    None
                } else {
                    #[allow(clippy::cast_precision_loss)]
                    Some(total_position as f32 / neighbor_count as f32)
                };
                (*node_index, barycenter, stable_idx)
            })
            .collect();

        sort_scored_nodes(&mut scored_nodes, centrality);
        ordering_by_rank.insert(
            rank,
            scored_nodes
                .into_iter()
                .map(|(node_index, _, _)| node_index)
                .collect(),
        );
        return;
    }

    let adjacent_position: BTreeMap<usize, usize> = adjacent_order
        .iter()
        .enumerate()
        .map(|(position, node)| (*node, position))
        .collect();

    // The barycenter of each node is the mean position of its neighbors in the
    // adjacent rank. Two implementations compute the *identical* result (integer
    // position sum divided once by the neighbor count); we pick by rank width:
    //
    // - Narrow ranks: the original per-node scan. Cheap, and avoids the single-pass
    //   setup allocations that would dominate when there are only a handful of nodes.
    // - Wide ranks: a single pass over the edge list that accumulates contributions
    //   into per-slot bins, turning the O(rank_size * edge_count) per-node rescan
    //   into O(edge_count + rank_size) — the cost driver of crossing minimization on
    //   fan-out graphs (parallel pipelines, ER/state diagrams, org charts).
    const SINGLE_PASS_RANK_THRESHOLD: usize = 8;

    let mut scored_nodes: Vec<(usize, Option<f32>, usize)> = if current_order.len()
        < SINGLE_PASS_RANK_THRESHOLD
    {
        current_order
            .iter()
            .enumerate()
            .map(|(stable_idx, node_index)| {
                let mut total_position = 0_usize;
                let mut neighbor_count = 0_usize;

                for edge in &ir.edges {
                    let Some(source) = endpoint_node_index(ir, edge.from) else {
                        continue;
                    };
                    let Some(target) = endpoint_node_index(ir, edge.to) else {
                        continue;
                    };

                    let neighbor = if use_incoming {
                        if target == *node_index
                            && barycenter_node_rank::<DENSE_RANK>(ranks, dense_node_rank, source)
                                == adjacent_rank
                        {
                            Some(source)
                        } else {
                            None
                        }
                    } else if source == *node_index
                        && barycenter_node_rank::<DENSE_RANK>(ranks, dense_node_rank, target)
                            == adjacent_rank
                    {
                        Some(target)
                    } else {
                        None
                    };

                    if let Some(adjacent_node) = neighbor
                        && let Some(position) = adjacent_position.get(&adjacent_node)
                    {
                        total_position = total_position.saturating_add(*position);
                        neighbor_count = neighbor_count.saturating_add(1);
                    }
                }

                let barycenter = if neighbor_count == 0 {
                    None
                } else {
                    Some(total_position as f32 / neighbor_count as f32)
                };
                (*node_index, barycenter, stable_idx)
            })
            .collect()
    } else {
        let local_slot: BTreeMap<usize, usize> = current_order
            .iter()
            .enumerate()
            .map(|(slot, node)| (*node, slot))
            .collect();
        let mut accumulators: Vec<(usize, usize)> = vec![(0, 0); current_order.len()];
        for edge in &ir.edges {
            let Some(source) = endpoint_node_index(ir, edge.from) else {
                continue;
            };
            let Some(target) = endpoint_node_index(ir, edge.to) else {
                continue;
            };
            let (node, adjacent_node) = if use_incoming {
                (target, source)
            } else {
                (source, target)
            };
            let Some(&slot) = local_slot.get(&node) else {
                continue;
            };
            if barycenter_node_rank::<DENSE_RANK>(ranks, dense_node_rank, adjacent_node)
                != adjacent_rank
            {
                continue;
            }
            if let Some(position) = adjacent_position.get(&adjacent_node)
                && let Some(accumulator) = accumulators.get_mut(slot)
            {
                accumulator.0 = accumulator.0.saturating_add(*position);
                accumulator.1 = accumulator.1.saturating_add(1);
            }
        }

        current_order
            .iter()
            .enumerate()
            .map(|(stable_idx, node_index)| {
                let (total_position, neighbor_count) =
                    accumulators.get(stable_idx).copied().unwrap_or((0, 0));
                let barycenter = if neighbor_count == 0 {
                    None
                } else {
                    Some(total_position as f32 / neighbor_count as f32)
                };
                (*node_index, barycenter, stable_idx)
            })
            .collect()
    };

    sort_scored_nodes(&mut scored_nodes, centrality);

    ordering_by_rank.insert(
        rank,
        scored_nodes
            .into_iter()
            .map(|(node_index, _, _)| node_index)
            .collect(),
    );
}

/// The single, shared ordering comparator for every barycenter arm, so the arms cannot drift apart in the
/// one place that determines deterministic output.
#[allow(unused_variables)] // centrality only used with fnx-integration feature
fn sort_scored_nodes(
    scored_nodes: &mut [(usize, Option<f32>, usize)],
    centrality: &CentralityAssist,
) {
    #[cfg(all(feature = "fnx-integration", not(target_arch = "wasm32")))]
    match centrality {
        CentralityAssist::Enabled(scores) => {
            scored_nodes.sort_by(|left, right| compare_with_centrality(*left, *right, scores));
        }
        CentralityAssist::Disabled => {
            scored_nodes.sort_by(|left, right| match (left.1, right.1) {
                (Some(lhs), Some(rhs)) => lhs.total_cmp(&rhs).then_with(|| left.0.cmp(&right.0)),
                (Some(_), None) => std::cmp::Ordering::Less,
                (None, Some(_)) => std::cmp::Ordering::Greater,
                (None, None) => left.2.cmp(&right.2).then_with(|| left.0.cmp(&right.0)),
            });
        }
    }

    #[cfg(not(all(feature = "fnx-integration", not(target_arch = "wasm32"))))]
    scored_nodes.sort_by(|left, right| match (left.1, right.1) {
        (Some(lhs), Some(rhs)) => lhs.total_cmp(&rhs).then_with(|| left.0.cmp(&right.0)),
        (Some(_), None) => std::cmp::Ordering::Less,
        (None, Some(_)) => std::cmp::Ordering::Greater,
        (None, None) => left.2.cmp(&right.2).then_with(|| left.0.cmp(&right.0)),
    });
}

/// Bench/test-only access to the two barycenter sweep arms.
///
/// An A/B split across two `rch` invocations is invalid. The paired sampler alternates both arms inside
/// one routine and one binary, so the bench crate needs to reach the reference implementation. Hidden
/// from docs; not part of the public API contract.
#[doc(hidden)]
#[cfg(any(test, feature = "bench-internals"))]
pub mod bench_internals {
    use super::{BTreeMap, LayoutConfig, MermaidDiagramIr};

    /// Rank assignment exactly as `layout_diagram_sugiyama_traced_with_config` computes it, so a bench
    /// feeds `crossing_minimization` the same input production does.
    #[must_use]
    pub fn prepare_ranks(ir: &MermaidDiagramIr, config: &LayoutConfig) -> BTreeMap<usize, usize> {
        let node_priority = super::stable_node_priorities(ir);
        let cycle_result = super::cycle_removal(ir, config.cycle_strategy, &node_priority);
        let mut ranks = super::rank_assignment(ir, &cycle_result, &node_priority);
        super::apply_ir_constraints(ir, &mut ranks);
        ranks
    }

    /// ORIG arm: the pre-`bd-9w78` `BTreeMap` sweep.
    #[must_use]
    pub fn crossing_minimization_btreemap(
        ir: &MermaidDiagramIr,
        ranks: &BTreeMap<usize, usize>,
        config: &LayoutConfig,
    ) -> (usize, BTreeMap<usize, Vec<usize>>) {
        super::crossing_minimization_impl::<false, false, false, false>(ir, ranks, config)
    }

    /// CAND arm: one packed node-rank table replacing only the hot `BTreeMap` rank probes.
    #[must_use]
    pub fn crossing_minimization_dense_rank(
        ir: &MermaidDiagramIr,
        ranks: &BTreeMap<usize, usize>,
        config: &LayoutConfig,
    ) -> (usize, BTreeMap<usize, Vec<usize>>) {
        super::crossing_minimization_impl::<true, false, false, false>(ir, ranks, config)
    }

    /// CAND arm for the follow-up lever: dense rank **plus** one accumulating edge pass per call, using
    /// reusable packed position/slot scratch instead of the two per-call `BTreeMap`s. Removes the
    /// `rank_size` factor from the old narrow-rank branch.
    #[must_use]
    pub fn crossing_minimization_single_pass(
        ir: &MermaidDiagramIr,
        ranks: &BTreeMap<usize, usize>,
        config: &LayoutConfig,
    ) -> (usize, BTreeMap<usize, Vec<usize>>) {
        super::crossing_minimization_impl::<true, true, false, false>(ir, ranks, config)
    }

    /// CAND arm for flat CSR incidence: build packed incoming/outgoing neighbors once, then make each
    /// reorder proportional to the current rank's incident edges instead of the whole edge list.
    #[must_use]
    pub fn crossing_minimization_flat_csr(
        ir: &MermaidDiagramIr,
        ranks: &BTreeMap<usize, usize>,
        config: &LayoutConfig,
    ) -> (usize, BTreeMap<usize, Vec<usize>>) {
        super::crossing_minimization_impl::<true, true, true, false>(ir, ranks, config)
    }

    /// CAND arm for the packed crossing counter: reuse the flat CSR storage after the last barycenter
    /// sweep as normalized rank-pair buckets plus an allocation-free `u32` Fenwick frontier.
    #[must_use]
    pub fn crossing_minimization_packed_crossings(
        ir: &MermaidDiagramIr,
        ranks: &BTreeMap<usize, usize>,
        config: &LayoutConfig,
    ) -> (usize, BTreeMap<usize, Vec<usize>>) {
        super::crossing_minimization_impl::<true, true, true, true>(ir, ranks, config)
    }
}

/// Adjacent-rank-pair node edges, precomputed once for incremental crossing counting.
///
/// Key `(upper_rank, lower_rank)` (consecutive ranks); value is `(source_node, target_node)`
/// pairs. Mirrors the edge filtering in [`total_crossings`] but stores node ids (stable across
/// reordering) instead of positions, so per-pair crossings can be recomputed cheaply after a
/// single-rank perturbation without rescanning every edge.
fn build_pair_node_edges(
    ir: &MermaidDiagramIr,
    ranks: &BTreeMap<usize, usize>,
) -> FxHashMap<(usize, usize), Vec<(usize, usize)>> {
    let mut pair_edges: FxHashMap<(usize, usize), Vec<(usize, usize)>> = FxHashMap::default();
    for edge in &ir.edges {
        let Some(mut source) = endpoint_node_index(ir, edge.from) else {
            continue;
        };
        let Some(mut target) = endpoint_node_index(ir, edge.to) else {
            continue;
        };
        let Some(mut source_rank) = ranks.get(&source).copied() else {
            continue;
        };
        let Some(mut target_rank) = ranks.get(&target).copied() else {
            continue;
        };
        if source_rank == target_rank {
            continue;
        }
        if source_rank > target_rank {
            std::mem::swap(&mut source, &mut target);
            std::mem::swap(&mut source_rank, &mut target_rank);
        }
        if target_rank != source_rank.saturating_add(1) {
            continue;
        }
        pair_edges
            .entry((source_rank, target_rank))
            .or_default()
            .push((source, target));
    }
    pair_edges
}

/// The two adjacent-rank-pair counters a single-rank perturbation can change.
///
/// [`crossing_refinement`] perturbs one rank at a time while its neighbours stand still, so the
/// neighbour-derived half of each trial's work -- position map, edge bucketing, sort order -- is a
/// loop invariant. Rebuilt once per rank visit and then reused by every trial in that visit.
/// `None` on a side means that pair has no usable dense domain (or no edges at all) and the trial
/// falls back to [`pair_crossings`], which computes the same number.
#[derive(Default)]
struct RankNeighbourCrossings {
    upper: Option<crate::egraph_ordering::FixedLayerCrossings>,
    lower: Option<crate::egraph_ordering::FixedLayerCrossings>,
}

impl RankNeighbourCrossings {
    /// Re-bucket both pairs against `rank`'s current neighbours. Must be called whenever a rank
    /// other than `rank` may have moved.
    fn rebuild(
        &mut self,
        rank: usize,
        ordering_by_rank: &BTreeMap<usize, Vec<usize>>,
        pair_edges: &FxHashMap<(usize, usize), Vec<(usize, usize)>>,
    ) {
        let moving = ordering_by_rank.get(&rank).map_or(&[][..], Vec::as_slice);
        self.upper = rank.checked_sub(1).and_then(|upper_rank| {
            let fixed = ordering_by_rank.get(&upper_rank)?;
            let edges = pair_edges.get(&(upper_rank, rank))?;
            crate::egraph_ordering::FixedLayerCrossings::new(fixed, moving, edges, true)
        });
        let lower_rank = rank.saturating_add(1);
        self.lower = ordering_by_rank.get(&lower_rank).and_then(|fixed| {
            let edges = pair_edges.get(&(rank, lower_rank))?;
            crate::egraph_ordering::FixedLayerCrossings::new(fixed, moving, edges, false)
        });
    }

    /// Crossings on the `(rank - 1, rank)` and `(rank, rank + 1)` pairs — the only two a
    /// perturbation confined to `rank` can change.
    fn count(
        &mut self,
        rank: usize,
        ordering_by_rank: &BTreeMap<usize, Vec<usize>>,
        pair_edges: &FxHashMap<(usize, usize), Vec<(usize, usize)>>,
    ) -> usize {
        let moving = ordering_by_rank.get(&rank).map_or(&[][..], Vec::as_slice);
        let upper = match self.upper.as_mut() {
            Some(counter) => counter.count(moving),
            None => rank.checked_sub(1).map_or(0, |upper_rank| {
                pair_crossings(upper_rank, rank, ordering_by_rank, pair_edges)
            }),
        };
        let lower = match self.lower.as_mut() {
            Some(counter) => counter.count(moving),
            None => pair_crossings(rank, rank.saturating_add(1), ordering_by_rank, pair_edges),
        };
        upper.saturating_add(lower)
    }
}

/// Crossings on a single adjacent rank pair for the current ordering — O(pair-edges · log).
///
/// The sum of `pair_crossings` over every consecutive `(r, r+1)` pair equals [`total_crossings`];
/// a perturbation confined to rank `r` only changes the `(r-1, r)` and `(r, r+1)` pairs, so the
/// refinement compares just those instead of recomputing the whole graph.
fn pair_crossings(
    upper_rank: usize,
    lower_rank: usize,
    ordering_by_rank: &BTreeMap<usize, Vec<usize>>,
    pair_edges: &FxHashMap<(usize, usize), Vec<(usize, usize)>>,
) -> usize {
    let Some(edges) = pair_edges.get(&(upper_rank, lower_rank)) else {
        return 0;
    };
    if edges.len() < 2 {
        return 0;
    }
    let (Some(upper_order), Some(lower_order)) = (
        ordering_by_rank.get(&upper_rank),
        ordering_by_rank.get(&lower_rank),
    ) else {
        return 0;
    };
    // Position lookup by DENSE ARRAY, not two from-scratch hash maps.
    //
    // This runs in the refinement loop -- a perturbation at rank `r` re-counts the `(r-1, r)` and
    // `(r, r+1)` pairs -- so these maps were rebuilt from empty over and over for orderings that
    // barely changed. Built with no capacity, each one grew by repeated `reserve_rehash`; on the
    // ER catalog workload `reserve_rehash` + `insert` + `build_hasher` measured 19% of the whole
    // job, on top of `crossing_count` itself. The keys are node indices, i.e. already dense, so a
    // flat `Vec` indexed by node id answers the same question with one memset and no hashing.
    //
    // `crossing_count_dense` in `egraph_ordering` makes exactly this trade; the sparsity guard is
    // copied from it so a pathological node-id domain still falls back to hashing instead of
    // allocating a huge mostly-empty array. Byte-identical either way: same positions, pushed in
    // the same edge order, so `edge_positions` and the inversion count are unchanged.
    const MISSING: usize = usize::MAX;
    let dense_domain = upper_order
        .iter()
        .chain(lower_order.iter())
        .copied()
        .max()
        .and_then(|max_node| max_node.checked_add(1))
        .filter(|&domain_len| {
            let useful_slots = upper_order
                .len()
                .saturating_add(lower_order.len())
                .saturating_add(edges.len().saturating_mul(2))
                .max(64);
            domain_len <= useful_slots.saturating_mul(8)
        });

    let mut edge_positions: Vec<(usize, usize)> = Vec::with_capacity(edges.len());
    if let Some(domain_len) = dense_domain {
        let mut upper_pos = vec![MISSING; domain_len];
        for (position, &node) in upper_order.iter().enumerate() {
            upper_pos[node] = position;
        }
        let mut lower_pos = vec![MISSING; domain_len];
        for (position, &node) in lower_order.iter().enumerate() {
            lower_pos[node] = position;
        }
        // `.get` not indexing: an edge may name a node absent from these two ranks entirely.
        for &(source, target) in edges {
            let source_position = upper_pos.get(source).copied().unwrap_or(MISSING);
            let target_position = lower_pos.get(target).copied().unwrap_or(MISSING);
            if source_position == MISSING || target_position == MISSING {
                continue;
            }
            edge_positions.push((source_position, target_position));
        }
    } else {
        let mut upper_pos: FxHashMap<usize, usize> = FxHashMap::default();
        for (position, &node) in upper_order.iter().enumerate() {
            upper_pos.insert(node, position);
        }
        let mut lower_pos: FxHashMap<usize, usize> = FxHashMap::default();
        for (position, &node) in lower_order.iter().enumerate() {
            lower_pos.insert(node, position);
        }
        for &(source, target) in edges {
            let (Some(&source_position), Some(&target_position)) =
                (upper_pos.get(&source), lower_pos.get(&target))
            else {
                continue;
            };
            edge_positions.push((source_position, target_position));
        }
    }
    edge_positions.sort_by(|left, right| left.0.cmp(&right.0).then_with(|| left.1.cmp(&right.1)));
    let mut target_positions: Vec<usize> = edge_positions
        .into_iter()
        .map(|(_source_position, target_position)| target_position)
        .collect();
    count_inversions(&mut target_positions)
}

/// Normalize one countable edge to `(upper_node, lower_position)` using the current ordering.
/// Returning the lower position directly lets the packed counter overwrite the no-longer-needed CSR
/// neighbor IDs with its Fenwick input without another lookup during the hot count.
fn packed_crossing_edge(
    ir: &MermaidDiagramIr,
    ranks: &BTreeMap<usize, usize>,
    positions: &[u32],
    from: IrEndpoint,
    to: IrEndpoint,
) -> Option<(usize, u32)> {
    let mut source = endpoint_node_index(ir, from)?;
    let mut target = endpoint_node_index(ir, to)?;
    let mut source_rank = ranks.get(&source).copied()?;
    let mut target_rank = ranks.get(&target).copied()?;

    if source_rank == target_rank {
        return None;
    }
    if source_rank > target_rank {
        std::mem::swap(&mut source, &mut target);
        std::mem::swap(&mut source_rank, &mut target_rank);
    }
    if target_rank != source_rank.saturating_add(1) {
        return None;
    }

    let source_position = positions.get(source).copied()?;
    let target_position = positions.get(target).copied()?;
    if source_position == BarycenterScratch::ABSENT || target_position == BarycenterScratch::ABSENT
    {
        return None;
    }
    Some((source, target_position))
}

#[inline]
fn packed_fenwick_prefix(tree: &[u32], mut index: usize) -> usize {
    let mut sum = 0_usize;
    while index > 0 {
        sum = sum.saturating_add(usize::try_from(tree[index]).unwrap_or(usize::MAX));
        index &= index - 1;
    }
    sum
}

#[inline]
fn packed_fenwick_add(tree: &mut [u32], mut index: usize) {
    while index < tree.len() {
        tree[index] = tree[index].saturating_add(1);
        let step = index & index.wrapping_neg();
        index = index.saturating_add(step);
    }
}

/// Allocation-free crossing count for the packed production arm.
///
/// Barycenter sweeps are finished before this runs, so their CSR can be destructively repurposed:
/// the first offset half becomes normalized upper-node buckets, the first neighbor half stores lower
/// positions, and the second offset half is a word-packed Fenwick frontier. Repeated e-graph probes
/// rebuild those same buffers in place; no nested map, edge bucket, sort buffer, or merge allocation
/// is created by the counter.
fn total_crossings_packed(
    ir: &MermaidDiagramIr,
    ranks: &BTreeMap<usize, usize>,
    ordering_by_rank: &BTreeMap<usize, Vec<usize>>,
    scratch: &mut BarycenterScratch,
) -> Option<usize> {
    let node_count = ir.nodes.len();
    if scratch.position_of.len() != node_count || scratch.slot_of.len() != node_count {
        return None;
    }
    let direction_width = node_count.checked_add(1)?;
    let offset_count = direction_width.checked_mul(2)?;
    if scratch.incidence_offsets.len() < offset_count
        || !scratch.incidence_neighbors.len().is_multiple_of(2)
    {
        return None;
    }
    let edge_capacity = scratch.incidence_neighbors.len() / 2;

    // Rebuild the current node-position table. Entries whose ordering rank disagrees with `ranks`
    // are deliberately absent, matching the old per-rank position-map lookup.
    scratch.position_of.fill(BarycenterScratch::ABSENT);
    for (rank, ordered_nodes) in ordering_by_rank {
        for (position, node) in ordered_nodes.iter().copied().enumerate() {
            if ranks.get(&node).copied() != Some(*rank) {
                continue;
            }
            let entry = scratch.position_of.get_mut(node)?;
            *entry = u32::try_from(position).ok()?;
        }
    }

    // Count normalized adjacent-rank edges per upper node into the first offset half.
    let (normalized_offsets, fenwick_storage) =
        scratch.incidence_offsets.split_at_mut(direction_width);
    normalized_offsets.fill(0);
    for edge in &ir.edges {
        let Some((upper_node, _lower_position)) =
            packed_crossing_edge(ir, ranks, &scratch.position_of, edge.from, edge.to)
        else {
            continue;
        };
        let count = normalized_offsets.get_mut(upper_node.checked_add(1)?)?;
        *count = count.checked_add(1)?;
    }
    for index in 1..direction_width {
        normalized_offsets[index] =
            normalized_offsets[index - 1].checked_add(normalized_offsets[index])?;
    }
    let packed_edge_count = usize::try_from(normalized_offsets[node_count]).ok()?;
    if packed_edge_count > edge_capacity || fenwick_storage.len() < direction_width {
        return None;
    }

    // `slot_of` is now a fill cursor; the original outgoing CSR is dead after the final sweep.
    scratch.slot_of[..node_count].copy_from_slice(&normalized_offsets[..node_count]);
    let normalized_positions = scratch.incidence_neighbors.get_mut(..edge_capacity)?;
    for edge in &ir.edges {
        let Some((upper_node, lower_position)) =
            packed_crossing_edge(ir, ranks, &scratch.position_of, edge.from, edge.to)
        else {
            continue;
        };
        let cursor = usize::try_from(*scratch.slot_of.get(upper_node)?).ok()?;
        *normalized_positions.get_mut(cursor)? = lower_position;
        scratch.slot_of[upper_node] = scratch.slot_of[upper_node].checked_add(1)?;
    }

    // Process one layer pair at a time. Query every edge of a source group before inserting that
    // group, so edges sharing a source never count as crossings (the old tuple sort's secondary key
    // provided the same property). Parallel and reversed edges retain their exact multiplicity.
    let mut total = 0_usize;
    for (upper_rank, upper_order) in ordering_by_rank {
        let Some(lower_rank) = upper_rank.checked_add(1) else {
            continue;
        };
        let Some(lower_order) = ordering_by_rank.get(&lower_rank) else {
            continue;
        };
        let fenwick_len = lower_order.len().checked_add(1)?;
        let fenwick = fenwick_storage.get_mut(..fenwick_len)?;
        fenwick.fill(0);
        let mut seen_edges = 0_usize;

        for (source_position, source) in upper_order.iter().copied().enumerate() {
            if ranks.get(&source).copied() != Some(*upper_rank)
                || scratch.position_of.get(source).copied() != u32::try_from(source_position).ok()
            {
                continue;
            }
            let start = usize::try_from(*normalized_offsets.get(source)?).ok()?;
            let end = usize::try_from(*normalized_offsets.get(source.checked_add(1)?)?).ok()?;
            let targets = normalized_positions.get(start..end)?;

            for target_position in targets.iter().copied() {
                let target_position = usize::try_from(target_position).ok()?;
                if target_position >= lower_order.len() {
                    return None;
                }
                let at_or_before = packed_fenwick_prefix(fenwick, target_position + 1);
                total = total.saturating_add(seen_edges.saturating_sub(at_or_before));
            }
            for target_position in targets.iter().copied() {
                let target_position = usize::try_from(target_position).ok()?;
                packed_fenwick_add(fenwick, target_position + 1);
                seen_edges = seen_edges.saturating_add(1);
            }
        }
    }

    Some(total)
}

fn total_crossings(
    ir: &MermaidDiagramIr,
    ranks: &BTreeMap<usize, usize>,
    ordering_by_rank: &BTreeMap<usize, Vec<usize>>,
) -> usize {
    let mut positions_by_rank: BTreeMap<usize, BTreeMap<usize, usize>> = BTreeMap::new();
    for (rank, ordered_nodes) in ordering_by_rank {
        positions_by_rank.insert(
            *rank,
            ordered_nodes
                .iter()
                .enumerate()
                .map(|(position, node)| (*node, position))
                .collect(),
        );
    }

    let mut edges_by_layer_pair: BTreeMap<(usize, usize), Vec<(usize, usize)>> = BTreeMap::new();
    for edge in &ir.edges {
        let Some(mut source) = endpoint_node_index(ir, edge.from) else {
            continue;
        };
        let Some(mut target) = endpoint_node_index(ir, edge.to) else {
            continue;
        };
        let Some(mut source_rank) = ranks.get(&source).copied() else {
            continue;
        };
        let Some(mut target_rank) = ranks.get(&target).copied() else {
            continue;
        };

        if source_rank == target_rank {
            continue;
        }
        if source_rank > target_rank {
            std::mem::swap(&mut source, &mut target);
            std::mem::swap(&mut source_rank, &mut target_rank);
        }
        if target_rank != source_rank.saturating_add(1) {
            continue;
        }

        let Some(source_position) = positions_by_rank
            .get(&source_rank)
            .and_then(|positions| positions.get(&source))
            .copied()
        else {
            continue;
        };
        let Some(target_position) = positions_by_rank
            .get(&target_rank)
            .and_then(|positions| positions.get(&target))
            .copied()
        else {
            continue;
        };

        edges_by_layer_pair
            .entry((source_rank, target_rank))
            .or_default()
            .push((source_position, target_position));
    }

    let mut total_crossings = 0_usize;
    for (_layer_pair, mut edge_positions) in edges_by_layer_pair {
        edge_positions
            .sort_by(|left, right| left.0.cmp(&right.0).then_with(|| left.1.cmp(&right.1)));
        let mut target_positions: Vec<usize> = edge_positions
            .into_iter()
            .map(|(_source_position, target_position)| target_position)
            .collect();
        total_crossings = total_crossings.saturating_add(count_inversions(&mut target_positions));
    }

    total_crossings
}

fn count_inversions(values: &mut [usize]) -> usize {
    if values.len() <= 1 {
        return 0;
    }

    let mid = values.len() / 2;
    let mut inversions = 0_usize;
    inversions = inversions.saturating_add(count_inversions(&mut values[..mid]));
    inversions = inversions.saturating_add(count_inversions(&mut values[mid..]));

    let mut merged = Vec::with_capacity(values.len());
    let (left, right) = values.split_at(mid);
    let mut left_idx = 0_usize;
    let mut right_idx = 0_usize;

    while left_idx < left.len() && right_idx < right.len() {
        if left[left_idx] <= right[right_idx] {
            merged.push(left[left_idx]);
            left_idx = left_idx.saturating_add(1);
        } else {
            merged.push(right[right_idx]);
            inversions = inversions.saturating_add(left.len().saturating_sub(left_idx));
            right_idx = right_idx.saturating_add(1);
        }
    }

    merged.extend_from_slice(&left[left_idx..]);
    merged.extend_from_slice(&right[right_idx..]);
    values.copy_from_slice(&merged);
    inversions
}

fn build_edge_paths(
    ir: &MermaidDiagramIr,
    nodes: &[LayoutNodeBox],
    highlighted_edge_indexes: &BTreeSet<usize>,
    edge_routing: EdgeRouting,
) -> Vec<LayoutEdgePath> {
    let horizontal_ranks = matches!(ir.direction, GraphDirection::LR | GraphDirection::RL);
    build_edge_paths_with_orientation(
        ir,
        nodes,
        highlighted_edge_indexes,
        horizontal_ranks,
        edge_routing,
    )
}

/// Route an exact directed path without building or scanning an obstacle set.
///
/// Consecutive path nodes occupy consecutive tree depths, with no peer node in either rank. The
/// open strip between their facing anchors therefore cannot contain a third node. Running the
/// general router with an empty obstacle slice produces the same points while deleting the
/// all-nodes scan for every edge.
fn build_directed_path_edge_paths(
    ir: &MermaidDiagramIr,
    nodes: &[LayoutNodeBox],
    highlighted_edge_indexes: &BTreeSet<usize>,
    edge_routing: EdgeRouting,
) -> Option<Vec<LayoutEdgePath>> {
    if !is_directed_path(ir) {
        return None;
    }

    build_directed_path_edge_paths_unchecked(ir, nodes, highlighted_edge_indexes, edge_routing)
}

fn build_directed_path_edge_paths_unchecked(
    ir: &MermaidDiagramIr,
    nodes: &[LayoutNodeBox],
    highlighted_edge_indexes: &BTreeSet<usize>,
    edge_routing: EdgeRouting,
) -> Option<Vec<LayoutEdgePath>> {
    let horizontal_ranks = matches!(ir.direction, GraphDirection::LR | GraphDirection::RL);
    let mut paths = Vec::with_capacity(ir.edges.len());
    for (edge_index, edge) in ir.edges.iter().enumerate() {
        let source = endpoint_node_index(ir, edge.from)?;
        let target = endpoint_node_index(ir, edge.to)?;
        let (source_box, target_box) = (nodes.get(source)?, nodes.get(target)?);
        let (source_anchor, target_anchor) = edge_anchors(
            source_box,
            target_box,
            horizontal_ranks,
            node_shape_at(ir, source_box),
            node_shape_at(ir, target_box),
        );
        let points = match edge_routing {
            EdgeRouting::Orthogonal => route_edge_points_with_obstacle_index(
                source_anchor,
                target_anchor,
                horizontal_ranks,
                &[],
                None,
            ),
            EdgeRouting::Spline => route_edge_points_spline_with_obstacle_index(
                source_anchor,
                target_anchor,
                horizontal_ranks,
                &[],
                None,
            ),
        };
        paths.push(LayoutEdgePath {
            edge_index,
            span: edge.span,
            points,
            reversed: highlighted_edge_indexes.contains(&edge_index),
            is_self_loop: false,
            parallel_offset: 0.0,
            bundle_count: 1,
            bundled: false,
        });
    }
    Some(paths)
}

fn build_edge_paths_with_orientation(
    ir: &MermaidDiagramIr,
    nodes: &[LayoutNodeBox],
    highlighted_edge_indexes: &BTreeSet<usize>,
    horizontal_ranks: bool,
    edge_routing: EdgeRouting,
) -> Vec<LayoutEdgePath> {
    // Track parallel edges: count edges between same (source, target) pair. The map is
    // read by key only (never iterated for output order), so an `FxHashMap` is
    // determinism-safe and turns the O(log n) keyed inserts/lookups — 2 per edge — into
    // O(1); the common flowchart has no parallel edges, so `any_parallel` lets the hot
    // per-edge path skip the lookup entirely.
    // Detect parallel edges (two edges sharing an unordered endpoint pair) with a cheap set pass that
    // stops at the first duplicate. The per-edge `(total, index)` counts are only READ when parallels
    // exist (see the routing loop's `if any_parallel`), and the common flowchart has none — so skip
    // building the count map AND the per-edge index Vec entirely in that case (a `FxHashSet` insert is
    // cheaper than `entry().or_insert()` + `Vec::push`, and the index Vec's alloc is avoided).
    let mut seen_pairs: FxHashSet<(usize, usize)> = FxHashSet::default();
    seen_pairs.reserve(ir.edges.len());
    let mut any_parallel = false;
    for edge in &ir.edges {
        let source = endpoint_node_index(ir, edge.from).unwrap_or(usize::MAX);
        let target = endpoint_node_index(ir, edge.to).unwrap_or(usize::MAX);
        if !seen_pairs.insert((source.min(target), source.max(target))) {
            any_parallel = true;
            break;
        }
    }
    // Only when parallels exist do we need the per-edge `(pair_total, pair_idx)`. Rebuilt identically
    // to the original single-pass counts; byte-identical for the routing loop below.
    let (edge_pair_count, edge_pair_index): (FxHashMap<(usize, usize), usize>, Vec<usize>) =
        if any_parallel {
            let mut count = FxHashMap::default();
            count.reserve(ir.edges.len());
            let mut index = Vec::with_capacity(ir.edges.len());
            for edge in &ir.edges {
                let source = endpoint_node_index(ir, edge.from).unwrap_or(usize::MAX);
                let target = endpoint_node_index(ir, edge.to).unwrap_or(usize::MAX);
                let key = (source.min(target), source.max(target));
                let c = count.entry(key).or_insert(0);
                index.push(*c);
                *c += 1;
            }
            (count, index)
        } else {
            (FxHashMap::default(), Vec::new())
        };

    // Build the obstacle set (all node bounds) **once** and reuse it for every edge,
    // instead of rebuilding an all-nodes-except-endpoints `Vec` per edge (O(edges*nodes)).
    // Each edge's own two endpoints are temporarily parked far away below so the
    // router's AABB check rejects them — equivalent to excluding them, O(1) per edge.
    let mut obstacle_bounds: Vec<LayoutRect> = nodes.iter().map(|n| n.bounds).collect();
    // Index the obstacle set for either a sparse/tree-like flowchart (the original
    // `edges <= 1.5*nodes` case) **or** a *large* dense graph. The density gate alone
    // kept wide layered graphs on the per-edge linear scan, but a fresh profile shows
    // `build_edge_paths` dominating layout there (≈1 ms / 960 edges at 16x32): the
    // mid-segment nudge scans every node obstacle even though each axis-aligned segment
    // spans only a couple of grid cells, so the index's localized candidate query is a
    // large win (16x32 −42%, 12x24 −25%). For *small* dense graphs the index's build +
    // candidate-sort overhead loses to the already-cheap scan (8x16 +5%), so dense
    // indexing is floored at `DENSE_INDEX_OBSTACLES`. The index query is a conservative
    // superset of the AABB scan, so routing stays byte-identical either way.
    // The `DENSE_INDEX_OBSTACLES` floor uses OBSTACLE COUNT as the crossover proxy, but it was calibrated
    // on the wide layered family where edges ≈ obstacles. The linear scan's real cost is `edges ×
    // obstacles`, so a graph with FEW obstacles but MANY edges (a dense DAG: 200 nodes / 790 edges) pays a
    // large O(edges·obstacles) scan yet is excluded by the count-only gate. Measured: `find_obstacle_nudge_x`
    // is 19.36% of the `dense_dag_200` pipeline, all in the per-edge linear obstacle scan, because 200
    // obstacles < 256 keeps the index off even though 790×200 ≈ 158k scan tests is the SAME work the already-
    // indexed 12x24 wide graph (288×552 ≈ 159k, index −25%) pays. So add a third, WORK-based disjunct. It is
    // purely additive — it can only ENABLE the index for more graphs, never disable it, so no currently-
    // indexed case can regress — and byte-identical for the same reason the count gate is (the index query is
    // a conservative superset of the AABB scan). The floor 100k sits above the one measured LOSS (8x16:
    // 128×224 ≈ 29k, index +5%, stays excluded) and below the measured WINS (12x24/16x32 and dense_dag_200).
    let sparse_routing = ir.edges.len() <= nodes.len().saturating_mul(3) / 2;
    let linear_scan_work = ir.edges.len().saturating_mul(obstacle_bounds.len());
    let index_eligible = sparse_routing
        || obstacle_bounds.len() >= ObstacleSpatialIndex::DENSE_INDEX_OBSTACLES
        || linear_scan_work >= ObstacleSpatialIndex::DENSE_INDEX_LINEAR_WORK;
    let mut obstacle_index =
        if index_eligible && obstacle_bounds.len() >= ObstacleSpatialIndex::MIN_INDEXED_OBSTACLES {
            ObstacleSpatialIndex::new(&obstacle_bounds)
        } else {
            None
        };

    // Presize to `ir.edges.len()` (the max; `filter_map` only drops unresolved-endpoint edges) so
    // the `Vec<LayoutEdgePath>` fills without the log(N) growth reallocs a `filter_map().collect()`
    // pays — `filter_map`'s 0 lower size-hint gives `collect` no starting capacity, so it doubles and
    // memcpys the fat `LayoutEdgePath` structs repeatedly. `edges.len()` is O(1) (no scan), so this
    // is a strict win; byte-identical (same elements, same order).
    let mut edge_paths = Vec::with_capacity(ir.edges.len());
    let routed = ir
        .edges
        .iter()
        .enumerate()
        .filter_map(|(edge_index, edge)| {
            let source = endpoint_node_index(ir, edge.from)?;
            let target = endpoint_node_index(ir, edge.to)?;
            let source_box = nodes.get(source)?;
            let target_box = nodes.get(target)?;

            let is_self_loop = source == target;
            let (pair_total, pair_idx) = if any_parallel {
                let key = (source.min(target), source.max(target));
                (
                    edge_pair_count.get(&key).copied().unwrap_or(1),
                    edge_pair_index.get(edge_index).copied().unwrap_or(0),
                )
            } else {
                (1, 0)
            };
            let parallel_offset = if pair_total > 1 {
                let offset_step = 12.0_f32;
                (pair_idx as f32 - (pair_total - 1) as f32 / 2.0) * offset_step
            } else {
                0.0
            };

            let points = if is_self_loop {
                route_self_loop(source_box, horizontal_ranks)
            } else {
                let (source_anchor, target_anchor) = edge_anchors(
                    source_box,
                    target_box,
                    horizontal_ranks,
                    node_shape_at(ir, source_box),
                    node_shape_at(ir, target_box),
                );
                // Exclude this edge's own endpoints from the shared obstacle set by
                // parking them far away (the router's AABB reject drops them), then
                // restore. Far enough that no realistic segment bbox can overlap.
                const FAR_AWAY: LayoutRect = LayoutRect {
                    x: 1.0e30,
                    y: 1.0e30,
                    width: 0.0,
                    height: 0.0,
                };
                let saved_source = obstacle_bounds.get(source).copied();
                let saved_target = obstacle_bounds.get(target).copied();
                if let Some(slot) = obstacle_bounds.get_mut(source) {
                    *slot = FAR_AWAY;
                }
                if let Some(slot) = obstacle_bounds.get_mut(target) {
                    *slot = FAR_AWAY;
                }
                let mut pts = match edge_routing {
                    EdgeRouting::Orthogonal => route_edge_points_with_obstacle_index(
                        source_anchor,
                        target_anchor,
                        horizontal_ranks,
                        &obstacle_bounds,
                        obstacle_index.as_mut(),
                    ),
                    EdgeRouting::Spline => route_edge_points_spline_with_obstacle_index(
                        source_anchor,
                        target_anchor,
                        horizontal_ranks,
                        &obstacle_bounds,
                        obstacle_index.as_mut(),
                    ),
                };
                if let (Some(slot), Some(saved)) = (obstacle_bounds.get_mut(source), saved_source) {
                    *slot = saved;
                }
                if let (Some(slot), Some(saved)) = (obstacle_bounds.get_mut(target), saved_target) {
                    *slot = saved;
                }
                if parallel_offset.abs() > 0.01 {
                    apply_parallel_offset(&mut pts, parallel_offset, horizontal_ranks);
                }
                pts
            };

            Some(LayoutEdgePath {
                edge_index,
                // The closure already holds `edge` (the `enumerate` index IS its position in
                // `ir.edges`), so the old `ir.edges.get(edge_index)` re-fetched the same element behind
                // a bounds check + never-taken `map_or` default. Byte-identical: `edge.span`.
                span: edge.span,
                points,
                reversed: highlighted_edge_indexes.contains(&edge_index),
                is_self_loop,
                parallel_offset,
                bundle_count: 1,
                bundled: false,
            })
        });
    edge_paths.extend(routed);
    edge_paths
}

/// Route a self-loop edge: goes out one side and returns on another.
fn route_self_loop(node_box: &LayoutNodeBox, horizontal_ranks: bool) -> EdgePoints {
    let b = &node_box.bounds;
    let loop_size = 24.0_f32;

    if horizontal_ranks {
        // Loop goes out the right side and returns from the top.
        let start = LayoutPoint {
            x: b.x + b.width,
            y: b.height.mul_add(0.4, b.y),
        };
        let corner1 = LayoutPoint {
            x: b.x + b.width + loop_size,
            y: b.height.mul_add(0.4, b.y),
        };
        let corner2 = LayoutPoint {
            x: b.x + b.width + loop_size,
            y: b.y - loop_size,
        };
        let corner3 = LayoutPoint {
            x: b.width.mul_add(0.6, b.x),
            y: b.y - loop_size,
        };
        let end = LayoutPoint {
            x: b.width.mul_add(0.6, b.x),
            y: b.y,
        };
        smallvec![start, corner1, corner2, corner3, end]
    } else {
        // Loop goes out the bottom and returns from the right.
        let start = LayoutPoint {
            x: b.width.mul_add(0.6, b.x),
            y: b.y + b.height,
        };
        let corner1 = LayoutPoint {
            x: b.width.mul_add(0.6, b.x),
            y: b.y + b.height + loop_size,
        };
        let corner2 = LayoutPoint {
            x: b.x + b.width + loop_size,
            y: b.y + b.height + loop_size,
        };
        let corner3 = LayoutPoint {
            x: b.x + b.width + loop_size,
            y: b.height.mul_add(0.4, b.y),
        };
        let end = LayoutPoint {
            x: b.x + b.width,
            y: b.height.mul_add(0.4, b.y),
        };
        smallvec![start, corner1, corner2, corner3, end]
    }
}

/// Apply parallel offset to an edge path to distinguish parallel edges.
fn apply_parallel_offset(points: &mut [LayoutPoint], offset: f32, horizontal_ranks: bool) {
    if points.len() < 2 {
        return;
    }
    // Offset perpendicular to the main routing direction.
    for pt in points.iter_mut() {
        if horizontal_ranks {
            pt.y += offset;
        } else {
            pt.x += offset;
        }
    }
}

/// A flat CSR (compressed-sparse-row) bucket grid over node-obstacle rects. Replaces the
/// earlier `FxHashMap<(i32,i32), Vec<usize>>` grid: the build avoids one heap `Vec`
/// allocation per occupied cell plus per-insert hashing (it counts then scatters into two
/// flat `Vec`s), and the query indexes the bucket directly instead of hashing each cell.
/// Byte-identical to the hash grid: the same `cell_of` mapping fills the same cells with the
/// same obstacle indices, and `query_segment` returns the same deduped candidate set (the two
/// nudge consumers select the minimum-index intersecting obstacle, so candidate order is
/// irrelevant — see `find_{vertical,horizontal}_segment_nudge_by_indices`).
struct ObstacleSpatialIndex {
    inv_cell_size: f32,
    min_cx: i32,
    min_cy: i32,
    ncols: usize,
    nrows: usize,
    /// `offsets[i]..offsets[i+1]` is cell `i`'s slice of `flat` (CSR row pointers).
    offsets: Vec<u32>,
    /// Obstacle indices bucketed by cell.
    flat: Vec<u32>,
    seen: Vec<u32>,
    generation: u32,
    candidates: Vec<usize>,
}

impl ObstacleSpatialIndex {
    const CELL_SIZE: f32 = 128.0;
    const MIN_INDEXED_OBSTACLES: usize = 64;
    /// Obstacle-count floor above which a *dense* graph (edges > 1.5×nodes) is still
    /// indexed. Below it the per-edge linear AABB scan beats the index's build +
    /// candidate-sort overhead; above it the localized query wins decisively. The
    /// crossover sits between the 8x16 wide graph (128 obstacles, scan faster) and the
    /// 12x24 wide graph (288 obstacles, index ~25% faster).
    const DENSE_INDEX_OBSTACLES: usize = 256;
    /// Linear-scan-work floor (`edges × obstacles`) above which a *dense* graph is indexed regardless of
    /// obstacle count. Captures the graphs the count-only `DENSE_INDEX_OBSTACLES` gate misses: few obstacles
    /// but many edges (a dense DAG), whose O(edges·obstacles) linear scan is the actual cost driver. Chosen
    /// to sit above the one measured index LOSS (8x16: 128×224 ≈ 29k, index +5%) and below the measured WINS
    /// (12x24: 288×552 ≈ 159k, index −25%; and `dense_dag_200`: 200×790 ≈ 158k). Additive with the count gate,
    /// so it can only enable indexing for more graphs, never regress a currently-indexed one.
    const DENSE_INDEX_LINEAR_WORK: usize = 100_000;
    /// Cap on grid cells per obstacle. A layout so spread out that its cell bbox exceeds
    /// this is not worth a dense grid — `new` returns `None` and the caller falls back to
    /// the per-edge linear AABB scan, which is byte-identical (just slower for that rare
    /// case). Real diagrams pack obstacles tightly, so this never trips for them.
    const MAX_CELLS_PER_OBSTACLE: usize = 64;

    #[inline]
    fn cell_of(value: f32, inv: f32) -> i32 {
        (value * inv).floor() as i32
    }

    /// Inclusive `(cx0, cx1, cy0, cy1)` cell range a rect spans, or `None` if non-finite.
    #[inline]
    fn rect_cells(rect: LayoutRect, inv: f32) -> Option<(i32, i32, i32, i32)> {
        let min_x = rect.x.min(rect.x + rect.width);
        let max_x = rect.x.max(rect.x + rect.width);
        let min_y = rect.y.min(rect.y + rect.height);
        let max_y = rect.y.max(rect.y + rect.height);
        if !(min_x.is_finite() && max_x.is_finite() && min_y.is_finite() && max_y.is_finite()) {
            return None;
        }
        Some((
            Self::cell_of(min_x, inv),
            Self::cell_of(max_x, inv),
            Self::cell_of(min_y, inv),
            Self::cell_of(max_y, inv),
        ))
    }

    fn new(obstacles: &[LayoutRect]) -> Option<Self> {
        // Adaptive cell size. A fixed 128px cell makes the grid's cell count scale with the
        // layout's WORLD area, so a tall+wide spread-out layout (e.g. a large gantt: ~26k×100k px)
        // blows past `MAX_CELLS_PER_OBSTACLE` and returns `None` — disabling the index and forcing
        // the O(N) per-edge linear obstacle scan → O(N²) routing (measured: `find_obstacle_nudge_x`
        // 72% of a 2000-task gantt layout, ~O(N²) scaling). Instead, size cells so the grid holds
        // ~one obstacle per cell regardless of aspect ratio: `cell = max(128, sqrt(area / count))`.
        // DENSE layouts keep exactly 128px (the `max` floor → bit-identical to before); only
        // spread-out layouts coarsen. Coarser cells return a SUPERSET of candidates that the exact
        // CGA test filters, so the routing result is byte-identical (same property that makes the
        // linear-scan fallback byte-identical) — only far faster (index instead of full scan).
        let mut wmin_x = f32::INFINITY;
        let mut wmax_x = f32::NEG_INFINITY;
        let mut wmin_y = f32::INFINITY;
        let mut wmax_y = f32::NEG_INFINITY;
        let mut finite = 0usize;
        for rect in obstacles {
            let lo_x = rect.x.min(rect.x + rect.width);
            let hi_x = rect.x.max(rect.x + rect.width);
            let lo_y = rect.y.min(rect.y + rect.height);
            let hi_y = rect.y.max(rect.y + rect.height);
            if lo_x.is_finite() && hi_x.is_finite() && lo_y.is_finite() && hi_y.is_finite() {
                wmin_x = wmin_x.min(lo_x);
                wmax_x = wmax_x.max(hi_x);
                wmin_y = wmin_y.min(lo_y);
                wmax_y = wmax_y.max(hi_y);
                finite += 1;
            }
        }
        if finite == 0 {
            return None; // no finite obstacles -> nothing to index
        }
        let span_x = (wmax_x - wmin_x).max(1.0);
        let span_y = (wmax_y - wmin_y).max(1.0);
        let target_cells = obstacles.len().max(1) as f32;
        let cell_size = (span_x * span_y / target_cells).sqrt().max(Self::CELL_SIZE);
        let inv = 1.0 / cell_size;
        let mut min_cx = i32::MAX;
        let mut min_cy = i32::MAX;
        let mut max_cx = i32::MIN;
        let mut max_cy = i32::MIN;
        // Compute each obstacle's cell range ONCE and cache it — the bbox, count, and scatter
        // passes below all need the identical `(cx0, cx1, cy0, cy1)`, so recomputing `rect_cells`
        // (4 min/max + 4 finite checks + 4 float floor-casts) per pass was 3× the work. Byte-
        // identical: the cached tuples equal what each pass would recompute, iterated in the same
        // obstacle order.
        let mut cells: Vec<Option<(i32, i32, i32, i32)>> = Vec::with_capacity(obstacles.len());
        for rect in obstacles {
            let rc = Self::rect_cells(*rect, inv);
            if let Some((cx0, cx1, cy0, cy1)) = rc {
                min_cx = min_cx.min(cx0);
                max_cx = max_cx.max(cx1);
                min_cy = min_cy.min(cy0);
                max_cy = max_cy.max(cy1);
            }
            cells.push(rc);
        }
        if min_cx > max_cx || min_cy > max_cy {
            return None; // no finite obstacles -> nothing to index
        }
        let ncols = (i64::from(max_cx) - i64::from(min_cx) + 1) as usize;
        let nrows = (i64::from(max_cy) - i64::from(min_cy) + 1) as usize;
        let cell_count = ncols.checked_mul(nrows)?;
        if cell_count
            > obstacles
                .len()
                .saturating_mul(Self::MAX_CELLS_PER_OBSTACLE)
                .max(4096)
        {
            return None; // too spread out; the caller uses the linear scan instead
        }

        let lin =
            |cx: i32, cy: i32| -> usize { (cy - min_cy) as usize * ncols + (cx - min_cx) as usize };

        // Pass 1: count obstacles per cell into offsets[i+1]. The `cx0..=cx1`/`cy0..=cy1` cell walk
        // uses plain loops instead of `RangeInclusive` iterators — the latter's per-step
        // exhaustion tracking showed as ~2.7% self here (profiled). `rect_cells` guarantees
        // `cx0 <= cx1` & `cy0 <= cy1`, and break-before-increment avoids the `hi + 1` overflow when
        // `hi == i32::MAX` (a finite-but-huge coordinate). Byte-identical to the inclusive ranges.
        let mut offsets = vec![0u32; cell_count + 1];
        for &rc in &cells {
            if let Some((cx0, cx1, cy0, cy1)) = rc {
                let mut cx = cx0;
                loop {
                    let mut cy = cy0;
                    loop {
                        offsets[lin(cx, cy) + 1] += 1;
                        if cy == cy1 {
                            break;
                        }
                        cy += 1;
                    }
                    if cx == cx1 {
                        break;
                    }
                    cx += 1;
                }
            }
        }
        // Prefix sum: offsets[i] becomes the start of cell i's bucket.
        for i in 1..offsets.len() {
            offsets[i] += offsets[i - 1];
        }
        let mut flat = vec![0u32; offsets[cell_count] as usize];
        let mut cursor = offsets.clone();
        // Pass 2: scatter each obstacle index into its cells (same plain-loop cell walk as pass 1).
        for (idx, &rc) in cells.iter().enumerate() {
            if let Some((cx0, cx1, cy0, cy1)) = rc {
                let mut cx = cx0;
                loop {
                    let mut cy = cy0;
                    loop {
                        let ci = lin(cx, cy);
                        flat[cursor[ci] as usize] = idx as u32;
                        cursor[ci] += 1;
                        if cy == cy1 {
                            break;
                        }
                        cy += 1;
                    }
                    if cx == cx1 {
                        break;
                    }
                    cx += 1;
                }
            }
        }

        Some(Self {
            inv_cell_size: inv,
            min_cx,
            min_cy,
            ncols,
            nrows,
            offsets,
            flat,
            seen: vec![0; obstacles.len()],
            generation: 0,
            candidates: Vec::new(),
        })
    }

    fn query_segment(&mut self, segment: (LayoutPoint, LayoutPoint), margin: f32) -> &[usize] {
        self.candidates.clear();
        self.generation = self.generation.wrapping_add(1);
        if self.generation == 0 {
            self.seen.fill(0);
            self.generation = 1;
        }

        let min_x = segment.0.x.min(segment.1.x) - margin;
        let max_x = segment.0.x.max(segment.1.x) + margin;
        let min_y = segment.0.y.min(segment.1.y) - margin;
        let max_y = segment.0.y.max(segment.1.y) + margin;
        if !(min_x.is_finite() && max_x.is_finite() && min_y.is_finite() && max_y.is_finite()) {
            return &self.candidates;
        }

        // Clamp the query cell range to the grid; cells outside it hold no obstacles, exactly
        // as the hash grid's missing entries did.
        let grid_max_cx = self.min_cx + self.ncols as i32 - 1;
        let grid_max_cy = self.min_cy + self.nrows as i32 - 1;
        let qx0 = Self::cell_of(min_x, self.inv_cell_size).max(self.min_cx);
        let qx1 = Self::cell_of(max_x, self.inv_cell_size).min(grid_max_cx);
        let qy0 = Self::cell_of(min_y, self.inv_cell_size).max(self.min_cy);
        let qy1 = Self::cell_of(max_y, self.inv_cell_size).min(grid_max_cy);

        // Plain-loop cell walk over `qx0..=qx1` × `qy0..=qy1` (see `new`): avoids `RangeInclusive`'s
        // per-step overhead on this per-edge-segment query. The query range CAN be empty (a segment
        // outside the grid clamps to qx0 > qx1), so guard it; break-before-increment is overflow-safe
        // when a clamped `qx1`/`qy1` reaches `i32::MAX`. Byte-identical to the inclusive ranges.
        if qx0 <= qx1 && qy0 <= qy1 {
            // Bind the loop-invariant `self` fields to locals ONCE. `candidates.push` below takes
            // `&mut self.candidates`, which forces LLVM to conservatively RELOAD `self.flat`/`self.seen`/
            // `self.offsets` (base+len) and `self.generation` through the `self` pointer every inner
            // iteration (measured: ~8% of `query_segment` self-time in reload movs). These four fields are
            // disjoint from `candidates`, so binding shared/`&mut` slices to them keeps their base pointers
            // in registers across the push. Byte-identical: same reads/writes in the same order.
            let (min_cx, min_cy, ncols) = (self.min_cx, self.min_cy, self.ncols);
            let generation = self.generation;
            let offsets = self.offsets.as_slice();
            let flat = self.flat.as_slice();
            let seen = self.seen.as_mut_slice();
            let candidates = &mut self.candidates;
            let mut cx = qx0;
            loop {
                let mut cy = qy0;
                loop {
                    let ci = (cy - min_cy) as usize * ncols + (cx - min_cx) as usize;
                    let start = offsets[ci] as usize;
                    let end = offsets[ci + 1] as usize;
                    // Index `flat[k]` directly rather than iterating `&flat[start..end]`: cells hold ~1
                    // obstacle each, so the sub-slice's per-cell bounds check costs more than the
                    // per-element bounds check it would elide (measured +0.15% layout instrs for the
                    // slice form vs −0.52% for this one).
                    #[allow(clippy::needless_range_loop)]
                    for k in start..end {
                        let idx = flat[k] as usize;
                        if seen[idx] != generation {
                            seen[idx] = generation;
                            candidates.push(idx);
                        }
                    }
                    if cy == qy1 {
                        break;
                    }
                    cy += 1;
                }
                if cx == qx1 {
                    break;
                }
                cx += 1;
            }
        }

        // No sort: the two consumers (`find_{vertical,horizontal}_segment_nudge_by_indices`)
        // select the minimum-index intersecting obstacle directly, which is order-independent.
        // Sorting the candidate set here was ~40% of layout self-time on obstacle-dense graphs
        // (e.g. large mindmaps forced to the tree router), and every query paid O(K log K).
        &self.candidates
    }
}

/// Shape of the IR node a laid-out box came from, defaulting to a rectangle when the box has no
/// matching IR node (synthetic boxes exist for routing).
fn node_shape_at(ir: &MermaidDiagramIr, node_box: &LayoutNodeBox) -> fm_core::NodeShape {
    ir.nodes
        .get(node_box.node_index)
        .map_or(fm_core::NodeShape::Rect, |node| node.shape)
}

fn edge_anchors(
    source_box: &LayoutNodeBox,
    target_box: &LayoutNodeBox,
    horizontal_ranks: bool,
    source_shape: fm_core::NodeShape,
    target_shape: fm_core::NodeShape,
) -> (LayoutPoint, LayoutPoint) {
    let source_center = source_box.bounds.center();
    let target_center = target_box.bounds.center();

    if horizontal_ranks {
        // Slanted shapes pull away from their box between the horizontal edges, so the side
        // midpoint is not on the drawn outline. Anchoring at the box there leaves the arrowhead
        // floating beside the node — a triangle is a quarter of its own width adrift.
        let source_inset = source_box.bounds.width * source_shape.horizontal_outline_inset_ratio();
        let target_inset = target_box.bounds.width * target_shape.horizontal_outline_inset_ratio();

        let (source_x, target_x) = if target_center.x >= source_center.x {
            (
                source_box.bounds.x + source_box.bounds.width - source_inset,
                target_box.bounds.x + target_inset,
            )
        } else {
            (
                source_box.bounds.x + source_inset,
                target_box.bounds.x + target_box.bounds.width - target_inset,
            )
        };
        (
            LayoutPoint {
                x: source_x,
                y: source_center.y,
            },
            LayoutPoint {
                x: target_x,
                y: target_center.y,
            },
        )
    } else {
        let (source_y, target_y) = if target_center.y >= source_center.y {
            (
                source_box.bounds.y + source_box.bounds.height,
                target_box.bounds.y,
            )
        } else {
            (
                source_box.bounds.y,
                target_box.bounds.y + target_box.bounds.height,
            )
        };
        (
            LayoutPoint {
                x: source_center.x,
                y: source_y,
            },
            LayoutPoint {
                x: target_center.x,
                y: target_y,
            },
        )
    }
}

#[cfg(test)]
fn route_edge_points(
    source: LayoutPoint,
    target: LayoutPoint,
    horizontal_ranks: bool,
) -> EdgePoints {
    route_edge_points_with_obstacles(source, target, horizontal_ranks, &[])
}

/// Route an edge with orthogonal segments, avoiding node bounding boxes.
///
/// When `obstacles` is non-empty, the router checks if the midpoint segment
/// intersects any obstacle and reroutes around it if needed.
#[cfg(test)]
fn route_edge_points_with_obstacles(
    source: LayoutPoint,
    target: LayoutPoint,
    horizontal_ranks: bool,
    obstacles: &[LayoutRect],
) -> EdgePoints {
    route_edge_points_with_obstacle_index(source, target, horizontal_ranks, obstacles, None)
}

fn route_edge_points_with_obstacle_index(
    source: LayoutPoint,
    target: LayoutPoint,
    horizontal_ranks: bool,
    obstacles: &[LayoutRect],
    mut obstacle_index: Option<&mut ObstacleSpatialIndex>,
) -> EdgePoints {
    let epsilon = 0.001_f32;

    let points = if horizontal_ranks {
        if (source.y - target.y).abs() < epsilon {
            let segment = (
                LayoutPoint {
                    x: source.x.min(target.x),
                    y: source.y,
                },
                LayoutPoint {
                    x: source.x.max(target.x),
                    y: target.y,
                },
            );
            if let Some(nudge) =
                find_obstacle_nudge_y(segment, source.y, obstacles, obstacle_index.as_deref_mut())
            {
                smallvec![
                    source,
                    LayoutPoint {
                        x: source.x,
                        y: nudge,
                    },
                    LayoutPoint {
                        x: target.x,
                        y: nudge,
                    },
                    target,
                ]
            } else {
                smallvec![source, target]
            }
        } else {
            let mid_x = f32::midpoint(source.x, target.x);
            let mid_segment = (
                LayoutPoint {
                    x: mid_x,
                    y: source.y.min(target.y),
                },
                LayoutPoint {
                    x: mid_x,
                    y: source.y.max(target.y),
                },
            );
            // Check if the vertical mid-segment clips through any obstacle.
            if let Some(nudge) =
                find_obstacle_nudge_x(mid_segment, mid_x, obstacles, obstacle_index.as_deref_mut())
            {
                // Route around: two vertical segments flanking the obstacle.
                smallvec![
                    source,
                    LayoutPoint {
                        x: nudge,
                        y: source.y,
                    },
                    LayoutPoint {
                        x: nudge,
                        y: target.y,
                    },
                    target,
                ]
            } else {
                smallvec![
                    source,
                    LayoutPoint {
                        x: mid_x,
                        y: source.y,
                    },
                    LayoutPoint {
                        x: mid_x,
                        y: target.y,
                    },
                    target,
                ]
            }
        }
    } else if (source.x - target.x).abs() < epsilon {
        let segment = (
            LayoutPoint {
                x: source.x,
                y: source.y.min(target.y),
            },
            LayoutPoint {
                x: target.x,
                y: source.y.max(target.y),
            },
        );
        if let Some(nudge) =
            find_obstacle_nudge_x(segment, source.x, obstacles, obstacle_index.as_deref_mut())
        {
            smallvec![
                source,
                LayoutPoint {
                    x: nudge,
                    y: source.y,
                },
                LayoutPoint {
                    x: nudge,
                    y: target.y,
                },
                target,
            ]
        } else {
            smallvec![source, target]
        }
    } else {
        let mid_y = f32::midpoint(source.y, target.y);
        let mid_segment = (
            LayoutPoint {
                x: source.x.min(target.x),
                y: mid_y,
            },
            LayoutPoint {
                x: source.x.max(target.x),
                y: mid_y,
            },
        );
        if let Some(nudge) = find_obstacle_nudge_y(mid_segment, mid_y, obstacles, obstacle_index) {
            smallvec![
                source,
                LayoutPoint {
                    x: source.x,
                    y: nudge,
                },
                LayoutPoint {
                    x: target.x,
                    y: nudge,
                },
                target,
            ]
        } else {
            smallvec![
                source,
                LayoutPoint {
                    x: source.x,
                    y: mid_y,
                },
                LayoutPoint {
                    x: target.x,
                    y: mid_y,
                },
                target,
            ]
        }
    };

    simplify_polyline(points)
}

/// Route an edge using spline-friendly control points.
///
/// The SVG backend already smooths edge waypoints with Catmull-Rom interpolation,
/// so this router emits a smaller set of bend and midpoint anchors instead of the
/// hard orthogonal staircase used by the default path router.
#[allow(dead_code)]
fn route_edge_points_spline_with_obstacles(
    source: LayoutPoint,
    target: LayoutPoint,
    horizontal_ranks: bool,
    obstacles: &[LayoutRect],
) -> EdgePoints {
    route_edge_points_spline_with_obstacle_index(source, target, horizontal_ranks, obstacles, None)
}

fn route_edge_points_spline_with_obstacle_index(
    source: LayoutPoint,
    target: LayoutPoint,
    horizontal_ranks: bool,
    obstacles: &[LayoutRect],
    obstacle_index: Option<&mut ObstacleSpatialIndex>,
) -> EdgePoints {
    let orthogonal = route_edge_points_with_obstacle_index(
        source,
        target,
        horizontal_ranks,
        obstacles,
        obstacle_index,
    );
    if orthogonal.len() <= 2 {
        return orthogonal;
    }

    // Replace each right-angle corner with a short diagonal across it — a chamfer.
    //
    // The previous implementation inserted the MIDPOINT of every orthogonal segment and then called
    // `simplify_polyline`, which drops axis-aligned-collinear middles. A midpoint of an axis-aligned
    // segment is collinear with its neighbours by definition, so every inserted point was removed
    // again and this function returned its input unchanged — for EVERY input, not just some. That is
    // why requesting `EdgeRouting::Spline` produced byte-identical geometry (bd-hfaw).
    //
    // A chamfer survives because its two points sit on DIFFERENT axes, so the segment between them is
    // diagonal and nothing collinear can be simplified away. It is also visible with the renderer as
    // it stands, which emits straight `L` commands only: a true cubic Bezier would need curve
    // commands in the SVG writer and control points the IR has no room for, so this is the honest
    // reachable approximation rather than a pretend Bezier.
    let mut chamfered: EdgePoints = SmallVec::with_capacity(orthogonal.len() * 2);
    chamfered.push(source);
    for corner_index in 1..orthogonal.len() - 1 {
        let before = orthogonal[corner_index - 1];
        let corner = orthogonal[corner_index];
        let after = orthogonal[corner_index + 1];

        // A quarter of the shorter adjacent segment, so a chamfer can never overshoot into the next
        // corner and invert the path on a short leg.
        let incoming = (corner.x - before.x).abs().max((corner.y - before.y).abs());
        let outgoing = (after.x - corner.x).abs().max((after.y - corner.y).abs());
        let cut = (incoming.min(outgoing) * 0.25).max(0.0);
        if cut <= f32::EPSILON {
            chamfered.push(corner);
            continue;
        }

        // Step back along the incoming leg and forward along the outgoing one. Each leg is
        // axis-aligned, so exactly one coordinate moves per point — which is what makes the segment
        // between the two points diagonal, and therefore un-simplifiable.
        let step_back = |from: f32, to: f32| {
            if (to - from).abs() <= f32::EPSILON {
                to
            } else if to > from {
                to - cut
            } else {
                to + cut
            }
        };
        let step_forward = |from: f32, to: f32| {
            if (to - from).abs() <= f32::EPSILON {
                from
            } else if to > from {
                from + cut
            } else {
                from - cut
            }
        };
        chamfered.push(LayoutPoint {
            x: step_back(before.x, corner.x),
            y: step_back(before.y, corner.y),
        });
        chamfered.push(LayoutPoint {
            x: step_forward(corner.x, after.x),
            y: step_forward(corner.y, after.y),
        });
    }
    chamfered.push(target);
    simplify_polyline(chamfered)
}

/// Check if a vertical segment at x-coordinate `mid_x` intersects any obstacle.
/// Returns a nudged x-coordinate that avoids the obstacle, or None if clear.
///
/// Uses CGA-based intersection queries for precise segment-rectangle detection.
fn find_obstacle_nudge_x(
    segment: (LayoutPoint, LayoutPoint),
    _mid_x: f32,
    obstacles: &[LayoutRect],
    obstacle_index: Option<&mut ObstacleSpatialIndex>,
) -> Option<f32> {
    const MARGIN: f32 = 8.0;
    if let Some(index) = obstacle_index {
        let candidates = index.query_segment(segment, MARGIN);
        cga_routing::find_vertical_segment_nudge_by_indices(
            segment.0, segment.1, obstacles, candidates, MARGIN,
        )
    } else {
        cga_routing::find_vertical_segment_nudge(segment.0, segment.1, obstacles, MARGIN)
    }
}

/// Check if a horizontal segment at y-coordinate `mid_y` intersects any obstacle.
/// Returns a nudged y-coordinate that avoids the obstacle, or None if clear.
///
/// Uses CGA-based intersection queries for precise segment-rectangle detection.
fn find_obstacle_nudge_y(
    segment: (LayoutPoint, LayoutPoint),
    _mid_y: f32,
    obstacles: &[LayoutRect],
    obstacle_index: Option<&mut ObstacleSpatialIndex>,
) -> Option<f32> {
    const MARGIN: f32 = 8.0;
    if let Some(index) = obstacle_index {
        let candidates = index.query_segment(segment, MARGIN);
        cga_routing::find_horizontal_segment_nudge_by_indices(
            segment.0, segment.1, obstacles, candidates, MARGIN,
        )
    } else {
        cga_routing::find_horizontal_segment_nudge(segment.0, segment.1, obstacles, MARGIN)
    }
}

fn simplify_polyline(mut points: EdgePoints) -> EdgePoints {
    if points.len() <= 2 {
        return points;
    }

    // Compact in place with a write cursor `w` instead of allocating a second `Vec` — every multi-point
    // edge previously paid an extra heap allocation for the simplified copy (the routed input was then
    // dropped). `LayoutPoint` is `Copy`, and `w <= r` always, so reading `points[r]` after writing the
    // compacted prefix `points[..w]` never aliases. Byte-identical to the push-into-new-Vec version:
    // same consecutive-duplicate skip and same axis-aligned-collinear middle removal, in the same order.
    let mut w = 0usize;
    for r in 0..points.len() {
        let point = points[r];
        if w > 0 && points[w - 1] == point {
            continue;
        }
        points[w] = point;
        w += 1;

        while w >= 3 {
            let c = points[w - 1];
            let b = points[w - 2];
            let a = points[w - 3];
            if is_axis_aligned_collinear(a, b, c) {
                // Drop the middle point `b`: overwrite its slot with `c` and shrink the prefix.
                points[w - 2] = c;
                w -= 1;
            } else {
                break;
            }
        }
    }

    points.truncate(w);
    points
}

fn is_axis_aligned_collinear(a: LayoutPoint, b: LayoutPoint, c: LayoutPoint) -> bool {
    let epsilon = 0.001_f32;
    ((a.x - b.x).abs() < epsilon && (b.x - c.x).abs() < epsilon)
        || ((a.y - b.y).abs() < epsilon && (b.y - c.y).abs() < epsilon)
}

/// Make a composite state's node BE its container.
///
/// A `state Processing { … }` block creates a cluster, and every `Idle --> Processing` transition
/// separately interns `Processing` as an ordinary node. The same declared state was therefore drawn
/// TWICE: a container holding `Validating`/`Computing`/`Formatting`, and a plain labelled box
/// elsewhere that absorbed ALL the transitions. A reader tracing `Idle --start--> Processing`
/// arrived at an empty rectangle, and the container that actually holds the contents had no incoming
/// transition at all (bd-9w54).
///
/// Giving the node its cluster's bounds fixes both halves at once: edge routing already targets node
/// boxes, so transitions now attach to the container's boundary, and the renderer skips drawing a
/// node that has become its own cluster — the cluster already draws that box and its title.
///
/// Matched on cluster TITLE == node id, which is exactly what `begin_state_cluster` writes
/// (`title.or(Some(name))`), and restricted to state diagrams so a flowchart `subgraph` that happens
/// to share a node's name is left alone.
fn anchor_composite_state_nodes(
    ir: &MermaidDiagramIr,
    nodes: &mut [LayoutNodeBox],
    clusters: &[LayoutClusterBox],
) {
    if !matches!(ir.diagram_type, DiagramType::State) {
        return;
    }
    for cluster in clusters {
        let Some(title) = cluster.title.as_deref() else {
            continue;
        };
        for node in nodes.iter_mut() {
            if node.node_id == title {
                node.bounds = cluster.bounds;
            }
        }
    }
}

/// Gap between a state's box and the note that annotates it — the span the dashed leader crosses.
const STATE_NOTE_GAP: f32 = 32.0;
/// Horizontal padding inside a state note box, per side.
const STATE_NOTE_PAD_X: f32 = 10.0;
/// Vertical padding inside a state note box, per side.
const STATE_NOTE_PAD_Y: f32 = 8.0;
/// Vertical gap between two notes stacked on the same side of the same state.
const STATE_NOTE_STACK_GAP: f32 = 8.0;
/// The renderer draws note text at `config.font_size * 0.8`, matching sequence notes, so the layout
/// estimate is scaled by the same factor — `metrics` measures at its own base size.
const STATE_NOTE_FONT_SCALE: f32 = 0.8;

/// Place a box beside each `note left/right of X` in a state diagram.
///
/// Notes are the only state-diagram content with no node of its own, so nothing in the Sugiyama
/// pipeline reserves room for them. They are positioned here, from the final node boxes, and the
/// canvas is grown afterwards by [`extend_bounds_for_state_notes`].
///
/// A note whose `target` matches no node is DROPPED rather than defaulted to some node: silently
/// attaching `note right of Typo` to whichever state happened to be first would be a worse failure
/// than not drawing it, because it invents a claim the source never made.
///
/// Several notes on the same side of the same state stack downward instead of coinciding.
fn build_state_note_geometry(
    ir: &MermaidDiagramIr,
    nodes: &[LayoutNodeBox],
    metrics: &fm_core::FontMetrics,
) -> Vec<LayoutStateNote> {
    // Class diagrams share this channel since bd-1fw3: `note for Duck "can swim"` is the same
    // shape as `note right of X : text` once parsed — a target name, a side and some text — so it
    // gets the same placement and the same renderer loop rather than a parallel implementation.
    // Every OTHER diagram type still returns empty here, which is what keeps flowchart, sequence
    // and the rest byte-identical.
    if !matches!(ir.diagram_type, DiagramType::State | DiagramType::Class)
        || ir.state_notes.is_empty()
    {
        return Vec::new();
    }

    let mut placed: Vec<LayoutStateNote> = Vec::with_capacity(ir.state_notes.len());
    for note in &ir.state_notes {
        let Some(target) = nodes.iter().find(|node| node.node_id == note.target) else {
            continue;
        };
        let side = if note.position.eq_ignore_ascii_case("left") {
            StateNoteSide::Left
        } else {
            StateNoteSide::Right
        };

        let (text_width, text_height) = metrics.estimate_dimensions(&note.text);
        let width = STATE_NOTE_FONT_SCALE.mul_add(text_width, 2.0 * STATE_NOTE_PAD_X);
        let height = STATE_NOTE_FONT_SCALE.mul_add(text_height, 2.0 * STATE_NOTE_PAD_Y);

        // Start beside the target, then clear any OTHER state box the note's own row runs into.
        // Without this a note on a state that shares its rank with a neighbour is drawn on top of
        // that neighbour, which trades one invisible note for two unreadable boxes.
        let row_top = target.bounds.center().y - height / 2.0;
        let row_bottom = row_top + height;
        let row_neighbours = nodes.iter().filter(|other| {
            other.node_index != target.node_index
                && other.bounds.y < row_bottom
                && other.bounds.y + other.bounds.height > row_top
        });
        // Folded as a single max/min over the whole row rather than nudged per neighbour: a
        // one-pass nudge in node order is not a fixpoint, so a node visited before the push could
        // still be overlapped afterwards.
        let x = match side {
            StateNoteSide::Right => {
                let clear_of = row_neighbours
                    .fold(target.bounds.x + target.bounds.width, |acc, other| {
                        acc.max(other.bounds.x + other.bounds.width)
                    });
                clear_of + STATE_NOTE_GAP
            }
            StateNoteSide::Left => {
                let clear_of =
                    row_neighbours.fold(target.bounds.x, |acc, other| acc.min(other.bounds.x));
                clear_of - STATE_NOTE_GAP - width
            }
        };
        // Stack below any note already placed on this same side of this same state.
        let mut y = target.bounds.center().y - height / 2.0;
        for earlier in &placed {
            if earlier.node_index == target.node_index && earlier.side == side {
                y = y.max(earlier.bounds.y + earlier.bounds.height + STATE_NOTE_STACK_GAP);
            }
        }

        let leader_y = target.bounds.center().y;
        let (leader_start_x, leader_end_x) = match side {
            StateNoteSide::Right => (target.bounds.x + target.bounds.width, x),
            StateNoteSide::Left => (target.bounds.x, x + width),
        };

        placed.push(LayoutStateNote {
            node_index: target.node_index,
            side,
            text: note.text.clone(),
            bounds: LayoutRect {
                x,
                y,
                width,
                height,
            },
            leader_start: LayoutPoint {
                x: leader_start_x,
                y: leader_y,
            },
            leader_end: LayoutPoint {
                x: leader_end_x,
                y: leader_y,
            },
        });
    }
    placed
}

/// Grow the canvas to hold the state notes [`build_state_note_geometry`] placed outside it.
///
/// Same requirement `extend_bounds_for_gantt_labels` exists for: a note sits beyond every node box
/// `compute_bounds` measured, so without this it is drawn past the viewBox edge and clipped —
/// exactly the failure bd-zwh3 documents for sequence fragment frames.
fn extend_bounds_for_state_notes(layout: &mut DiagramLayout) {
    if layout.extensions.state_notes.is_empty() {
        return;
    }
    let mut min_x = layout.bounds.x;
    let mut min_y = layout.bounds.y;
    let mut max_x = layout.bounds.x + layout.bounds.width;
    let mut max_y = layout.bounds.y + layout.bounds.height;
    for note in &layout.extensions.state_notes {
        min_x = min_x.min(note.bounds.x);
        min_y = min_y.min(note.bounds.y);
        max_x = max_x.max(note.bounds.x + note.bounds.width);
        max_y = max_y.max(note.bounds.y + note.bounds.height);
    }
    layout.bounds.x = min_x;
    layout.bounds.y = min_y;
    layout.bounds.width = max_x - min_x;
    layout.bounds.height = max_y - min_y;
}

fn build_cluster_boxes(
    ir: &MermaidDiagramIr,
    nodes: &[LayoutNodeBox],
    spacing: LayoutSpacing,
    metrics: &fm_core::FontMetrics,
) -> Vec<LayoutClusterBox> {
    if ir.clusters.is_empty() {
        return Vec::new();
    }

    // Step 1: Compute initial raw bounds for each cluster from its direct/all members.
    let mut cluster_bounds: Vec<Option<(f32, f32, f32, f32)>> =
        Vec::with_capacity(ir.clusters.len());
    for cluster in &ir.clusters {
        let mut min_x = f32::INFINITY;
        let mut min_y = f32::INFINITY;
        let mut max_x = f32::NEG_INFINITY;
        let mut max_y = f32::NEG_INFINITY;

        for member in &cluster.members {
            if let Some(node_box) = nodes.iter().find(|n| n.node_index == member.0) {
                min_x = min_x.min(node_box.bounds.x);
                min_y = min_y.min(node_box.bounds.y);
                max_x = max_x.max(node_box.bounds.x + node_box.bounds.width);
                max_y = max_y.max(node_box.bounds.y + node_box.bounds.height);
            }
        }

        if min_x.is_finite() && min_y.is_finite() && max_x.is_finite() && max_y.is_finite() {
            cluster_bounds.push(Some((min_x, min_y, max_x, max_y)));
        } else {
            cluster_bounds.push(None);
        }
    }

    // Step 2: Map cluster_index -> subgraph
    let mut cluster_to_subgraph: Vec<Option<fm_core::IrSubgraphId>> = vec![None; ir.clusters.len()];
    for sg in &ir.graph.subgraphs {
        if let Some(c_id) = sg.cluster
            && c_id.0 < cluster_to_subgraph.len()
        {
            cluster_to_subgraph[c_id.0] = Some(sg.id);
        }
    }

    // Compute nesting depth for each cluster
    let mut depths: Vec<(usize, usize)> = (0..ir.clusters.len())
        .map(|idx| {
            let depth = cluster_to_subgraph[idx]
                .map(|sg_id| subgraph_depth(ir, sg_id))
                .unwrap_or(0);
            (depth, idx)
        })
        .collect();

    // Sort by depth descending (deepest / innermost children first)
    depths.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));

    const HEADER_CLEARANCE: f32 = 28.0;
    const NESTING_INSET: f32 = 16.0;

    let mut final_boxes: Vec<Option<LayoutClusterBox>> = vec![None; ir.clusters.len()];

    for &(_depth, cluster_index) in &depths {
        let Some(cluster) = ir.clusters.get(cluster_index) else {
            continue;
        };
        let Some((mut min_x, mut min_y, mut max_x, mut max_y)) = cluster_bounds[cluster_index]
        else {
            continue;
        };

        // If this cluster has children subgraphs, expand its bounds to enclose all child cluster boxes
        if let Some(sg_id) = cluster_to_subgraph[cluster_index]
            && let Some(sg) = ir.graph.subgraph(sg_id)
        {
            for &child_sg_id in &sg.children {
                if let Some(child_sg) = ir.graph.subgraph(child_sg_id)
                    && let Some(child_c_id) = child_sg.cluster
                    && let Some(Some(child_box)) = final_boxes.get(child_c_id.0)
                {
                    min_x = min_x.min(child_box.bounds.x - NESTING_INSET + spacing.cluster_padding);
                    max_x = max_x.max(
                        child_box.bounds.x + child_box.bounds.width + NESTING_INSET
                            - spacing.cluster_padding,
                    );
                    min_y = min_y.min(
                        child_box.bounds.y - HEADER_CLEARANCE - NESTING_INSET
                            + spacing.cluster_padding,
                    );
                    max_y = max_y.max(
                        child_box.bounds.y + child_box.bounds.height + NESTING_INSET
                            - spacing.cluster_padding,
                    );
                }
            }
        }

        let title = cluster
            .title
            .and_then(|label_id| ir.labels.get(label_id.0))
            .map(|label| label.text.clone());

        let contents_width = 2.0f32.mul_add(spacing.cluster_padding, max_x - min_x);
        let title_width = title
            .as_deref()
            .map_or(0.0, |text| cluster_title_width(text, metrics));

        let box_obj = LayoutClusterBox {
            cluster_index,
            span: cluster.span,
            title,
            color: None,
            bounds: LayoutRect {
                x: min_x - spacing.cluster_padding,
                y: min_y - spacing.cluster_padding,
                width: contents_width.max(title_width),
                height: 2.0f32.mul_add(spacing.cluster_padding, max_y - min_y),
            },
        };
        final_boxes[cluster_index] = Some(box_obj);
    }

    final_boxes.into_iter().flatten().collect()
}

/// Width a cluster box needs so its title fits inside it (bd-tm5p).
///
/// Mirrors `fm-render-svg`'s cluster-label geometry: the text starts at `bounds.x + 8.0`, so the same
/// 8px is mirrored on the right. The label renders at `detail.cluster_font_size`, which is
/// `config.font_size * 0.9` at full detail and `* 0.86` at reduced detail — NOT the node font size —
/// so the estimate is scaled to the larger of those, because under-sizing is what lets the title
/// escape while over-sizing only adds padding.
fn cluster_title_width(title: &str, metrics: &fm_core::FontMetrics) -> f32 {
    if title.trim().is_empty() {
        return 0.0;
    }
    // Swimlane/section clusters render with their prefix stripped, so measure the displayed text.
    let displayed = title
        .strip_prefix("swimlane:")
        .or_else(|| title.strip_prefix("section "))
        .unwrap_or(title);
    let text_width = metrics.estimate_dimensions(displayed).0 * CLUSTER_FONT_SCALE;
    16.0 + text_width
}

/// The larger of the renderer's two `cluster_font_size` factors (`0.9` full detail, `0.86` reduced).
/// Sizing to the larger one is the direction that over-sizes rather than lets the title spill.
const CLUSTER_FONT_SCALE: f32 = 0.9;

fn build_state_cluster_dividers(
    ir: &MermaidDiagramIr,
    nodes: &[LayoutNodeBox],
    clusters: &[LayoutClusterBox],
) -> Vec<LayoutClusterDivider> {
    const STATE_REGION_PREFIX: &str = "__state_region_";

    ir.graph
        .subgraphs
        .iter()
        .filter_map(|subgraph| {
            if subgraph.grid_span <= 1 {
                return None;
            }

            let cluster_index = subgraph.cluster?.0;
            let cluster_bounds = clusters
                .iter()
                .find(|cluster| cluster.cluster_index == cluster_index)
                .map(|cluster| cluster.bounds)?;

            let mut region_vertical_extents = subgraph
                .children
                .iter()
                .filter_map(|child_id| ir.graph.subgraph(*child_id))
                .filter(|child| child.key.starts_with(STATE_REGION_PREFIX))
                .filter_map(|child| {
                    let mut min_y = f32::INFINITY;
                    let mut max_y = f32::NEG_INFINITY;

                    for member in ir.graph.subgraph_members_recursive(child.id) {
                        let Some(node_box) = nodes.get(member.0) else {
                            continue;
                        };
                        min_y = min_y.min(node_box.bounds.y);
                        max_y = max_y.max(node_box.bounds.y + node_box.bounds.height);
                    }

                    (min_y.is_finite() && max_y.is_finite()).then_some((min_y, max_y))
                })
                .collect::<Vec<_>>();

            if region_vertical_extents.len() < 2 {
                return None;
            }

            region_vertical_extents.sort_by(|left, right| {
                left.0
                    .total_cmp(&right.0)
                    .then_with(|| left.1.total_cmp(&right.1))
            });

            Some(
                region_vertical_extents
                    .windows(2)
                    .map(|pair| {
                        let divider_y = (pair[0].1 + pair[1].0) * 0.5;
                        LayoutClusterDivider {
                            cluster_index,
                            start: LayoutPoint {
                                x: cluster_bounds.x + 12.0,
                                y: divider_y,
                            },
                            end: LayoutPoint {
                                x: cluster_bounds.x + cluster_bounds.width - 12.0,
                                y: divider_y,
                            },
                        }
                    })
                    .collect::<Vec<_>>(),
            )
        })
        .flatten()
        .collect()
}

fn compute_bounds(
    nodes: &[LayoutNodeBox],
    clusters: &[LayoutClusterBox],
    edges: &[LayoutEdgePath],
    spacing: LayoutSpacing,
) -> LayoutRect {
    let mut min_x = f32::INFINITY;
    let mut min_y = f32::INFINITY;
    let mut max_x = f32::NEG_INFINITY;
    let mut max_y = f32::NEG_INFINITY;

    for node in nodes {
        min_x = min_x.min(node.bounds.x);
        min_y = min_y.min(node.bounds.y);
        max_x = max_x.max(node.bounds.x + node.bounds.width);
        max_y = max_y.max(node.bounds.y + node.bounds.height);
    }

    for cluster in clusters {
        min_x = min_x.min(cluster.bounds.x);
        min_y = min_y.min(cluster.bounds.y);
        max_x = max_x.max(cluster.bounds.x + cluster.bounds.width);
        max_y = max_y.max(cluster.bounds.y + cluster.bounds.height);
    }

    for edge in edges {
        for point in &edge.points {
            min_x = min_x.min(point.x);
            min_y = min_y.min(point.y);
            max_x = max_x.max(point.x);
            max_y = max_y.max(point.y);
        }
    }

    if !min_x.is_finite() || !min_y.is_finite() || !max_x.is_finite() || !max_y.is_finite() {
        return LayoutRect {
            x: 0.0,
            y: 0.0,
            width: 0.0,
            height: 0.0,
        };
    }

    LayoutRect {
        x: min_x - spacing.cluster_padding,
        y: min_y - spacing.cluster_padding,
        width: 2.0f32.mul_add(spacing.cluster_padding, max_x - min_x),
        height: 2.0f32.mul_add(spacing.cluster_padding, max_y - min_y),
    }
}

/// Bundle parallel edges that share the same (source, target) node pair and arrow type.
/// Edges with ≥ `min_bundle` duplicates are collapsed: the first edge becomes the
/// representative with `bundle_count` set to the group size, and the remaining edges
/// are marked `bundled = true` so renderers can skip them.
fn bundle_parallel_edges(ir: &MermaidDiagramIr, edges: &mut [LayoutEdgePath]) {
    let min_bundle = 2_usize;

    // Group edge indices by (source_node, target_node, arrow_type).
    let mut groups: BTreeMap<(usize, usize, &str), Vec<usize>> = BTreeMap::new();

    for (path_idx, path) in edges.iter().enumerate() {
        if path.is_self_loop || path.bundled {
            continue;
        }
        let Some(edge) = ir.edges.get(path.edge_index) else {
            continue;
        };
        // ⚠️ A LABELLED EDGE IS NEVER BUNDLED, because bundling DELETES it. The representative keeps
        // its own label and gains a `×N` marker; every other edge in the group is marked `bundled`
        // and never rendered, so its label — text the author wrote — is gone from the document.
        //
        // Measured on `c4_dynamic`: `Rel(signin, store, "select * from users where username = ?")`
        // and `Rel_Back(store, signin, "Returns the stored hash")` both resolve to signin→store with
        // an Arrow, so the second collapsed into the first and "Returns the stored hash" appeared
        // NOWHERE. The reader saw `×2` in its place. mermaid draws both relationships with both
        // labels; found by `scripts/headtohead/chromium_text_diff.mjs`.
        //
        // Bundling stays for the case it was built for — several IDENTICAL unlabelled connections
        // between the same pair, where collapsing them declutters and discards nothing. The moment
        // any edge in the group carries a label, the group is not redundant and must not be merged.
        if edge.label.is_some() {
            continue;
        }
        let Some(source) = endpoint_node_index(ir, edge.from) else {
            continue;
        };
        let Some(target) = endpoint_node_index(ir, edge.to) else {
            continue;
        };
        let key = (source, target, edge.arrow.as_str());
        groups.entry(key).or_default().push(path_idx);
    }

    for indices in groups.values() {
        if indices.len() < min_bundle {
            continue;
        }
        // First edge becomes the bundle representative.
        let representative = indices[0];
        edges[representative].bundle_count = indices.len();

        // Mark remaining edges as absorbed into the bundle.
        for &idx in &indices[1..] {
            edges[idx].bundled = true;
        }
    }
}

fn compute_edge_length_metrics(edges: &[LayoutEdgePath]) -> (f32, f32) {
    let mut total = 0.0_f32;
    let mut reversed_total = 0.0_f32;

    for edge in edges {
        let length = polyline_length(&edge.points);
        total += length;
        if edge.reversed {
            reversed_total += length;
        }
    }

    (total, reversed_total)
}

fn polyline_length(points: &[LayoutPoint]) -> f32 {
    points
        .windows(2)
        .map(|pair| {
            let dx = pair[1].x - pair[0].x;
            let dy = pair[1].y - pair[0].y;
            // `hypot(x, 0) == |x|` and `hypot(0, y) == |y|` exactly (IEEE-754), so axis-aligned
            // segments skip the expensive libm `hypotf` and return a byte-identical result. Every
            // sequence-diagram segment is axis-aligned (horizontal messages + rectangular
            // self-loops), and orthogonal routing makes most segments of other diagrams axis-aligned
            // too; genuinely diagonal segments still fall through to `hypot`.
            if dy == 0.0 {
                dx.abs()
            } else if dx == 0.0 {
                dy.abs()
            } else {
                dx.hypot(dy)
            }
        })
        .sum()
}

fn build_cycle_cluster_map(
    ir: &MermaidDiagramIr,
    cycle_result: &CycleRemovalResult,
    node_priority: &[usize],
) -> CycleClusterMap {
    let node_count = ir.nodes.len();
    let edges = resolved_edges(ir);
    let detection = detect_cycle_components(node_count, &edges, node_priority);

    let mut node_representative = (0..node_count).collect::<Vec<_>>();
    let mut cluster_heads = BTreeSet::new();
    let mut cluster_members = BTreeMap::new();

    for component_index in &detection.cyclic_component_indexes {
        let Some(component_nodes) = detection.components.get(*component_index) else {
            continue;
        };
        if component_nodes.len() <= 1 {
            // Skip self-loops for cluster collapse — they're single nodes.
            continue;
        }

        // Choose the lowest-priority node as the representative (cluster head).
        let head = *component_nodes
            .iter()
            .min_by(|a, b| compare_priority(**a, **b, node_priority))
            .unwrap_or(&component_nodes[0]);

        cluster_heads.insert(head);
        let mut members = component_nodes.clone();
        members.sort_by(|a, b| compare_priority(*a, *b, node_priority));
        for &member in &members {
            node_representative[member] = head;
        }
        cluster_members.insert(head, members);
    }

    let _ = cycle_result; // Used for type coherence; detection is recomputed for isolation.

    CycleClusterMap {
        node_representative,
        cluster_heads,
        cluster_members,
    }
}

fn build_cycle_cluster_results(
    collapse_map: &CycleClusterMap,
    nodes: &mut [LayoutNodeBox],
    clusters: &mut Vec<LayoutClusterBox>,
    spacing: LayoutSpacing,
) -> Vec<LayoutCycleCluster> {
    let mut cycle_clusters = Vec::new();

    for (head, members) in &collapse_map.cluster_members {
        if members.len() <= 1 {
            continue;
        }

        // Find the head node's bounding box (copy values to satisfy borrow checker).
        let Some(head_box) = nodes.iter().find(|n| n.node_index == *head) else {
            continue;
        };
        let base_x = head_box.bounds.x;
        let base_y = head_box.bounds.y;
        let head_height = head_box.bounds.height;

        // Arrange member nodes (excluding head) in a compact grid within the cluster bounds.
        let non_head_members: Vec<usize> = members.iter().copied().filter(|m| m != head).collect();
        let member_count = non_head_members.len();
        let cols = ((member_count as f32).sqrt().ceil() as usize).max(1);

        let sub_spacing = spacing.node_spacing * 0.5;
        for (idx, &member_index) in non_head_members.iter().enumerate() {
            let col = idx % cols;
            let row = idx / cols;
            if let Some(member_box) = nodes.iter_mut().find(|n| n.node_index == member_index) {
                member_box.bounds.x =
                    (col as f32).mul_add(member_box.bounds.width + sub_spacing, base_x);
                member_box.bounds.y = (row as f32).mul_add(
                    member_box.bounds.height + sub_spacing,
                    base_y + head_height + spacing.cluster_padding,
                );
            }
        }

        // Compute the cluster bounding box over all members.
        let mut min_x = f32::INFINITY;
        let mut min_y = f32::INFINITY;
        let mut max_x = f32::NEG_INFINITY;
        let mut max_y = f32::NEG_INFINITY;
        for &member_index in members {
            if let Some(member_box) = nodes.iter().find(|n| n.node_index == member_index) {
                min_x = min_x.min(member_box.bounds.x);
                min_y = min_y.min(member_box.bounds.y);
                max_x = max_x.max(member_box.bounds.x + member_box.bounds.width);
                max_y = max_y.max(member_box.bounds.y + member_box.bounds.height);
            }
        }

        if min_x.is_finite() && min_y.is_finite() && max_x.is_finite() && max_y.is_finite() {
            let cluster_bounds = LayoutRect {
                x: min_x - spacing.cluster_padding,
                y: min_y - spacing.cluster_padding,
                width: 2.0f32.mul_add(spacing.cluster_padding, max_x - min_x),
                height: 2.0f32.mul_add(spacing.cluster_padding, max_y - min_y),
            };

            cycle_clusters.push(LayoutCycleCluster {
                head_node_index: *head,
                member_node_indexes: members.clone(),
                bounds: cluster_bounds,
            });

            // Also add as a regular cluster box for rendering consistency.
            clusters.push(LayoutClusterBox {
                cluster_index: clusters.len(),
                span: Span::default(),
                title: None,
                color: None,
                bounds: cluster_bounds,
            });
        }
    }

    cycle_clusters
}

fn endpoint_node_index(ir: &MermaidDiagramIr, endpoint: IrEndpoint) -> Option<usize> {
    match endpoint {
        IrEndpoint::Node(node) => {
            if node.0 < ir.nodes.len() {
                Some(node.0)
            } else {
                None
            }
        }
        IrEndpoint::Port(port) => {
            let node_idx = ir.ports.get(port.0).map(|port_ref| port_ref.node.0)?;
            if node_idx < ir.nodes.len() {
                Some(node_idx)
            } else {
                None
            }
        }
        IrEndpoint::Unresolved => None,
    }
}

fn push_snapshot(
    trace: &mut LayoutTrace,
    stage: &'static str,
    node_count: usize,
    edge_count: usize,
    reversed_edges: usize,
    crossing_count: usize,
) {
    trace.snapshots.push(LayoutStageSnapshot {
        stage,
        reversed_edges,
        crossing_count,
        node_count,
        edge_count,
    });
}

#[must_use]
pub const fn layout_stats_from(layout: &DiagramLayout) -> LayoutStats {
    layout.stats
}

#[must_use]
pub fn build_layout_guard_report(
    ir: &MermaidDiagramIr,
    traced: &TracedLayout,
) -> MermaidGuardReport {
    build_layout_guard_report_with_pressure(
        ir,
        traced,
        fm_core::MermaidNativePressureSignals::default().into_report(),
    )
}

#[must_use]
pub fn build_layout_guard_report_with_pressure(
    ir: &MermaidDiagramIr,
    traced: &TracedLayout,
    pressure: MermaidPressureReport,
) -> MermaidGuardReport {
    let complexity = MermaidComplexity {
        nodes: ir.nodes.len(),
        edges: ir.edges.len(),
        labels: ir.labels.len(),
        clusters: ir.clusters.len(),
        ports: ir.ports.len(),
        style_refs: ir.nodes.iter().map(|node| node.classes.len()).sum(),
        score: ir
            .nodes
            .len()
            .saturating_mul(4)
            .saturating_add(ir.edges.len().saturating_mul(3))
            .saturating_add(ir.labels.len().saturating_mul(2))
            .saturating_add(ir.clusters.len().saturating_mul(5))
            .saturating_add(ir.ports.len()),
    };

    let max_nodes = MermaidConfig::default().max_nodes;
    let max_edges = MermaidConfig::default().max_edges;
    let max_label_chars = MermaidConfig::default().max_label_chars;
    let max_label_lines = MermaidConfig::default().max_label_lines;
    let label_chars_over = ir
        .labels
        .iter()
        .map(|label| label.text.chars().count().saturating_sub(max_label_chars))
        .sum();
    let label_lines_over = ir
        .labels
        .iter()
        .map(|label| label.text.lines().count().saturating_sub(max_label_lines))
        .sum();
    let guard = traced.trace.guard;
    let budget_exceeded = guard.time_budget_exceeded
        || guard.iteration_budget_exceeded
        || guard.route_budget_exceeded;
    let node_limit_exceeded = ir.nodes.len() > max_nodes;
    let edge_limit_exceeded = ir.edges.len() > max_edges;

    let degradation = fm_core::compute_degradation_plan(&fm_core::DegradationContext {
        pressure_tier: pressure.tier,
        route_budget_exceeded: guard.route_budget_exceeded,
        layout_budget_exceeded: guard.iteration_budget_exceeded,
        time_budget_exceeded: guard.time_budget_exceeded,
        node_limit_exceeded,
        edge_limit_exceeded,
    });

    MermaidGuardReport {
        complexity,
        label_chars_over,
        label_lines_over,
        node_limit_exceeded,
        edge_limit_exceeded,
        label_limit_exceeded: label_chars_over > 0 || label_lines_over > 0,
        route_budget_exceeded: guard.route_budget_exceeded,
        layout_budget_exceeded: guard.time_budget_exceeded || guard.iteration_budget_exceeded,
        limits_exceeded: node_limit_exceeded
            || edge_limit_exceeded
            || label_chars_over > 0
            || label_lines_over > 0,
        budget_exceeded,
        route_ops_estimate: guard.estimated_route_ops,
        layout_iterations_estimate: guard.estimated_layout_iterations,
        layout_time_estimate_ms: guard.estimated_layout_time_ms,
        layout_requested_algorithm: Some(traced.trace.dispatch.requested.as_str().to_string()),
        layout_selected_algorithm: Some(traced.trace.dispatch.selected.as_str().to_string()),
        guard_reason: Some(guard.reason.to_string()),
        observability: fm_core::MermaidObservabilityIds::default(),
        pressure,
        budget_broker: fm_core::MermaidBudgetLedger::default(),
        degradation,
    }
}

#[must_use]
#[allow(clippy::too_many_lines)]
pub fn build_layout_decision_ledger(
    ir: &MermaidDiagramIr,
    traced: &TracedLayout,
    guard_report: &MermaidGuardReport,
) -> MermaidLayoutDecisionLedger {
    MermaidLayoutDecisionLedger {
        entries: vec![build_layout_decision_record(
            ir,
            traced,
            guard_report.observability.clone(),
            guard_report.pressure.clone(),
            guard_report.budget_broker.total_budget_ms,
            guard_report.budget_broker.exhausted,
        )],
    }
}

#[must_use]
pub fn build_layout_decision_explanation(
    ir: &MermaidDiagramIr,
    traced: &TracedLayout,
    pressure: MermaidPressureReport,
    budget_total_ms: u64,
    budget_exhausted: bool,
) -> MermaidLayoutDecisionExplanation {
    build_layout_decision_record(
        ir,
        traced,
        MermaidObservabilityIds::default(),
        pressure,
        budget_total_ms,
        budget_exhausted,
    )
    .explanation()
}

#[allow(clippy::too_many_lines)]
fn build_layout_decision_record(
    ir: &MermaidDiagramIr,
    traced: &TracedLayout,
    observability: MermaidObservabilityIds,
    pressure: MermaidPressureReport,
    budget_total_ms: u64,
    budget_exhausted: bool,
) -> MermaidLayoutDecisionRecord {
    let dispatch = traced.trace.dispatch;
    let guard = traced.trace.guard;
    let metrics = GraphMetrics::from_ir(ir);
    let confidence_permille =
        layout_decision_confidence_permille(dispatch, guard, metrics, pressure.tier);

    let alternatives = concrete_layout_algorithms()
        .into_iter()
        .map(|algorithm| {
            let available_for_diagram = algorithm_available_for_diagram(ir.diagram_type, algorithm);
            let note = if algorithm == dispatch.selected {
                Some(format!("selected via {}", dispatch.reason))
            } else if algorithm == dispatch.requested && !available_for_diagram {
                Some(String::from(
                    "requested explicitly but unavailable for this diagram type",
                ))
            } else if algorithm == dispatch.requested {
                Some(String::from("explicitly requested by caller"))
            } else if available_for_diagram {
                Some(String::from("available alternative"))
            } else {
                None
            };
            MermaidLayoutDecisionAlternative {
                algorithm: algorithm.as_str().to_string(),
                selected: algorithm == dispatch.selected,
                available_for_diagram,
                note,
            }
        })
        .collect();

    let mut notes = Vec::new();
    if dispatch.requested == LayoutAlgorithm::Auto {
        notes.push(String::from(auto_selection_reason(ir, dispatch.selected)));
    }
    if dispatch.capability_unavailable {
        notes.push(format!(
            "requested '{}' was unavailable for '{}'; used '{}'",
            dispatch.requested.as_str(),
            ir.diagram_type.as_str(),
            dispatch.selected.as_str()
        ));
    }
    if guard.fallback_applied {
        notes.push(format!(
            "guardrail fallback changed layout from '{}' to '{}'",
            guard.initial_algorithm.as_str(),
            guard.selected_algorithm.as_str()
        ));
    }

    MermaidLayoutDecisionRecord {
        kind: String::from("layout_decision"),
        trace_id: observability.trace_id,
        decision_id: observability.decision_id,
        policy_id: observability.policy_id,
        schema_version: observability.schema_version,
        requested_algorithm: dispatch.requested.as_str().to_string(),
        selected_algorithm: dispatch.selected.as_str().to_string(),
        capability_unavailable: dispatch.capability_unavailable,
        decision_mode: dispatch.decision_mode.to_string(),
        dispatch_reason: dispatch.reason.to_string(),
        guard_reason: guard.reason.to_string(),
        fallback_applied: guard.fallback_applied,
        confidence_permille,
        selected_expected_loss_permille: dispatch.selected_expected_loss_permille,
        node_count: traced.layout.nodes.len(),
        edge_count: traced.layout.edges.len(),
        crossing_count: traced.layout.stats.crossing_count,
        reversed_edges: traced.layout.stats.reversed_edges,
        estimated_layout_time_ms: guard.estimated_layout_time_ms,
        estimated_layout_iterations: guard.estimated_layout_iterations,
        estimated_route_ops: guard.estimated_route_ops,
        pressure_source: pressure.source,
        pressure_tier: pressure.tier,
        budget_total_ms,
        budget_exhausted,
        state_posterior: vec![
            MermaidDecisionWeight {
                key: String::from("tree_like"),
                value_permille: u32::from(dispatch.posterior_tree_like_permille),
            },
            MermaidDecisionWeight {
                key: String::from("dense_graph"),
                value_permille: u32::from(dispatch.posterior_dense_graph_permille),
            },
            MermaidDecisionWeight {
                key: String::from("layered_general"),
                value_permille: u32::from(dispatch.posterior_layered_permille),
            },
        ],
        expected_loss: vec![
            MermaidDecisionWeight {
                key: String::from("sugiyama"),
                value_permille: dispatch.sugiyama_expected_loss_permille,
            },
            MermaidDecisionWeight {
                key: String::from("tree"),
                value_permille: dispatch.tree_expected_loss_permille,
            },
            MermaidDecisionWeight {
                key: String::from("force"),
                value_permille: dispatch.force_expected_loss_permille,
            },
        ],
        alternatives,
        notes,
    }
}

const fn concrete_layout_algorithms() -> [LayoutAlgorithm; 12] {
    [
        LayoutAlgorithm::Sugiyama,
        LayoutAlgorithm::Force,
        LayoutAlgorithm::Tree,
        LayoutAlgorithm::Radial,
        LayoutAlgorithm::Timeline,
        LayoutAlgorithm::Gantt,
        LayoutAlgorithm::XyChart,
        LayoutAlgorithm::Sankey,
        LayoutAlgorithm::Kanban,
        LayoutAlgorithm::Grid,
        LayoutAlgorithm::Sequence,
        LayoutAlgorithm::Pie,
    ]
}

fn layout_decision_confidence_permille(
    dispatch: LayoutDispatch,
    guard: LayoutGuardDecision,
    metrics: GraphMetrics,
    pressure_tier: MermaidPressureTier,
) -> u16 {
    let mut confidence =
        if dispatch.requested != LayoutAlgorithm::Auto && !dispatch.capability_unavailable {
            970_u16
        } else if dispatch.capability_unavailable {
            420_u16
        } else {
            match dispatch.selected {
                LayoutAlgorithm::Sequence
                | LayoutAlgorithm::Timeline
                | LayoutAlgorithm::Gantt
                | LayoutAlgorithm::XyChart
                | LayoutAlgorithm::Sankey
                | LayoutAlgorithm::Kanban
                | LayoutAlgorithm::Grid
                | LayoutAlgorithm::Radial
                | LayoutAlgorithm::Pie
                | LayoutAlgorithm::Quadrant
                | LayoutAlgorithm::GitGraph
                | LayoutAlgorithm::Architecture
                | LayoutAlgorithm::Packet => 900,
                LayoutAlgorithm::Tree if metrics.is_tree_like => 880,
                LayoutAlgorithm::Force if metrics.is_dense || metrics.back_edge_count > 0 => 760,
                LayoutAlgorithm::Sugiyama => 820,
                LayoutAlgorithm::Tree => 700,
                LayoutAlgorithm::Force => 680,
                LayoutAlgorithm::Auto => 500,
            }
        };

    if guard.fallback_applied {
        confidence = confidence.saturating_sub(180);
    }
    if guard.time_budget_exceeded || guard.iteration_budget_exceeded || guard.route_budget_exceeded
    {
        confidence = confidence.saturating_sub(80);
    }

    let pressure_penalty = match pressure_tier {
        MermaidPressureTier::Unknown | MermaidPressureTier::Nominal => 0,
        MermaidPressureTier::Elevated => 20,
        MermaidPressureTier::High => 50,
        MermaidPressureTier::Critical => 90,
    };
    confidence.saturating_sub(pressure_penalty)
}

#[cfg(test)]
mod barycenter_arms_tests {
    use std::collections::BTreeMap;

    use super::{
        BarycenterScratch, LayoutConfig, bench_internals, total_crossings, total_crossings_packed,
    };
    use fm_core::{ArrowType, DiagramType, IrEdge, IrEndpoint, IrNode, IrNodeId, MermaidDiagramIr};

    /// Build a layered graph with `layers * width` nodes, forward edges (including skips), and
    /// `back_edges` back-edges so the SCC detector produces cycles — the shape that routes to Sugiyama
    /// and therefore actually executes the barycenter sweep.
    fn layered_cyclic_ir(
        layers: usize,
        width: usize,
        back_edges: usize,
        seed: u64,
    ) -> MermaidDiagramIr {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Flowchart);
        for index in 0..layers * width {
            ir.nodes.push(IrNode {
                id: format!("N{index}"),
                ..IrNode::default()
            });
        }
        let mut state = seed | 1;
        let mut next = move || {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state
        };
        let edge = |ir: &mut MermaidDiagramIr, from: usize, to: usize| {
            ir.edges.push(IrEdge {
                from: IrEndpoint::Node(IrNodeId(from)),
                to: IrEndpoint::Node(IrNodeId(to)),
                arrow: ArrowType::Arrow,
                ..IrEdge::default()
            });
        };
        for layer in 0..layers.saturating_sub(1) {
            for slot in 0..width {
                let from = layer * width + slot;
                // one straight edge plus a pseudo-random skip, to make barycenters non-trivial
                edge(&mut ir, from, (layer + 1) * width + slot);
                let target_slot = usize::try_from(next() % (width as u64)).unwrap_or(0);
                edge(&mut ir, from, (layer + 1) * width + target_slot);
            }
        }
        for k in 0..back_edges {
            let from = (layers - 1) * width + (k % width);
            let to = (k * 7) % width;
            edge(&mut ir, from, to);
        }
        ir
    }

    /// The dense sweep must produce **exactly** the ordering (and crossing count) the `BTreeMap` sweep
    /// produced. Layout output is a determinism gate for this project, so anything less than equality on
    /// every rank is a hard failure. Covers narrow ranks (below the old `SINGLE_PASS_RANK_THRESHOLD = 8`,
    /// which took the per-node rescan branch) and wide ranks (which took the single-pass branch).
    #[test]
    fn dense_barycenter_sweep_matches_btreemap_sweep() {
        let config = LayoutConfig::default();
        for (layers, width, back_edges) in [
            (25, 4, 20), // narrow ranks: the old per-node full-edge rescan branch
            (12, 3, 8),  // narrower still
            (6, 16, 12), // wide ranks: the old single-pass branch
            (10, 8, 0),  // exactly at the old threshold, acyclic
            (3, 1, 0),   // degenerate: one node per rank (fast-path)
            (18, 6, 30), // heavily cyclic
        ] {
            for seed in [0x2545_F491_4F6C_DD1D_u64, 0x9E37_79B9_7F4A_7C15] {
                let ir = layered_cyclic_ir(layers, width, back_edges, seed);
                let ranks = bench_internals::prepare_ranks(&ir, &config);
                let orig = bench_internals::crossing_minimization_btreemap(&ir, &ranks, &config);
                let dense = bench_internals::crossing_minimization_dense_rank(&ir, &ranks, &config);
                let single =
                    bench_internals::crossing_minimization_single_pass(&ir, &ranks, &config);
                let flat_csr =
                    bench_internals::crossing_minimization_flat_csr(&ir, &ranks, &config);
                let packed_crossings =
                    bench_internals::crossing_minimization_packed_crossings(&ir, &ranks, &config);
                assert_eq!(
                    flat_csr, packed_crossings,
                    "packed crossing count diverged from the flat-CSR sweep \
                     (layers={layers} width={width} back_edges={back_edges} seed={seed:#x})"
                );
                assert_eq!(
                    single, flat_csr,
                    "flat-CSR sweep diverged from the single-pass sweep \
                     (layers={layers} width={width} back_edges={back_edges} seed={seed:#x})"
                );
                assert_eq!(
                    dense, single,
                    "single-pass sweep diverged from the dense-rank sweep \
                     (layers={layers} width={width} back_edges={back_edges} seed={seed:#x})"
                );
                assert_eq!(
                    orig, dense,
                    "dense barycenter sweep diverged from the BTreeMap sweep \
                     (layers={layers} width={width} back_edges={back_edges} seed={seed:#x})"
                );
            }
        }
    }

    #[test]
    fn flat_csr_preserves_per_node_edge_order_and_multiplicity() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Flowchart);
        for index in 0..4 {
            ir.nodes.push(IrNode {
                id: format!("N{index}"),
                ..IrNode::default()
            });
        }
        for (from, to) in [
            (0, 2),
            (1, 2),
            (0, 3),
            (0, 2), // parallel edge: multiplicity must survive
            (2, 2), // self edge appears in both directions
            (99, 0),
            (0, 99),
        ] {
            ir.edges.push(IrEdge {
                from: IrEndpoint::Node(IrNodeId(from)),
                to: IrEndpoint::Node(IrNodeId(to)),
                arrow: ArrowType::Arrow,
                ..IrEdge::default()
            });
        }

        let scratch = BarycenterScratch::new::<true, true>(&ir);
        let direction_width = ir.nodes.len() + 1;
        let neighbors = |node: usize, incoming: bool| {
            let base = if incoming { 0 } else { direction_width };
            let start = usize::try_from(scratch.incidence_offsets[base + node]).unwrap_or(0);
            let end = usize::try_from(scratch.incidence_offsets[base + node + 1]).unwrap_or(0);
            scratch.incidence_neighbors[start..end].to_vec()
        };

        assert_eq!(neighbors(2, true), vec![0, 1, 0, 2]);
        assert_eq!(neighbors(3, true), vec![0]);
        assert_eq!(neighbors(0, false), vec![2, 3, 2]);
        assert_eq!(neighbors(1, false), vec![2]);
        assert_eq!(neighbors(2, false), vec![2]);
    }

    #[test]
    fn packed_total_crossings_matches_maps_across_repeated_reorders() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Flowchart);
        for index in 0..7 {
            ir.nodes.push(IrNode {
                id: format!("N{index}"),
                ..IrNode::default()
            });
        }
        for (from, to) in [
            (0, 3),
            (1, 4),
            (2, 5),
            (4, 0), // reversed adjacent-rank edge
            (0, 5),
            (0, 5), // parallel edge: multiplicity must survive
            (1, 0), // same-rank edge: ignored
            (2, 6), // long edge: ignored
            (5, 6),
            (99, 0),
            (0, 99),
        ] {
            ir.edges.push(IrEdge {
                from: IrEndpoint::Node(IrNodeId(from)),
                to: IrEndpoint::Node(IrNodeId(to)),
                arrow: ArrowType::Arrow,
                ..IrEdge::default()
            });
        }

        let ranks = BTreeMap::from([(0, 0), (1, 0), (2, 0), (3, 1), (4, 1), (5, 1), (6, 2)]);
        let mut ordering = BTreeMap::from([(0, vec![2, 0, 1]), (1, vec![4, 3, 5]), (2, vec![6])]);
        let mut scratch = BarycenterScratch::new::<true, true>(&ir);
        let offset_ptr = scratch.incidence_offsets.as_ptr();
        let neighbor_ptr = scratch.incidence_neighbors.as_ptr();
        let offset_capacity = scratch.incidence_offsets.capacity();
        let neighbor_capacity = scratch.incidence_neighbors.capacity();

        for _ in 0..3 {
            let expected = total_crossings(&ir, &ranks, &ordering);
            let actual = total_crossings_packed(&ir, &ranks, &ordering, &mut scratch)
                .expect("packed scratch should represent this graph");
            assert_eq!(expected, actual);
            assert_eq!(scratch.incidence_offsets.as_ptr(), offset_ptr);
            assert_eq!(scratch.incidence_neighbors.as_ptr(), neighbor_ptr);
            assert_eq!(scratch.incidence_offsets.capacity(), offset_capacity);
            assert_eq!(scratch.incidence_neighbors.capacity(), neighbor_capacity);
            ordering.get_mut(&1).expect("rank exists").rotate_left(1);
        }
    }

    #[test]
    fn packed_total_crossings_preserves_exact_edge_semantics() {
        let check = |node_count: usize,
                     rank_entries: &[(usize, usize)],
                     ordering: BTreeMap<usize, Vec<usize>>,
                     edges: &[(usize, usize)],
                     expected: usize| {
            let mut ir = MermaidDiagramIr::empty(DiagramType::Flowchart);
            for index in 0..node_count {
                ir.nodes.push(IrNode {
                    id: format!("N{index}"),
                    ..IrNode::default()
                });
            }
            for &(from, to) in edges {
                ir.edges.push(IrEdge {
                    from: IrEndpoint::Node(IrNodeId(from)),
                    to: IrEndpoint::Node(IrNodeId(to)),
                    arrow: ArrowType::Arrow,
                    ..IrEdge::default()
                });
            }
            let ranks: BTreeMap<usize, usize> = rank_entries.iter().copied().collect();
            let reference = total_crossings(&ir, &ranks, &ordering);
            assert_eq!(reference, expected, "reference case is malformed");
            let mut scratch = BarycenterScratch::new::<true, true>(&ir);
            assert_eq!(
                total_crossings_packed(&ir, &ranks, &ordering, &mut scratch),
                Some(expected)
            );
        };

        // Target order within one source is irrelevant: same-source edges never cross.
        check(
            3,
            &[(0, 0), (1, 1), (2, 1)],
            BTreeMap::from([(0, vec![0]), (1, vec![1, 2])]),
            &[(0, 2), (0, 1)],
            0,
        );
        // Every edge in the 2-wide upper-left bundle crosses every edge in the 3-wide
        // upper-right bundle; multiplicity is exact.
        check(
            4,
            &[(0, 0), (1, 0), (2, 1), (3, 1)],
            BTreeMap::from([(0, vec![0, 1]), (1, vec![2, 3])]),
            &[(0, 3), (0, 3), (1, 2), (1, 2), (1, 2)],
            6,
        );
        // Equal-target parallel bundles do not cross.
        check(
            3,
            &[(0, 0), (1, 0), (2, 1)],
            BTreeMap::from([(0, vec![0, 1]), (1, vec![2])]),
            &[(0, 2), (0, 2), (1, 2), (1, 2), (1, 2)],
            0,
        );
        // One edge is stored lower-to-upper in the IR but participates after rank normalization.
        check(
            4,
            &[(0, 0), (1, 0), (2, 1), (3, 1)],
            BTreeMap::from([(0, vec![0, 1]), (1, vec![2, 3])]),
            &[(3, 0), (1, 2)],
            1,
        );
        // Adjacent rank pairs are independent sums, never one flattened inversion stream.
        check(
            6,
            &[(0, 0), (1, 0), (2, 1), (3, 1), (4, 2), (5, 2)],
            BTreeMap::from([(0, vec![0, 1]), (1, vec![2, 3]), (2, vec![4, 5])]),
            &[(0, 3), (1, 2), (2, 5), (3, 4)],
            2,
        );
        // Sparse ranks at the integer boundary preserve saturating-adjacency semantics.
        check(
            4,
            &[
                (0, usize::MAX - 1),
                (1, usize::MAX - 1),
                (2, usize::MAX),
                (3, usize::MAX),
            ],
            BTreeMap::from([(usize::MAX - 1, vec![0, 1]), (usize::MAX, vec![2, 3])]),
            &[(0, 3), (1, 2)],
            1,
        );

        // Wrong-rank occurrences are ignored, duplicate nodes use their last position, omitted nodes
        // stay absent, and invalid endpoints follow the reference counter's filters.
        let mut ir = MermaidDiagramIr::empty(DiagramType::Flowchart);
        for index in 0..5 {
            ir.nodes.push(IrNode {
                id: format!("N{index}"),
                ..IrNode::default()
            });
        }
        for (from, to) in [(0, 3), (1, 2), (4, 2), (99, 0), (0, 99)] {
            ir.edges.push(IrEdge {
                from: IrEndpoint::Node(IrNodeId(from)),
                to: IrEndpoint::Node(IrNodeId(to)),
                arrow: ArrowType::Arrow,
                ..IrEdge::default()
            });
        }
        let ranks = BTreeMap::from([(0, 0), (1, 0), (2, 1), (3, 1), (4, 0)]);
        let ordering = BTreeMap::from([(0, vec![2, 0, 1, 0]), (1, vec![2, 3])]);
        let expected = total_crossings(&ir, &ranks, &ordering);
        let mut scratch = BarycenterScratch::new::<true, true>(&ir);
        assert_eq!(
            total_crossings_packed(&ir, &ranks, &ordering, &mut scratch),
            Some(expected)
        );
    }
}

