    #[test]
    fn reciprocal_edges_are_not_bundled_as_parallel_duplicates() {
        let ir = graph_ir(DiagramType::Flowchart, 2, &[(0, 1), (1, 0), (0, 1)]);
        let layout = layout_diagram(&ir);
        let edge = |edge_index| {
            layout
                .edges
                .iter()
                .find(|path| path.edge_index == edge_index)
                .expect("every IR edge should retain a layout path")
        };

        assert_eq!(edge(0).bundle_count, 2);
        assert!(!edge(0).bundled);
        assert_eq!(edge(1).bundle_count, 1);
        assert!(!edge(1).bundled);
        assert!(edge(2).bundled);
    }

    /// gitGraph commits must be placed by BRANCH, not stacked into a single column (bd-5wbp).
    ///
    /// The property, not the numbers: same branch → same centre; different branch → centres at least
    /// a commit diameter apart; and the down-the-chain order is untouched. Labels are deliberately
    /// uneven in width because commit boxes are label-sized — left-aligning them within a lane put a
    /// wide merge commit at a different centre from a bare commit on the same branch.
    #[test]
    fn gitgraph_commits_are_placed_in_their_branch_lane() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::GitGraph);
        // main, develop, develop, "merge develop" back on main.
        let lanes = [0_usize, 1, 1, 0];
        for (index, text) in ["c1", "on develop", "d2", "merge develop"]
            .iter()
            .enumerate()
        {
            ir.labels.push(IrLabel {
                text: (*text).to_string(),
                span: Span::default(),
            });
            ir.nodes.push(IrNode {
                id: format!("commit_{index}"),
                label: Some(IrLabelId(index)),
                shape: NodeShape::Circle,
                ..IrNode::default()
            });
        }
        ir.git_graph_meta = Some(fm_core::IrGitGraphMeta {
            branches: vec!["main".to_string(), "develop".to_string()],
            commit_lanes: lanes.iter().copied().enumerate().collect(),
        });

        let layout = layout_diagram(&ir);
        assert_eq!(layout.nodes.len(), 4);
        let centre_x = |i: usize| {
            let bounds = layout.nodes[i].bounds;
            bounds.x + bounds.width * 0.5
        };
        let diameter = layout.nodes[0]
            .bounds
            .width
            .min(layout.nodes[0].bounds.height);

        assert_eq!(centre_x(0), centre_x(3), "main commits must share a lane");
        assert_eq!(
            centre_x(1),
            centre_x(2),
            "develop commits must share a lane"
        );
        assert!(
            (centre_x(0) - centre_x(1)).abs() >= diameter,
            "lanes {} and {} are closer than one commit diameter ({diameter})",
            centre_x(0),
            centre_x(1)
        );

        // Separation must not have been bought by reordering the chain.
        for pair in layout.nodes.windows(2) {
            assert!(
                pair[1].bounds.y > pair[0].bounds.y,
                "commit order along the chain changed"
            );
        }
    }

    fn labeled_graph_ir(node_count: usize, edges: &[(usize, usize)]) -> MermaidDiagramIr {
        let mut ir = graph_ir(DiagramType::Flowchart, node_count, edges);
        for index in 0..node_count {
            ir.labels.push(IrLabel {
                text: format!("Node {index}"),
                span: Span::default(),
            });
            ir.nodes[index].label = Some(IrLabelId(index));
        }
        ir
    }

    /// Force-directed edges must stop on the node's drawn OUTLINE, not on its bounding box.
    ///
    /// A circle is inscribed in its bounds and touches them only at the four side midpoints, so a
    /// diagonally-arriving edge clipped to the rectangle lands as much as (sqrt(2)-1) of the
    /// radius outside the drawn shape — a visible gap between arrowhead and node. The main
    /// Sugiyama path is immune because `edge_anchors` attaches at side midpoints, which is exactly
    /// where an inscribed circle or diamond meets its box; the force path clips along an arbitrary
    /// direction and has no such guarantee.
    ///
    /// Asserted as a distance from the node centre rather than as fixed coordinates, so the test
    /// states the geometric property instead of pinning whatever the current formula emits.
    /// Horizontal edge anchors must sit on the DRAWN outline, which for slanted shapes is inside
    /// the bounding box (bd-7c9c).
    ///
    /// A triangle is drawn apex-top over a full-width base, so at mid-height it spans only the
    /// middle half of its box: anchoring at the box side leaves the arrowhead a quarter of the
    /// node's width out in empty space. Trapezoids and parallelograms slant by
    /// SLANTED_SHAPE_INSET_RATIO across their full height, so half of that is gone by mid-height.
    #[test]
    fn horizontal_anchors_follow_slanted_shape_outlines() {
        fn boxes() -> (LayoutNodeBox, LayoutNodeBox) {
            let make = |index: usize, x: f32| LayoutNodeBox {
                node_index: index,
                node_id: format!("N{index}"),
                rank: 0,
                order: index,
                span: Span::default(),
                bounds: LayoutRect {
                    x,
                    y: 0.0,
                    width: 100.0,
                    height: 60.0,
                },
            };
            (make(0, 0.0), make(1, 400.0))
        }

        let (source, target) = boxes();

        // Triangle: a quarter of the width in on each side.
        let (from, to) = crate::edge_anchors(
            &source,
            &target,
            true,
            fm_core::NodeShape::Triangle,
            fm_core::NodeShape::Triangle,
        );
        assert!(
            (from.x - 75.0).abs() < 1e-3,
            "triangle source anchor should be at 75.0 (box right 100.0 minus a quarter width), got {from:?}"
        );
        assert!(
            (to.x - 425.0).abs() < 1e-3,
            "triangle target anchor should be at 425.0 (box left 400.0 plus a quarter width), got {to:?}"
        );

        // Parallelogram: half the 0.15 slant, so 7.5 units on a 100-wide node.
        let (from, to) = crate::edge_anchors(
            &source,
            &target,
            true,
            fm_core::NodeShape::Parallelogram,
            fm_core::NodeShape::Trapezoid,
        );
        assert!((from.x - 92.5).abs() < 1e-3, "got {from:?}");
        assert!((to.x - 407.5).abs() < 1e-3, "got {to:?}");

        // NEGATIVE CONTROLS. These shapes already touched their box at the side midpoints, so this
        // change must not move them at all — that is what makes it targeted rather than a global
        // shift, and a wrong inset table would break these first.
        for shape in [
            fm_core::NodeShape::Rect,
            fm_core::NodeShape::Rounded,
            fm_core::NodeShape::Circle,
            fm_core::NodeShape::Diamond,
            fm_core::NodeShape::Hexagon,
            fm_core::NodeShape::Stadium,
        ] {
            let (from, to) = crate::edge_anchors(&source, &target, true, shape, shape);
            assert!(
                (from.x - 100.0).abs() < 1e-3 && (to.x - 400.0).abs() < 1e-3,
                "{shape:?} must still anchor on the box, got {from:?} -> {to:?}"
            );
        }

        // Vertical anchors are unchanged for every shape: a triangle's apex is at top-centre and
        // its base spans the full width, so top/bottom midpoints were always on the outline.
        let (from, to) = crate::edge_anchors(
            &source,
            &target,
            false,
            fm_core::NodeShape::Triangle,
            fm_core::NodeShape::Triangle,
        );
        assert!(
            (from.y - 60.0).abs() < 1e-3 && (to.y - 0.0).abs() < 1e-3,
            "got {from:?} -> {to:?}"
        );
    }

    #[test]
    fn force_edges_stop_on_round_node_outlines_not_the_bounding_box() {
        let bounds = LayoutRect {
            x: 0.0,
            y: 0.0,
            width: 80.0,
            height: 80.0,
        };
        let centre = bounds.center();

        // A DIAGONAL approach is the whole point. An end-to-end force layout of two nodes settles
        // them roughly axis-aligned, where clipping to the box happens to land on a side midpoint
        // and the bug cannot appear — a test built that way passes without exercising anything.
        let approach = LayoutPoint {
            x: centre.x + 100.0,
            y: centre.y + 100.0,
        };

        let endpoint =
            crate::clip_to_shape_border(centre, approach, &bounds, fm_core::NodeShape::Circle);

        let half_w = bounds.width / 2.0;
        let half_h = bounds.height / 2.0;
        let normalised = ((endpoint.x - centre.x) / half_w).hypot((endpoint.y - centre.y) / half_h);
        assert!(
            (normalised - 1.0).abs() < 1e-3,
            "edge endpoint {endpoint:?} sits at {normalised:.4}x the inscribed radius; 1.0 is the \
             drawn outline, and clipping to the bounding box gives sqrt(2) here"
        );

        // Negative control: the RECT shape must still clip to the box, so this test cannot be
        // satisfied by making every shape round.
        let rect_endpoint =
            crate::clip_to_shape_border(centre, approach, &bounds, fm_core::NodeShape::Rect);
        assert!(
            (rect_endpoint.x - (bounds.x + bounds.width)).abs() < 1e-3
                && (rect_endpoint.y - (bounds.y + bounds.height)).abs() < 1e-3,
            "a rectangle must still clip to its corner, got {rect_endpoint:?}"
        );

        // Axis-aligned approaches agree for both shapes — this is why the Sugiyama path, which
        // anchors at side midpoints, was never affected.
        let side_on = LayoutPoint {
            x: centre.x + 100.0,
            y: centre.y,
        };
        let round_side =
            crate::clip_to_shape_border(centre, side_on, &bounds, fm_core::NodeShape::Circle);
        let rect_side =
            crate::clip_to_shape_border(centre, side_on, &bounds, fm_core::NodeShape::Rect);
        assert!((round_side.x - rect_side.x).abs() < 1e-3);
        assert!((round_side.y - rect_side.y).abs() < 1e-3);
    }

    fn toggle_edge(ir: &mut MermaidDiagramIr, from: usize, to: usize) {
        if let Some(index) = ir.edges.iter().position(|edge| {
            edge.from == IrEndpoint::Node(IrNodeId(from))
                && edge.to == IrEndpoint::Node(IrNodeId(to))
        }) {
            ir.edges.remove(index);
            return;
        }

        ir.edges.push(IrEdge {
            from: IrEndpoint::Node(IrNodeId(from)),
            to: IrEndpoint::Node(IrNodeId(to)),
            arrow: ArrowType::Arrow,
            ..IrEdge::default()
        });
    }

    fn append_labeled_node(ir: &mut MermaidDiagramIr, label_text: &str) -> usize {
        let label_index = ir.labels.len();
        ir.labels.push(IrLabel {
            text: label_text.to_string(),
            span: Span::default(),
        });
        let node_index = ir.nodes.len();
        ir.nodes.push(IrNode {
            id: format!("N{node_index}"),
            label: Some(IrLabelId(label_index)),
            ..IrNode::default()
        });
        node_index
    }

    fn sample_dependency_graph() -> TestDependencyGraph {
        let root = SubgraphRegion {
            id: SubgraphRegionId(0),
            kind: SubgraphRegionKind::ExplicitSubgraph,
            label: "subgraph:api".to_string(),
            node_indexes: [0, 1].into_iter().collect(),
            #[allow(clippy::iter_on_single_items)]
            edge_indexes: [0].into_iter().collect(),
            subgraph_indexes: [0].into_iter().collect(),
            depends_on: BTreeSet::new(),
            dependents: [SubgraphRegionId(1)].into_iter().collect(),
            inputs: [RegionInput::Node(0), RegionInput::Edge(0)]
                .into_iter()
                .collect(),
            estimated_bytes: 96,
        };
        let child = SubgraphRegion {
            id: SubgraphRegionId(1),
            kind: SubgraphRegionKind::ConnectivityFragment,
            label: "component:1".to_string(),
            node_indexes: [2, 3].into_iter().collect(),
            edge_indexes: std::iter::once(1).collect(),
            subgraph_indexes: BTreeSet::new(),
            depends_on: std::iter::once(SubgraphRegionId(0)).collect(),
            dependents: BTreeSet::new(),
            inputs: [RegionInput::Node(2), RegionInput::Edge(1)]
                .into_iter()
                .collect(),
            estimated_bytes: 72,
        };

        let mut regions = BTreeMap::new();
        regions.insert(root.id, root.clone());
        regions.insert(child.id, child.clone());

        let mut index = BTreeMap::new();
        for region in [root, child] {
            for input in &region.inputs {
                index
                    .entry(*input)
                    .or_insert_with(BTreeSet::new)
                    .insert(region.id);
            }
        }

        TestDependencyGraph {
            regions,
            index,
            estimated_overhead_bytes: 168,
        }
    }

    fn sample_layout_dependency_ir() -> MermaidDiagramIr {
        let mut ir = labeled_graph_ir(5, &[(0, 1), (1, 2), (2, 3), (3, 4)]);
        ir.graph.nodes = (0..ir.nodes.len())
            .map(|node_index| IrGraphNode {
                node_id: IrNodeId(node_index),
                clusters: Vec::new(),
                subgraphs: Vec::new(),
                ..IrGraphNode::default()
            })
            .collect();
        ir.graph.edges = ir
            .edges
            .iter()
            .enumerate()
            .map(|(edge_index, edge)| IrGraphEdge {
                edge_id: edge_index,
                from: edge.from,
                to: edge.to,
                span: edge.span,
                ..IrGraphEdge::default()
            })
            .collect();

        ir.graph.subgraphs.push(IrSubgraph {
            id: IrSubgraphId(0),
            key: "api".to_string(),
            title: None,
            parent: None,
            children: vec![IrSubgraphId(1)],
            members: vec![IrNodeId(0)],
            cluster: None,
            grid_span: 1,
            span: Span::at_line(1, 1),
            direction: None,
        });
        ir.graph.subgraphs.push(IrSubgraph {
            id: IrSubgraphId(1),
            key: "worker".to_string(),
            title: None,
            parent: Some(IrSubgraphId(0)),
            children: Vec::new(),
            members: vec![IrNodeId(1)],
            cluster: None,
            grid_span: 1,
            span: Span::at_line(2, 1),
            direction: None,
        });
        ir.graph.nodes[0].subgraphs.push(IrSubgraphId(0));
        ir.graph.nodes[1].subgraphs.push(IrSubgraphId(0));
        ir.graph.nodes[1].subgraphs.push(IrSubgraphId(1));

        ir
    }

    fn large_subgraph_dependency_ir() -> MermaidDiagramIr {
        sized_subgraph_dependency_ir(32)
    }

    fn sized_subgraph_dependency_ir(nodes_per_subgraph: usize) -> MermaidDiagramIr {
        let total = nodes_per_subgraph * 2;
        let mut edges = Vec::new();
        for node_index in 0..nodes_per_subgraph - 1 {
            edges.push((node_index, node_index + 1));
        }
        for node_index in nodes_per_subgraph..total - 1 {
            edges.push((node_index, node_index + 1));
        }
        let mut ir = labeled_graph_ir(total, &edges);
        ir.graph.nodes = (0..ir.nodes.len())
            .map(|node_index| IrGraphNode {
                node_id: IrNodeId(node_index),
                clusters: Vec::new(),
                subgraphs: Vec::new(),
                ..IrGraphNode::default()
            })
            .collect();
        ir.graph.edges = ir
            .edges
            .iter()
            .enumerate()
            .map(|(edge_index, edge)| IrGraphEdge {
                edge_id: edge_index,
                from: edge.from,
                to: edge.to,
                span: edge.span,
                ..IrGraphEdge::default()
            })
            .collect();
        ir.graph.subgraphs.push(IrSubgraph {
            id: IrSubgraphId(0),
            key: "left".to_string(),
            title: None,
            parent: None,
            children: Vec::new(),
            members: (0..nodes_per_subgraph).map(IrNodeId).collect(),
            cluster: None,
            grid_span: 1,
            span: Span::at_line(1, 1),
            direction: None,
        });
        ir.graph.subgraphs.push(IrSubgraph {
            id: IrSubgraphId(1),
            key: "right".to_string(),
            title: None,
            parent: None,
            children: Vec::new(),
            members: (nodes_per_subgraph..total).map(IrNodeId).collect(),
            cluster: None,
            grid_span: 1,
            span: Span::at_line(2, 1),
            direction: None,
        });
        for node in &mut ir.graph.nodes[..nodes_per_subgraph] {
            node.subgraphs.push(IrSubgraphId(0));
        }
        for node in &mut ir.graph.nodes[nodes_per_subgraph..total] {
            node.subgraphs.push(IrSubgraphId(1));
        }
        ir
    }

