    #[test]
    fn timeline_layout_keeps_periods_on_baseline_and_stacks_events() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Timeline);
        for label in ["2024", "2025", "Kickoff", "Launch", "Retro"] {
            ir.labels.push(IrLabel {
                text: label.to_string(),
                ..IrLabel::default()
            });
        }
        ir.nodes.push(IrNode {
            id: "period_2024".to_string(),
            label: Some(IrLabelId(0)),
            shape: NodeShape::Rect,
            ..IrNode::default()
        });
        ir.nodes.push(IrNode {
            id: "period_2025".to_string(),
            label: Some(IrLabelId(1)),
            shape: NodeShape::Rect,
            ..IrNode::default()
        });
        for (node_id, label_id) in [
            ("kickoff", IrLabelId(2)),
            ("launch", IrLabelId(3)),
            ("retro", IrLabelId(4)),
        ] {
            ir.nodes.push(IrNode {
                id: node_id.to_string(),
                label: Some(label_id),
                shape: NodeShape::Rounded,
                ..IrNode::default()
            });
        }
        for (from, to) in [(0, 2), (0, 3), (1, 4)] {
            ir.edges.push(IrEdge {
                from: IrEndpoint::Node(IrNodeId(from)),
                to: IrEndpoint::Node(IrNodeId(to)),
                arrow: ArrowType::Arrow,
                ..IrEdge::default()
            });
        }

        let layout = layout_diagram_timeline(&ir);
        let centers = layout
            .nodes
            .iter()
            .map(|node| (node.node_id.as_str(), node.bounds.center()))
            .collect::<BTreeMap<_, _>>();

        let period_2024 = centers.get("period_2024").expect("2024 period");
        let period_2025 = centers.get("period_2025").expect("2025 period");
        let kickoff = centers.get("kickoff").expect("kickoff event");
        let launch = centers.get("launch").expect("launch event");
        let retro = centers.get("retro").expect("retro event");

        assert!((period_2024.y - period_2025.y).abs() < 0.001);
        assert!(period_2024.x < period_2025.x);
        assert!((kickoff.x - period_2024.x).abs() < 0.001);
        assert!((launch.x - period_2024.x).abs() < 0.001);
        assert!((retro.x - period_2025.x).abs() < 0.001);
        assert!(kickoff.y > period_2024.y);
        assert!(launch.y > kickoff.y);
        assert!(retro.y > period_2025.y);
        assert_eq!(layout.extensions.axis_ticks.len(), 2);
    }

    /// A tick that merely EXISTS is not an axis. If the tick labelled with a task's start date does
    /// not sit on that task's left edge, the axis indexes days the bars do not start on — which is
    /// strictly worse than the no-axis state bd-trsd found, because a wrong axis is still read as
    /// authoritative. Ticks were emitted in raw day-space while the bars were normalized, so every
    /// tick was >= 20px left of the day it named.
    /// A kanban lane band must carry the DECLARED column name, not a generated placeholder
    /// (bd-u3fo).
    ///
    /// The label was unconditionally `lane 1`, `lane 2`, … so a column the user named `Alpha`
    /// reached the band as `lane 1`. The name was not merely undrawn — it never arrived, so no
    /// renderer could recover it. That is why a terminal-rendering symptom has its cause here.
    ///
    /// ⚠️ Note for anyone grepping: the bead describes this label as `column N`. That string is in
    /// `layout_diagram_sankey_traced`, a different diagram type; the kanban placeholder is
    /// `lane N`. I patched the sankey one first by mistake and reverted it — the two look alike and
    /// only one is this bug.
    #[test]
    fn kanban_lane_bands_carry_the_declared_column_name() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Kanban);
        for text in ["Alpha", "Beta", "Card1", "Card2"] {
            ir.labels.push(IrLabel {
                text: text.to_string(),
                ..IrLabel::default()
            });
        }
        for (node_id, label) in [("t1", IrLabelId(2)), ("t2", IrLabelId(3))] {
            ir.nodes.push(IrNode {
                id: node_id.to_string(),
                label: Some(label),
                ..IrNode::default()
            });
        }
        // An edge separates the two cards into different RANKS; ranking here is edge-driven, so
        // without it both land in rank 0 and only one band is produced.
        ir.edges.push(IrEdge {
            from: IrEndpoint::Node(IrNodeId(0)),
            to: IrEndpoint::Node(IrNodeId(1)),
            arrow: ArrowType::Arrow,
            ..IrEdge::default()
        });
        for subgraph_index in 0..2usize {
            ir.graph.nodes.push(IrGraphNode {
                subgraphs: vec![IrSubgraphId(subgraph_index)],
                ..IrGraphNode::default()
            });
            ir.graph.subgraphs.push(IrSubgraph {
                id: IrSubgraphId(subgraph_index),
                key: format!("col{subgraph_index}"),
                title: Some(IrLabelId(subgraph_index)),
                members: vec![IrNodeId(subgraph_index)],
                ..IrSubgraph::default()
            });
        }

        let layout = crate::layout_diagram_kanban_traced(&ir).layout;
        let labels: Vec<&str> = layout
            .extensions
            .bands
            .iter()
            .map(|band| band.label.as_str())
            .collect();

        assert!(
            labels.contains(&"Alpha") && labels.contains(&"Beta"),
            "lane bands lost their declared column names: {labels:?}"
        );
        // The placeholder must be GONE, not merely joined by the real names. Asserting only that
        // "Alpha" appears would pass on a band labelled `lane 1` plus a second band that happened
        // to carry it.
        assert!(
            !labels.iter().any(|label| label.starts_with("lane ")),
            "a generated placeholder survived alongside the declared names: {labels:?}"
        );
    }

    /// Control for the fallback: a card outside any column must still produce a LABELLED band.
    /// Without this, the recovery above could be "fixed" by emitting an empty label whenever the
    /// subgraph lookup misses, which trades a wrong name for a blank one.
    #[test]
    fn kanban_lane_band_falls_back_when_a_card_has_no_column() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Kanban);
        ir.labels.push(IrLabel {
            text: "Orphan".to_string(),
            ..IrLabel::default()
        });
        ir.nodes.push(IrNode {
            id: "t1".to_string(),
            label: Some(IrLabelId(0)),
            ..IrNode::default()
        });
        ir.graph.nodes.push(IrGraphNode::default());

        let layout = crate::layout_diagram_kanban_traced(&ir).layout;
        for band in &layout.extensions.bands {
            assert!(
                !band.label.is_empty(),
                "an uncolumned card produced a blank band label"
            );
        }
    }

    #[test]
    fn gantt_axis_ticks_land_on_the_bars_they_index() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Gantt);
        for label in ["Design", "Build"] {
            ir.labels.push(IrLabel {
                text: label.to_string(),
                ..IrLabel::default()
            });
        }
        for (node_id, label) in [("a1", IrLabelId(0)), ("a2", IrLabelId(1))] {
            ir.nodes.push(IrNode {
                id: node_id.to_string(),
                label: Some(label),
                ..IrNode::default()
            });
        }
        ir.gantt_meta = Some(IrGanttMeta {
            sections: vec![IrGanttSection {
                name: "Core".to_string(),
            }],
            tasks: vec![
                IrGanttTask {
                    node: IrNodeId(0),
                    section_idx: 0,
                    task_id: Some("a1".to_string()),
                    start: Some(GanttDate::Absolute("2026-01-01".to_string())),
                    end: Some(GanttDate::DurationDays(3)),
                    ..Default::default()
                },
                IrGanttTask {
                    node: IrNodeId(1),
                    section_idx: 0,
                    task_id: Some("a2".to_string()),
                    start: Some(GanttDate::Absolute("2026-01-04".to_string())),
                    end: Some(GanttDate::DurationDays(4)),
                    ..Default::default()
                },
            ],
            ..Default::default()
        });

        let layout = layout_diagram_gantt(&ir);
        let ticks = &layout.extensions.axis_ticks;

        // One tick per day from the first start through the chart's END BOUNDARY: a task starting
        // 2026-01-01 and running 7 days occupies through 01-07 and ends 01-08, so 8 ticks
        // (bd-pqp2f). Neither an empty axis nor a tick per pixel.
        assert_eq!(
            ticks.len(),
            8,
            "expected one tick per day over the inclusive span, got {:?}",
            ticks.iter().map(|t| t.label.as_str()).collect::<Vec<_>>()
        );

        for (task_index, start_label) in [(0usize, "2026-01-01"), (1usize, "2026-01-04")] {
            let tick = ticks
                .iter()
                .find(|tick| tick.label == start_label)
                .unwrap_or_else(|| panic!("no tick labelled {start_label}"));
            let bar_left = layout.nodes[task_index].bounds.x;
            assert!(
                (tick.position - bar_left).abs() <= 1.0,
                "tick {start_label} sits at {} but the bar starting that day has its left edge at \
                 {bar_left}: the axis does not index its own bars",
                tick.position
            );
        }

        // Control on the OTHER axis of the same claim: consecutive ticks are exactly one column
        // apart, so the fix is a translation of the whole tick row and not a per-tick refit that
        // happens to land on the two bars probed above.
        for pair in ticks.windows(2) {
            assert!(
                (pair[1].position - pair[0].position - 48.0).abs() <= 0.01,
                "consecutive ticks must be one 48px column apart, got {} -> {}",
                pair[0].position,
                pair[1].position
            );
        }
    }

    /// Build a one-task gantt whose axis directives are set directly, so each test varies exactly
    /// one directive against the same geometry.
    fn gantt_axis_probe(
        start: &str,
        duration_days: u32,
        axis_format: Option<&str>,
        tick_interval: Option<fm_core::GanttTickInterval>,
        weekday_start: Option<u8>,
    ) -> DiagramLayout {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Gantt);
        ir.labels.push(IrLabel {
            text: "Work".to_string(),
            ..IrLabel::default()
        });
        ir.nodes.push(IrNode {
            id: "a1".to_string(),
            label: Some(IrLabelId(0)),
            ..IrNode::default()
        });
        ir.gantt_meta = Some(IrGanttMeta {
            sections: vec![IrGanttSection {
                name: "S".to_string(),
            }],
            axis_format: axis_format.map(str::to_string),
            tick_interval,
            weekday_start,
            tasks: vec![IrGanttTask {
                node: IrNodeId(0),
                section_idx: 0,
                task_id: Some("a1".to_string()),
                start: Some(GanttDate::Absolute(start.to_string())),
                end: Some(GanttDate::DurationDays(duration_days)),
                ..Default::default()
            }],
            ..Default::default()
        });
        layout_diagram_gantt(&ir)
    }

    fn tick_labels(layout: &DiagramLayout) -> Vec<String> {
        layout
            .extensions
            .axis_ticks
            .iter()
            .map(|tick| tick.label.clone())
            .collect()
    }

    /// `axisFormat` is read here or nowhere (bd-w3pw): the tick label is built in layout, not in any
    /// renderer. Before bd-trsd drew the axis there was no label to format, so the directive could
    /// only ever have been asserted against a struct field.
    #[test]
    fn gantt_axis_format_rewrites_every_tick_label() {
        let formatted = gantt_axis_probe("2026-01-01", 3, Some("%m/%d"), None, None);
        // ⚠️ ONE MORE TICK THAN BEFORE, and it is the chart's END BOUNDARY (bd-pqp2f). The
        // axis used to stop at the last day a bar OCCUPIED; mermaid labels the exclusive end,
        // measured on gantt_basic where it draws 2026-01-08 and we drew through 2026-01-07.
        assert_eq!(
            tick_labels(&formatted),
            vec!["01/01", "01/02", "01/03", "01/04"],
            "axisFormat %m/%d must produce month/day labels"
        );

        // Control: the SAME geometry with no directive keeps the ISO label, so the assertion above
        // is about the directive and not about some unconditional relabelling.
        let plain = gantt_axis_probe("2026-01-01", 3, None, None, None);
        assert_eq!(
            tick_labels(&plain),
            vec!["2026-01-01", "2026-01-02", "2026-01-03", "2026-01-04"],
            "with no axisFormat the tick label must stay ISO"
        );
        assert_eq!(
            formatted.extensions.axis_ticks.len(),
            plain.extensions.axis_ticks.len(),
            "axisFormat changes label text only, never tick density"
        );
        for (formatted_tick, plain_tick) in formatted
            .extensions
            .axis_ticks
            .iter()
            .zip(&plain.extensions.axis_ticks)
        {
            assert!(
                (formatted_tick.position - plain_tick.position).abs() < 0.01,
                "axisFormat must not move a tick"
            );
        }

        // Names, and an unknown specifier surviving verbatim rather than vanishing: a swallowed
        // typo is a mysteriously missing piece of every label with nothing to point at.
        // A one-day task still spans two ticks: `total_span_days` has a floor of 1, so the axis
        // always shows a measurable interval rather than a single unanchored mark.
        assert_eq!(
            tick_labels(&gantt_axis_probe(
                "2026-01-01",
                1,
                Some("%a %d %B %Y"),
                None,
                None
            )),
            vec!["Thu 01 January 2026", "Fri 02 January 2026"]
        );
        assert_eq!(
            tick_labels(&gantt_axis_probe(
                "2026-01-01",
                1,
                Some("%Y-%Q"),
                None,
                None
            )),
            vec!["2026-%Q", "2026-%Q"]
        );
    }

    /// `tickInterval` is the density directive: without it a year-long chart gets 365 overlapping
    /// daily ticks, which is the state bd-trsd's fix shipped and the reason mermaid has the knob.
    #[test]
    fn gantt_tick_interval_thins_the_axis_to_period_starts() {
        // 2026-01-01 + 90 days spans January, February and March.
        let monthly = gantt_axis_probe(
            "2026-01-01",
            90,
            None,
            Some(fm_core::GanttTickInterval::Month),
            None,
        );
        // ⚠️ ONE MORE TICK THAN BEFORE, and it is the chart's END BOUNDARY (bd-pqp2f). The
        // axis used to stop at the last day a bar OCCUPIED; mermaid labels the exclusive end,
        // measured on gantt_basic where it draws 2026-01-08 and we drew through 2026-01-07.
        assert_eq!(
            tick_labels(&monthly),
            vec!["2026-01-01", "2026-02-01", "2026-03-01", "2026-04-01"],
            "tickInterval 1month must emit one tick per month start"
        );
        // Positions must still be the real day offsets, not a re-spaced row: Feb 1 is 31 days in
        // and Mar 1 is 59 (2026 is not a leap year), at 48px per day.
        let positions: Vec<f32> = monthly
            .extensions
            .axis_ticks
            .iter()
            .map(|tick| tick.position)
            .collect();
        assert!(
            (positions[1] - positions[0] - 31.0 * 48.0).abs() < 0.01
                && (positions[2] - positions[1] - 28.0 * 48.0).abs() < 0.01,
            "monthly ticks must sit on their real days, got {positions:?}"
        );

        // Non-vacuity: the same span with no directive is still one tick per day.
        let daily = gantt_axis_probe("2026-01-01", 90, None, None, None);
        // 90 occupied days plus the end boundary (bd-pqp2f).
        assert_eq!(daily.extensions.axis_ticks.len(), 91);

        // A span containing NO boundary must not lose its axis entirely — six days cross no
        // first-of-month, and silently emitting nothing would undo bd-trsd for exactly the
        // documents that asked for a coarser axis.
        let too_short = gantt_axis_probe(
            "2026-01-02",
            5,
            None,
            Some(fm_core::GanttTickInterval::Month),
            None,
        );
        assert_eq!(tick_labels(&too_short), vec!["2026-01-02"]);
    }

    /// `weekday` moves every week boundary, so it can only be observed through a weekly tick
    /// interval — and it must actually move them, not merely be accepted.
    #[test]
    fn gantt_weekday_directive_moves_the_weekly_tick_boundaries() {
        // 2026-01-01 is a Thursday; the probe spans 2026-01-01..2026-01-14.
        let mondays = gantt_axis_probe(
            "2026-01-01",
            14,
            None,
            Some(fm_core::GanttTickInterval::Week),
            Some(1),
        );
        assert_eq!(
            tick_labels(&mondays),
            vec!["2026-01-05", "2026-01-12"],
            "weekday monday must put the weekly ticks on Mondays"
        );

        // Control: the default (sunday) over the identical span lands on different days, so the
        // assertion above cannot be satisfied by ignoring the directive.
        let sundays = gantt_axis_probe(
            "2026-01-01",
            14,
            None,
            Some(fm_core::GanttTickInterval::Week),
            None,
        );
        assert_eq!(tick_labels(&sundays), vec!["2026-01-04", "2026-01-11"]);
    }

    #[test]
    fn gantt_layout_groups_tasks_by_section_and_orders_slots_horizontally() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Gantt);
        for label in ["Scope", "Estimate", "Build"] {
            ir.labels.push(IrLabel {
                text: label.to_string(),
                ..IrLabel::default()
            });
        }
        for (node_id, label) in [
            ("task_1", IrLabelId(0)),
            ("task_3", IrLabelId(1)),
            ("task_2", IrLabelId(2)),
        ] {
            ir.nodes.push(IrNode {
                id: node_id.to_string(),
                label: Some(label),
                ..IrNode::default()
            });
        }
        ir.gantt_meta = Some(IrGanttMeta {
            sections: vec![
                IrGanttSection {
                    name: "Planning".to_string(),
                },
                IrGanttSection {
                    name: "Delivery".to_string(),
                },
            ],
            tasks: vec![
                IrGanttTask {
                    node: IrNodeId(0),
                    section_idx: 0,
                    task_id: Some("task_1".to_string()),
                    start: Some(GanttDate::Absolute("2026-02-01".to_string())),
                    end: Some(GanttDate::DurationDays(2)),
                    ..Default::default()
                },
                IrGanttTask {
                    node: IrNodeId(1),
                    section_idx: 0,
                    task_id: Some("task_3".to_string()),
                    start: Some(GanttDate::Absolute("2026-02-03".to_string())),
                    end: Some(GanttDate::DurationDays(3)),
                    ..Default::default()
                },
                IrGanttTask {
                    node: IrNodeId(2),
                    section_idx: 1,
                    task_id: Some("task_2".to_string()),
                    start: Some(GanttDate::Absolute("2026-02-04".to_string())),
                    end: Some(GanttDate::DurationDays(2)),
                    ..Default::default()
                },
            ],
            ..Default::default()
        });

        let layout = layout_diagram_gantt(&ir);
        let nodes = layout
            .nodes
            .iter()
            .map(|node| (node.node_id.as_str(), node))
            .collect::<BTreeMap<_, _>>();

        let task_1 = nodes.get("task_1").expect("task_1");
        let task_2 = nodes.get("task_2").expect("task_2");
        let task_3 = nodes.get("task_3").expect("task_3");

        // GOLDEN-CHANGE of an ASSERTION, not a relaxation (bd-h9gx). This used to read
        // `assert!(task_1.bounds.width >= 156.0)`, which pinned the 156px minimum-bar-width floor —
        // and that floor was part of the defect: it made every task under 3.25 days over-long, and it
        // sat alongside a `max(label_width, ..)` term that let a rename change bar length. Bar width is
        // now purely temporal, so the correct assertion is the one the floor was hiding: task_1
        // declares DurationDays(2), so its bar is exactly two 48px columns. This is strictly stronger
        // than the old bound — it pins an exact value where the old one allowed anything above 156.
        assert_eq!(
            task_1.bounds.width, 96.0,
            "a 2-day task must be exactly 2 columns wide (2 * 48), independent of its label"
        );
        assert!(task_1.bounds.center().x < task_2.bounds.center().x);
        assert!(task_1.bounds.center().x < task_3.bounds.center().x);
        assert!(task_3.bounds.center().y > task_1.bounds.center().y);
        assert!((task_1.bounds.center().y - task_2.bounds.center().y).abs() > 10.0);
        assert_eq!(layout.extensions.bands.len(), 2);
        // ⚠️ ONE MORE TICK THAN BEFORE, and it is the chart's END BOUNDARY (bd-pqp2f). The
        // axis used to stop at the last day a bar OCCUPIED; mermaid labels the exclusive end,
        // measured on gantt_basic where it draws 2026-01-08 and we drew through 2026-01-07.
        assert_eq!(layout.extensions.axis_ticks.len(), 6);
        assert_eq!(layout.extensions.axis_ticks[0].label, "2026-02-01");
    }

    #[test]
    fn gantt_layout_honors_inclusive_end_dates_and_excludes() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Gantt);
        for label in ["Build", "Verify"] {
            ir.labels.push(IrLabel {
                text: label.to_string(),
                ..IrLabel::default()
            });
        }
        for (node_id, label) in [("build", IrLabelId(0)), ("verify", IrLabelId(1))] {
            ir.nodes.push(IrNode {
                id: node_id.to_string(),
                label: Some(label),
                ..IrNode::default()
            });
        }
        ir.gantt_meta = Some(IrGanttMeta {
            inclusive_end_dates: true,
            excludes: vec![GanttExclude::Weekends],
            sections: vec![IrGanttSection {
                name: "Alpha".to_string(),
            }],
            tasks: vec![
                IrGanttTask {
                    node: IrNodeId(0),
                    section_idx: 0,
                    task_id: Some("build".to_string()),
                    start: Some(GanttDate::Absolute("2026-02-06".to_string())),
                    end: Some(GanttDate::Absolute("2026-02-09".to_string())),
                    ..Default::default()
                },
                IrGanttTask {
                    node: IrNodeId(1),
                    section_idx: 0,
                    task_id: Some("verify".to_string()),
                    start: Some(GanttDate::AfterTask("build".to_string())),
                    end: Some(GanttDate::DurationDays(1)),
                    depends_on: vec!["build".to_string()],
                    ..Default::default()
                },
            ],
            ..Default::default()
        });

        let layout = layout_diagram_gantt(&ir);
        let nodes = layout
            .nodes
            .iter()
            .map(|node| (node.node_id.as_str(), node))
            .collect::<BTreeMap<_, _>>();

        let build = nodes.get("build").expect("build");
        let verify = nodes.get("verify").expect("verify");
        assert!(build.bounds.width > 3.5 * 48.0);
        assert!(verify.bounds.center().x > build.bounds.center().x);
    }

