    #[test]
    fn force_layout_self_loop() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Er);
        ir.nodes.push(IrNode {
            id: "A".to_string(),
            ..IrNode::default()
        });
        // Self-loop edge should be skipped (not cause crash).
        ir.edges.push(IrEdge {
            from: IrEndpoint::Node(IrNodeId(0)),
            to: IrEndpoint::Node(IrNodeId(0)),
            arrow: ArrowType::Arrow,
            ..IrEdge::default()
        });
        let layout = layout_diagram_force(&ir);
        assert_eq!(layout.nodes.len(), 1);
        assert_eq!(layout.edges.len(), 1);

        // It must be DRAWABLE, not merely present. This previously produced two identical points —
        // `clip_to_shape_border` returns its input unchanged when the direction is zero-length, and
        // a self-loop's two endpoints are the same centre — so the path had no extent and rendered
        // as nothing at all. An ER self-reference silently vanished.
        let path = &layout.edges[0];
        assert!(
            path.is_self_loop,
            "a from == to edge must be flagged as a self-loop"
        );
        assert!(
            path.points.len() >= 3,
            "a self-loop needs a routed path, got {} point(s)",
            path.points.len()
        );
        let min_x = path.points.iter().map(|p| p.x).fold(f32::MAX, f32::min);
        let max_x = path.points.iter().map(|p| p.x).fold(f32::MIN, f32::max);
        let min_y = path.points.iter().map(|p| p.y).fold(f32::MAX, f32::min);
        let max_y = path.points.iter().map(|p| p.y).fold(f32::MIN, f32::max);
        assert!(
            (max_x - min_x) > 1.0 && (max_y - min_y) > 1.0,
            "a self-loop must enclose area to be visible; got extent {}x{}",
            max_x - min_x,
            max_y - min_y
        );
        assert!(
            path.points
                .iter()
                .all(|p| p.x.is_finite() && p.y.is_finite()),
            "self-loop path must not contain non-finite coordinates"
        );
    }

    /// A force-layout edge must not be drawn through an unrelated node (bd-h2ze).
    ///
    /// `force_build_edge_paths` emitted a bare `[from, to]` line for every edge and never consulted
    /// the obstacle machinery `build_edge_paths` has always used — not overridden, never CALLED.
    /// Measured on the committed corpus: 30 edges across five goldens crossing unrelated node
    /// boxes, worst 33.2px into a 66.5px-tall box, i.e. the node's CENTRE. An edge through a node
    /// reads as connecting to it, so the picture asserted relationships nobody wrote.
    ///
    /// Driven at `force_build_edge_paths` with HAND-PLACED boxes rather than through
    /// `layout_diagram_force`, because force placement is emergent: my first attempt asked the
    /// solver for three collinear nodes, it produced a triangle, and the non-vacuity control
    /// correctly failed. Fixing the geometry by hand is what makes the fixture actually contain
    /// the defect.
    #[test]
    fn force_layout_edges_do_not_cross_unrelated_nodes() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Er);
        for node_id in ["LEFT", "MIDDLE", "RIGHT"] {
            ir.nodes.push(IrNode {
                id: node_id.to_string(),
                ..IrNode::default()
            });
        }
        ir.edges.push(IrEdge {
            from: IrEndpoint::Node(IrNodeId(0)),
            to: IrEndpoint::Node(IrNodeId(2)),
            arrow: ArrowType::Arrow,
            ..IrEdge::default()
        });

        // Three boxes on one row: LEFT, MIDDLE, RIGHT. A centre-to-centre line from LEFT to RIGHT
        // runs straight through MIDDLE.
        let boxes: Vec<LayoutNodeBox> = ["LEFT", "MIDDLE", "RIGHT"]
            .iter()
            .enumerate()
            .map(|(i, id)| LayoutNodeBox {
                node_index: i,
                node_id: (*id).to_string(),
                rank: 0,
                order: i,
                span: Span::default(),
                bounds: LayoutRect {
                    x: 100.0 + 200.0 * i as f32,
                    y: 100.0,
                    width: 100.0,
                    height: 60.0,
                },
            })
            .collect();

        let middle = boxes[1].bounds;
        let margin = 3.0_f32;
        let inside = |p: LayoutPoint| {
            p.x > middle.x + margin
                && p.x < middle.x + middle.width - margin
                && p.y > middle.y + margin
                && p.y < middle.y + middle.height - margin
        };

        // NON-VACUITY FIRST: the straight centre-to-centre line must actually cross MIDDLE, or this
        // fixture cannot detect the defect and the assertion below would pass for free.
        let a = boxes[0].bounds.center();
        let b = boxes[2].bounds.center();
        let straight_hits = (0..=200).any(|step| {
            let t = step as f32 / 200.0;
            inside(LayoutPoint {
                x: a.x + (b.x - a.x) * t,
                y: a.y + (b.y - a.y) * t,
            })
        });
        assert!(
            straight_hits,
            "CONTROL FAILED: a straight LEFT->RIGHT line misses MIDDLE, so this fixture cannot \
             detect the defect it was written for"
        );

        let edges = crate::force_build_edge_paths(&ir, &boxes);
        assert_eq!(edges.len(), 1);
        let edge = &edges[0];

        // ENDPOINTS UNCHANGED: a route that avoids a node by RETARGETING is not a fix.
        let near = |p: &LayoutPoint, r: &LayoutRect| {
            p.x >= r.x - 1.0
                && p.x <= r.x + r.width + 1.0
                && p.y >= r.y - 1.0
                && p.y <= r.y + r.height + 1.0
        };
        assert!(
            near(edge.points.first().unwrap(), &boxes[0].bounds)
                && near(edge.points.last().unwrap(), &boxes[2].bounds),
            "endpoints moved off their nodes: {:?}",
            edge.points.iter().map(|p| (p.x, p.y)).collect::<Vec<_>>()
        );

        // THE CLAIM: no sampled point on the routed path lies inside MIDDLE.
        let mut hit: Option<LayoutPoint> = None;
        for pair in edge.points.windows(2) {
            for step in 0..=60 {
                let t = step as f32 / 60.0;
                let sample = LayoutPoint {
                    x: pair[0].x + (pair[1].x - pair[0].x) * t,
                    y: pair[0].y + (pair[1].y - pair[0].y) * t,
                };
                if inside(sample) {
                    hit = Some(sample);
                }
            }
        }
        assert!(
            hit.is_none(),
            "edge LEFT->RIGHT passes through MIDDLE at {hit:?}; path is {:?}",
            edge.points.iter().map(|p| (p.x, p.y)).collect::<Vec<_>>()
        );
    }

    /// Two relationships between the same pair must be two visible lines, not one (Force path).
    ///
    /// `force_build_edge_paths` gave every edge between a pair the same centre-to-centre geometry,
    /// so an ER model with `A ||--o{ B : owns` and `A ||--o{ B : rents` drew one line and silently
    /// lost the other. Sugiyama has fanned these apart via `apply_parallel_offset` all along.
    #[test]
    fn force_layout_parallel_edges_do_not_coincide() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Er);
        for node_id in ["CUSTOMER", "ORDER"] {
            ir.nodes.push(IrNode {
                id: node_id.to_string(),
                ..IrNode::default()
            });
        }
        for _ in 0..3 {
            ir.edges.push(IrEdge {
                from: IrEndpoint::Node(IrNodeId(0)),
                to: IrEndpoint::Node(IrNodeId(1)),
                arrow: ArrowType::Arrow,
                ..IrEdge::default()
            });
        }

        let layout = layout_diagram_force(&ir);
        assert_eq!(layout.edges.len(), 3);
        for (left, right) in [(0, 1), (1, 2), (0, 2)] {
            assert_ne!(
                layout.edges[left].points.as_slice(),
                layout.edges[right].points.as_slice(),
                "parallel edges {left} and {right} have identical geometry, so only one is visible"
            );
        }

        // A single edge between the pair must NOT be displaced — the fan is centred on zero, so a
        // lone edge keeps the geometry it had before this fix and no golden moves for it.
        let mut single = MermaidDiagramIr::empty(DiagramType::Er);
        for node_id in ["CUSTOMER", "ORDER"] {
            single.nodes.push(IrNode {
                id: node_id.to_string(),
                ..IrNode::default()
            });
        }
        single.edges.push(IrEdge {
            from: IrEndpoint::Node(IrNodeId(0)),
            to: IrEndpoint::Node(IrNodeId(1)),
            arrow: ArrowType::Arrow,
            ..IrEdge::default()
        });
        let single_layout = layout_diagram_force(&single);
        assert_eq!(single_layout.edges[0].parallel_offset, 0.0);
        assert_eq!(
            layout.edges[1].parallel_offset, 0.0,
            "the middle edge of an odd fan sits on the centre line"
        );
    }

    /// The two layouts must fan a repeated pair by the same amount, or a diagram's edge separation
    /// changes when dispatch picks a different algorithm for reasons unrelated to its edges.
    #[test]
    fn force_and_sugiyama_agree_on_parallel_edge_offsets() {
        let mut ir = labeled_graph_ir(2, &[]);
        for _ in 0..4 {
            ir.edges.push(IrEdge {
                from: IrEndpoint::Node(IrNodeId(0)),
                to: IrEndpoint::Node(IrNodeId(1)),
                arrow: ArrowType::Arrow,
                ..IrEdge::default()
            });
        }

        let mut force: Vec<f32> = layout_diagram_force(&ir)
            .edges
            .iter()
            .map(|edge| edge.parallel_offset)
            .collect();
        let mut sugiyama: Vec<f32> = layout_diagram(&ir)
            .edges
            .iter()
            .map(|edge| edge.parallel_offset)
            .collect();
        force.sort_by(f32::total_cmp);
        sugiyama.sort_by(f32::total_cmp);
        assert_eq!(
            force, sugiyama,
            "the two builders fan the same four parallel edges differently"
        );
        assert_eq!(
            force,
            vec![-18.0, -6.0, 6.0, 18.0],
            "a four-edge fan is symmetric about zero in 12px steps"
        );
    }

    /// The self-loop must leave the node's box, or it is drawn underneath the node and invisible.
    #[test]
    fn force_layout_self_loop_escapes_the_node_box() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Er);
        ir.nodes.push(IrNode {
            id: "EMPLOYEE".to_string(),
            ..IrNode::default()
        });
        ir.edges.push(IrEdge {
            from: IrEndpoint::Node(IrNodeId(0)),
            to: IrEndpoint::Node(IrNodeId(0)),
            arrow: ArrowType::Arrow,
            ..IrEdge::default()
        });

        let layout = layout_diagram_force(&ir);
        let node = &layout.nodes[0].bounds;
        let path = &layout.edges[0];
        assert!(
            path.points.iter().any(|point| {
                point.x < node.x
                    || point.x > node.x + node.width
                    || point.y < node.y
                    || point.y > node.y + node.height
            }),
            "every point of the self-loop is inside the node box {node:?}, so the loop is drawn \
             under the node and cannot be seen: {:?}",
            path.points
        );
    }

    #[test]
    fn force_layout_connected_nodes_closer_than_disconnected() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Er);
        for node_id in ["A", "B", "C"] {
            ir.nodes.push(IrNode {
                id: (*node_id).to_string(),
                ..IrNode::default()
            });
        }
        // Only A-B connected, C is isolated.
        ir.edges.push(IrEdge {
            from: IrEndpoint::Node(IrNodeId(0)),
            to: IrEndpoint::Node(IrNodeId(1)),
            arrow: ArrowType::Line,
            ..IrEdge::default()
        });

        let layout = layout_diagram_force(&ir);
        let a = layout.nodes.iter().find(|n| n.node_id == "A").unwrap();
        let b = layout.nodes.iter().find(|n| n.node_id == "B").unwrap();
        let c = layout.nodes.iter().find(|n| n.node_id == "C").unwrap();

        let a_center = a.bounds.center();
        let b_center = b.bounds.center();
        let c_center = c.bounds.center();

        let dist_ab = (a_center.x - b_center.x).hypot(a_center.y - b_center.y);
        let dist_ac = (a_center.x - c_center.x).hypot(a_center.y - c_center.y);

        // Connected nodes should generally be closer than disconnected.
        assert!(
            dist_ab < dist_ac * 1.5,
            "Connected A-B distance ({dist_ab}) should be less than A-C distance ({dist_ac})"
        );
    }

    #[test]
    fn force_layout_with_clusters() {
        let mut ir = MermaidDiagramIr::empty(DiagramType::Er);
        for node_id in ["A", "B", "C", "D"] {
            ir.nodes.push(IrNode {
                id: (*node_id).to_string(),
                ..IrNode::default()
            });
        }
        ir.edges.push(IrEdge {
            from: IrEndpoint::Node(IrNodeId(0)),
            to: IrEndpoint::Node(IrNodeId(1)),
            arrow: ArrowType::Line,
            ..IrEdge::default()
        });
        ir.edges.push(IrEdge {
            from: IrEndpoint::Node(IrNodeId(2)),
            to: IrEndpoint::Node(IrNodeId(3)),
            arrow: ArrowType::Line,
            ..IrEdge::default()
        });
        // Cluster 0: A, B. Cluster 1: C, D.
        ir.clusters.push(IrCluster {
            id: IrClusterId(0),
            title: None,
            members: vec![IrNodeId(0), IrNodeId(1)],
            grid_span: 1,
            span: fm_core::Span::default(),
            c4_boundary_type: None,
        });
        ir.clusters.push(IrCluster {
            id: IrClusterId(1),
            title: None,
            members: vec![IrNodeId(2), IrNodeId(3)],
            grid_span: 1,
            span: fm_core::Span::default(),
            c4_boundary_type: None,
        });

        let layout = layout_diagram_force(&ir);
        assert_eq!(layout.nodes.len(), 4);
        assert_eq!(layout.clusters.len(), 2);
        // Cluster bounds should be non-zero.
        for cluster in &layout.clusters {
            assert!(cluster.bounds.width > 0.0);
            assert!(cluster.bounds.height > 0.0);
        }
    }

